INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_1_kor_u2_L01_basic#1','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C1',1,'mc','auto','「고쳐쓰기」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X01']::text[],false,'{"seq":1,"concept":"K6-1-u2-C1","difficulty":1,"kind":"mc","stem":"「고쳐쓰기」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓴 글을 점검해 더 잘 전달되도록 손보는 일","correct":true},{"t":"처음 쓴 글을 버리고 처음부터 다시 쓰는 일","mis":"K6-1-u2-X01"},{"t":"글씨를 예쁘게 다시 옮겨 적는 일","mis":"K6-1-u2-X01"},{"t":"친구 글을 그대로 베껴 쓰는 일","mis":"K6-1-u2-X01"}],"explanation":["다시 쓰기나 옮겨 적기가 아니에요.","점검한 내용을 바탕으로 해요.","필요한 곳만 손보아 글을 낫게 만들어요."]}'::jsonb),
('g6_1_kor_u2_L01_basic#2','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C15',1,'mc','auto','「사물함을 정리하면 좋은 점」에서 글의 주제와 어울리지 않는 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15']::text[],false,'{"seq":2,"concept":"K6-1-u2-C15","difficulty":1,"kind":"mc","stem":"「사물함을 정리하면 좋은 점」에서 글의 주제와 어울리지 않는 문장은 어느 것인가요?","options":[{"t":"우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","correct":true},{"t":"종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","mis":"K6-1-u2-X15"},{"t":"사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","mis":"K6-1-u2-X15"},{"t":"사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","mis":"K6-1-u2-X15"}],"explanation":["글의 주제는 사물함 정리예요.","급식실 이야기는 주제에서 벗어나요.","주제에서 벗어난 문장은 빼요."],"asset":{"type":"passage","lines":["사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","수업이 시작되었는데도 교과서를 못 찾아 허둥대기 쉽습니다.","종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","그러므로 일주일에 한 번은 사물함을 정리한다."],"title":"설명 글 「사물함을 정리하면 좋은 점」"}}'::jsonb),
('g6_1_kor_u2_L01_basic#3','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C2',1,'match','auto','고칠 일과 그에 알맞은 손질을 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-1-u2-C2","difficulty":1,"kind":"match","stem":"고칠 일과 그에 알맞은 손질을 이으세요.","pairs":[{"l":"주제에서 벗어난 내용","r":"빼기"},{"l":"부족한 내용","r":"더하기"},{"l":"순서가 뒤엉킨 부분","r":"옮기기"}],"mis":"K6-1-u2-X03","explanation":["벗어난 것은 빼요.","모자란 것은 더해요.","뒤엉킨 것은 옮겨요."]}'::jsonb),
('g6_1_kor_u2_L01_basic#4','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C4',1,'ox','auto','고쳐 쓴 글을 다른 사람과 나누면 내가 못 본 곳을 알게 될 수 있어요.',ARRAY['K6-1-u2-X10']::text[],false,'{"seq":4,"concept":"K6-1-u2-C4","difficulty":1,"kind":"ox","stem":"고쳐 쓴 글을 다른 사람과 나누면 내가 못 본 곳을 알게 될 수 있어요.","answer":"O","reason_options":[{"t":"친구가 내가 놓친 곳을 짚어 주고 읽는 사람의 반응을 알 수 있기 때문에","correct":true},{"t":"나누면 무조건 칭찬을 받기 때문에","mis":"K6-1-u2-X10"}],"mis":"K6-1-u2-X10","explanation":["세아는 못 본 곳을 친구가 짚어 줬어요.","읽는 사람의 반응을 바로 알 수 있어요.","고쳐쓰기에 큰 도움이 돼요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"학급 게시판에 올린 내 글에 댓글이 세 개 달렸어. 내가 못 본 곳을 친구가 짚어 줬어."},{"who":"민석","text":"나도 올려 봤는데, 읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라."}]}}'::jsonb),
('g6_1_kor_u2_L01_basic#5','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C2',2,'mc','auto','「사물함을 정리하면 좋은 점」의 마지막 문장이 어색한 까닭은 무엇인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X04','K6-1-u2-X11']::text[],false,'{"seq":5,"concept":"K6-1-u2-C2","difficulty":2,"kind":"mc","stem":"「사물함을 정리하면 좋은 점」의 마지막 문장이 어색한 까닭은 무엇인가요?","options":[{"t":"앞 문장들은 「~습니다」로 썼는데 마지막만 「정리한다」로 말투가 어긋나서","correct":true},{"t":"사물함 이야기가 아니어서","mis":"K6-1-u2-X15"},{"t":"문장이 너무 짧아서","mis":"K6-1-u2-X04"},{"t":"제목과 같은 낱말을 써서","mis":"K6-1-u2-X11"}],"explanation":["마지막 문장도 사물함 이야기예요.","말투가 앞 문장들과 달라요.","「정리합시다」처럼 말투를 맞춰요."],"asset":{"type":"passage","lines":["사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","수업이 시작되었는데도 교과서를 못 찾아 허둥대기 쉽습니다.","종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","그러므로 일주일에 한 번은 사물함을 정리한다."],"title":"설명 글 「사물함을 정리하면 좋은 점」"}}'::jsonb),
('g6_1_kor_u2_L01_basic#6','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C3',2,'match','auto','살필 내용과 수준을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u2-C3","difficulty":2,"kind":"match","stem":"살필 내용과 수준을 알맞게 이으세요.","pairs":[{"l":"제목이 내용을 잘 나타내는가","r":"글 수준"},{"l":"뒷받침 문장이 중심 문장과 어울리는가","r":"문단 수준"},{"l":"주어와 서술어가 호응하는가","r":"문장 수준"}],"mis":"K6-1-u2-X04","explanation":["제목은 글 전체를 봐야 알아요.","뒷받침 문장은 문단 하나를 보면 알아요.","호응은 한 문장만 봐도 알아요."]}'::jsonb),
('g6_1_kor_u2_L01_basic#7','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C5',2,'mc','auto','친구 글에 남길 댓글로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X06','K6-1-u2-X07','K6-1-u2-X08']::text[],false,'{"seq":7,"concept":"K6-1-u2-C5","difficulty":2,"kind":"mc","stem":"친구 글에 남길 댓글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「첫 문단이 눈에 잘 들어왔어. 셋째 문장은 주제와 조금 멀어 보여.」","correct":true},{"t":"「무슨 말인지 하나도 모르겠어. 다시 써.」","mis":"K6-1-u2-X06"},{"t":"「그냥 다 좋아. 고칠 곳이 하나도 없어.」","mis":"K6-1-u2-X07"},{"t":"「셋째 문장 고쳐.」","mis":"K6-1-u2-X08"}],"explanation":["다시 쓰라는 말은 글쓴이를 위축시켜요.","막연한 칭찬은 쓸모가 적어요.","잘한 곳을 먼저, 고칠 곳은 까닭과 함께 말해요."]}'::jsonb),
('g6_1_kor_u2_L01_basic#8','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C6',2,'ox','auto','온라인 게시판에 글을 올릴 때에는 줄임말이나 은어를 써도 괜찮아요.',ARRAY['K6-1-u2-X09']::text[],false,'{"seq":8,"concept":"K6-1-u2-C6","difficulty":2,"kind":"ox","stem":"온라인 게시판에 글을 올릴 때에는 줄임말이나 은어를 써도 괜찮아요.","answer":"X","reason_options":[{"t":"한 번 올린 글은 널리 퍼지고 읽는 사람이 여럿이기 때문에","correct":true},{"t":"친구끼리는 줄임말이 더 빨리 통하기 때문에","mis":"K6-1-u2-X09"}],"mis":"K6-1-u2-X09","explanation":["올린 글은 여러 사람이 읽어요.","한 번 올리면 널리 퍼져요.","줄임말 · 은어 · 비속어를 쓰지 않아요."]}'::jsonb),
('g6_1_kor_u2_L01_basic#9','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C3',2,'mc','auto','고쳐 쓸 때 살피는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X04']::text[],false,'{"seq":9,"concept":"K6-1-u2-C3","difficulty":2,"kind":"mc","stem":"고쳐 쓸 때 살피는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"글 → 문단 → 문장","correct":true},{"t":"문장 → 문단 → 글","mis":"K6-1-u2-X05"},{"t":"띄어쓰기 → 글씨 → 제목","mis":"K6-1-u2-X05"},{"t":"문단 → 글 → 문장","mis":"K6-1-u2-X04"}],"explanation":["큰 것부터 봐요.","작은 것부터 고치면 헛수고가 생겨요.","글 → 문단 → 문장 차례예요."]}'::jsonb),
('g6_1_kor_u2_L01_basic#10','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C7',3,'mc','auto','「고쳐 쓰라는 말은 내 글이 잘못됐다는 뜻이야.」라고 생각하는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X02','K6-1-u2-X01']::text[],false,'{"seq":10,"concept":"K6-1-u2-C7","difficulty":3,"kind":"mc","stem":"「고쳐 쓰라는 말은 내 글이 잘못됐다는 뜻이야.」라고 생각하는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「여기만 손보면 네가 하고 싶은 말이 더 잘 전해진다는 뜻이야. 작게 고친 것도 잘 고친 거야.」","correct":true},{"t":"「맞아, 그러니까 글을 통째로 다시 써.」","mis":"K6-1-u2-X02"},{"t":"「고칠 곳이 있으면 처음부터 새로 쓰는 게 빨라.」","mis":"K6-1-u2-X01"},{"t":"「완벽하게 고치지 못할 거면 손대지 마.」","mis":"K6-1-u2-X02"}],"explanation":["고쳐쓰기는 혼나는 일이 아니에요.","다시 쓰기가 아니에요.","필요한 곳만 손봐도 글이 나아져요."]}'::jsonb),
('g6_1_kor_u2_L01_challenge#1','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C2',2,'mc','auto','「사물함을 정리하면 좋은 점」에서 급식실 문장에 해야 할 손질은 무엇인가요?',ARRAY['K6-1-u2-X03','K6-1-u2-X01']::text[],false,'{"seq":1,"concept":"K6-1-u2-C2","difficulty":2,"kind":"mc","stem":"「사물함을 정리하면 좋은 점」에서 급식실 문장에 해야 할 손질은 무엇인가요?","options":[{"t":"빼기","correct":true},{"t":"더하기","mis":"K6-1-u2-X03"},{"t":"옮기기","mis":"K6-1-u2-X03"},{"t":"글씨 다시 쓰기","mis":"K6-1-u2-X01"}],"explanation":["급식실 문장은 주제와 상관없어요.","옮겨도 주제와 맞지 않아요.","주제에서 벗어난 내용은 빼요."],"asset":{"type":"passage","lines":["사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","수업이 시작되었는데도 교과서를 못 찾아 허둥대기 쉽습니다.","종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","그러므로 일주일에 한 번은 사물함을 정리한다."],"title":"설명 글 「사물함을 정리하면 좋은 점」"}}'::jsonb),
('g6_1_kor_u2_L01_challenge#2','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C1',2,'ox','auto','고쳐쓰기를 할 때에는 처음 쓴 글을 버리고 처음부터 새로 써야 해요.',ARRAY['K6-1-u2-X01']::text[],false,'{"seq":2,"concept":"K6-1-u2-C1","difficulty":2,"kind":"ox","stem":"고쳐쓰기를 할 때에는 처음 쓴 글을 버리고 처음부터 새로 써야 해요.","answer":"X","reason_options":[{"t":"고쳐쓰기는 점검한 내용을 바탕으로 필요한 곳만 손보는 일이기 때문에","correct":true},{"t":"처음 쓴 글에는 좋은 곳이 하나도 없기 때문에","mis":"K6-1-u2-X01"}],"mis":"K6-1-u2-X01","explanation":["고쳐쓰기는 다시 쓰기가 아니에요.","처음 쓴 글에도 살릴 곳이 있어요.","필요한 곳만 손봐요."]}'::jsonb),
('g6_1_kor_u2_L01_challenge#3','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C3',3,'error','auto','고쳐 쓸 때 살피는 수준을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u2-X04']::text[],false,'{"seq":3,"concept":"K6-1-u2-C3","difficulty":3,"kind":"error","stem":"고쳐 쓸 때 살피는 수준을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"규리 — 「제목이 내용과 어울리는지는 한 문장만 보면 알 수 있어.」","correct":true,"mis_target":"K6-1-u2-X04"},{"t":"하율 — 「처음 · 가운데 · 끝의 흐름은 글 전체를 봐야 해.」","mis":"K6-1-u2-X04"},{"t":"서진 — 「띄어쓰기는 문장 수준에서 살펴.」","mis":"K6-1-u2-X04"}],"explanation":["하율과 서진은 바르게 말했어요.","제목과 내용은 글 전체를 봐야 알아요.","규리는 글 수준의 일을 문장 수준으로 보았어요."]}'::jsonb),
('g6_1_kor_u2_L01_challenge#4','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C4',3,'mc','auto','민석이가 「읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라.」라고 한 말에서 알 수 있는 것은 무엇인가요?',ARRAY['K6-1-u2-X10','K6-1-u2-X05']::text[],false,'{"seq":4,"concept":"K6-1-u2-C4","difficulty":3,"kind":"mc","stem":"민석이가 「읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라.」라고 한 말에서 알 수 있는 것은 무엇인가요?","options":[{"t":"글을 나누면 읽는 사람을 떠올리게 되어 고쳐쓰기에 도움이 된다","correct":true},{"t":"글을 나누면 더 고치지 않아도 된다","mis":"K6-1-u2-X10"},{"t":"글을 나누는 것은 칭찬을 받으려는 것이다","mis":"K6-1-u2-X10"},{"t":"읽는 사람이 없으면 띄어쓰기만 보면 된다","mis":"K6-1-u2-X05"}],"explanation":["읽는 사람을 떠올리면 문장을 더 꼼꼼히 봐요.","나눈 뒤에도 다시 점검해요.","나누는 것은 고쳐쓰기를 돕는 일이에요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"학급 게시판에 올린 내 글에 댓글이 세 개 달렸어. 내가 못 본 곳을 친구가 짚어 줬어."},{"who":"민석","text":"나도 올려 봤는데, 읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라."}]}}'::jsonb),
('g6_1_kor_u2_L01_challenge#5','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C5',3,'mc','auto','같은 내용이라도 댓글의 말하는 방식이 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X06','K6-1-u2-X07','K6-1-u2-X08']::text[],false,'{"seq":5,"concept":"K6-1-u2-C5","difficulty":3,"kind":"mc","stem":"같은 내용이라도 댓글의 말하는 방식이 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말하는 방식에 따라 글쓴이가 다시 고쳐 쓰고 싶어질 수도, 쓰기 싫어질 수도 있기 때문에","correct":true},{"t":"고칠 곳은 많이 늘어놓을수록 도움이 되기 때문에","mis":"K6-1-u2-X06"},{"t":"칭찬만 하면 글쓴이가 기뻐하기 때문에","mis":"K6-1-u2-X07"},{"t":"까닭은 말하지 않아도 글쓴이가 알기 때문에","mis":"K6-1-u2-X08"}],"explanation":["고칠 곳만 늘어놓으면 위축돼요.","막연한 칭찬은 도움이 적어요.","방식에 따라 다시 쓰고 싶은 마음이 달라져요."]}'::jsonb),
('g6_1_kor_u2_L01_challenge#6','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C6',3,'match','auto','온라인에 글을 올릴 때의 일과 알맞은 것을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u2-C6","difficulty":3,"kind":"match","stem":"온라인에 글을 올릴 때의 일과 알맞은 것을 이으세요.","pairs":[{"l":"여러 사람이 읽고 의견을 준다","r":"좋은 점"},{"l":"한 번 올린 글은 널리 퍼진다","r":"주의할 점"},{"l":"자료를 옮길 때 출처를 밝힌다","r":"지킬 것"}],"mis":"K6-1-u2-X09","explanation":["의견을 받을 수 있는 것은 좋은 점이에요.","널리 퍼지는 것은 주의할 점이에요.","출처를 밝히는 것은 지킬 것이에요."]}'::jsonb),
('g6_1_kor_u2_L01_challenge#7','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C7',3,'mc','auto','세 군데만 고쳤는데 「이 정도로는 소용없어.」라고 말하는 친구에게 알맞은 생각은 어느 것인가요?',ARRAY['K6-1-u2-X02','K6-1-u2-X01','K6-1-u2-X10']::text[],false,'{"seq":7,"concept":"K6-1-u2-C7","difficulty":3,"kind":"mc","stem":"세 군데만 고쳤는데 「이 정도로는 소용없어.」라고 말하는 친구에게 알맞은 생각은 어느 것인가요?","options":[{"t":"한 군데를 고쳤으면 그만큼 나아진 것이다","correct":true},{"t":"완벽하게 고치지 않으면 고친 것이 아니다","mis":"K6-1-u2-X02"},{"t":"다 지우고 처음부터 다시 써야 한다","mis":"K6-1-u2-X01"},{"t":"고칠 곳이 있으면 글을 올리지 않는다","mis":"K6-1-u2-X10"}],"explanation":["완벽한 글을 만드는 일이 아니에요.","작게 고친 것도 잘 고친 것이에요.","고친 만큼 글이 나아져요."]}'::jsonb),
('g6_1_kor_u2_L01_challenge#8','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C2',4,'mc','auto','「사물함을 정리하면 좋은 점」을 고칠 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X01','K6-1-u2-X03','K6-1-u2-X15']::text[],false,'{"seq":8,"concept":"K6-1-u2-C2","difficulty":4,"kind":"mc","stem":"「사물함을 정리하면 좋은 점」을 고칠 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"급식실 문장은 빼고, 마지막 문장은 「정리합시다」로 바꾸어 말투를 맞춘다","correct":true},{"t":"글 전체를 지우고 다른 주제로 새로 쓴다","mis":"K6-1-u2-X01"},{"t":"급식실 문장을 맨 앞으로 옮긴다","mis":"K6-1-u2-X03"},{"t":"모든 문장을 「~한다」로 바꾸고 급식실 문장도 그대로 둔다","mis":"K6-1-u2-X15"}],"explanation":["필요한 곳만 손봐요.","벗어난 문장은 옮기지 않고 빼요.","어색한 말투는 바꾸어 맞춰요."],"asset":{"type":"passage","lines":["사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","수업이 시작되었는데도 교과서를 못 찾아 허둥대기 쉽습니다.","종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","그러므로 일주일에 한 번은 사물함을 정리한다."],"title":"설명 글 「사물함을 정리하면 좋은 점」"}}'::jsonb),
('g6_1_kor_u2_L01_challenge#9','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C1',4,'essay','teacher','「고쳐쓰기」가 무엇인지 내 말로 설명하고, 고쳐쓰기가 「다시 쓰기」와 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C1","difficulty":4,"kind":"essay","stem":"「고쳐쓰기」가 무엇인지 내 말로 설명하고, 고쳐쓰기가 「다시 쓰기」와 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 고쳐쓰기는 쓴 글을 다시 읽고 점검해서 하고 싶은 말이 더 잘 전해지도록 필요한 곳만 손보는 일이다. 주제에서 벗어난 것은 빼고, 부족한 것은 더하고, 어색한 표현은 바꾸고, 뒤엉킨 순서는 옮긴다. 다시 쓰기는 처음 쓴 글을 버리고 처음부터 새로 쓰는 것이지만 고쳐쓰기는 처음 쓴 글을 살리면서 고칠 곳만 손본다는 점이 다르다.","scoring_points":["고쳐쓰기를 점검해 필요한 곳만 손보는 일로 설명했는가","빼기 · 더하기 · 바꾸기 · 옮기기 가운데 한 가지 이상을 들었는가","다시 쓰기와의 차이를 썼는가"]},"explanation":["점검하고 손보는 일이에요.","네 가지 손질을 떠올려요.","처음 쓴 글을 살린다는 점이 달라요."]}'::jsonb),
('g6_1_kor_u2_L01_challenge#10','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C5',4,'essay','teacher','친구가 쓴 글에 고칠 곳이 보였어요. 친구가 다시 고쳐 쓰고 싶어지도록 댓글을 쓰고, 왜 그렇게 썼는지 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C5","difficulty":4,"kind":"essay","stem":"친구가 쓴 글에 고칠 곳이 보였어요. 친구가 다시 고쳐 쓰고 싶어지도록 댓글을 쓰고, 왜 그렇게 썼는지 까닭을 쓰세요.","answer_guide":{"answer":"예: 댓글 — 「사물함이 어지러울 때 생기는 일을 예로 들어서 바로 이해가 됐어. 급식실이 바뀌었다는 문장은 사물함 이야기와 멀어 보여서 빼면 더 좋겠어.」 까닭 — 잘한 곳을 먼저 말해야 글쓴이가 위축되지 않고, 고칠 곳은 까닭을 함께 말해야 어디를 왜 고칠지 알 수 있기 때문이다.","scoring_points":["잘한 곳을 먼저 말했는가","고칠 곳을 까닭과 함께 말했는가","그렇게 쓴 까닭을 썼는가"]},"explanation":["잘한 곳부터 짚어요.","고칠 곳은 까닭과 함께 말해요.","글쓴이의 마음을 생각해요."]}'::jsonb),
('g6_1_kor_u2_L02_basic#1','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C8',1,'mc','auto','해준의 감상문에 어울리는 제목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X11','K6-1-u2-X15']::text[],false,'{"seq":1,"concept":"K6-1-u2-C8","difficulty":1,"kind":"mc","stem":"해준의 감상문에 어울리는 제목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"무너져도 다시 손을 대는 힘","correct":true},{"t":"바닷가 여름 풍경 소개","mis":"K6-1-u2-X11"},{"t":"모래를 좋아하는 우리 집 강아지","mis":"K6-1-u2-X15"},{"t":"모래성 이야기 줄거리","mis":"K6-1-u2-X11"}],"explanation":["라 문단에서 새로 생각하게 된 것을 봐요.","줄거리나 풍경만 알리는 제목은 부족해요.","글쓴이가 느낀 것이 드러나야 해요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb),
('g6_1_kor_u2_L02_basic#2','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C11',1,'mc','auto','문단에서 하고 싶은 말을 담은 문장을 무엇이라고 하나요?',ARRAY['K6-1-u2-X14','K6-1-u2-X11']::text[],false,'{"seq":2,"concept":"K6-1-u2-C11","difficulty":1,"kind":"mc","stem":"문단에서 하고 싶은 말을 담은 문장을 무엇이라고 하나요?","options":[{"t":"중심 문장","correct":true},{"t":"뒷받침 문장","mis":"K6-1-u2-X14"},{"t":"제목","mis":"K6-1-u2-X11"},{"t":"끝 문장","mis":"K6-1-u2-X14"}],"explanation":["문단에는 하고 싶은 말이 있어요.","그 말을 담은 문장이 중심 문장이에요.","뒷받침 문장은 그것을 자세히 설명해요."]}'::jsonb),
('g6_1_kor_u2_L02_basic#3','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C15',1,'mc','auto','해준의 감상문 나 문단에서 빼야 할 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X16']::text[],false,'{"seq":3,"concept":"K6-1-u2-C15","difficulty":1,"kind":"mc","stem":"해준의 감상문 나 문단에서 빼야 할 문장은 어느 것인가요?","options":[{"t":"우리 집 강아지도 모래를 좋아한다.","correct":true},{"t":"저녁마다 파도가 성을 지웠다.","mis":"K6-1-u2-X15"},{"t":"새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다.","mis":"K6-1-u2-X15"},{"t":"미르는 여름 내내 쌓았다.","mis":"K6-1-u2-X16"}],"explanation":["나 문단의 중심은 미르가 모래성을 쌓은 일이에요.","강아지 이야기는 상관이 없어요.","「여름 내내 쌓았다」는 지우지 말고 고쳐요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb),
