('g6_1_kor_u2_L09_basic#8','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C35',2,'ox','auto','글에 넣은 사진이 보기 좋아도 내용과 이어지지 않으면 빼는 것도 고쳐쓰기예요.',ARRAY['K6-1-u2-X43']::text[],false,'{"seq":8,"concept":"K6-1-u2-C35","difficulty":2,"kind":"ox","stem":"글에 넣은 사진이 보기 좋아도 내용과 이어지지 않으면 빼는 것도 고쳐쓰기예요.","answer":"O","reason_options":[{"t":"사진과 영상도 글의 한 부분이라 내용과 이어져야 하기 때문에","correct":true},{"t":"사진은 글이 아니라 고칠 필요가 없기 때문에","mis":"K6-1-u2-X43"}],"mis":"K6-1-u2-X43","explanation":["도서관 바깥 풍경은 숫자 설명과 이어지지 않아요.","책등 숫자가 보이는 서가 사진은 이어져요.","겉도는 자료는 빼요."]}'::jsonb),
('g6_1_kor_u2_L09_basic#9','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C34',2,'mc','auto','맞춤법 검사기를 쓸 때 알맞은 태도는 어느 것인가요?',ARRAY['K6-1-u2-X42','K6-1-u2-X41']::text[],false,'{"seq":9,"concept":"K6-1-u2-C34","difficulty":2,"kind":"mc","stem":"맞춤법 검사기를 쓸 때 알맞은 태도는 어느 것인가요?","options":[{"t":"도구가 고친 곳도 왜 그렇게 고쳤는지 확인하고 받아들인다","correct":true},{"t":"도구가 고친 대로 모두 받아들인다","mis":"K6-1-u2-X42"},{"t":"도구가 글의 중심 생각까지 정해 준다","mis":"K6-1-u2-X42"},{"t":"도구를 썼으니 다시 읽지 않는다","mis":"K6-1-u2-X41"}],"explanation":["까닭을 모르면 다음에도 똑같이 틀려요.","중심 생각은 도구가 정하지 못해요.","고칠지 말지는 글쓴이가 정해요."]}'::jsonb),
('g6_1_kor_u2_L09_basic#10','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C32',3,'mc','auto','다빈이 정후의 의견을 따르지 않은 것에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u2-X40','K6-1-u2-X41']::text[],false,'{"seq":10,"concept":"K6-1-u2-C32","difficulty":3,"kind":"mc","stem":"다빈이 정후의 의견을 따르지 않은 것에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"숫자를 설명하는 글이라 책 목록은 하려던 말을 흐리게 하므로 따르지 않은 까닭이 분명하다","correct":true},{"t":"친구 의견을 따르지 않았으니 예의가 없다","mis":"K6-1-u2-X40"},{"t":"정후의 의견이 틀렸으니 다시는 의견을 받지 않는다","mis":"K6-1-u2-X41"},{"t":"친구가 말하면 무조건 넣어야 한다","mis":"K6-1-u2-X40"}],"explanation":["의견을 고르는 것은 글쓴이예요.","기준은 하려던 말이 더 잘 전해지는가예요.","따르지 않은 까닭을 말할 수 있으면 돼요."],"asset":{"type":"speech","turns":[{"who":"정후","text":"다빈아, 글 끝에 네가 좋아하는 책 목록도 넣으면 어때?"},{"who":"다빈","text":"고맙지만 이 글은 숫자를 설명하는 글이라 그건 안 넣기로 했어."}]}}'::jsonb),
('g6_1_kor_u2_L09_challenge#1','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C31',2,'mc','auto','「의자 이야기는 빼면 좋겠어. 숫자 설명과 멀어 보여서.」는 의견의 네 갈래 가운데 무엇인가요?',ARRAY['K6-1-u2-X39']::text[],false,'{"seq":1,"concept":"K6-1-u2-C31","difficulty":2,"kind":"mc","stem":"「의자 이야기는 빼면 좋겠어. 숫자 설명과 멀어 보여서.」는 의견의 네 갈래 가운데 무엇인가요?","options":[{"t":"고쳤으면 하는 점","correct":true},{"t":"새롭게 안 점","mis":"K6-1-u2-X39"},{"t":"궁금한 점","mis":"K6-1-u2-X39"},{"t":"좋은 점","mis":"K6-1-u2-X39"}],"explanation":["빼자고 말했어요.","까닭도 함께 말했어요.","고칠 곳과 까닭은 고쳤으면 하는 점이에요."],"asset":{"type":"speech","turns":[{"who":"승아","text":"숫자에 뜻이 있는 줄 몰랐어."},{"who":"우진","text":"도서관마다 숫자가 같은지 궁금해."},{"who":"정후","text":"첫 문단이 짧아서 읽기 좋았어."},{"who":"승아","text":"의자 이야기는 빼면 좋겠어. 숫자 설명과 멀어 보여서."}]}}'::jsonb),
('g6_1_kor_u2_L09_challenge#2','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C33',2,'mc','auto','승아의 댓글에 다빈이 단 답글에서 본받을 점은 무엇인가요?',ARRAY['K6-1-u2-X41','K6-1-u2-X06','K6-1-u2-X01']::text[],false,'{"seq":2,"concept":"K6-1-u2-C33","difficulty":2,"kind":"mc","stem":"승아의 댓글에 다빈이 단 답글에서 본받을 점은 무엇인가요?","options":[{"t":"읽었다는 것과 어떻게 고쳤는지를 알려 주었다","correct":true},{"t":"댓글을 읽고 아무 말도 하지 않았다","mis":"K6-1-u2-X41"},{"t":"승아의 의견이 틀렸다고 말했다","mis":"K6-1-u2-X06"},{"t":"의견을 듣고 글을 처음부터 다시 썼다","mis":"K6-1-u2-X01"}],"explanation":["댓글을 받고 끝내지 않았어요.","고마움을 표현했어요.","한 문장 더 넣어 고친 것을 알렸어요."],"asset":{"type":"speech","turns":[{"who":"승아","text":"도서관마다 숫자가 같은지 궁금하다고 했는데, 나도 그게 궁금했어."},{"who":"다빈","text":"알려 줘서 고마워. 그 부분을 한 문장 더 넣어서 고쳐 뒀어."}]}}'::jsonb),
