('g6_1_kor_u2_review_b#18','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C15',3,'mc','auto','하린의 초고에서 「배 두척」을 고칠 때 쓸 부호와 쓰임을 바르게 짝 지은 것은 어느 것인가요?',ARRAY['K6-1-u2-X23','K6-1-u2-X29']::text[],false,'{"seq":18,"concept":"K6-1-u2-C15","difficulty":3,"kind":"mc","stem":"하린의 초고에서 「배 두척」을 고칠 때 쓸 부호와 쓰임을 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"두∨척 — 띄어 쓸 곳에 ∨","correct":true},{"t":"두⌒척 — 띄어 쓸 곳에 ⌒","mis":"K6-1-u2-X23"},{"t":"두⊂척 — 띄어 쓸 곳에 ⊂","mis":"K6-1-u2-X23"},{"t":"부호 없이 문장을 다시 쓴다","mis":"K6-1-u2-X29"}],"explanation":["⌒ 는 붙일 때 써요.","⊂ 는 더 넣을 때 써요.","띄울 곳에는 ∨ 예요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb),
('g6_1_kor_u2_review_b#19','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C11',3,'mc','auto','하린의 감상문에서 중심 생각을 가장 잘 담은 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X14']::text[],false,'{"seq":19,"concept":"K6-1-u2-C11","difficulty":3,"kind":"mc","stem":"하린의 감상문에서 중심 생각을 가장 잘 담은 문장은 어느 것인가요?","options":[{"t":"나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄 수 있는 사람이 되겠다.","correct":true},{"t":"우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","mis":"K6-1-u2-X15"},{"t":"배 두 척을 강물에 띄우는 마지막 장면도 기억에 남는다.","mis":"K6-1-u2-X14"},{"t":"지난 토요일 학교 강당에서 연극을 보았다.","mis":"K6-1-u2-X14"}],"explanation":["놀이터 문장은 상관없어요.","장면 · 본 때는 뒷받침이에요.","하린이 하고 싶은 말은 기다려 주는 마음이에요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb),
('g6_1_kor_u2_review_b#20','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C27',3,'mc','auto','로운의 글 제목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X36','K6-1-u2-X11']::text[],false,'{"seq":20,"concept":"K6-1-u2-C27","difficulty":3,"kind":"mc","stem":"로운의 글 제목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"반마다 순서가 있는 텃밭 물 주기","correct":true},{"t":"세상의 모든 채소","mis":"K6-1-u2-X36"},{"t":"체육 창고 이야기","mis":"K6-1-u2-X36"},{"t":"우리 학교","mis":"K6-1-u2-X11"}],"explanation":["너무 넓은 제목은 내용과 달라요.","창고는 내용과 상관없어요.","내용과 일치하고 짧게 지어요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb),
('g6_1_kor_u2_review_b#21','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C39',3,'match','auto','책상과 문에 일어난 일에 알맞은 표현을 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K6-1-u2-C39","difficulty":3,"kind":"match","stem":"책상과 문에 일어난 일에 알맞은 표현을 이으세요.","pairs":[{"l":"내가 책상 위에 책을","r":"놓았다"},{"l":"언제부터인가 책상 위에 책이","r":"놓여 있었다"},{"l":"바람에 문이","r":"닫혔다"}],"mis":"K6-1-u2-X47","explanation":["내가 한 일은 주동이에요.","저절로 그리 된 것은 피동이에요.","바람이라는 다른 힘이 닫았어요."]}'::jsonb),
('g6_1_kor_u2_review_b#22','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C20',3,'mc','auto','하린이 「나는 「수」를 자주 붙여 써.」라고 알게 되었어요. 다음에 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X24','K6-1-u2-X29','K6-1-u2-X42']::text[],false,'{"seq":22,"concept":"K6-1-u2-C20","difficulty":3,"kind":"mc","stem":"하린이 「나는 「수」를 자주 붙여 써.」라고 알게 되었어요. 다음에 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다음 글을 쓸 때 「수」 앞뒤를 꼭 확인하기로 정해 둔다","correct":true},{"t":"띄어쓰기는 원래 어려우니 신경 쓰지 않는다","mis":"K6-1-u2-X24"},{"t":"틀릴 때마다 글을 처음부터 다시 쓴다","mis":"K6-1-u2-X29"},{"t":"검사기가 알아서 고쳐 주니 확인하지 않는다","mis":"K6-1-u2-X42"}],"explanation":["띄어쓰기는 뜻 문제예요.","다시 쓰지 않아도 돼요.","내 버릇 한 가지를 정해 챙겨요."]}'::jsonb),
('g6_1_kor_u2_review_b#23','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C32',4,'mc','auto','하린이 받은 의견을 처리한 방법을 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X40','K6-1-u2-X01','K6-1-u2-X42']::text[],false,'{"seq":23,"concept":"K6-1-u2-C32","difficulty":4,"kind":"mc","stem":"하린이 받은 의견을 처리한 방법을 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"하려던 말에 도움이 되는 보미 · 서준의 의견은 받아들이고, 지호의 의견은 까닭을 들어 넣지 않아 알맞다","correct":true},{"t":"지호의 의견도 꼭 넣었어야 했다","mis":"K6-1-u2-X40"},{"t":"도윤이 말대로 처음부터 다시 썼어야 했다","mis":"K6-1-u2-X01"},{"t":"검사기가 고친 대로 받아들였으니 알맞다","mis":"K6-1-u2-X42"}],"explanation":["의견을 모두 따를 필요는 없어요.","다시 쓰지 않아요.","하린은 까닭을 확인했어요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb),
('g6_1_kor_u2_review_b#24','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C5',4,'essay','teacher','하린의 글에 달린 도윤이와 채아의 댓글이 왜 알맞지 않은지 쓰고, 두 사람의 댓글을 알맞게 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u2-C5","difficulty":4,"kind":"essay","stem":"하린의 글에 달린 도윤이와 채아의 댓글이 왜 알맞지 않은지 쓰고, 두 사람의 댓글을 알맞게 고쳐 쓰세요.","answer_guide":{"answer":"예: 도윤이는 고칠 곳만 말하고 다시 쓰라고 해서 하린이가 위축될 수 있다. 채아는 「고칠 곳 하나도 없어」라고 막연하게 칭찬해서 하린이에게 쓸모 있는 말이 되지 못한다. 고친 도윤이 댓글 — 「할머니 대사를 그대로 넣어서 장면이 생생했어. 「할머니가 말했다」는 「할머니께서 말씀하셨다」로 고치면 더 좋겠어. 할머니는 웃어른이니까.」 고친 채아 댓글 — 「마지막 다짐이 마음에 남았어. 다만 놀이터 문장은 연극과 멀어 보여서 빼면 좋겠어.」","scoring_points":["도윤이 댓글의 문제를 썼는가","채아 댓글의 문제를 썼는가","잘한 곳 → 고칠 곳 → 까닭 차례로 고쳐 썼는가"]},"explanation":["두 댓글의 문제를 찾아요.","왜 알맞지 않은지 써요.","잘한 곳 · 고칠 곳 · 까닭으로 고쳐요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"틀린 데가 너무 많아. 처음부터 다시 써."},{"who":"채아","text":"잘 썼네. 고칠 곳 하나도 없어."},{"who":"서준","text":"할머니가 서두르지 않는 장면이 눈에 그려졌어. 놀이터 문장은 연극 이야기와 멀어 보여서 빼면 좋겠어."},{"who":"보미","text":"연극을 보게 된 이야기가 맨 끝에 있어서 조금 헷갈렸어. 맨 앞으로 옮기면 어때?"}]}}'::jsonb),
('g6_1_kor_u2_review_b#25','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C16',4,'essay','teacher','띄어쓰기를 「글씨 문제가 아니라 뜻 문제」라고 하는 까닭을 예를 들어 설명하고, 띄어쓰기 원리 두 가지를 예와 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u2-C16","difficulty":4,"kind":"essay","stem":"띄어쓰기를 「글씨 문제가 아니라 뜻 문제」라고 하는 까닭을 예를 들어 설명하고, 띄어쓰기 원리 두 가지를 예와 함께 쓰세요.","answer_guide":{"answer":"예: 「큰집에 다녀왔다」와 「큰 집에 다녀왔다」는 띄어쓰기 하나로 친척 어른 댁과 크기가 큰 집으로 뜻이 갈린다. 읽는 사람은 글쓴이의 마음을 볼 수 없어서 띄어쓰기로 뜻을 알아내므로 띄어쓰기는 뜻 문제이다. 원리 첫째, 세는 말은 앞의 수와 띄어 써서 「나무 두 그루」처럼 쓴다. 둘째, 잇는 말은 앞뒤를 띄어 써서 「학생 및 학부모」처럼 쓴다.","scoring_points":["뜻이 갈리는 예를 들었는가","뜻 문제인 까닭을 썼는가","띄어쓰기 원리 두 가지를 예와 함께 썼는가"]},"explanation":["뜻이 갈리는 예를 들어요.","읽는 사람의 처지에서 써요.","원리를 예와 함께 써요."]}'::jsonb),
('g6_1_kor_u2_review_c#1','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C2',1,'mc','auto','글에 부족한 내용이 있을 때 하는 손질은 어느 것인가요?',ARRAY['K6-1-u2-X03','K6-1-u2-X01']::text[],false,'{"seq":1,"concept":"K6-1-u2-C2","difficulty":1,"kind":"mc","stem":"글에 부족한 내용이 있을 때 하는 손질은 어느 것인가요?","options":[{"t":"더하기","correct":true},{"t":"빼기","mis":"K6-1-u2-X03"},{"t":"옮기기","mis":"K6-1-u2-X03"},{"t":"지우고 다시 쓰기","mis":"K6-1-u2-X01"}],"explanation":["벗어난 것은 빼요.","뒤엉킨 것은 옮겨요.","모자란 것은 더해요."]}'::jsonb),
('g6_1_kor_u2_review_c#2','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C3',1,'mc','auto','「상관없는 뒷받침 문장은 없는가」는 어느 수준에서 살필 일인가요?',ARRAY['K6-1-u2-X04','K6-1-u2-X05']::text[],false,'{"seq":2,"concept":"K6-1-u2-C3","difficulty":1,"kind":"mc","stem":"「상관없는 뒷받침 문장은 없는가」는 어느 수준에서 살필 일인가요?","options":[{"t":"문단 수준","correct":true},{"t":"글 수준","mis":"K6-1-u2-X04"},{"t":"문장 수준","mis":"K6-1-u2-X04"},{"t":"맞춤법 수준","mis":"K6-1-u2-X05"}],"explanation":["뒷받침 문장은 문단 안에 있어요.","중심 문장과 견주어 봐요.","문단 수준의 일이에요."]}'::jsonb),
('g6_1_kor_u2_review_c#3','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C19',1,'mc','auto','「할수있다」를 바르게 띄어 쓴 것은 어느 것인가요?',ARRAY['K6-1-u2-X28','K6-1-u2-X24']::text[],false,'{"seq":3,"concept":"K6-1-u2-C19","difficulty":1,"kind":"mc","stem":"「할수있다」를 바르게 띄어 쓴 것은 어느 것인가요?","options":[{"t":"할 수 있다","correct":true},{"t":"할수있다","mis":"K6-1-u2-X28"},{"t":"할수 있다","mis":"K6-1-u2-X28"},{"t":"할 수있다","mis":"K6-1-u2-X24"}],"explanation":["「수」는 홀로 못 쓰는 이름씨예요.","앞말과 띄어 써요.","「있다」도 띄어 써요."]}'::jsonb),
('g6_1_kor_u2_review_c#4','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C22',1,'ox','auto','감상문에는 인상 깊은 장면과 함께 그 장면이 왜 남았는지도 써요.',ARRAY['K6-1-u2-X31']::text[],false,'{"seq":4,"concept":"K6-1-u2-C22","difficulty":1,"kind":"ox","stem":"감상문에는 인상 깊은 장면과 함께 그 장면이 왜 남았는지도 써요.","answer":"O","reason_options":[{"t":"까닭까지 써야 내가 느끼고 생각한 것이 드러나기 때문에","correct":true},{"t":"장면만 고르면 까닭은 읽는 사람이 알아서 짐작하기 때문에","mis":"K6-1-u2-X31"}],"mis":"K6-1-u2-X31","explanation":["「좋았다」로 끝내지 않아요.","왜 남았는지 써요.","그래야 감상문이 돼요."]}'::jsonb),
('g6_1_kor_u2_review_c#5','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C25',1,'mc','auto','한 문장이 너무 길 때 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X34','K6-1-u2-X35']::text[],false,'{"seq":5,"concept":"K6-1-u2-C25","difficulty":1,"kind":"mc","stem":"한 문장이 너무 길 때 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 가지씩 담기도록 여러 문장으로 나눈다","correct":true},{"t":"문장을 더 이어 붙인다","mis":"K6-1-u2-X33"},{"t":"주어와 서술어를 뺀다","mis":"K6-1-u2-X34"},{"t":"같은 낱말을 더 넣는다","mis":"K6-1-u2-X35"}],"explanation":["이어 붙이면 더 길어져요.","성분을 빼면 뜻이 흐려져요.","한 문장에 한 가지씩 나눠요."]}'::jsonb),
('g6_1_kor_u2_review_c#6','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C31',1,'mc','auto','「숫자에 뜻이 있는 줄 몰랐어.」는 의견의 네 갈래 가운데 무엇인가요?',ARRAY['K6-1-u2-X39']::text[],false,'{"seq":6,"concept":"K6-1-u2-C31","difficulty":1,"kind":"mc","stem":"「숫자에 뜻이 있는 줄 몰랐어.」는 의견의 네 갈래 가운데 무엇인가요?","options":[{"t":"새롭게 안 점","correct":true},{"t":"궁금한 점","mis":"K6-1-u2-X39"},{"t":"좋은 점","mis":"K6-1-u2-X39"},{"t":"고쳤으면 하는 점","mis":"K6-1-u2-X39"}],"explanation":["몰랐던 것이에요.","이제 알게 되었어요.","새롭게 안 점이에요."]}'::jsonb),
('g6_1_kor_u2_review_c#7','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C38',1,'mc','auto','「내일」과 어울리는 서술어는 어느 것인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X18']::text[],false,'{"seq":7,"concept":"K6-1-u2-C38","difficulty":1,"kind":"mc","stem":"「내일」과 어울리는 서술어는 어느 것인가요?","options":[{"t":"갈 것이다","correct":true},{"t":"갔다","mis":"K6-1-u2-X20"},{"t":"간다","mis":"K6-1-u2-X20"},{"t":"가셨다","mis":"K6-1-u2-X18"}],"explanation":["내일은 아직 오지 않은 때예요.","앞으로의 일에는 「~ㄹ 것이다」를 써요.","「내일 갈 것이다」로 써요."]}'::jsonb),
('g6_1_kor_u2_review_c#8','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C33',1,'ox','auto','글을 게시판에 올린 뒤에는 제대로 올라갔는지 다시 들어가 확인해요.',ARRAY['K6-1-u2-X41']::text[],false,'{"seq":8,"concept":"K6-1-u2-C33","difficulty":1,"kind":"ox","stem":"글을 게시판에 올린 뒤에는 제대로 올라갔는지 다시 들어가 확인해요.","answer":"O","reason_options":[{"t":"올린 뒤 확인하고 댓글을 읽으며 다시 점검하는 것까지가 공유하기이기 때문에","correct":true},{"t":"한 번 올리면 다시 볼 필요가 없기 때문에","mis":"K6-1-u2-X41"}],"mis":"K6-1-u2-X41","explanation":["올리고 끝내지 않아요.","확인하고 댓글을 읽어요.","다시 점검해요."]}'::jsonb),
('g6_1_kor_u2_review_c#9','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C15',2,'ox','auto','하린의 초고에서 놀이터 문장은 연극 이야기와 상관없어서 빼는 것이 알맞아요.',ARRAY['K6-1-u2-X15']::text[],false,'{"seq":9,"concept":"K6-1-u2-C15","difficulty":2,"kind":"ox","stem":"하린의 초고에서 놀이터 문장은 연극 이야기와 상관없어서 빼는 것이 알맞아요.","answer":"O","reason_options":[{"t":"감상문의 중심인 연극 「종이배」와 이어지지 않는 문장이기 때문에","correct":true},{"t":"놀이터 이야기는 재미가 없기 때문에","mis":"K6-1-u2-X15"}],"mis":"K6-1-u2-X15","explanation":["중심과 견주어 봐요.","놀이터는 연극과 상관없어요.","벗어난 문장은 빼요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb),
('g6_1_kor_u2_review_c#10','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C14',2,'match','auto','하린의 초고 문장과 어긋난 갈래를 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C14","difficulty":2,"kind":"match","stem":"하린의 초고 문장과 어긋난 갈래를 이으세요.","pairs":[{"l":"할머니가 말했다","r":"높임"},{"l":"전혀 지루했다","r":"부정"},{"l":"배 두척","r":"띄어쓰기"}],"mis":"K6-1-u2-X04","explanation":["웃어른에게는 높임을 써요.","전혀 뒤에는 부정이 와요.","세는 말은 띄어요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb),
('g6_1_kor_u2_review_c#11','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C20',2,'mc','auto','하린의 초고에서 띄어 쓸 곳을 부호로 바르게 표시한 것은 어느 것인가요?',ARRAY['K6-1-u2-X23','K6-1-u2-X29']::text[],false,'{"seq":11,"concept":"K6-1-u2-C20","difficulty":2,"kind":"mc","stem":"하린의 초고에서 띄어 쓸 곳을 부호로 바르게 표시한 것은 어느 것인가요?","options":[{"t":"두∨척 · 및∨학생 · 줄∨수","correct":true},{"t":"두⌒척 · 및⌒학생 · 줄⌒수","mis":"K6-1-u2-X23"},{"t":"두⊂척 · 및⊂학생 · 줄⊂수","mis":"K6-1-u2-X23"},{"t":"부호 없이 글을 처음부터 다시 쓴다","mis":"K6-1-u2-X29"}],"explanation":["⌒ 는 붙일 때 써요.","⊂ 는 내용을 더 넣을 때 써요.","띄울 곳에는 ∨ 를 표시해요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb),
('g6_1_kor_u2_review_c#12','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C5',2,'ox','auto','도윤이의 댓글은 하린이가 다시 고쳐 쓰고 싶어지게 하는 좋은 댓글이에요.',ARRAY['K6-1-u2-X06']::text[],false,'{"seq":12,"concept":"K6-1-u2-C5","difficulty":2,"kind":"ox","stem":"도윤이의 댓글은 하린이가 다시 고쳐 쓰고 싶어지게 하는 좋은 댓글이에요.","answer":"X","reason_options":[{"t":"고칠 곳만 말하고 다시 쓰라고 해 글쓴이를 위축시키기 때문에","correct":true},{"t":"틀린 곳을 많이 말해 줄수록 좋은 댓글이기 때문에","mis":"K6-1-u2-X06"}],"mis":"K6-1-u2-X06","explanation":["잘한 곳이 하나도 없어요.","까닭도 없어요.","글쓴이가 쓰기 싫어질 수 있어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"틀린 데가 너무 많아. 처음부터 다시 써."},{"who":"채아","text":"잘 썼네. 고칠 곳 하나도 없어."},{"who":"서준","text":"할머니가 서두르지 않는 장면이 눈에 그려졌어. 놀이터 문장은 연극 이야기와 멀어 보여서 빼면 좋겠어."},{"who":"보미","text":"연극을 보게 된 이야기가 맨 끝에 있어서 조금 헷갈렸어. 맨 앞으로 옮기면 어때?"}]}}'::jsonb),
('g6_1_kor_u2_review_c#13','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C32',2,'ox','auto','하린은 보미와 서준의 의견은 받아들이고 지호의 의견은 받아들이지 않았어요.',ARRAY['K6-1-u2-X40']::text[],false,'{"seq":13,"concept":"K6-1-u2-C32","difficulty":2,"kind":"ox","stem":"하린은 보미와 서준의 의견은 받아들이고 지호의 의견은 받아들이지 않았어요.","answer":"O","reason_options":[{"t":"하려던 말이 더 잘 전해지는 의견만 골라 받아들였기 때문에","correct":true},{"t":"친구 의견은 모두 따라야 하기 때문에","mis":"K6-1-u2-X40"}],"mis":"K6-1-u2-X40","explanation":["보미 — 차례 옮기기를 받아들였어요.","서준 — 놀이터 문장 빼기를 받아들였어요.","지호의 의견은 까닭을 들어 넣지 않았어요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb),
('g6_1_kor_u2_review_c#14','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C28',2,'mc','auto','「상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.」의 문제로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X33','K6-1-u2-X05']::text[],false,'{"seq":14,"concept":"K6-1-u2-C28","difficulty":2,"kind":"mc","stem":"「상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.」의 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"누가 언제 한 말인지 알 수 없어 확인되지 않은 자료이다","correct":true},{"t":"상추는 텃밭과 상관없다","mis":"K6-1-u2-X15"},{"t":"문장이 너무 짧다","mis":"K6-1-u2-X33"},{"t":"띄어쓰기가 틀렸다","mis":"K6-1-u2-X05"}],"explanation":["상추는 텃밭과 관련 있어요.","「누가 그랬다」는 확인할 수 없어요.","믿을 수 있는 자료로 바꾸고 출처를 밝혀요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb),
('g6_1_kor_u2_review_c#15','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C29',2,'match','auto','설명하는 글 「텃밭 물 주기」의 내용이 들어갈 곳을 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-1-u2-C29","difficulty":2,"kind":"match","stem":"설명하는 글 「텃밭 물 주기」의 내용이 들어갈 곳을 이으세요.","pairs":[{"l":"텃밭에 물 주는 순서가 왜 있는지 궁금하지 않나요?","r":"처음"},{"l":"반마다 요일을 나누어 아침에 물을 줍니다","r":"가운데"},{"l":"순서를 지키면 채소도 우리도 편해집니다","r":"끝"}],"mis":"K6-1-u2-X12","explanation":["관심을 끄는 말은 처음이에요.","자세한 설명은 가운데예요.","간추려 맺는 말은 끝이에요."]}'::jsonb),
('g6_1_kor_u2_review_c#16','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C6',2,'ox','auto','온라인에 한 번 올린 글은 널리 퍼질 수 있으므로 읽는 사람을 떠올리며 써야 해요.',ARRAY['K6-1-u2-X09']::text[],false,'{"seq":16,"concept":"K6-1-u2-C6","difficulty":2,"kind":"ox","stem":"온라인에 한 번 올린 글은 널리 퍼질 수 있으므로 읽는 사람을 떠올리며 써야 해요.","answer":"O","reason_options":[{"t":"여러 사람이 읽고 퍼질 수 있어 읽는 사람이 누구인지가 고칠 때의 기준이 되기 때문에","correct":true},{"t":"올린 글은 금방 사라지기 때문에","mis":"K6-1-u2-X09"}],"mis":"K6-1-u2-X09","explanation":["올린 글은 널리 퍼져요.","읽는 사람을 떠올려요.","그것이 고쳐쓰기의 기준이 돼요."]}'::jsonb),
('g6_1_kor_u2_review_c#17','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C22',3,'ox','auto','하린은 할머니가 서두르지 않는 장면을 고르고 그 까닭을 「나도 기다려 줄 수 있는 사람이 되겠다」로 이어 썼어요.',ARRAY['K6-1-u2-X31']::text[],false,'{"seq":17,"concept":"K6-1-u2-C22","difficulty":3,"kind":"ox","stem":"하린은 할머니가 서두르지 않는 장면을 고르고 그 까닭을 「나도 기다려 줄 수 있는 사람이 되겠다」로 이어 썼어요.","answer":"O","reason_options":[{"t":"인상 깊은 장면과 그 장면에서 얻은 생각을 이어 썼기 때문에","correct":true},{"t":"장면만 쓰면 감상문이 되기 때문에","mis":"K6-1-u2-X31"}],"mis":"K6-1-u2-X31","explanation":["장면을 골랐어요.","그 장면에서 생각한 것을 썼어요.","장면과 까닭이 이어져요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb),
('g6_1_kor_u2_review_c#18','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C2',3,'mc','auto','하린의 초고에 해야 할 손질을 바르게 짝 지은 것은 어느 것인가요?',ARRAY['K6-1-u2-X03','K6-1-u2-X01','K6-1-u2-X05']::text[],false,'{"seq":18,"concept":"K6-1-u2-C2","difficulty":3,"kind":"mc","stem":"하린의 초고에 해야 할 손질을 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"놀이터 문장 — 빼기 · 연극을 본 이야기 — 옮기기 · 「전혀 지루했다」 — 바꾸기","correct":true},{"t":"놀이터 문장 — 옮기기 · 연극을 본 이야기 — 빼기 · 「전혀 지루했다」 — 더하기","mis":"K6-1-u2-X03"},{"t":"모든 문장 — 지우고 다시 쓰기","mis":"K6-1-u2-X01"},{"t":"놀이터 문장 — 그대로 · 연극을 본 이야기 — 그대로 · 띄어쓰기만 바꾸기","mis":"K6-1-u2-X05"}],"explanation":["벗어난 것은 빼요.","뒤엉킨 것은 옮겨요.","어색한 표현은 바꿔요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb),
('g6_1_kor_u2_review_c#19','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C10',3,'ox','auto','하린의 감상문 중심 내용을 「서두르지 않는 마음」으로도, 「가르쳐 주는 사람의 기다림」으로도 볼 수 있어요.',ARRAY['K6-1-u2-X13']::text[],false,'{"seq":19,"concept":"K6-1-u2-C10","difficulty":3,"kind":"ox","stem":"하린의 감상문 중심 내용을 「서두르지 않는 마음」으로도, 「가르쳐 주는 사람의 기다림」으로도 볼 수 있어요.","answer":"O","reason_options":[{"t":"두 가지 모두 할머니 장면과 하린의 다짐에서 근거를 댈 수 있기 때문에","correct":true},{"t":"중심 내용은 아무렇게나 정해도 되기 때문에","mis":"K6-1-u2-X13"}],"mis":"K6-1-u2-X13","explanation":["할머니는 서두르지 않았어요.","하린은 기다려 주겠다고 했어요.","근거가 있으면 둘 다 좋은 답이에요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb),
('g6_1_kor_u2_review_c#20','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C28',3,'mc','auto','「누가 그랬다」를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X37','K6-1-u2-X38']::text[],false,'{"seq":20,"concept":"K6-1-u2-C28","difficulty":3,"kind":"mc","stem":"「누가 그랬다」를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학교 텃밭 담당 선생님이나 믿을 수 있는 책에서 확인하고 출처를 밝혀 쓴다","correct":true},{"t":"그대로 둔다","mis":"K6-1-u2-X37"},{"t":"「인터넷에서 봤다」로만 바꾼다","mis":"K6-1-u2-X37"},{"t":"그 문장을 다른 글에서 그대로 베껴 온다","mis":"K6-1-u2-X38"}],"explanation":["확인되지 않은 말은 쓰지 않아요.","「인터넷」만으로는 누가 언제 썼는지 몰라요.","확인하고 출처를 밝혀요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb),
('g6_1_kor_u2_review_c#21','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C38',3,'error','auto','문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X46']::text[],false,'{"seq":21,"concept":"K6-1-u2-C38","difficulty":3,"kind":"error","stem":"문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?","options":[{"t":"하율 — 「내일 우리 반은 텃밭에 물을 주었다.」","correct":true,"mis_target":"K6-1-u2-X20"},{"t":"서진 — 「어제 우리 반은 텃밭에 물을 주었다.」","mis":"K6-1-u2-X46"},{"t":"라온 — 「텃밭이 물로 채워졌다.」","mis":"K6-1-u2-X46"}],"explanation":["서진은 어제와 「주었다」를 맞췄어요.","라온은 당하는 말로 받았어요.","하율은 내일과 「주었다」가 어긋나요."]}'::jsonb),
('g6_1_kor_u2_review_c#22','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C16',3,'ox','auto','「아버지가방에들어가신다」는 띄어쓰기에 따라 뜻이 달라질 수 있어요.',ARRAY['K6-1-u2-X24']::text[],false,'{"seq":22,"concept":"K6-1-u2-C16","difficulty":3,"kind":"ox","stem":"「아버지가방에들어가신다」는 띄어쓰기에 따라 뜻이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"「아버지가 방에」와 「아버지 가방에」처럼 어디서 띄느냐에 따라 뜻이 갈리기 때문에","correct":true},{"t":"붙여 써도 뜻은 하나뿐이기 때문에","mis":"K6-1-u2-X24"}],"mis":"K6-1-u2-X24","explanation":["「가방」으로 읽을 수도 있어요.","「가 ∨ 방」으로 읽을 수도 있어요.","띄어쓰기가 뜻을 갈라요."]}'::jsonb),
('g6_1_kor_u2_review_c#23','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C29',4,'mc','auto','로운의 글을 가장 알맞게 고친 계획은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X37','K6-1-u2-X38']::text[],false,'{"seq":23,"concept":"K6-1-u2-C29","difficulty":4,"kind":"mc","stem":"로운의 글을 가장 알맞게 고친 계획은 어느 것인가요?","options":[{"t":"첫 문장을 나누고 · 「물을」을 넣고 · 확인되지 않은 상추 문장은 확인 뒤 출처를 밝히고 · 창고 문장은 뺀다","correct":true},{"t":"첫 문장을 더 길게 이어 붙인다","mis":"K6-1-u2-X33"},{"t":"창고 문장은 두고 상추 문장은 그대로 쓴다","mis":"K6-1-u2-X37"},{"t":"찾은 자료를 그대로 붙여 넣어 글을 늘린다","mis":"K6-1-u2-X38"}],"explanation":["길게 이으면 더 안 읽혀요.","확인되지 않은 자료는 쓰지 않아요.","나누고 · 채우고 · 확인하고 · 빼요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb),
('g6_1_kor_u2_review_c#24','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C25',4,'essay','teacher','로운의 설명하는 글 초고를 명확한 문장의 조건과 자료 확인을 생각하며 고쳐 쓰고, 무엇을 고쳤는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u2-C25","difficulty":4,"kind":"essay","stem":"로운의 설명하는 글 초고를 명확한 문장의 조건과 자료 확인을 생각하며 고쳐 쓰고, 무엇을 고쳤는지 쓰세요.","answer_guide":{"answer":"예: 우리 학교 텃밭에는 물 주는 순서가 있습니다. 이 순서는 반마다 정해 둔 것입니다. 순서를 지키면 같은 곳에 물을 두 번 주는 일이 없어 채소가 잘 자랍니다. 당번은 아침마다 텃밭에 물을 줍니다. 상추는 물을 너무 많이 주면 뿌리가 상할 수 있어 조심해야 한다고 텃밭 담당 선생님께서 알려 주셨습니다. — 긴 첫 문장을 나누고, 되풀이되던 「순서」를 줄이고, 빠진 「물을」을 넣고, 「누가 그랬다」를 확인한 출처로 바꾸고, 창고 문장을 뺐다.","scoring_points":["긴 문장을 나누고 겹치는 표현을 줄였는가","빠진 성분을 채웠는가","확인되지 않은 자료와 상관없는 문장을 고쳤는가"]},"explanation":["한 문장에 한 가지씩 나눠요.","빠진 성분을 채워요.","자료를 확인하고 벗어난 문장을 빼요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb),
('g6_1_kor_u2_review_c#25','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C38',4,'essay','teacher','「어제」 · 「내 생각은」 · 「화면이」로 시작하는 문장을 하나씩 호응이 맞게 쓰고, 각 문장에서 서술어를 어떻게 맞추었는지 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u2-C38","difficulty":4,"kind":"essay","stem":"「어제」 · 「내 생각은」 · 「화면이」로 시작하는 문장을 하나씩 호응이 맞게 쓰고, 각 문장에서 서술어를 어떻게 맞추었는지 설명하세요.","answer_guide":{"answer":"예: 어제 나는 도서관에서 책을 빌렸다. — 어제는 지난 때라 서술어를 「빌렸다」로 맞추었다. 내 생각은 작은 고침도 소중하다는 것이다. — 주어가 「내 생각은」이라 「~것이다」로 받았다. 화면이 밝은 빛으로 채워졌다. — 화면이 스스로 한 일이 아니어서 「채워졌다」로 받았다.","scoring_points":["세 문장을 호응이 맞게 썼는가","시간 표현에 맞춘 까닭을 썼는가","주어에 맞춘 까닭(~것이다 · ~되다)을 썼는가"]},"explanation":["시간 말에 서술어를 맞춰요.","「내 생각은」은 「~것이다」로 받아요.","스스로 한 일이 아니면 「~되다 · ~히다」로 받아요."]}'::jsonb),
('g6_1_kor_u2_review_d#1','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C2',1,'mc','auto','어색한 표현을 알맞은 말로 고치는 손질은 어느 것인가요?',ARRAY['K6-1-u2-X03']::text[],false,'{"seq":1,"concept":"K6-1-u2-C2","difficulty":1,"kind":"mc","stem":"어색한 표현을 알맞은 말로 고치는 손질은 어느 것인가요?","options":[{"t":"바꾸기","correct":true},{"t":"빼기","mis":"K6-1-u2-X03"},{"t":"더하기","mis":"K6-1-u2-X03"},{"t":"옮기기","mis":"K6-1-u2-X03"}],"explanation":["빼기는 벗어난 내용을 지우는 일이에요.","더하기는 모자란 내용을 넣는 일이에요.","어색한 표현은 바꿔요."]}'::jsonb),
('g6_1_kor_u2_review_d#2','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C3',1,'ox','auto','고쳐 쓸 때에는 글 → 문단 → 문장의 차례로 큰 것부터 살펴요.',ARRAY['K6-1-u2-X05']::text[],false,'{"seq":2,"concept":"K6-1-u2-C3","difficulty":1,"kind":"ox","stem":"고쳐 쓸 때에는 글 → 문단 → 문장의 차례로 큰 것부터 살펴요.","answer":"O","reason_options":[{"t":"큰 것부터 봐야 다듬은 문장이 통째로 빠지는 헛수고가 줄기 때문에","correct":true},{"t":"작은 것은 고칠 필요가 없기 때문에","mis":"K6-1-u2-X05"}],"mis":"K6-1-u2-X05","explanation":["큰 것부터 봐요.","작은 것도 나중에 고쳐요.","헛수고가 줄어들어요."]}'::jsonb),
('g6_1_kor_u2_review_d#3','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C19',1,'mc','auto','조사를 바르게 붙여 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u2-X27','K6-1-u2-X24']::text[],false,'{"seq":3,"concept":"K6-1-u2-C19","difficulty":1,"kind":"mc","stem":"조사를 바르게 붙여 쓴 문장은 어느 것인가요?","options":[{"t":"친구에게 편지를 썼다","correct":true},{"t":"친구 에게 편지를 썼다","mis":"K6-1-u2-X27"},{"t":"친구에게 편지 를 썼다","mis":"K6-1-u2-X27"},{"t":"친구에게편지를썼다","mis":"K6-1-u2-X24"}],"explanation":["「에게」 · 「를」은 조사예요.","조사는 앞말에 붙여요.","낱말과 낱말 사이는 띄어요."]}'::jsonb),
('g6_1_kor_u2_review_d#4','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C23',1,'ox','auto','감상문에는 처음부터 끝까지의 모든 장면을 빠짐없이 적어요.',ARRAY['K6-1-u2-X32']::text[],false,'{"seq":4,"concept":"K6-1-u2-C23","difficulty":1,"kind":"ox","stem":"감상문에는 처음부터 끝까지의 모든 장면을 빠짐없이 적어요.","answer":"X","reason_options":[{"t":"줄거리는 짧게 쓰고 인상 깊은 장면과 생각을 자세히 쓰기 때문에","correct":true},{"t":"모든 장면을 써야 읽는 사람이 이해하기 때문에","mis":"K6-1-u2-X32"}],"mis":"K6-1-u2-X32","explanation":["모든 장면을 쓰면 줄거리 요약이 돼요.","줄거리는 간단히 써요.","장면과 생각을 길게 써요."]}'::jsonb),
('g6_1_kor_u2_review_d#5','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C25',1,'ox','auto','같은 낱말을 여러 번 되풀이하면 뜻이 더 또렷해져요.',ARRAY['K6-1-u2-X35']::text[],false,'{"seq":5,"concept":"K6-1-u2-C25","difficulty":1,"kind":"ox","stem":"같은 낱말을 여러 번 되풀이하면 뜻이 더 또렷해져요.","answer":"X","reason_options":[{"t":"겹치는 표현은 하나로 줄여야 읽기 쉽고 뜻이 또렷해지기 때문에","correct":true},{"t":"되풀이할수록 중요하다는 뜻이 되기 때문에","mis":"K6-1-u2-X35"}],"mis":"K6-1-u2-X35","explanation":["다빈은 「번호」를 되풀이했어요.","고친 글에서는 숫자 · 표시로 갈랐어요.","겹치는 표현은 줄여요."]}'::jsonb),
('g6_1_kor_u2_review_d#6','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C28',1,'ox','auto','누가 언제 썼는지 알 수 없는 글도 설명하는 글의 자료로 그대로 써도 돼요.',ARRAY['K6-1-u2-X37']::text[],false,'{"seq":6,"concept":"K6-1-u2-C28","difficulty":1,"kind":"ox","stem":"누가 언제 썼는지 알 수 없는 글도 설명하는 글의 자료로 그대로 써도 돼요.","answer":"X","reason_options":[{"t":"믿을 수 있는지, 지금도 맞는지 확인할 수 없기 때문에","correct":true},{"t":"인터넷에 있는 글은 모두 맞기 때문에","mis":"K6-1-u2-X37"}],"mis":"K6-1-u2-X37","explanation":["누가 만들었는지 확인해요.","언제 만들었는지 확인해요.","확인하지 않은 자료는 쓰지 않아요."]}'::jsonb),
('g6_1_kor_u2_review_d#7','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C38',1,'ox','auto','「지난주」와 「본다」는 서로 잘 어울려요.',ARRAY['K6-1-u2-X20']::text[],false,'{"seq":7,"concept":"K6-1-u2-C38","difficulty":1,"kind":"ox","stem":"「지난주」와 「본다」는 서로 잘 어울려요.","answer":"X","reason_options":[{"t":"지난주는 지난 때라 「보았다」로 받아야 하기 때문에","correct":true},{"t":"시간을 나타내는 말은 서술어와 상관없기 때문에","mis":"K6-1-u2-X20"}],"mis":"K6-1-u2-X20","explanation":["시간 말이 서술어를 끌고 가요.","지난주는 지난 때예요.","「지난주에 보았다」로 써요."]}'::jsonb),
('g6_1_kor_u2_review_d#8','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C7',1,'ox','auto','고쳐쓰기를 할 때 한 군데만 고쳐도 글은 그만큼 나아져요.',ARRAY['K6-1-u2-X02']::text[],false,'{"seq":8,"concept":"K6-1-u2-C7","difficulty":1,"kind":"ox","stem":"고쳐쓰기를 할 때 한 군데만 고쳐도 글은 그만큼 나아져요.","answer":"O","reason_options":[{"t":"고쳐쓰기는 완벽한 글을 만드는 일이 아니라 필요한 곳을 손보는 일이기 때문에","correct":true},{"t":"한 군데만 고치면 고친 것이 아니기 때문에","mis":"K6-1-u2-X02"}],"mis":"K6-1-u2-X02","explanation":["완벽할 필요가 없어요.","작게 고친 것도 잘 고친 것이에요.","고친 만큼 나아져요."]}'::jsonb),
('g6_1_kor_u2_review_d#9','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C9',2,'mc','auto','하린의 초고에서 맨 끝 문장 「지난 토요일 학교 강당에서 ~ 이 연극을 보았다.」는 어디로 옮기는 것이 알맞은가요?',ARRAY['K6-1-u2-X12','K6-1-u2-X03','K6-1-u2-X16']::text[],false,'{"seq":9,"concept":"K6-1-u2-C9","difficulty":2,"kind":"mc","stem":"하린의 초고에서 맨 끝 문장 「지난 토요일 학교 강당에서 ~ 이 연극을 보았다.」는 어디로 옮기는 것이 알맞은가요?","options":[{"t":"글의 맨 앞(처음)","correct":true},{"t":"그대로 맨 끝","mis":"K6-1-u2-X12"},{"t":"놀이터 문장 바로 뒤","mis":"K6-1-u2-X03"},{"t":"빼 버린다","mis":"K6-1-u2-X16"}],"explanation":["언제 어디서 보았는지는 보게 된 이야기예요.","처음에 와야 해요.","내용은 그대로 두고 차례만 옮겨요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb),
('g6_1_kor_u2_review_d#10','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C13',2,'ox','auto','「할머니가 말했다」는 뜻이 통하니까 고칠 필요가 없어요.',ARRAY['K6-1-u2-X17']::text[],false,'{"seq":10,"concept":"K6-1-u2-C13","difficulty":2,"kind":"ox","stem":"「할머니가 말했다」는 뜻이 통하니까 고칠 필요가 없어요.","answer":"X","reason_options":[{"t":"뜻이 통해도 높임 호응이 어긋나면 바른 문장이 아니기 때문에","correct":true},{"t":"할머니는 높일 필요가 없기 때문에","mis":"K6-1-u2-X17"}],"mis":"K6-1-u2-X17","explanation":["내용과 형식을 함께 봐요.","웃어른에게는 높임이 어울려요.","「할머니께서 말씀하셨다」로 고쳐요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb),
('g6_1_kor_u2_review_d#11','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C17',2,'ox','auto','「배 두척」은 세는 말 「척」을 앞의 수와 띄어 「배 두 척」으로 써야 해요.',ARRAY['K6-1-u2-X25']::text[],false,'{"seq":11,"concept":"K6-1-u2-C17","difficulty":2,"kind":"ox","stem":"「배 두척」은 세는 말 「척」을 앞의 수와 띄어 「배 두 척」으로 써야 해요.","answer":"O","reason_options":[{"t":"척은 배를 세는 말이고 세는 말은 앞의 수와 띄어 쓰기 때문에","correct":true},{"t":"배와 두를 붙여 써야 하기 때문에","mis":"K6-1-u2-X25"}],"mis":"K6-1-u2-X25","explanation":["척은 배를 세는 말이에요.","수와 세는 말은 띄어요.","「배 두 척」으로 써요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb),
('g6_1_kor_u2_review_d#12','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C7',2,'mc','auto','채아의 댓글 「잘 썼네. 고칠 곳 하나도 없어.」를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X07','K6-1-u2-X06','K6-1-u2-X08']::text[],false,'{"seq":12,"concept":"K6-1-u2-C7","difficulty":2,"kind":"mc","stem":"채아의 댓글 「잘 썼네. 고칠 곳 하나도 없어.」를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「할머니 장면이 자세해서 좋았어. 「전혀 지루했다」는 「지루하지 않았다」로 고치면 좋겠어.」","correct":true},{"t":"「정말 정말 잘 썼어.」","mis":"K6-1-u2-X07"},{"t":"「틀린 데 많아.」","mis":"K6-1-u2-X06"},{"t":"「전혀 지루했다 고쳐.」","mis":"K6-1-u2-X08"}],"explanation":["막연한 칭찬은 쓸모가 적어요.","고칠 곳만 말하면 위축돼요.","어디가 왜 좋은지, 무엇을 고칠지 말해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"틀린 데가 너무 많아. 처음부터 다시 써."},{"who":"채아","text":"잘 썼네. 고칠 곳 하나도 없어."},{"who":"서준","text":"할머니가 서두르지 않는 장면이 눈에 그려졌어. 놀이터 문장은 연극 이야기와 멀어 보여서 빼면 좋겠어."},{"who":"보미","text":"연극을 보게 된 이야기가 맨 끝에 있어서 조금 헷갈렸어. 맨 앞으로 옮기면 어때?"}]}}'::jsonb),
('g6_1_kor_u2_review_d#13','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C34',2,'ox','auto','맞춤법 검사기를 쓰면 내가 자주 틀리는 곳을 알 수 있어요.',ARRAY['K6-1-u2-X42']::text[],false,'{"seq":13,"concept":"K6-1-u2-C34","difficulty":2,"kind":"ox","stem":"맞춤법 검사기를 쓰면 내가 자주 틀리는 곳을 알 수 있어요.","answer":"O","reason_options":[{"t":"검사기가 띄어쓰기와 맞춤법을 짚어 주어 내 버릇을 알게 해 주기 때문에","correct":true},{"t":"검사기가 글을 다 써 주기 때문에","mis":"K6-1-u2-X42"}],"mis":"K6-1-u2-X42","explanation":["검사기는 빠르게 짚어 줘요.","자주 틀리는 곳이 보여요.","고칠지 말지는 내가 정해요."]}'::jsonb),
('g6_1_kor_u2_review_d#14','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C15',2,'mc','auto','로운의 글에서 빼야 할 문장은 어느 것인가요?',ARRAY['K6-1-u2-X16','K6-1-u2-X15']::text[],false,'{"seq":14,"concept":"K6-1-u2-C15","difficulty":2,"kind":"mc","stem":"로운의 글에서 빼야 할 문장은 어느 것인가요?","options":[{"t":"텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다.","correct":true},{"t":"당번은 아침마다 텃밭에 줍니다.","mis":"K6-1-u2-X16"},{"t":"상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","mis":"K6-1-u2-X16"},{"t":"그래서 순서를 지켜야 한다.","mis":"K6-1-u2-X15"}],"explanation":["물 주기와 관련된 문장은 고쳐 써요.","창고 문 이야기는 상관없어요.","벗어난 문장은 빼요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb),
('g6_1_kor_u2_review_d#15','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C31',2,'match','auto','「텃밭 물 주기」를 읽은 친구들의 말과 의견의 갈래를 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-1-u2-C31","difficulty":2,"kind":"match","stem":"「텃밭 물 주기」를 읽은 친구들의 말과 의견의 갈래를 이으세요.","pairs":[{"l":"텃밭에 순서가 있는 줄 몰랐어","r":"새롭게 안 점"},{"l":"비 오는 날은 어떻게 하는지 궁금해","r":"궁금한 점"},{"l":"창고 문장은 빼면 좋겠어, 물 주기와 멀어서","r":"고쳤으면 하는 점"}],"mis":"K6-1-u2-X39","explanation":["몰랐던 것을 알게 됐어요.","더 알고 싶은 것이에요.","고칠 곳과 까닭이에요."]}'::jsonb),
('g6_1_kor_u2_review_d#16','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C30',2,'ox','auto','줄임말이나 은어는 친구들이 아는 말이니 설명하는 글에 써도 돼요.',ARRAY['K6-1-u2-X09']::text[],false,'{"seq":16,"concept":"K6-1-u2-C30","difficulty":2,"kind":"ox","stem":"줄임말이나 은어는 친구들이 아는 말이니 설명하는 글에 써도 돼요.","answer":"X","reason_options":[{"t":"읽는 사람이 아는 말로 풀어 써야 하고 줄임말 · 은어는 뜻이 흐려지기 때문에","correct":true},{"t":"줄임말이 더 짧아 좋기 때문에","mis":"K6-1-u2-X09"}],"mis":"K6-1-u2-X09","explanation":["모든 읽는 사람이 아는 말이 아니에요.","뜻이 흐려질 수 있어요.","읽는 사람이 아는 말로 풀어 써요."]}'::jsonb),
('g6_1_kor_u2_review_d#17','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C3',3,'mc','auto','하린의 초고에서 「연극을 본 이야기가 맨 끝에 있다」는 문제를 찾으려면 어떻게 읽어야 하나요?',ARRAY['K6-1-u2-X04','K6-1-u2-X05']::text[],false,'{"seq":17,"concept":"K6-1-u2-C3","difficulty":3,"kind":"mc","stem":"하린의 초고에서 「연극을 본 이야기가 맨 끝에 있다」는 문제를 찾으려면 어떻게 읽어야 하나요?","options":[{"t":"글 전체의 처음 · 가운데 · 끝 흐름을 살핀다","correct":true},{"t":"한 문장씩 서술어만 살핀다","mis":"K6-1-u2-X04"},{"t":"띄어쓰기만 살핀다","mis":"K6-1-u2-X05"},{"t":"낱말 뜻만 살핀다","mis":"K6-1-u2-X04"}],"explanation":["한 문장만 보면 차례가 안 보여요.","띄어쓰기와 상관없어요.","글 수준에서 흐름을 봐요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb),
('g6_1_kor_u2_review_d#18','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C7',3,'mc','auto','하린이 「고칠 곳이 이렇게 많으니 나는 글을 못 쓰나 봐.」라고 했어요. 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u2-X01','K6-1-u2-X02','K6-1-u2-X10']::text[],false,'{"seq":18,"concept":"K6-1-u2-C7","difficulty":3,"kind":"mc","stem":"하린이 「고칠 곳이 이렇게 많으니 나는 글을 못 쓰나 봐.」라고 했어요. 알맞은 말은 어느 것인가요?","options":[{"t":"「여기 몇 군데만 손보면 네가 하고 싶은 말이 더 잘 전해질 거야.」","correct":true},{"t":"「맞아, 처음부터 새로 써.」","mis":"K6-1-u2-X01"},{"t":"「완벽하게 못 고칠 거면 그만둬.」","mis":"K6-1-u2-X02"},{"t":"「고칠 곳이 많으면 올리지 마.」","mis":"K6-1-u2-X10"}],"explanation":["고쳐 쓰라는 말은 혼내는 말이 아니에요.","완벽할 필요가 없어요.","필요한 곳만 손보면 나아져요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb),
('g6_1_kor_u2_review_d#19','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C12',3,'mc','auto','로운의 글에서 「당번은 아침마다 텃밭에 줍니다.」는 어떻게 하는 것이 알맞은가요?',ARRAY['K6-1-u2-X16','K6-1-u2-X03','K6-1-u2-X34']::text[],false,'{"seq":19,"concept":"K6-1-u2-C12","difficulty":3,"kind":"mc","stem":"로운의 글에서 「당번은 아침마다 텃밭에 줍니다.」는 어떻게 하는 것이 알맞은가요?","options":[{"t":"빼지 않고 「당번은 아침마다 텃밭에 물을 줍니다.」로 고친다","correct":true},{"t":"물 주기와 상관없으니 뺀다","mis":"K6-1-u2-X16"},{"t":"창고 문장 뒤로 옮긴다","mis":"K6-1-u2-X03"},{"t":"그대로 둔다","mis":"K6-1-u2-X34"}],"explanation":["물 주기와 관련 있는 문장이에요.","목적어가 빠졌을 뿐이에요.","지우지 말고 고쳐 써요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb),
('g6_1_kor_u2_review_d#20','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C26',3,'ox','auto','「당번은 아침마다 텃밭에 줍니다.」는 말로 하면 통하지만 글에서는 「물을」을 넣어야 해요.',ARRAY['K6-1-u2-X34']::text[],false,'{"seq":20,"concept":"K6-1-u2-C26","difficulty":3,"kind":"ox","stem":"「당번은 아침마다 텃밭에 줍니다.」는 말로 하면 통하지만 글에서는 「물을」을 넣어야 해요.","answer":"O","reason_options":[{"t":"읽는 사람은 그 자리에 없어 무엇을 주는지 알 수 없기 때문에","correct":true},{"t":"글은 말보다 길어야 하기 때문에","mis":"K6-1-u2-X34"}],"mis":"K6-1-u2-X34","explanation":["말할 때는 서로 알아서 빼도 통해요.","읽는 사람은 그 자리에 없었어요.","필수 성분을 갖춰요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb),
('g6_1_kor_u2_review_d#21','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C19',3,'mc','auto','「나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄 수 있는 사람이 되겠다.」에서 띄어 쓴 「수」에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X27','K6-1-u2-X25','K6-1-u2-X24']::text[],false,'{"seq":21,"concept":"K6-1-u2-C19","difficulty":3,"kind":"mc","stem":"「나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄 수 있는 사람이 되겠다.」에서 띄어 쓴 「수」에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"홀로 못 쓰는 이름씨라 앞말과 띄어 쓴다","correct":true},{"t":"조사라서 앞말에 붙여 써야 한다","mis":"K6-1-u2-X27"},{"t":"세는 말이라 수와 붙여 쓴다","mis":"K6-1-u2-X25"},{"t":"띄어쓰기는 뜻과 상관없어 아무렇게나 써도 된다","mis":"K6-1-u2-X24"}],"explanation":["「수」는 조사가 아니에요.","세는 말도 아니에요.","홀로 못 쓰는 이름씨라 띄어요."]}'::jsonb),
('g6_1_kor_u2_review_d#22','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C4',3,'mc','auto','세아와 민석이의 말을 함께 볼 때 글을 공유하는 일의 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X10']::text[],false,'{"seq":22,"concept":"K6-1-u2-C4","difficulty":3,"kind":"mc","stem":"세아와 민석이의 말을 함께 볼 때 글을 공유하는 일의 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내가 못 본 곳을 친구가 짚어 주고, 읽는 사람을 떠올리며 더 꼼꼼히 고치게 된다","correct":true},{"t":"친구가 대신 글을 써 준다","mis":"K6-1-u2-X10"},{"t":"공유하면 더 고칠 필요가 없다","mis":"K6-1-u2-X10"},{"t":"칭찬을 많이 받아 기분이 좋다","mis":"K6-1-u2-X10"}],"explanation":["친구는 대신 쓰지 않아요.","공유한 뒤에도 고쳐요.","못 본 곳과 읽는 사람을 알게 돼요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"학급 게시판에 올린 내 글에 댓글이 세 개 달렸어. 내가 못 본 곳을 친구가 짚어 줬어."},{"who":"민석","text":"나도 올려 봤는데, 읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라."}]}}'::jsonb),
('g6_1_kor_u2_review_d#23','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C37',4,'mc','auto','하린의 감상문을 학급 게시판에 소개하는 글로 바꿀 때 가장 알맞은 문장은 어느 것인가요?',ARRAY['K6-1-u2-X44','K6-1-u2-X45','K6-1-u2-X09']::text[],false,'{"seq":23,"concept":"K6-1-u2-C37","difficulty":4,"kind":"mc","stem":"하린의 감상문을 학급 게시판에 소개하는 글로 바꿀 때 가장 알맞은 문장은 어느 것인가요?","options":[{"t":"할머니가 손녀에게 종이배 접는 법을 서두르지 않고 가르치는 장면에서, 기다려 주는 것도 가르침이라는 걸 알게 되었습니다.","correct":true},{"t":"이 연극은 최고예요. 무조건 보세요.","mis":"K6-1-u2-X44"},{"t":"연극은 배우가 무대에서 하는 공연입니다.","mis":"K6-1-u2-X45"},{"t":"ㄹㅇ 꿀잼 연극 강추","mis":"K6-1-u2-X09"}],"explanation":["자랑은 알 수 있는 것이 없어요.","누구에게나 있는 말은 소개가 아니에요.","줄임말 없이 그려 볼 수 있게 써요."]}'::jsonb),
('g6_1_kor_u2_review_d#24','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C32',4,'essay','teacher','하린이 친구들의 의견을 어떻게 골라 받아들였는지 쓰고, 의견을 고르는 기준이 왜 필요한지 내 생각을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u2-C32","difficulty":4,"kind":"essay","stem":"하린이 친구들의 의견을 어떻게 골라 받아들였는지 쓰고, 의견을 고르는 기준이 왜 필요한지 내 생각을 쓰세요.","answer_guide":{"answer":"예: 하린은 연극을 본 이야기를 맨 앞으로 옮기자는 보미의 의견과 놀이터 문장을 빼자는 서준의 의견을 받아들였다. 다른 연극 이름을 다 적자는 지호의 의견은 「종이배」 감상문과 멀어서 넣지 않았다. 의견을 모두 따르면 글이 하려던 말과 멀어질 수 있다. 그래서 「이 의견을 따르면 내가 하려던 말이 더 잘 전해지는가?」라는 기준으로 골라야 내 글이 나아진다.","scoring_points":["받아들인 의견과 받아들이지 않은 의견을 썼는가","받아들이지 않은 까닭을 썼는가","기준이 필요한 까닭을 썼는가"]},"explanation":["세 친구의 의견을 나눠 봐요.","넣지 않은 까닭을 써요.","기준이 왜 필요한지 써요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb),
('g6_1_kor_u2_review_d#25','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C39',4,'essay','teacher','「닫다 · 닫히다」 또는 「놓다 · 놓이다」를 골라 두 말을 넣은 문장을 하나씩 만들고, 두 말이 어떻게 다른지 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u2-C39","difficulty":4,"kind":"essay","stem":"「닫다 · 닫히다」 또는 「놓다 · 놓이다」를 골라 두 말을 넣은 문장을 하나씩 만들고, 두 말이 어떻게 다른지 설명하세요.","answer_guide":{"answer":"예: 나는 책상 위에 책을 놓았다. / 책상 위에 책이 놓여 있었다. 「놓다」는 내가 스스로 하는 일을 나타내는 말이고, 「놓이다」는 다른 힘에 의해 그렇게 된 일을 나타내는 말이다. 스스로 하는 일에는 「-이-」를 붙이지 않는다.","scoring_points":["두 말을 넣은 문장을 하나씩 바르게 만들었는가","스스로 하는 일과 그리 되는 일로 차이를 설명했는가","-히- · -리- · -이-를 붙이는 경우를 바르게 썼는가"]},"explanation":["두 말을 골라요.","문장을 하나씩 만들어요.","스스로 하는가, 그리 되는가로 견주어요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K6-1-u3-C1','kor',6,1,'u3',1,'토론이 필요한 상황 — 같은 일을 두고 찬성과 반대로 생각이 갈리는 문제에서 토론이 필요하며, 답이 이미 정해져 있거나 자료를 찾아보면 곧바로 확인되는 물음(학교가 문을 연 해 · 교실 온도)은 토론 주제가 되지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],1),
('K6-1-u3-C2','kor',6,1,'u3',1,'토의와 토론의 다른 점 — 둘 다 문제를 해결하려고 함께 이야기하지만, 토의는 편을 나누지 않고 방법을 모으는 말하기이고 토론은 찬성 측과 반대 측으로 편이 갈리는 말하기로, 가르는 잣대는 「찬반으로 편이 갈리는가」 하나이다',ARRAY['6국01-07 듣기 · 말하기']::text[],2),
('K6-1-u3-C3','kor',6,1,'u3',1,'토론의 뜻 — 어떤 문제를 두고 찬성 측과 반대 측으로 나뉘어 각자 근거를 들어 자기 주장이 옳음을 밝히는 말하기로, 목소리가 큰 쪽이 이기는 것이 아니라 타당한 이유와 근거를 내놓고 정해진 절차를 지켜 겨룬다',ARRAY['6국01-07 듣기 · 말하기']::text[],3),
('K6-1-u3-C4','kor',6,1,'u3',1,'주장 · 이유 · 근거의 세 층 — 주장은 내가 옳다고 내세우는 생각, 이유는 그렇게 주장하는 까닭(내 머릿속에서 나온 문장), 근거는 이유를 뒷받침하는 객관적인 자료(밖에서 가져와 확인할 수 있는 것)이며, 세 층이 위아래로 맞물려야 말이 선다',ARRAY['6국01-02 듣기 · 말하기']::text[],4),
('K6-1-u3-C5','kor',6,1,'u3',1,'토론의 네 단계 — 주장 펼치기(주장 · 이유 · 근거를 냄) → 반론하기(상대 허점을 짚고 답함) → 주장 다지기(남은 것을 추려 다시 세움) → 판정하기(기준을 밝히고 더 설득력 있는 쪽을 정함)의 차례로 나아가며, 각 단계에 지킬 규칙이 있다',ARRAY['6국01-07 듣기 · 말하기']::text[],5),
('K6-1-u3-C6','kor',6,1,'u3',1,'경청하는 태도 — 상대 발언을 끝까지 듣고 메모한 뒤 말차례에 되받으며, 듣지 않으면 무엇을 되받을지도 알 수 없으므로 경청은 예의이면서 실력이다',ARRAY['6국01-07 듣기 · 말하기']::text[],6),
('K6-1-u3-C7','kor',6,1,'u3',1,'토론의 목적 — 토론은 찬반으로 겨루는 방식이 맞지만 그렇게 겨루는 목적은 상대를 누르는 것이 아니라 더 합리적인 결정에 이르는 것이며, 근거를 겨누고 결과에 승복한다',ARRAY['6국01-07 듣기 · 말하기']::text[],7),
('K6-1-u3-C8','kor',6,1,'u3',1,'토론 주제의 갈래 — 참인지 거짓인지 따지는 문제 · 좋고 나쁨을 따지는 문제 · 무엇을 하자고 정하는 문제가 있으나 셋을 딱 잘라 나눌 필요는 없으며, 우리가 바꿔 볼 수 있는 「무엇을 하자고 정하는 문제」가 교실 토론에 가장 잘 맞는다',ARRAY['6국01-07 듣기 · 말하기']::text[],8),
('K6-1-u3-C9','kor',6,1,'u3',2,'주장 펼치기 — 양측이 차례로 주장 → 이유 → 근거를 함께 내놓는 단계로, 세 층이 다 있어야 주장 펼치기가 되며 사회자는 주제와 순서를 안내한다',ARRAY['6국01-07 듣기 · 말하기']::text[],9),
('K6-1-u3-C10','kor',6,1,'u3',2,'근거가 될 수 있는 것 — 설문 조사 결과 · 통계 · 이름을 밝힌 전문가의 말처럼 밖에서 가져와 누가 언제 무엇을 조사했는지 확인할 수 있는 것이 근거이고, 「그렇게 느낀다 · 그럴 것 같다」로 끝나는 문장은 이유이다',ARRAY['6국01-02 듣기 · 말하기']::text[],10),
('K6-1-u3-C11','kor',6,1,'u3',2,'반론의 뜻과 범위 — 반론은 상대 주장에 맞서 반대되는 자기 주장을 밝히는 말하기로, 주장 펼치기에서 나온 내용(주장 · 이유 · 근거)에 대해서만 되받고 새 이야기를 꺼내지 않으며, 정리할 때에는 발언을 그대로 옮기지 않고 핵심만 요약한다',ARRAY['6국01-07 듣기 · 말하기']::text[],11),
('K6-1-u3-C12','kor',6,1,'u3',2,'반론에 답변하기 — 답변할 때에는 상대가 물은 그 지점에 곧바로 답하면서 그 반론이 타당하지 않음을 밝히거나, 인정할 것은 인정하고 자료로 다시 세우며, 같은 말을 되풀이하는 것(공평하니까 공평하다)은 답변이 아니다',ARRAY['6국01-07 듣기 · 말하기']::text[],12),
('K6-1-u3-C13','kor',6,1,'u3',2,'반론은 사람을 겨누지 않는다 — 「그것도 모르십니까?」처럼 사람이나 말투를 겨눈 말은 반론이 아니고 「그 자료는 조사한 때가 나와 있지 않습니다」처럼 주장 · 이유 · 근거를 겨누어야 하며, 토론은 공식적인 말하기이므로 높임말을 쓰고 공격적인 말투로 흐르지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],13),
('K6-1-u3-C14','kor',6,1,'u3',2,'주장 다지기 — 같은 말을 되풀이하는 단계가 아니라 앞 두 단계에서 확인된 것만 추려 자기편 주장을 다시 세우는 단계로, 짧은 문장 · 「요컨대 · 따라서」 같은 이어 주는 말 · 또박또박 힘 있는 목소리로 말하며 무너진 근거를 다시 꺼내지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],14),
('K6-1-u3-C15','kor',6,1,'u3',2,'판정의 첫 조건 — 명확한 기준 — 판정할 때 가장 먼저 있어야 하는 것은 무엇을 보고 정할지 미리 밝혀 둔 명확한 기준(타당한 이유를 냈는가 · 믿을 수 있는 근거를 냈는가 등)이며, 기준이 없으면 판정이 아니라 취향이 된다',ARRAY['6국01-02 듣기 · 말하기']::text[],15),
('K6-1-u3-C16','kor',6,1,'u3',2,'판정은 옳고 그름을 가리지 않는다 — 판정은 어느 쪽 생각이 옳은지 가려 주는 일이 아니라 정해 둔 기준으로 볼 때 어느 쪽이 더 설득력 있게 말했는지를 정하는 일이라 기준이 달라지면 결과도 달라질 수 있으며, 토론자는 그 결과에 승복한다',ARRAY['6국01-02 듣기 · 말하기']::text[],16),
('K6-1-u3-C17','kor',6,1,'u3',2,'토론 전 과정의 규칙 — 단계마다 다른 규칙 말고도 처음부터 끝까지 지킬 규칙이 있다 — 높임말을 쓰고 · 말차례를 지키고(끼어들지 않고) · 주제와 이어지는 말만 하고 · 상대를 존중한다',ARRAY['6국01-07 듣기 · 말하기']::text[],17),
('K6-1-u3-C18','kor',6,1,'u3',4,'학급 토론 주제 고르기 — 친구들이 관심 있어 하고 · 찬성과 반대가 뚜렷하게 갈리고 · 양쪽 모두 근거를 찾을 수 있고 · 우리 힘으로 바꿔 볼 수 있는 문제를 고르며, 늘 그래 왔던 일에도 「꼭 그래야 할까」라고 물으면 좋은 주제가 나온다',ARRAY['6국01-07 듣기 · 말하기']::text[],18),
('K6-1-u3-C19','kor',6,1,'u3',4,'입장 먼저, 역할은 나중 — 주제가 정해지면 먼저 모두가 자기 생각(찬성 · 반대)을 정하고 역할은 그다음에 나누며, 찬성과 반대가 비슷한 수로 갈려야 토론이 팽팽해진다',ARRAY['6국01-07 듣기 · 말하기']::text[],19),
('K6-1-u3-C20','kor',6,1,'u3',4,'토론 준비표 — 준비표에는 주장 → 이유 → 이유마다 근거를 적고 예상 반론과 답변까지 덧붙이며, 이유는 두세 가지를 준비해 하나가 무너져도 남은 것으로 버틸 수 있게 한다',ARRAY['6국01-07 듣기 · 말하기']::text[],20),
('K6-1-u3-C21','kor',6,1,'u3',4,'근거를 찾는 곳 — 믿을 만한 곳에서 낸 책과 누리집 자료 · 그 일을 오래 해 온 전문가의 의견(누구의 말인지 반드시 적음) · 우리 반이나 학년에 직접 물어 수를 센 설문 조사에서 근거를 찾고, 모은 자료는 같은 편끼리 바꾸어 읽어 본다',ARRAY['6국01-02 듣기 · 말하기']::text[],21),
('K6-1-u3-C22','kor',6,1,'u3',4,'예상 반론과 답변 준비 — 상대가 무엇이라 되받을지 미리 적고 그에 대한 답변을 준비하며, 이 과정에서 내 근거의 약한 곳이 먼저 드러나므로 건너뛰지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],22),
('K6-1-u3-C23','kor',6,1,'u3',4,'토론의 네 역할 — 사회자(주제와 규칙을 알리고 말차례를 이끎 · 주제에서 벗어나지 않게 함) · 토론자(근거를 들어 간결하고 분명하게 말하고 상대 말을 끝까지 들음) · 판정단(기준을 정해 공정하게 판정 · 자기 생각과 같은 편에 후하게 주지 않음) · 청중(메모하며 듣고 잘한 곳 · 인상 깊은 근거를 짚음)으로, 모두에게 할 일이 있다',ARRAY['6국01-07 듣기 · 말하기']::text[],23),
('K6-1-u3-C24','kor',6,1,'u3',4,'진행 순서와 협의 시간 — 찬성 · 반대 주장 펼치기 → 반대 측 반론과 찬성 측 답변 → 찬성 측 반론과 반대 측 답변 → 찬성 · 반대 주장 다지기 → 판정단의 판정과 정리의 차례로 굴러가며, 단계 사이 협의 시간에 같은 편끼리 반론과 답변을 맞춘다',ARRAY['6국01-07 듣기 · 말하기']::text[],24),
('K6-1-u3-C25','kor',6,1,'u3',4,'뜨거워질수록 침착하게 — 질문과 답이 빠르게 오가는 반론하기에서는 감정이 앞서기 쉬우므로 말차례를 기다리고 · 한 번에 한 가지만 되받고 · 졌다고 느껴질 때에도 침착하게 이어 가며, 지나치게 뜨거워지면 서로의 말이 들리지 않아 되받을 수도 없다',ARRAY['6국01-07 듣기 · 말하기']::text[],25),
('K6-1-u3-C26','kor',6,1,'u3',6,'근거를 따지는 세 물음 — 근거가 타당한지는 「주장이나 이유와 관련 있는가(관련성) · 출처가 분명한가(신뢰성) · 언제 누구를 조사했는지 충분히 구체적인가(충분성)」 세 물음으로 따지되, 셋을 딱 잘라 나누기보다 한 번씩 던져 보고 전체적으로 타당한지 본다 — 내 근거를 다듬을 때도, 상대 근거에 반론할 때도 쓴다',ARRAY['6국01-02 듣기 · 말하기']::text[],26),
('K6-1-u3-C27','kor',6,1,'u3',6,'힘을 내지 못하는 근거 — 「어떤 동영상에서 봤는데」(누가 만든 무엇인지 모름) · 「많은 사람이 그렇게 답했다」(언제 몇 명에게 물었는지 없음) · 이유와 이어지지 않는 다른 이야기처럼, 세 물음 가운데 하나만 걸려도 근거는 흔들린다',ARRAY['6국01-02 듣기 · 말하기']::text[],27),
('K6-1-u3-C28','kor',6,1,'u3',6,'충분성은 자료 개수가 아니다 — 자료를 다섯 개나 내도 각각이 흐릿하면 그대로이며, 충분하다는 것은 자료 하나가 언제 · 누구를 · 어떻게 조사한 것인지 밝혀져 있다는 뜻이라 자세한 자료 하나로도 충분할 수 있다',ARRAY['6국01-02 듣기 · 말하기']::text[],28),
('K6-1-u3-C29','kor',6,1,'u3',6,'경험도 근거가 될 수 있다 — 나에게만 일어난 지나치게 드문 일(운동장에서 지갑을 주웠다)은 근거가 되기 어렵지만, 여러 사람이 그럴 만하다고 여길 일을 느낌으로 두지 않고 세거나 재어서 정리하면(한 시간 동안 출입을 세었더니) 근거가 될 수 있다',ARRAY['6국01-02 듣기 · 말하기']::text[],29),
('K6-1-u3-C30','kor',6,1,'u3',6,'믿을 만한 자료 고르기 — 공신력 있는 곳(정부 기관 · 대학 · 연구소 · 언론사)에서 · 가장 최근에 낸 · 주제와 직접 이어지는 · 한쪽에 치우치지 않은 자료를 고르며, 무언가를 팔려는 글이나 광고에 가까운 기사는 근거로 삼기 어렵다',ARRAY['6국01-02 듣기 · 말하기']::text[],30),
('K6-1-u3-C31','kor',6,1,'u3',6,'근거를 내놓는 법 — 세부 사항을 모두 읽지 않고 중요한 내용만 추려 분명하게 전하고, 표나 그림으로 보이면 한눈에 들어오며, 말할 때 누가 언제 낸 자료인지를 먼저 밝힌다 — 「어디서 봤는데」로 시작하면 좋은 자료도 흔들린다',ARRAY['6국01-07 듣기 · 말하기']::text[],31),
('K6-1-u3-C32','kor',6,1,'u3',8,'사회 문제로 주제 정하기 — 늘 그래 왔던 일에 「꼭 그래야 할까」라고 묻고 많은 친구가 관심 있어 할 문제를 고르되, 사회 문제는 아는 것이 적으면 겉돌기 쉬우므로 주제를 정한 뒤 먼저 알려진 사실(지금 제한 속도 · 사고 건수)부터 함께 맞춰 본다',ARRAY['6국01-07 듣기 · 말하기']::text[],32),
('K6-1-u3-C33','kor',6,1,'u3',8,'판정단의 공정함 — 판정단은 판정 기준을 미리 정해 적어 두고, 토론에서 실제로 나온 말과 자료만으로 판정하며, 평소 자기 생각과 같은 편이나 친한 친구가 있는 편에 후하게 주지 않는다',ARRAY['6국01-02 듣기 · 말하기']::text[],33),
('K6-1-u3-C34','kor',6,1,'u3',8,'메모하며 듣기 — 주장 펼치기는 준비한 대로 말하면 되지만 반론하기는 그 순간에 들은 것으로만 할 수 있어 승패가 여기서 갈리므로, 원고를 다시 읽지 말고 상대측 주장(한 문장) · 이유의 개수 · 근거의 출처 · 답이 닿지 않은 물음을 핵심만 짧게 메모해 가장 약한 한 곳을 되받는다',ARRAY['6국01-02 듣기 · 말하기']::text[],34),
('K6-1-u3-C35','kor',6,1,'u3',8,'판정 기준 네 갈래 — 주장 펼치기(주장이 설득력 있고 이유와 근거가 타당한가) · 반론하기(상대 이유나 근거의 문제를 찾아 되받고 반론에 알맞게 답했는가) · 주장 다지기(다시 정리해 분명히 했는가) · 태도(규칙을 지키고 경청하며 예의 바르게 참여했는가)로 본다',ARRAY['6국01-02 듣기 · 말하기']::text[],35),
('K6-1-u3-C36','kor',6,1,'u3',8,'판정 뒤의 마무리 — 「우리가 이겼다 · 판정이 이상하다」로 끝내면 남는 것이 승패뿐이므로 판정 결과에는 승복하고 「저 근거는 나도 다시 찾아봐야겠다」처럼 생각을 남기며, 토론 뒤 생각이 바뀌거나 더 굳어지는 것은 부끄러운 일이 아니라 토론을 제대로 한 표시이다',ARRAY['6국01-07 듣기 · 말하기']::text[],36),
('K6-1-u3-C37','kor',6,1,'u3',11,'실천 토론 주제 고르기 — 역사 · 환경 · 생활 어느 갈래에서 찾든 찬반이 갈리고 양쪽 모두 근거를 찾을 수 있어야 하며, 연도나 이름처럼 자료를 찾으면 답이 하나로 나오는 물음은 토론 주제가 아니다',ARRAY['6국01-07 듣기 · 말하기']::text[],37),
('K6-1-u3-C38','kor',6,1,'u3',11,'근거는 나누어 모으고 골라 쓴다 — 모둠 안에서 찾을 영역(통계 · 전문가의 말 · 다른 고장 사례)을 나누고, 누가 언제 낸 자료인지 함께 적고, 같은 편끼리 바꾸어 읽으며 세 물음을 던진 뒤 가장 센 두 가지만 골라 준비표에 옮긴다',ARRAY['6국01-02 듣기 · 말하기']::text[],38),
('K6-1-u3-C39','kor',6,1,'u3',11,'원탁 토론 — 찬반 토론이 편을 나누어 정해진 단계대로 겨루고 사회자와 판정단을 두는 것과 달리, 원탁 토론은 편을 나누지 않고 모두가 대등하게 한 차례에 한 번씩 돌아가며 말하며 답이 둘로 갈리지 않는 문제에 알맞다 — 어느 쪽이든 근거를 들어 말한다는 점은 같다',ARRAY['6국01-07 듣기 · 말하기']::text[],39),
('K6-1-u3-C40','kor',6,1,'u3',11,'역사 논쟁은 관점의 차이 — 역사에 관한 논쟁에는 옳고 그름이 있는 것이 아니라 무엇을 더 중요하게 여겼는지 서로 다른 관점이 있으므로(배움의 기회 · 남은 것의 진짜 모습), 한쪽을 틀린 편으로 만들지 않고 판정 뒤에도 상대 생각을 낮추어 말하지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],40),
('K6-1-u3-C41','kor',6,1,'u3',11,'토론 뒤 나눌 이야기 — 토론은 끝났을 때가 아니라 새롭게 알게 된 사실 · 다른 역할을 맡았던 친구 가운데 잘한 사람과 그 까닭 · 생각이 바뀌었거나 더 굳어진 곳을 나눌 때 비로소 마무리된다',ARRAY['6국01-07 듣기 · 말하기']::text[],41),
('K6-1-u3-C42','kor',6,1,'u3',11,'토론자에게 필요한 힘 — 자기 주장을 타당한 이유와 근거로 뒷받침하는 힘 · 상대의 반론이나 질문에 알맞게 답하는 힘 · 상대 근거의 타당성을 따져 보는 힘 · 자신감 있게 그러면서도 예의 바르게 표현하는 힘이며, 말을 많이 하거나 크게 하는 것과 토론을 잘하는 것은 다르다',ARRAY['6국01-07 듣기 · 말하기']::text[],42),
('K6-1-u3-C43','kor',6,1,'u3',11,'겹받침 읽기 — 겹받침은 뒤에 자음이 오면 두 자음 가운데 하나만 소리 나고 그 뒤의 ㄱ · ㄷ · ㅂ · ㅅ · ㅈ은 된소리가 된다 — ㄻ은 [ㅁ](젊다 [점따] · 옮기다 [옴기다]), ㄿ은 [ㅂ](읊다 [읍따] · 가락을 붙여 시를 읽거나 외다), ㄺ은 [ㄱ](굵다 [국따] · 늙지 [늑찌])이되 ㄺ 뒤에 ㄱ이 오면 [ㄹ](굵고 [굴꼬]) (기초 다지기)',ARRAY['기초 다지기(겹받침)']::text[],43)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K6-1-u3-X01','kor',6,'u3',ARRAY['K6-1-u3-C1','K6-1-u3-C18','K6-1-u3-C32','K6-1-u3-C37']::text[],'답이 이미 정해져 있거나 자료를 찾아보면 곧바로 확인되는 물음(학생 수 · 연도 · 지켜야 할 규칙)도 토론 주제가 된다고 여긴다','찬반이 갈리나?'),
('K6-1-u3-X02','kor',6,'u3',ARRAY['K6-1-u3-C2','K6-1-u3-C3']::text[],'편을 나누지 않고 방법을 모으는 토의와 찬반으로 편이 갈리는 토론을 헷갈린다','찬반으로 편이 갈리나?'),
('K6-1-u3-X03','kor',6,'u3',ARRAY['K6-1-u3-C3','K6-1-u3-C39']::text[],'토론을 한 사람이 여러 사람 앞에서 자기 생각을 알리는 말하기(연설 · 발표)로 여긴다','찬성 측과 반대 측'),
('K6-1-u3-X04','kor',6,'u3',ARRAY['K6-1-u3-C4','K6-1-u3-C10']::text[],'그렇게 주장하는 까닭(이유)과 밖에서 가져온 자료(근거)를 헷갈려, 내 느낌이나 생각을 근거로 여긴다','내 까닭? 밖의 자료?'),
('K6-1-u3-X05','kor',6,'u3',ARRAY['K6-1-u3-C9','K6-1-u3-C4']::text[],'주장만 내세우고 이유나 근거를 함께 내지 않는다','주장 → 이유 → 근거'),
('K6-1-u3-X06','kor',6,'u3',ARRAY['K6-1-u3-C5','K6-1-u3-C24']::text[],'토론의 네 단계의 차례나 각 단계에서 하는 일을 헷갈린다','펼치기 → 반론 → 다지기 → 판정'),
('K6-1-u3-X07','kor',6,'u3',ARRAY['K6-1-u3-C6','K6-1-u3-C17']::text[],'허점이 보이면 상대 말을 끊고 끼어들어 곧바로 되받는다','말차례를 기다려요'),
('K6-1-u3-X08','kor',6,'u3',ARRAY['K6-1-u3-C6','K6-1-u3-C34']::text[],'상대 말을 듣지 않고 준비한 원고를 그대로 읽는다','듣고 메모해야 되받아요'),
('K6-1-u3-X09','kor',6,'u3',ARRAY['K6-1-u3-C7']::text[],'토론을 어떻게든 상대를 눌러 이겨야 하는 시합으로 여긴다','목적은 합리적인 결정'),
('K6-1-u3-X10','kor',6,'u3',ARRAY['K6-1-u3-C8']::text[],'토론 주제의 갈래를 반드시 딱 잘라 나눌 수 있어야 토론할 수 있다고 여긴다','딱 잘라 나눌 필요는 없어요'),
('K6-1-u3-X11','kor',6,'u3',ARRAY['K6-1-u3-C11','K6-1-u3-C17']::text[],'반론이나 답변에서 주장 펼치기에 나오지 않은, 주제와 상관없는 새 이야기를 꺼낸다','펼친 내용에 대해서만'),
('K6-1-u3-X12','kor',6,'u3',ARRAY['K6-1-u3-C11','K6-1-u3-C34']::text[],'반론을 정리하거나 메모할 때 상대 발언을 한 글자도 빠짐없이 그대로 옮겨 적는다','핵심만 짧게'),
('K6-1-u3-X13','kor',6,'u3',ARRAY['K6-1-u3-C12']::text[],'반론에 답할 때 상대가 물은 것에 답하지 않고 같은 말을 되풀이한다(공평하니까 공평합니다)','물은 그 지점에 답하기'),
('K6-1-u3-X14','kor',6,'u3',ARRAY['K6-1-u3-C13']::text[],'반론에서 주장 · 이유 · 근거가 아니라 사람이나 말투를 겨누거나, 반말 · 공격적인 말투를 쓴다','근거를 겨눠요'),
('K6-1-u3-X15','kor',6,'u3',ARRAY['K6-1-u3-C14']::text[],'주장 다지기를 처음 한 말을 그대로 되풀이하는 단계로 여기거나, 반론에서 무너진 근거를 다시 꺼낸다','남은 것만 추려 다시'),
('K6-1-u3-X16','kor',6,'u3',ARRAY['K6-1-u3-C15','K6-1-u3-C35']::text[],'판정을 미리 밝힌 기준 없이 목소리 크기 · 말한 길이 · 평소 생각 같은 것으로 한다','기준이 먼저'),
('K6-1-u3-X17','kor',6,'u3',ARRAY['K6-1-u3-C16']::text[],'판정 결과가 어느 쪽 생각이 옳은지를 가려 준다고 여긴다','더 설득력 있게 말한 쪽'),
('K6-1-u3-X18','kor',6,'u3',ARRAY['K6-1-u3-C16','K6-1-u3-C36']::text[],'판정 결과가 마음에 들지 않으면 승복하지 않고 판정단 탓을 한다','결과에 승복해요'),
('K6-1-u3-X19','kor',6,'u3',ARRAY['K6-1-u3-C18','K6-1-u3-C37']::text[],'친구들이 관심 없거나 우리 힘으로 바꿀 수 없는 문제를 토론 주제로 고른다','관심 · 바꿔 볼 수 있나'),
('K6-1-u3-X20','kor',6,'u3',ARRAY['K6-1-u3-C19']::text[],'모두가 자기 생각을 정하기 전에 역할부터 나누거나, 찬반을 한쪽으로 기울게 나눈다','생각 먼저, 역할은 나중'),
('K6-1-u3-X21','kor',6,'u3',ARRAY['K6-1-u3-C20']::text[],'이유를 하나만 준비해 그것이 무너지면 버틸 것이 없다','이유는 두세 가지'),
('K6-1-u3-X22','kor',6,'u3',ARRAY['K6-1-u3-C21','K6-1-u3-C38']::text[],'전문가의 말이나 찾은 자료를 쓸 때 누구의 말인지 · 어디서 낸 자료인지 적지 않는다','누구의 말인지 적기'),
('K6-1-u3-X23','kor',6,'u3',ARRAY['K6-1-u3-C22']::text[],'예상 반론과 답변을 미리 적어 보는 준비를 건너뛰어도 된다고 여긴다','약한 곳이 먼저 보여요'),
('K6-1-u3-X24','kor',6,'u3',ARRAY['K6-1-u3-C23','K6-1-u3-C33']::text[],'판정단이 자기 생각과 같은 편이나 친한 친구가 있는 편에 후하게 준다','나온 말과 자료만'),
('K6-1-u3-X25','kor',6,'u3',ARRAY['K6-1-u3-C23']::text[],'사회자 · 토론자 · 판정단 · 청중이 할 일을 서로 헷갈린다','이끎 · 말함 · 정함 · 들음'),
('K6-1-u3-X26','kor',6,'u3',ARRAY['K6-1-u3-C25']::text[],'반론하기에서 감정이 앞서 목소리를 높이거나 한꺼번에 여러 가지를 몰아친다','한 번에 한 가지, 침착하게'),
('K6-1-u3-X27','kor',6,'u3',ARRAY['K6-1-u3-C26','K6-1-u3-C27']::text[],'주장이나 이유와 이어지지 않는 자료도 근거로 쓸 수 있다고 여긴다','이유와 이어지나?'),
('K6-1-u3-X28','kor',6,'u3',ARRAY['K6-1-u3-C26','K6-1-u3-C27']::text[],'어디서 나왔는지 확인할 수 없는 자료(어떤 누리집 · 어떤 동영상)를 근거로 쓴다','출처가 분명한가?'),
('K6-1-u3-X29','kor',6,'u3',ARRAY['K6-1-u3-C26','K6-1-u3-C27']::text[],'「많은 사람 · 다들」처럼 언제 몇 명에게 물었는지 없는 흐릿한 자료를 근거로 쓴다','언제 · 누구를?'),
('K6-1-u3-X30','kor',6,'u3',ARRAY['K6-1-u3-C28']::text[],'자료의 개수가 많거나 길면 충분한 근거라고 여긴다','개수가 아니라 구체성'),
('K6-1-u3-X31','kor',6,'u3',ARRAY['K6-1-u3-C21','K6-1-u3-C29']::text[],'전문가의 말이나 내가 겪은 일, 사람에게 물은 자료는 무조건 근거가 될 수 없다고 여긴다','확인되고 정리되면 근거'),
('K6-1-u3-X32','kor',6,'u3',ARRAY['K6-1-u3-C29']::text[],'나에게만 일어난 드문 일이나 느낌을 세거나 재지 않고 그대로 근거로 쓴다','세거나 재어서'),
('K6-1-u3-X33','kor',6,'u3',ARRAY['K6-1-u3-C30']::text[],'오래된 자료나 무언가를 팔려는 광고 글, 한쪽에 치우친 자료를 근거로 쓴다','공신력 · 최근 · 치우침 없음'),
('K6-1-u3-X34','kor',6,'u3',ARRAY['K6-1-u3-C31']::text[],'근거를 내놓을 때 세부 사항을 모두 읽거나, 누가 언제 낸 자료인지 밝히지 않고 「어디서 봤는데」로 시작한다','출처를 먼저 밝혀요'),
('K6-1-u3-X35','kor',6,'u3',ARRAY['K6-1-u3-C26']::text[],'근거를 세 물음으로 따지지 않고 숫자가 있는지 · 그럴듯해 보이는지만 보거나, 세 물음 가운데 하나만 통과하면 된다고 여긴다','세 물음을 한 번씩'),
('K6-1-u3-X36','kor',6,'u3',ARRAY['K6-1-u3-C32']::text[],'사회 문제를 주제로 정하고 알려진 사실을 함께 맞춰 보지 않은 채 토론한다','사실부터 함께 맞춰요'),
('K6-1-u3-X37','kor',6,'u3',ARRAY['K6-1-u3-C23']::text[],'청중은 토론에서 할 일이 없다고 여긴다','메모하고 짚어 줘요'),
('K6-1-u3-X38','kor',6,'u3',ARRAY['K6-1-u3-C34']::text[],'토론 중에 상대의 말투 · 목소리 크기 · 옷차림처럼 되받을 거리가 아닌 것을 메모한다','되받을 거리를 적어요'),
('K6-1-u3-X39','kor',6,'u3',ARRAY['K6-1-u3-C36']::text[],'토론 중이나 뒤에 생각이 바뀌면 진 것이라 여겨 무너진 근거를 끝까지 붙잡는다','바뀌어도 괜찮아요'),
('K6-1-u3-X40','kor',6,'u3',ARRAY['K6-1-u3-C36','K6-1-u3-C41']::text[],'토론이 끝난 뒤 승패만 말하거나 상대의 준비를 깎아내린다','배운 것을 나눠요'),
('K6-1-u3-X41','kor',6,'u3',ARRAY['K6-1-u3-C39']::text[],'편을 나누지 않고 대등하게 말하는 원탁 토론과 편을 나누어 겨루는 찬반 토론을 헷갈린다','편을 나누나?'),
('K6-1-u3-X42','kor',6,'u3',ARRAY['K6-1-u3-C40']::text[],'역사에 관한 논쟁을 한쪽은 옳고 다른 쪽은 틀린 문제로 여긴다','무엇을 더 중요하게 여겼나'),
('K6-1-u3-X43','kor',6,'u3',ARRAY['K6-1-u3-C38']::text[],'모은 근거를 같은 편끼리 바꾸어 읽거나 고르지 않고 모두 준비표에 옮긴다','가장 센 두 가지'),
('K6-1-u3-X44','kor',6,'u3',ARRAY['K6-1-u3-C43']::text[],'겹받침의 두 자음을 모두 소리 내거나, 어느 자음이 소리 나는지 · 뒤 자음이 된소리가 되는지를 틀리게 읽는다(굵고 [국꼬])','ㄻ [ㅁ] · ㄿ [ㅂ] · ㄺ [ㄱ], ㄺ+ㄱ [ㄹ]'),
('K6-1-u3-X45','kor',6,'u3',ARRAY['K6-1-u3-C42']::text[],'말을 많이 하거나 크게 하는 것을 토론을 잘하는 것으로 여긴다','근거 · 답변 · 예의')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_1_kor_u3_L01_basic#1','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C3',1,'mc','auto','「토론」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X02','K6-1-u3-X03','K6-1-u3-X09']::text[],false,'{"seq":1,"concept":"K6-1-u3-C3","difficulty":1,"kind":"mc","stem":"「토론」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"찬성과 반대로 나뉘어 근거를 들어 자기 주장이 옳음을 밝히는 말하기","correct":true},{"t":"편을 나누지 않고 여럿이 의견을 모아 방법을 찾는 말하기","mis":"K6-1-u3-X02"},{"t":"한 사람이 여러 사람 앞에서 자기 생각을 알리는 말하기","mis":"K6-1-u3-X03"},{"t":"목소리가 큰 쪽이 이기는 말하기","mis":"K6-1-u3-X09"}],"explanation":["편 없이 방법을 모으는 것은 토의예요.","혼자 알리는 말하기는 토론이 아니에요.","찬반으로 나뉘어 근거를 들어 겨뤄요."]}'::jsonb),
('g6_1_kor_u3_L01_basic#2','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C1',1,'mc','auto','다음 가운데 토론이 필요한 상황은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":2,"concept":"K6-1-u3-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 토론이 필요한 상황은 어느 것인가요?","options":[{"t":"학교 앞 도로에 과속 방지 턱을 더 놓을지 정하기","correct":true},{"t":"우리 학교가 문을 연 해가 언제인지 알아보기","mis":"K6-1-u3-X01"},{"t":"교실 온도가 몇 도인지 재어 보기","mis":"K6-1-u3-X01"},{"t":"불이 났을 때 대피하는 길 익히기","mis":"K6-1-u3-X01"}],"explanation":["문을 연 해는 찾아보면 확인돼요.","온도는 재면 알 수 있어요.","찬반으로 갈리는 문제라야 토론이 돼요."]}'::jsonb),
('g6_1_kor_u3_L01_basic#3','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C4',1,'match','auto','말한 내용과 그 층을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-1-u3-C4","difficulty":1,"kind":"match","stem":"말한 내용과 그 층을 알맞게 이으세요.","pairs":[{"l":"학교 앞 도로의 제한 속도를 낮춰야 합니다","r":"주장"},{"l":"차가 빠르면 아이들이 피할 시간이 없기 때문입니다","r":"이유"},{"l":"우리 시가 지난해 낸 어린이 보행 사고 통계","r":"근거"}],"mis":"K6-1-u3-X04","explanation":["내세우는 생각은 주장이에요.","그렇게 생각한 까닭은 이유예요.","밖에서 가져온 자료는 근거예요."]}'::jsonb),
('g6_1_kor_u3_L01_basic#4','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C2',1,'ox','auto','토의와 토론의 가장 큰 다른 점은 찬성과 반대로 편이 갈리는가예요.',ARRAY['K6-1-u3-X02']::text[],false,'{"seq":4,"concept":"K6-1-u3-C2","difficulty":1,"kind":"ox","stem":"토의와 토론의 가장 큰 다른 점은 찬성과 반대로 편이 갈리는가예요.","answer":"O","reason_options":[{"t":"토의는 편을 나누지 않고 방법을 모으고, 토론은 찬반으로 나뉘어 겨루기 때문에","correct":true},{"t":"토의는 혼자 하고 토론은 여럿이 하기 때문에","mis":"K6-1-u3-X02"}],"mis":"K6-1-u3-X02","explanation":["둘 다 여럿이 함께 이야기해요.","둘 다 문제를 해결하려고 해요.","다른 점은 찬반으로 편이 갈리는가예요."]}'::jsonb),
('g6_1_kor_u3_L01_basic#5','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C5',2,'mc','auto','토론의 네 단계를 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":5,"concept":"K6-1-u3-C5","difficulty":2,"kind":"mc","stem":"토론의 네 단계를 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"주장 펼치기 → 반론하기 → 주장 다지기 → 판정하기","correct":true},{"t":"반론하기 → 주장 펼치기 → 판정하기 → 주장 다지기","mis":"K6-1-u3-X06"},{"t":"주장 펼치기 → 판정하기 → 반론하기 → 주장 다지기","mis":"K6-1-u3-X06"},{"t":"판정하기 → 주장 펼치기 → 반론하기 → 주장 다지기","mis":"K6-1-u3-X06"}],"explanation":["먼저 주장을 내놓아야 되받을 수 있어요.","다지기는 반론 뒤에 해요.","판정은 맨 마지막이에요."]}'::jsonb),
('g6_1_kor_u3_L01_basic#6','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C6',2,'mc','auto','토론에 참여하는 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X07','K6-1-u3-X08','K6-1-u3-X14']::text[],false,'{"seq":6,"concept":"K6-1-u3-C6","difficulty":2,"kind":"mc","stem":"토론에 참여하는 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"상대 발언을 끝까지 듣고 메모한 뒤 말차례에 되받는다","correct":true},{"t":"허점이 보이면 말을 끊고 곧바로 지적한다","mis":"K6-1-u3-X07"},{"t":"상대가 무슨 말을 하든 준비한 원고를 그대로 읽는다","mis":"K6-1-u3-X08"},{"t":"상대 말투가 거슬리면 그 점부터 짚는다","mis":"K6-1-u3-X14"}],"explanation":["끼어들면 말차례가 무너져요.","듣지 않으면 되받을 수 없어요.","끝까지 듣고 메모한 뒤 되받아요."]}'::jsonb),
('g6_1_kor_u3_L01_basic#7','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C1',2,'mc','auto','온유와 강토의 대화에서 토론이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X02','K6-1-u3-X09']::text[],false,'{"seq":7,"concept":"K6-1-u3-C1","difficulty":2,"kind":"mc","stem":"온유와 강토의 대화에서 토론이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 일을 두고 찬성과 반대로 생각이 갈리기 때문에","correct":true},{"t":"공원 넓이가 얼마인지 알아봐야 하기 때문에","mis":"K6-1-u3-X01"},{"t":"편을 나누지 않고 방법만 모으면 되기 때문에","mis":"K6-1-u3-X02"},{"t":"목소리가 큰 사람의 생각을 따르면 되기 때문에","mis":"K6-1-u3-X09"}],"explanation":["넓이는 재어 보면 알 수 있어요.","두 사람은 생각이 갈렸어요.","찬반으로 갈리면 토론이 필요해요."],"asset":{"type":"speech","turns":[{"who":"온유","text":"마을 공원 한쪽에 반려견 놀이터를 만들면 좋겠어. 목줄을 풀고 뛸 곳이 없어서 개들이 인도까지 나오잖아."},{"who":"강토","text":"나는 반대야. 공원은 모두가 쓰는 곳인데 한쪽을 떼어 주면 아이들이 뛸 곳이 줄어들어."}]}}'::jsonb),
('g6_1_kor_u3_L01_basic#8','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C7',2,'ox','auto','토론은 상대를 어떻게든 눌러 이기는 것이 목적이에요.',ARRAY['K6-1-u3-X09']::text[],false,'{"seq":8,"concept":"K6-1-u3-C7","difficulty":2,"kind":"ox","stem":"토론은 상대를 어떻게든 눌러 이기는 것이 목적이에요.","answer":"X","reason_options":[{"t":"겨루는 방식이지만 목적은 더 합리적인 결정에 이르는 것이기 때문에","correct":true},{"t":"토론은 이기고 지는 것이 전부이기 때문에","mis":"K6-1-u3-X09"}],"mis":"K6-1-u3-X09","explanation":["토론은 찬반으로 겨뤄요.","그러나 누르는 것이 목적이 아니에요.","더 나은 답을 찾고 결과에 승복해요."]}'::jsonb),
('g6_1_kor_u3_L01_basic#9','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C4',2,'mc','auto','「우리 구청이 낸 지난해 안전사고 통계입니다.」는 주장 · 이유 · 근거 가운데 무엇인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X06']::text[],false,'{"seq":9,"concept":"K6-1-u3-C4","difficulty":2,"kind":"mc","stem":"「우리 구청이 낸 지난해 안전사고 통계입니다.」는 주장 · 이유 · 근거 가운데 무엇인가요?","options":[{"t":"근거","correct":true},{"t":"주장","mis":"K6-1-u3-X04"},{"t":"이유","mis":"K6-1-u3-X04"},{"t":"판정","mis":"K6-1-u3-X06"}],"explanation":["내세우는 생각이 아니에요.","내가 생각한 까닭도 아니에요.","밖에서 가져온 자료는 근거예요."]}'::jsonb),
('g6_1_kor_u3_L01_basic#10','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C8',3,'mc','auto','교실 토론 주제로 가장 잘 맞는 것은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X10']::text[],false,'{"seq":10,"concept":"K6-1-u3-C8","difficulty":3,"kind":"mc","stem":"교실 토론 주제로 가장 잘 맞는 것은 어느 것인가요?","options":[{"t":"「우리 반 앉는 곳을 한 달마다 바꾸어야 한다.」처럼 무엇을 하자고 정하는 문제","correct":true},{"t":"「이 자료는 언제 만들어졌는가」처럼 찾아보면 곧바로 확인되는 물음","mis":"K6-1-u3-X01"},{"t":"세 갈래 가운데 어느 것인지 딱 잘라 나눌 수 있어야만 쓸 수 있는 문제","mis":"K6-1-u3-X10"},{"t":"「복도에서 뛰지 않는다」처럼 이미 지키기로 정해진 규칙","mis":"K6-1-u3-X01"}],"explanation":["확인되는 물음은 토론이 안 돼요.","갈래를 딱 잘라 나눌 필요는 없어요.","우리가 바꿔 볼 수 있는 일이 잘 맞아요."]}'::jsonb),
('g6_1_kor_u3_L01_challenge#1','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C2',2,'mc','auto','「학예회에서 우리 반이 무엇을 할지 아이디어 모으기」에 알맞은 말하기는 어느 것인가요?',ARRAY['K6-1-u3-X02','K6-1-u3-X03']::text[],false,'{"seq":1,"concept":"K6-1-u3-C2","difficulty":2,"kind":"mc","stem":"「학예회에서 우리 반이 무엇을 할지 아이디어 모으기」에 알맞은 말하기는 어느 것인가요?","options":[{"t":"토의 — 편을 나누지 않고 함께 방법을 찾는 일이므로","correct":true},{"t":"토론 — 여럿이 함께 이야기하므로","mis":"K6-1-u3-X02"},{"t":"토론 — 문제를 해결하려는 말하기이므로","mis":"K6-1-u3-X02"},{"t":"연설 — 한 사람이 정해서 알리므로","mis":"K6-1-u3-X03"}],"explanation":["여럿이 이야기하는 건 토의도 같아요.","문제를 해결하려는 것도 같아요.","편이 갈리지 않으니 토의예요."]}'::jsonb),
('g6_1_kor_u3_L01_challenge#2','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C4',2,'ox','auto','「목줄을 풀 곳이 없어 인도에서 사고가 나기 쉽기 때문입니다.」는 근거예요.',ARRAY['K6-1-u3-X04']::text[],false,'{"seq":2,"concept":"K6-1-u3-C4","difficulty":2,"kind":"ox","stem":"「목줄을 풀 곳이 없어 인도에서 사고가 나기 쉽기 때문입니다.」는 근거예요.","answer":"X","reason_options":[{"t":"그렇게 주장하는 까닭이므로 이유이고, 근거는 밖에서 가져온 객관적인 자료이기 때문에","correct":true},{"t":"까닭을 말하는 문장도 모두 근거이기 때문에","mis":"K6-1-u3-X04"}],"mis":"K6-1-u3-X04","explanation":["「~때문입니다」는 까닭이에요.","까닭은 이유예요.","근거는 확인할 수 있는 자료예요."]}'::jsonb),
('g6_1_kor_u3_L01_challenge#3','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C3',3,'error','auto','토론에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X02','K6-1-u3-X03']::text[],false,'{"seq":3,"concept":"K6-1-u3-C3","difficulty":3,"kind":"error","stem":"토론에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하율 — 「토론은 편을 나누지 않고 의견을 모아 더 나은 안을 만드는 말하기야.」","correct":true,"mis_target":"K6-1-u3-X02"},{"t":"서진 — 「토론은 찬반으로 나뉘어 근거를 들어 말해.」","mis":"K6-1-u3-X03"},{"t":"라온 — 「토의와 토론 모두 문제를 해결하려고 함께 이야기해.」","mis":"K6-1-u3-X02"}],"explanation":["서진은 토론의 뜻을 바르게 말했어요.","라온은 같은 점을 바르게 말했어요.","하율이 말한 것은 토의예요."]}'::jsonb),
('g6_1_kor_u3_L01_challenge#4','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C5',3,'mc','auto','상대 주장의 잘못된 곳을 짚고, 그에 답하는 단계는 어느 것인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":4,"concept":"K6-1-u3-C5","difficulty":3,"kind":"mc","stem":"상대 주장의 잘못된 곳을 짚고, 그에 답하는 단계는 어느 것인가요?","options":[{"t":"반론하기","correct":true},{"t":"주장 펼치기","mis":"K6-1-u3-X06"},{"t":"주장 다지기","mis":"K6-1-u3-X06"},{"t":"판정하기","mis":"K6-1-u3-X06"}],"explanation":["주장 펼치기는 처음 내놓는 단계예요.","다지기는 다시 세우는 단계예요.","되받는 단계는 반론하기예요."]}'::jsonb),
('g6_1_kor_u3_L01_challenge#5','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C6',3,'mc','auto','경청을 「예의이면서 실력」이라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X16','K6-1-u3-X08','K6-1-u3-X07']::text[],false,'{"seq":5,"concept":"K6-1-u3-C6","difficulty":3,"kind":"mc","stem":"경청을 「예의이면서 실력」이라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"상대 말을 끝까지 들어야 무엇을 되받을지 알 수 있기 때문에","correct":true},{"t":"듣는 척만 해도 판정단이 좋게 보기 때문에","mis":"K6-1-u3-X16"},{"t":"준비한 원고만 잘 읽으면 되기 때문에","mis":"K6-1-u3-X08"},{"t":"상대 말이 끝나기 전에 끼어들어야 이기기 때문에","mis":"K6-1-u3-X07"}],"explanation":["판정은 기준으로 해요.","원고만 읽으면 되받을 수 없어요.","들어야 날카롭게 되받아요."]}'::jsonb),
('g6_1_kor_u3_L01_challenge#6','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C8',3,'mc','auto','어떤 문제가 토론 주제가 되는지에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X10','K6-1-u3-X01']::text[],false,'{"seq":6,"concept":"K6-1-u3-C8","difficulty":3,"kind":"mc","stem":"어떤 문제가 토론 주제가 되는지에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"갈래를 딱 잘라 나눌 필요는 없고, 무엇을 하자고 정하는 문제가 교실 토론에 잘 맞는다","correct":true},{"t":"갈래를 반드시 딱 잘라 나눌 수 있어야 토론할 수 있다","mis":"K6-1-u3-X10"},{"t":"자료를 찾으면 곧바로 답이 나오는 물음이 가장 좋은 주제다","mis":"K6-1-u3-X01"},{"t":"답이 이미 정해진 규칙일수록 토론하기 좋다","mis":"K6-1-u3-X01"}],"explanation":["갈래는 딱 잘라 나누지 않아도 돼요.","확인되는 물음은 토론이 안 돼요.","우리가 바꿔 볼 수 있는 일이 잘 맞아요."]}'::jsonb),
('g6_1_kor_u3_L01_challenge#7','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C7',3,'mc','auto','「서로 겨루어 보면 더 나은 답이 드러난다」라고 여기는 사람의 행동으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X14','K6-1-u3-X18']::text[],false,'{"seq":7,"concept":"K6-1-u3-C7","difficulty":3,"kind":"mc","stem":"「서로 겨루어 보면 더 나은 답이 드러난다」라고 여기는 사람의 행동으로 알맞은 것은 어느 것인가요?","options":[{"t":"근거를 겨누고, 판정 결과에 승복한다","correct":true},{"t":"말이 거칠어져도 상대를 끝까지 누른다","mis":"K6-1-u3-X09"},{"t":"상대의 말투를 짚어 기를 꺾는다","mis":"K6-1-u3-X14"},{"t":"판정이 마음에 들지 않으면 따르지 않는다","mis":"K6-1-u3-X18"}],"explanation":["누르려 하면 말이 거칠어져요.","말투가 아니라 근거를 겨눠요.","결과에 승복해요."]}'::jsonb),
('g6_1_kor_u3_L01_challenge#8','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C4',4,'mc','auto','온유의 주장에 붙일 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05','K6-1-u3-X28']::text[],false,'{"seq":8,"concept":"K6-1-u3-C4","difficulty":4,"kind":"mc","stem":"온유의 주장에 붙일 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"구청이 지난해 낸 공원 주변 반려견 안전사고 자료","correct":true},{"t":"개들이 뛰어놀면 귀여울 것 같다는 내 느낌","mis":"K6-1-u3-X04"},{"t":"반려견 놀이터를 만들어야 한다는 말을 한 번 더 하기","mis":"K6-1-u3-X05"},{"t":"어디서 봤는지 모르는 동영상 이야기","mis":"K6-1-u3-X28"}],"explanation":["느낌은 근거가 아니에요.","주장을 되풀이한 것은 근거가 아니에요.","누가 언제 낸 자료인지 확인돼야 해요."],"asset":{"type":"speech","turns":[{"who":"온유","text":"마을 공원 한쪽에 반려견 놀이터를 만들면 좋겠어. 목줄을 풀고 뛸 곳이 없어서 개들이 인도까지 나오잖아."},{"who":"강토","text":"나는 반대야. 공원은 모두가 쓰는 곳인데 한쪽을 떼어 주면 아이들이 뛸 곳이 줄어들어."}]}}'::jsonb),
('g6_1_kor_u3_L01_challenge#9','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C2',4,'essay','teacher','토의와 토론이 어떻게 같고 어떻게 다른지 쓰고, 각각에 알맞은 예를 하나씩 드세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C2","difficulty":4,"kind":"essay","stem":"토의와 토론이 어떻게 같고 어떻게 다른지 쓰고, 각각에 알맞은 예를 하나씩 드세요.","answer_guide":{"answer":"예: 토의와 토론은 둘 다 문제를 해결하려고 여럿이 함께 이야기한다는 점이 같다. 다른 점은 찬반으로 편이 갈리는가이다. 토의는 편을 나누지 않고 의견을 모아 더 나은 방법을 찾는다. 예를 들어 학예회에서 우리 반이 무엇을 할지 아이디어를 모으는 일이다. 토론은 찬성 측과 반대 측으로 나뉘어 근거를 들어 자기 주장이 옳음을 밝힌다. 예를 들어 공원에 반려견 놀이터를 만들어야 하는가를 두고 겨루는 일이다.","scoring_points":["같은 점을 썼는가","찬반으로 편이 갈리는가로 다른 점을 썼는가","토의와 토론의 예를 하나씩 알맞게 들었는가"]},"explanation":["함께 이야기한다는 점은 같아요.","편이 갈리는지 살펴요.","예를 하나씩 들어요."]}'::jsonb),
('g6_1_kor_u3_L01_challenge#10','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C4',4,'essay','teacher','「공원에 반려견 놀이터를 만들어야 한다」라는 주장에 이유와 근거를 하나씩 붙여 쓰고, 이유와 근거가 어떻게 다른지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C4","difficulty":4,"kind":"essay","stem":"「공원에 반려견 놀이터를 만들어야 한다」라는 주장에 이유와 근거를 하나씩 붙여 쓰고, 이유와 근거가 어떻게 다른지 설명하세요.","answer_guide":{"answer":"예: 이유 — 목줄을 풀 곳이 없어 개들이 인도까지 나와 사고가 나기 쉽기 때문이다. 근거 — 우리 구청이 지난해 낸 공원 주변 안전사고 통계이다. 이유는 그렇게 주장하는 까닭으로 내 머릿속에서 나온 문장이고, 근거는 그 이유를 뒷받침하는 객관적인 자료로 밖에서 가져와 누가 언제 냈는지 확인할 수 있는 것이다.","scoring_points":["주장에 이어지는 이유를 썼는가","확인할 수 있는 근거를 썼는가","이유와 근거의 차이를 바르게 설명했는가"]},"explanation":["까닭을 먼저 써요.","밖에서 가져온 자료를 붙여요.","내 까닭과 밖의 자료로 견줘요."]}'::jsonb),
('g6_1_kor_u3_L02_basic#1','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C9',1,'mc','auto','주장 펼치기에서 함께 내야 하는 것은 어느 것인가요?',ARRAY['K6-1-u3-X05','K6-1-u3-X06']::text[],false,'{"seq":1,"concept":"K6-1-u3-C9","difficulty":1,"kind":"mc","stem":"주장 펼치기에서 함께 내야 하는 것은 어느 것인가요?","options":[{"t":"주장 · 이유 · 근거","correct":true},{"t":"주장만","mis":"K6-1-u3-X05"},{"t":"반론과 답변","mis":"K6-1-u3-X06"},{"t":"판정 기준","mis":"K6-1-u3-X06"}],"explanation":["주장만 내면 확인할 수 없어요.","반론은 다음 단계예요.","세 층이 다 있어야 해요."]}'::jsonb),
('g6_1_kor_u3_L02_basic#2','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C10',1,'mc','auto','근거가 될 수 있는 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05']::text[],false,'{"seq":2,"concept":"K6-1-u3-C10","difficulty":1,"kind":"mc","stem":"근거가 될 수 있는 것은 어느 것인가요?","options":[{"t":"우리 학교 고학년 백스무 명에게 물은 설문 결과","correct":true},{"t":"운동장이 좁아서 답답하다고 느낀다","mis":"K6-1-u3-X04"},{"t":"나누어 쓰면 더 재미없을 것 같다","mis":"K6-1-u3-X04"},{"t":"운동장은 나누어 써야 한다","mis":"K6-1-u3-X05"}],"explanation":["느낌은 이유에 가까워요.","「같다」로 끝나는 말은 근거가 아니에요.","확인할 수 있는 설문은 근거예요."]}'::jsonb),
('g6_1_kor_u3_L02_basic#3','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C13',1,'ox','auto','반론할 때에는 「그것도 모르십니까?」처럼 말해도 돼요.',ARRAY['K6-1-u3-X14']::text[],false,'{"seq":3,"concept":"K6-1-u3-C13","difficulty":1,"kind":"ox","stem":"반론할 때에는 「그것도 모르십니까?」처럼 말해도 돼요.","answer":"X","reason_options":[{"t":"반론은 사람이 아니라 주장 · 이유 · 근거를 겨누어야 하기 때문에","correct":true},{"t":"날카롭게 말해야 반론이 세지기 때문에","mis":"K6-1-u3-X14"}],"mis":"K6-1-u3-X14","explanation":["그 말은 사람을 겨눠요.","토론은 공식적인 말하기예요.","근거를 겨누어 되받아요."]}'::jsonb),
('g6_1_kor_u3_L02_basic#4','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C15',1,'mc','auto','판정할 때 가장 먼저 있어야 하는 것은 어느 것인가요?',ARRAY['K6-1-u3-X16']::text[],false,'{"seq":4,"concept":"K6-1-u3-C15","difficulty":1,"kind":"mc","stem":"판정할 때 가장 먼저 있어야 하는 것은 어느 것인가요?","options":[{"t":"무엇을 보고 정할지 미리 밝혀 둔 명확한 판정 기준","correct":true},{"t":"판정단이 평소 어느 쪽 생각에 가까웠는지","mis":"K6-1-u3-X16"},{"t":"어느 쪽이 더 큰 목소리로 말했는지","mis":"K6-1-u3-X16"},{"t":"어느 쪽 토론자 수가 더 많은지","mis":"K6-1-u3-X16"}],"explanation":["평소 생각은 판정과 관계없어요.","목소리 크기는 기준이 아니에요.","기준이 없으면 판정이 아니라 취향이에요."]}'::jsonb),
('g6_1_kor_u3_L02_basic#5','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C10',2,'match','auto','운동장 토론의 발언을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u3-C10","difficulty":2,"kind":"match","stem":"운동장 토론의 발언을 알맞게 이으세요.","pairs":[{"l":"부딪히는 사고가 자주 일어난다","r":"찬성 측 이유"},{"l":"학생 회의가 조사한 보건실 이용 자료","r":"찬성 측 근거"},{"l":"학년이 섞여 노는 놀이가 사라진다","r":"반대 측 이유"},{"l":"이름을 밝히지 않은 선생님의 말","r":"반대 측 근거"}],"mis":"K6-1-u3-X04","explanation":["까닭인지 자료인지 먼저 나눠요.","그다음 찬반을 갈라요.","이유 아래에 근거가 놓여요."],"asset":{"type":"speech","turns":[{"who":"사회자 라온","text":"지금부터 「점심시간 운동장은 학년별로 나누어 써야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 벼리","text":"점심시간 운동장은 학년별로 나누어 써야 합니다. 모든 학년이 한꺼번에 나오면 부딪히는 사고가 자주 일어나기 때문입니다. 학생 회의가 지난 학기에 조사한 보건실 이용 자료를 보면, 운동장에서 부딪혀 다친 학생이 예순두 명이었습니다."},{"who":"반대 측 새얀","text":"운동장을 학년별로 나누어서는 안 됩니다. 학년이 섞여 노는 놀이가 사라지기 때문입니다. 저희가 만난 어느 선생님께서도 학년이 섞여 놀 때 아이들이 서로 배우는 것이 많다고 하셨습니다."}]}}'::jsonb),
('g6_1_kor_u3_L02_basic#6','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C11',2,'mc','auto','새얀이의 첫 반론이 겨눈 곳은 어디인가요?',ARRAY['K6-1-u3-X14','K6-1-u3-X11','K6-1-u3-X06']::text[],false,'{"seq":6,"concept":"K6-1-u3-C11","difficulty":2,"kind":"mc","stem":"새얀이의 첫 반론이 겨눈 곳은 어디인가요?","options":[{"t":"찬성 측 근거 — 보건실 자료만으로는 학년이 섞였기 때문인지 알 수 없다는 점","correct":true},{"t":"벼리의 말투","mis":"K6-1-u3-X14"},{"t":"급식실 이야기","mis":"K6-1-u3-X11"},{"t":"반대 측 자신의 주장","mis":"K6-1-u3-X06"}],"explanation":["말투를 겨누지 않았어요.","새 이야기를 꺼내지 않았어요.","찬성 측 근거를 겨누었어요."],"asset":{"type":"speech","turns":[{"who":"반대 측 새얀","text":"보건실을 찾은 학생 수만으로는 학년이 섞였기 때문인지 알 수 없습니다. 같은 학년끼리 부딪힌 경우는 몇 건이었습니까?"},{"who":"찬성 측 벼리","text":"좋은 지적입니다. 같은 학년끼리 부딪힌 경우도 있었습니다. 다만 그 가운데 마흔한 건이 서로 다른 학년 사이에서 일어났습니다."},{"who":"찬성 측 벼리","text":"반대 측께 묻겠습니다. 근거로 드신 선생님이 어느 분인지 밝히지 않으셨습니다. 확인할 수 없는 말은 근거로 삼기 어렵지 않습니까?"},{"who":"반대 측 새얀","text":"성함까지 적어 두지는 못했습니다. 다만 여러 해 아이들을 보아 오신 분입니다."}]}}'::jsonb),
('g6_1_kor_u3_L02_basic#7','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C14',2,'mc','auto','주장 다지기에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X06']::text[],false,'{"seq":7,"concept":"K6-1-u3-C14","difficulty":2,"kind":"mc","stem":"주장 다지기에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"앞 두 단계에서 남은 것을 추려 자기편 주장을 다시 세운다","correct":true},{"t":"주장 펼치기에서 한 말을 그대로 되풀이한다","mis":"K6-1-u3-X15"},{"t":"반론에서 무너진 근거도 다시 꺼내 힘준다","mis":"K6-1-u3-X15"},{"t":"상대 주장을 처음으로 되받는다","mis":"K6-1-u3-X06"}],"explanation":["되풀이하는 단계가 아니에요.","무너진 근거를 꺼내면 약해져요.","남은 것을 추려 다시 세워요."]}'::jsonb),
('g6_1_kor_u3_L02_basic#8','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C17',2,'mc','auto','토론에서 해도 되는 말은 어느 것인가요?',ARRAY['K6-1-u3-X14','K6-1-u3-X11','K6-1-u3-X07']::text[],false,'{"seq":8,"concept":"K6-1-u3-C17","difficulty":2,"kind":"mc","stem":"토론에서 해도 되는 말은 어느 것인가요?","options":[{"t":"「말씀 잘 들었습니다. 다만 한 가지 여쭙겠습니다.」","correct":true},{"t":"「운동장 나누자고? 말도 안 돼.」","mis":"K6-1-u3-X14"},{"t":"「그런데 저는 요즘 급식이 더 문제라고 봅니다.」","mis":"K6-1-u3-X11"},{"t":"상대가 말하는 중간에 끼어들어 되받는 말","mis":"K6-1-u3-X07"}],"explanation":["반말로 깎아내리면 안 돼요.","주제와 상관없는 말이에요.","말차례를 지키고 높임말을 써요."]}'::jsonb),
('g6_1_kor_u3_L02_basic#9','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C16',2,'ox','auto','판정 결과는 어느 쪽 생각이 옳은지를 가려 주는 것이에요.',ARRAY['K6-1-u3-X17']::text[],false,'{"seq":9,"concept":"K6-1-u3-C16","difficulty":2,"kind":"ox","stem":"판정 결과는 어느 쪽 생각이 옳은지를 가려 주는 것이에요.","answer":"X","reason_options":[{"t":"정해 둔 기준으로 볼 때 어느 쪽이 더 설득력 있게 말했는지를 정하는 일이기 때문에","correct":true},{"t":"판정단은 언제나 옳은 답을 알기 때문에","mis":"K6-1-u3-X17"}],"mis":"K6-1-u3-X17","explanation":["토론이 끝나도 두 생각은 남아요.","기준이 달라지면 결과도 달라져요.","더 설득력 있게 말한 쪽을 정해요."]}'::jsonb),
('g6_1_kor_u3_L02_basic#10','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C12',3,'mc','auto','벼리가 새얀이의 반론에 답한 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":10,"concept":"K6-1-u3-C12","difficulty":3,"kind":"mc","stem":"벼리가 새얀이의 반론에 답한 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"인정할 것은 인정하고, 서로 다른 학년 사이 마흔한 건이라는 자료로 다시 세웠다","correct":true},{"t":"물은 것에 답하지 않고 「안전하니까 나눠야 합니다」만 되풀이했다","mis":"K6-1-u3-X13"},{"t":"새얀이의 말투를 문제 삼았다","mis":"K6-1-u3-X14"},{"t":"새로운 주제를 꺼내 말을 돌렸다","mis":"K6-1-u3-X11"}],"explanation":["벼리는 물은 것에 곧바로 답했어요.","사람을 겨누지 않았어요.","인정하고 자료로 다시 세웠어요."],"asset":{"type":"speech","turns":[{"who":"반대 측 새얀","text":"보건실을 찾은 학생 수만으로는 학년이 섞였기 때문인지 알 수 없습니다. 같은 학년끼리 부딪힌 경우는 몇 건이었습니까?"},{"who":"찬성 측 벼리","text":"좋은 지적입니다. 같은 학년끼리 부딪힌 경우도 있었습니다. 다만 그 가운데 마흔한 건이 서로 다른 학년 사이에서 일어났습니다."},{"who":"찬성 측 벼리","text":"반대 측께 묻겠습니다. 근거로 드신 선생님이 어느 분인지 밝히지 않으셨습니다. 확인할 수 없는 말은 근거로 삼기 어렵지 않습니까?"},{"who":"반대 측 새얀","text":"성함까지 적어 두지는 못했습니다. 다만 여러 해 아이들을 보아 오신 분입니다."}]}}'::jsonb),
('g6_1_kor_u3_L02_challenge#1','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C11',2,'mc','auto','반론하기에서 오간 말을 정리하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X12','K6-1-u3-X11','K6-1-u3-X38']::text[],false,'{"seq":1,"concept":"K6-1-u3-C11","difficulty":2,"kind":"mc","stem":"반론하기에서 오간 말을 정리하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"발언을 그대로 옮기지 않고 핵심만 요약한다","correct":true},{"t":"상대 발언을 한 글자도 빠짐없이 옮겨 적는다","mis":"K6-1-u3-X12"},{"t":"주장 펼치기에 나오지 않은 새 이야기도 함께 되받는다","mis":"K6-1-u3-X11"},{"t":"상대의 표정까지 자세히 적는다","mis":"K6-1-u3-X38"}],"explanation":["다 옮기면 다음 말을 놓쳐요.","펼친 내용에 대해서만 되받아요.","핵심만 요약해요."]}'::jsonb),
('g6_1_kor_u3_L02_challenge#2','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C14',2,'ox','auto','주장 다지기에서는 「요컨대」, 「따라서」 같은 말을 써서 짧고 힘 있게 말하면 좋아요.',ARRAY['K6-1-u3-X15']::text[],false,'{"seq":2,"concept":"K6-1-u3-C14","difficulty":2,"kind":"ox","stem":"주장 다지기에서는 「요컨대」, 「따라서」 같은 말을 써서 짧고 힘 있게 말하면 좋아요.","answer":"O","reason_options":[{"t":"정리하는 단계라는 표시가 되고 중심이 또렷해지기 때문에","correct":true},{"t":"같은 말을 여러 번 되풀이할수록 설득력이 커지기 때문에","mis":"K6-1-u3-X15"}],"mis":"K6-1-u3-X15","explanation":["이어 주는 말은 정리의 표시예요.","짧게 말하면 중심이 또렷해요.","되풀이가 아니라 다시 세우기예요."]}'::jsonb),
('g6_1_kor_u3_L02_challenge#3','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C16',3,'mc','auto','윤재의 판정에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X18','K6-1-u3-X16']::text[],false,'{"seq":3,"concept":"K6-1-u3-C16","difficulty":3,"kind":"mc","stem":"윤재의 판정에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"정한 두 기준으로 보아 찬성 측이 더 설득력 있었다는 것이지, 반대 측 생각이 틀렸다는 뜻은 아니다","correct":true},{"t":"반대 측 생각은 틀렸으니 버려야 한다","mis":"K6-1-u3-X17"},{"t":"판정이 마음에 들지 않으면 반대 측은 따르지 않아도 된다","mis":"K6-1-u3-X18"},{"t":"윤재가 평소 찬성 측 생각이어서 찬성 측을 골랐다","mis":"K6-1-u3-X16"}],"explanation":["판정은 옳고 그름을 가리지 않아요.","결과에 승복해요.","윤재는 기준을 밝히고 정했어요."],"asset":{"type":"speech","turns":[{"who":"판정단 윤재","text":"저희는 두 가지 기준으로 보았습니다. 첫째, 주장에 대한 타당한 이유를 냈는가. 둘째, 객관적이고 믿을 수 있는 근거를 냈는가."},{"who":"판정단 윤재","text":"두 기준으로 볼 때 찬성 측이 조금 더 설득력 있었다고 판정합니다. 반대 측의 이유는 충분히 공감이 갔지만 근거로 든 말의 출처가 확인되지 않았습니다. 반대 측이 안전을 다르게 지킬 방법을 낸 점은 좋았습니다."}]}}'::jsonb),
('g6_1_kor_u3_L02_challenge#4','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C13',3,'error','auto','반론하는 말을 했어요. 알맞지 않은 말을 한 친구는 누구인가요?',ARRAY['K6-1-u3-X14','K6-1-u3-X29','K6-1-u3-X27']::text[],false,'{"seq":4,"concept":"K6-1-u3-C13","difficulty":3,"kind":"error","stem":"반론하는 말을 했어요. 알맞지 않은 말을 한 친구는 누구인가요?","options":[{"t":"가온 — 「그렇게 준비도 안 하고 토론에 나온 것이 이해가 안 됩니다.」","correct":true,"mis_target":"K6-1-u3-X14"},{"t":"보미 — 「그 자료는 조사한 때가 나와 있지 않습니다.」","mis":"K6-1-u3-X29"},{"t":"지안 — 「그 이유는 주장과 이어지지 않아 보입니다.」","mis":"K6-1-u3-X27"}],"explanation":["보미는 근거를 겨누었어요.","지안은 이유를 겨누었어요.","가온은 사람을 겨누었어요."]}'::jsonb),
('g6_1_kor_u3_L02_challenge#5','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C12',3,'mc','auto','「그 자료는 언제 조사했는지 나와 있지 않습니다.」라는 반론에 대한 답변으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":5,"concept":"K6-1-u3-C12","difficulty":3,"kind":"mc","stem":"「그 자료는 언제 조사했는지 나와 있지 않습니다.」라는 반론에 대한 답변으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「지난 학기에 학생 회의가 조사한 자료입니다. 조사한 때는 자료 맨 위에 적혀 있습니다.」","correct":true},{"t":"「어쨌든 저희 주장이 맞습니다.」","mis":"K6-1-u3-X13"},{"t":"「그런 것까지 따지는 건 예의가 아닙니다.」","mis":"K6-1-u3-X14"},{"t":"「그런데 요즘은 급식이 더 문제입니다.」","mis":"K6-1-u3-X11"}],"explanation":["되풀이는 답변이 아니에요.","반론한 사람을 겨누면 안 돼요.","물은 그 지점에 곧바로 답해요."]}'::jsonb),
('g6_1_kor_u3_L02_challenge#6','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C10',3,'mc','auto','새얀이가 근거로 든 「어느 선생님」의 말이 힘을 잃은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X31','K6-1-u3-X27','K6-1-u3-X16']::text[],false,'{"seq":6,"concept":"K6-1-u3-C10","difficulty":3,"kind":"mc","stem":"새얀이가 근거로 든 「어느 선생님」의 말이 힘을 잃은 까닭은 무엇인가요?","options":[{"t":"누구의 말인지 밝히지 않아 확인할 수 없기 때문에","correct":true},{"t":"선생님의 말은 언제나 근거로 쓸 수 없기 때문에","mis":"K6-1-u3-X31"},{"t":"반대 측 이유와 상관없는 이야기였기 때문에","mis":"K6-1-u3-X27"},{"t":"새얀이의 목소리가 작았기 때문에","mis":"K6-1-u3-X16"}],"explanation":["전문가의 말도 근거가 될 수 있어요.","이유와는 이어졌어요.","누구의 말인지 밝혀야 해요."],"asset":{"type":"speech","turns":[{"who":"반대 측 새얀","text":"보건실을 찾은 학생 수만으로는 학년이 섞였기 때문인지 알 수 없습니다. 같은 학년끼리 부딪힌 경우는 몇 건이었습니까?"},{"who":"찬성 측 벼리","text":"좋은 지적입니다. 같은 학년끼리 부딪힌 경우도 있었습니다. 다만 그 가운데 마흔한 건이 서로 다른 학년 사이에서 일어났습니다."},{"who":"찬성 측 벼리","text":"반대 측께 묻겠습니다. 근거로 드신 선생님이 어느 분인지 밝히지 않으셨습니다. 확인할 수 없는 말은 근거로 삼기 어렵지 않습니까?"},{"who":"반대 측 새얀","text":"성함까지 적어 두지는 못했습니다. 다만 여러 해 아이들을 보아 오신 분입니다."}]}}'::jsonb),
('g6_1_kor_u3_L02_challenge#7','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C5',3,'match','auto','단계와 그 단계에서 하는 일을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u3-C5","difficulty":3,"kind":"match","stem":"단계와 그 단계에서 하는 일을 이으세요.","pairs":[{"l":"주장과 이유, 근거를 처음으로 내놓는다","r":"주장 펼치기"},{"l":"상대 근거의 허점을 짚고 그에 답한다","r":"반론하기"},{"l":"남은 것만 추려 자기편 주장을 다시 강조한다","r":"주장 다지기"},{"l":"기준을 밝히고 더 설득력 있는 쪽을 정한다","r":"판정하기"}],"mis":"K6-1-u3-X06","explanation":["처음 내놓는 단계부터 찾아요.","되받는 단계와 다시 세우는 단계를 갈라요.","정하는 단계는 맨 끝이에요."]}'::jsonb),
('g6_1_kor_u3_L02_challenge#8','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C14',4,'mc','auto','벼리와 새얀이의 주장 다지기를 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X14']::text[],false,'{"seq":8,"concept":"K6-1-u3-C14","difficulty":4,"kind":"mc","stem":"벼리와 새얀이의 주장 다지기를 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"벼리는 반론에서 확인된 마흔한 건을 추려 다시 세웠고, 새얀이는 안전을 지킬 다른 방법으로 자기 주장을 다졌다","correct":true},{"t":"두 사람 모두 처음 한 말을 그대로 되풀이했을 뿐이다","mis":"K6-1-u3-X15"},{"t":"새얀이는 확인되지 않은 선생님 말을 다시 꺼내 힘을 더했다","mis":"K6-1-u3-X15"},{"t":"주장 다지기에서는 상대 말투를 짚는 것이 가장 중요하다","mis":"K6-1-u3-X14"}],"explanation":["두 사람은 되풀이하지 않았어요.","새얀이는 무너진 근거를 꺼내지 않았어요.","남은 것을 추려 다시 세웠어요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"요컨대 문제는 안전입니다. 서로 다른 학년 사이에서 일어난 마흔한 건은 학년을 나누면 줄어듭니다. 따라서 점심시간 운동장은 학년별로 나누어 써야 합니다."},{"who":"반대 측 새얀","text":"저희가 지키려는 것은 함께 노는 시간입니다. 안전은 나누지 않고도 지킬 수 있습니다. 뛰는 곳과 공놀이하는 곳을 갈라 놓으면 됩니다. 따라서 운동장을 학년별로 나눌 필요는 없습니다."}]}}'::jsonb),
('g6_1_kor_u3_L02_challenge#9','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C13',4,'essay','teacher','반론이 「사람을 겨누지 않고 주장 · 이유 · 근거를 겨누어야 한다」는 것이 무슨 뜻인지 설명하고, 운동장 토론에서 반대 측 근거를 겨누는 반론을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C13","difficulty":4,"kind":"essay","stem":"반론이 「사람을 겨누지 않고 주장 · 이유 · 근거를 겨누어야 한다」는 것이 무슨 뜻인지 설명하고, 운동장 토론에서 반대 측 근거를 겨누는 반론을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 반론은 상대가 내놓은 주장이나 이유, 근거에서 잘못되거나 궁금한 곳을 짚는 것이지, 상대가 준비를 못 했다거나 말투가 거슬린다고 말하는 것이 아니다. 토론은 공식적인 말하기라 높임말을 쓰고 공격적인 말투를 피한다. 반론 — 「근거로 드신 선생님의 말은 어느 분이 언제 하신 말인지 밝혀지지 않아 확인하기 어렵습니다.」","scoring_points":["사람이 아니라 주장 · 이유 · 근거를 겨눈다는 뜻을 썼는가","높임말 · 존중하는 태도를 썼는가","반대 측 근거를 겨누는 반론을 높임말로 썼는가"]},"explanation":["겨누는 곳이 어디인지 써요.","공식적인 말하기임을 떠올려요.","근거의 허점을 짚어요."]}'::jsonb),
('g6_1_kor_u3_L02_challenge#10','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C15',4,'essay','teacher','판정할 때 명확한 기준이 왜 먼저 있어야 하는지 쓰고, 「판정 결과가 늘 옳은 것은 아니다」라는 말의 뜻을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C15","difficulty":4,"kind":"essay","stem":"판정할 때 명확한 기준이 왜 먼저 있어야 하는지 쓰고, 「판정 결과가 늘 옳은 것은 아니다」라는 말의 뜻을 설명하세요.","answer_guide":{"answer":"예: 무엇을 보고 정했는지 밝히지 않으면 판정이 판정단의 취향이 되어 토론자가 결과에 승복하기 어렵다. 그래서 「타당한 이유를 냈는가 · 믿을 수 있는 근거를 냈는가」처럼 기준을 먼저 밝혀야 한다. 판정은 어느 쪽 생각이 옳은지 가리는 일이 아니라 정한 기준으로 볼 때 어느 쪽이 더 설득력 있게 말했는지 정하는 일이다. 그래서 기준이 달라지면 결과도 달라질 수 있고, 판정 뒤에도 두 생각은 그대로 남는다.","scoring_points":["기준이 없으면 취향이 되고 승복하기 어렵다는 점을 썼는가","판정은 더 설득력 있게 말한 쪽을 정하는 일임을 썼는가","기준에 따라 결과가 달라질 수 있음을 썼는가"]},"explanation":["기준이 없을 때를 떠올려요.","판정이 무엇을 정하는지 써요.","기준이 바뀌면 어떻게 될지 써요."]}'::jsonb),
('g6_1_kor_u3_L04_basic#1','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C18',1,'mc','auto','우리 반 토론 주제로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":1,"concept":"K6-1-u3-C18","difficulty":1,"kind":"mc","stem":"우리 반 토론 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"청소 당번을 제비뽑기로 정할 것인가","correct":true},{"t":"우리 반 학생 수가 몇 명인가","mis":"K6-1-u3-X01"},{"t":"지난주 급식 식단에 무엇이 나왔는가","mis":"K6-1-u3-X01"},{"t":"복도에서 뛰지 말아야 하는가","mis":"K6-1-u3-X01"}],"explanation":["학생 수는 세어 보면 알아요.","식단은 찾아보면 확인돼요.","찬반이 갈리고 우리가 바꿔 볼 수 있어야 해요."]}'::jsonb),
('g6_1_kor_u3_L04_basic#2','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C23',1,'match','auto','역할과 할 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u3-C23","difficulty":1,"kind":"match","stem":"역할과 할 일을 알맞게 이으세요.","pairs":[{"l":"주제와 규칙을 알리고 말차례를 이끈다","r":"사회자"},{"l":"근거를 들어 간결하고 분명하게 주장한다","r":"토론자"},{"l":"기준을 정해 공정하게 판정한다","r":"판정단"},{"l":"메모하며 듣고 잘한 곳을 짚어 준다","r":"청중"}],"mis":"K6-1-u3-X25","explanation":["이끄는 사람은 사회자예요.","말하는 사람은 토론자예요.","정하는 사람은 판정단, 듣고 짚는 사람은 청중이에요."]}'::jsonb),
('g6_1_kor_u3_L04_basic#3','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C22',1,'ox','auto','예상되는 상대측 반론과 답변을 미리 적어 보는 일은 건너뛰어도 돼요.',ARRAY['K6-1-u3-X23']::text[],false,'{"seq":3,"concept":"K6-1-u3-C22","difficulty":1,"kind":"ox","stem":"예상되는 상대측 반론과 답변을 미리 적어 보는 일은 건너뛰어도 돼요.","answer":"X","reason_options":[{"t":"적어 보는 동안 내 근거의 약한 곳이 먼저 보이기 때문에","correct":true},{"t":"토론에서는 그때그때 떠오르는 대로 답하면 되기 때문에","mis":"K6-1-u3-X23"}],"mis":"K6-1-u3-X23","explanation":["상대의 반론을 미리 떠올려요.","내 근거의 약한 곳이 보여요.","그래서 건너뛰지 않아요."]}'::jsonb),
('g6_1_kor_u3_L04_basic#4','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C21',1,'mc','auto','전문가의 의견을 근거로 쓸 때 반드시 함께 적어 둘 것은 어느 것인가요?',ARRAY['K6-1-u3-X38','K6-1-u3-X04','K6-1-u3-X22']::text[],false,'{"seq":4,"concept":"K6-1-u3-C21","difficulty":1,"kind":"mc","stem":"전문가의 의견을 근거로 쓸 때 반드시 함께 적어 둘 것은 어느 것인가요?","options":[{"t":"누구의 말인지","correct":true},{"t":"그 사람의 목소리","mis":"K6-1-u3-X38"},{"t":"내가 그 말을 좋아하는지","mis":"K6-1-u3-X04"},{"t":"아무것도 적지 않아도 된다","mis":"K6-1-u3-X22"}],"explanation":["목소리는 근거와 상관없어요.","내 마음은 근거가 아니에요.","누구의 말인지 적어야 확인돼요."]}'::jsonb),
('g6_1_kor_u3_L04_basic#5','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C20',2,'mc','auto','준비표의 「우리 반 스물여섯 명에게 물어보니 …」는 어느 층인가요?',ARRAY['K6-1-u3-X05','K6-1-u3-X04','K6-1-u3-X13']::text[],false,'{"seq":5,"concept":"K6-1-u3-C20","difficulty":2,"kind":"mc","stem":"준비표의 「우리 반 스물여섯 명에게 물어보니 …」는 어느 층인가요?","options":[{"t":"근거","correct":true},{"t":"주장","mis":"K6-1-u3-X05"},{"t":"이유","mis":"K6-1-u3-X04"},{"t":"우리 측 답변","mis":"K6-1-u3-X13"}],"explanation":["하자고 내세운 말이 아니에요.","까닭을 말한 문장도 아니에요.","물어서 센 자료는 근거예요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 청소 당번은 제비뽑기로 정해야 한다.","주장 — 청소 당번은 제비뽑기로 정해야 합니다.","이유 — 힘든 곳을 늘 같은 사람이 맡게 되는 일을 막을 수 있기 때문입니다.","근거 — 우리 반 스물여섯 명에게 물어보니, 지난 학기에 화장실 청소를","세 번 넘게 맡은 학생이 아홉 명이었습니다.","예상 반론 — 제비뽑기는 잘 맞는 일을 못 살립니다.","우리 측 답변 — 뽑은 뒤 서로 바꿀 수 있게 하면 풀립니다."],"title":"찬성 측 토론 준비표"}}'::jsonb),
('g6_1_kor_u3_L04_basic#6','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C19',2,'mc','auto','토론 주제가 정해진 뒤 가장 먼저 할 일은 어느 것인가요?',ARRAY['K6-1-u3-X20','K6-1-u3-X06']::text[],false,'{"seq":6,"concept":"K6-1-u3-C19","difficulty":2,"kind":"mc","stem":"토론 주제가 정해진 뒤 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"모두가 자기 생각을 먼저 정한다","correct":true},{"t":"사회자와 판정단부터 뽑는다","mis":"K6-1-u3-X20"},{"t":"친한 친구끼리 한편이 된다","mis":"K6-1-u3-X20"},{"t":"곧바로 판정 기준을 발표한다","mis":"K6-1-u3-X06"}],"explanation":["역할은 그다음에 나눠요.","친한 사이로 편을 정하지 않아요.","먼저 모두가 자기 생각을 정해요."]}'::jsonb),
('g6_1_kor_u3_L04_basic#7','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C22',2,'mc','auto','준비표의 「우리 측 답변」이 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X11','K6-1-u3-X14']::text[],false,'{"seq":7,"concept":"K6-1-u3-C22","difficulty":2,"kind":"mc","stem":"준비표의 「우리 측 답변」이 알맞은 까닭은 무엇인가요?","options":[{"t":"「잘 맞는 일을 못 살린다」는 반론에 서로 바꿀 수 있게 하는 방법으로 곧바로 답했기 때문에","correct":true},{"t":"「어쨌든 공평하다」고만 했기 때문에","mis":"K6-1-u3-X13"},{"t":"반론과 상관없는 이야기를 했기 때문에","mis":"K6-1-u3-X11"},{"t":"반론한 친구의 말투를 짚었기 때문에","mis":"K6-1-u3-X14"}],"explanation":["되풀이는 답변이 아니에요.","반론과 이어지게 답해요.","물은 그 지점에 곧바로 답했어요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 청소 당번은 제비뽑기로 정해야 한다.","주장 — 청소 당번은 제비뽑기로 정해야 합니다.","이유 — 힘든 곳을 늘 같은 사람이 맡게 되는 일을 막을 수 있기 때문입니다.","근거 — 우리 반 스물여섯 명에게 물어보니, 지난 학기에 화장실 청소를","세 번 넘게 맡은 학생이 아홉 명이었습니다.","예상 반론 — 제비뽑기는 잘 맞는 일을 못 살립니다.","우리 측 답변 — 뽑은 뒤 서로 바꿀 수 있게 하면 풀립니다."],"title":"찬성 측 토론 준비표"}}'::jsonb),
('g6_1_kor_u3_L04_basic#8','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C25',2,'ox','auto','반론하기에서 감정이 앞설 때일수록 말차례를 기다리고 한 번에 한 가지만 되받아요.',ARRAY['K6-1-u3-X26']::text[],false,'{"seq":8,"concept":"K6-1-u3-C25","difficulty":2,"kind":"ox","stem":"반론하기에서 감정이 앞설 때일수록 말차례를 기다리고 한 번에 한 가지만 되받아요.","answer":"O","reason_options":[{"t":"지나치게 뜨거워지면 서로의 말이 들리지 않아 되받을 수도 없기 때문에","correct":true},{"t":"목소리를 높여야 상대가 물러서기 때문에","mis":"K6-1-u3-X26"}],"mis":"K6-1-u3-X26","explanation":["반론하기는 뜨거워지기 쉬워요.","듣지 못하면 되받을 수 없어요.","침착하게 한 가지씩 되받아요."]}'::jsonb),
('g6_1_kor_u3_L04_basic#9','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C24',2,'mc','auto','진행 순서에서 「반대 측 반론과 찬성 측 답변」 바로 다음에 오는 것은 어느 것인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":9,"concept":"K6-1-u3-C24","difficulty":2,"kind":"mc","stem":"진행 순서에서 「반대 측 반론과 찬성 측 답변」 바로 다음에 오는 것은 어느 것인가요?","options":[{"t":"찬성 측 반론과 반대 측 답변","correct":true},{"t":"찬성 측 주장 펼치기","mis":"K6-1-u3-X06"},{"t":"판정단의 판정","mis":"K6-1-u3-X06"},{"t":"반대 측 주장 다지기","mis":"K6-1-u3-X06"}],"explanation":["주장 펼치기는 이미 끝났어요.","판정은 맨 끝이에요.","이번에는 찬성 측이 되받아요."]}'::jsonb),
('g6_1_kor_u3_L04_basic#10','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C18',3,'mc','auto','「늘 그래 왔던 일에도 꼭 그래야 할까」라고 물어보라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X01','K6-1-u3-X19']::text[],false,'{"seq":10,"concept":"K6-1-u3-C18","difficulty":3,"kind":"mc","stem":"「늘 그래 왔던 일에도 꼭 그래야 할까」라고 물어보라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"당연해 보이던 곳에서 찬반이 갈리는 좋은 주제가 나오기 때문에","correct":true},{"t":"늘 하던 일은 모두 잘못된 일이기 때문에","mis":"K6-1-u3-X09"},{"t":"답이 정해진 일이 가장 좋은 주제이기 때문에","mis":"K6-1-u3-X01"},{"t":"우리가 바꿀 수 없는 일일수록 토론이 재미있기 때문에","mis":"K6-1-u3-X19"}],"explanation":["늘 하던 일이 모두 잘못된 것은 아니에요.","답이 정해진 일은 토론이 안 돼요.","당연한 곳에서 좋은 주제가 나와요."]}'::jsonb),
('g6_1_kor_u3_L04_challenge#1','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C20',2,'mc','auto','토론 준비표에 이유를 두세 가지 준비하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X05','K6-1-u3-X15']::text[],false,'{"seq":1,"concept":"K6-1-u3-C20","difficulty":2,"kind":"mc","stem":"토론 준비표에 이유를 두세 가지 준비하는 까닭은 무엇인가요?","options":[{"t":"하나가 무너져도 남은 것으로 버틸 수 있기 때문에","correct":true},{"t":"이유가 많을수록 판정단이 무조건 점수를 주기 때문에","mis":"K6-1-u3-X30"},{"t":"이유가 많으면 근거를 찾지 않아도 되기 때문에","mis":"K6-1-u3-X05"},{"t":"같은 이유를 여러 번 말하기 위해서","mis":"K6-1-u3-X15"}],"explanation":["개수만으로 점수를 받지 않아요.","이유마다 근거가 필요해요.","하나가 무너져도 버틸 수 있어요."]}'::jsonb),
('g6_1_kor_u3_L04_challenge#2','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C23',2,'ox','auto','판정단은 자기 생각과 같은 편이면 점수를 조금 더 줘도 돼요.',ARRAY['K6-1-u3-X24']::text[],false,'{"seq":2,"concept":"K6-1-u3-C23","difficulty":2,"kind":"ox","stem":"판정단은 자기 생각과 같은 편이면 점수를 조금 더 줘도 돼요.","answer":"X","reason_options":[{"t":"판정단은 정한 기준으로 공정하게 판정해야 하기 때문에","correct":true},{"t":"판정단도 자기 생각이 있기 때문에","mis":"K6-1-u3-X24"}],"mis":"K6-1-u3-X24","explanation":["판정단도 생각이 있을 수 있어요.","그러나 판정은 기준으로 해요.","같은 편이라고 후하게 주지 않아요."]}'::jsonb),
('g6_1_kor_u3_L04_challenge#3','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C21',3,'mc','auto','「힘든 곳을 늘 같은 사람이 맡게 된다」는 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X29','K6-1-u3-X27']::text[],false,'{"seq":3,"concept":"K6-1-u3-C21","difficulty":3,"kind":"mc","stem":"「힘든 곳을 늘 같은 사람이 맡게 된다」는 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지난 학기 청소 점검표에 남은, 학생별 화장실 청소 횟수 기록","correct":true},{"t":"청소가 귀찮다고 느낀 적이 있다는 내 생각","mis":"K6-1-u3-X04"},{"t":"제비뽑기가 재미있어 보인다는 친구 한 명의 말","mis":"K6-1-u3-X29"},{"t":"점심시간 운동장 사고 자료","mis":"K6-1-u3-X27"}],"explanation":["내 생각은 근거가 아니에요.","친구 한 명의 말은 흐릿해요.","이유와 곧바로 이어지는 기록이에요."]}'::jsonb),
('g6_1_kor_u3_L04_challenge#4','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C22',3,'mc','auto','「제비뽑기를 하면 힘이 센 학생이 가벼운 구역을 뽑을 수도 있습니다.」라는 반론에 대한 답변으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X08','K6-1-u3-X14']::text[],false,'{"seq":4,"concept":"K6-1-u3-C22","difficulty":3,"kind":"mc","stem":"「제비뽑기를 하면 힘이 센 학생이 가벼운 구역을 뽑을 수도 있습니다.」라는 반론에 대한 답변으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「그 점은 뽑은 뒤 서로 바꿀 수 있게 하면 풀립니다. 처음 나누는 방법이 공평해야 바꾸는 일도 공평해집니다.」","correct":true},{"t":"「어쨌든 제비뽑기가 공평합니다. 공평하니까 공평합니다.」","mis":"K6-1-u3-X13"},{"t":"「그 이야기는 들을 필요가 없습니다.」","mis":"K6-1-u3-X08"},{"t":"「힘센 사람이 양보하면 되는데 그것도 모르십니까?」","mis":"K6-1-u3-X14"}],"explanation":["되풀이는 답이 아니에요.","반론을 듣고 답해야 해요.","물은 점을 풀어 주며 답해요."]}'::jsonb),
('g6_1_kor_u3_L04_challenge#5','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C23',3,'error','auto','토론에서 맡은 일을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X37','K6-1-u3-X25','K6-1-u3-X24']::text[],false,'{"seq":5,"concept":"K6-1-u3-C23","difficulty":3,"kind":"error","stem":"토론에서 맡은 일을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"다온(청중) — 「청중은 할 일이 없으니 쉬면서 들으면 돼.」","correct":true,"mis_target":"K6-1-u3-X37"},{"t":"이준(사회자) — 「주제에서 벗어나면 다시 주제로 이끌게.」","mis":"K6-1-u3-X25"},{"t":"하린(판정단) — 「내 생각과 같은 편이라고 후하게 주지 않을게.」","mis":"K6-1-u3-X24"}],"explanation":["이준은 사회자의 일을 바르게 말했어요.","하린은 판정단의 일을 바르게 말했어요.","청중도 메모하고 잘한 곳을 짚어요."]}'::jsonb),
('g6_1_kor_u3_L04_challenge#6','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C24',3,'mc','auto','토론 단계 사이에 협의 시간을 두는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X16','K6-1-u3-X06']::text[],false,'{"seq":6,"concept":"K6-1-u3-C24","difficulty":3,"kind":"mc","stem":"토론 단계 사이에 협의 시간을 두는 까닭은 무엇인가요?","options":[{"t":"같은 편끼리 반론과 답변을 맞춰 두기 위해서","correct":true},{"t":"상대 편 원고를 몰래 보기 위해서","mis":"K6-1-u3-X09"},{"t":"판정단이 미리 승패를 정하기 위해서","mis":"K6-1-u3-X16"},{"t":"토론을 빨리 끝내기 위해서","mis":"K6-1-u3-X06"}],"explanation":["몰래 보는 것은 규칙을 어겨요.","판정은 끝난 뒤 기준으로 해요.","같은 편끼리 맞춰 두는 시간이에요."]}'::jsonb),
('g6_1_kor_u3_L04_challenge#7','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C19',3,'mc','auto','찬성과 반대를 비슷한 수로 나누는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X20','K6-1-u3-X16']::text[],false,'{"seq":7,"concept":"K6-1-u3-C19","difficulty":3,"kind":"mc","stem":"찬성과 반대를 비슷한 수로 나누는 까닭은 무엇인가요?","options":[{"t":"한쪽이 얇으면 토론이 기울어 팽팽하게 겨룰 수 없기 때문에","correct":true},{"t":"많은 쪽이 무조건 이기게 하려고","mis":"K6-1-u3-X09"},{"t":"역할을 먼저 정해야 하기 때문에","mis":"K6-1-u3-X20"},{"t":"판정단이 수를 세어 판정하기 때문에","mis":"K6-1-u3-X16"}],"explanation":["수로 이기는 것이 아니에요.","역할은 생각을 정한 다음이에요.","팽팽해야 토론이 살아나요."]}'::jsonb),
('g6_1_kor_u3_L04_challenge#8','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C25',4,'mc','auto','반론하기에서 말이 겹치고 목소리가 커지기 시작했어요. 토론자가 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X26','K6-1-u3-X14','K6-1-u3-X08']::text[],false,'{"seq":8,"concept":"K6-1-u3-C25","difficulty":4,"kind":"mc","stem":"반론하기에서 말이 겹치고 목소리가 커지기 시작했어요. 토론자가 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말차례를 기다렸다가 상대 근거의 가장 약한 한 곳만 침착하게 되받는다","correct":true},{"t":"더 큰 목소리로 한꺼번에 여러 가지를 몰아친다","mis":"K6-1-u3-X26"},{"t":"상대 말투가 거칠다고 맞받아친다","mis":"K6-1-u3-X14"},{"t":"준비한 원고를 처음부터 다시 읽는다","mis":"K6-1-u3-X08"}],"explanation":["몰아치면 서로 들리지 않아요.","말투가 아니라 근거를 겨눠요.","침착하게 한 가지씩 되받아요."]}'::jsonb),
('g6_1_kor_u3_L04_challenge#9','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C20',4,'essay','teacher','「우리 반 앉는 곳을 한 달마다 바꾸어야 한다」를 주제로 찬성이나 반대 가운데 하나를 골라 토론 준비표(주장 · 이유 · 근거)를 쓰고, 예상 반론과 답변을 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C20","difficulty":4,"kind":"essay","stem":"「우리 반 앉는 곳을 한 달마다 바꾸어야 한다」를 주제로 찬성이나 반대 가운데 하나를 골라 토론 준비표(주장 · 이유 · 근거)를 쓰고, 예상 반론과 답변을 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 주장 — 앉는 곳을 한 달마다 바꾸어야 한다. 이유 — 여러 친구와 가까워질 기회가 생기기 때문이다. 근거 — 우리 반 스물여섯 명에게 지난주에 물어보니 열여덟 명이 「옆자리 친구와 더 친해졌다」고 답했다. 예상 반론 — 자주 바꾸면 수업에 집중하기 어렵다. 답변 — 한 달은 새 자리에 익숙해지기에 충분한 시간이고, 설문에서 집중이 어려웠다고 답한 사람은 적었다.","scoring_points":["주장 · 이유 · 근거를 층에 맞게 썼는가","근거에 누구에게 언제 물었는지 밝혔는가","예상 반론에 곧바로 답하는 답변을 썼는가"]},"explanation":["주장 · 이유 · 근거를 차례로 써요.","확인할 수 있는 근거를 써요.","반론에 곧바로 답해요."]}'::jsonb),
('g6_1_kor_u3_L04_challenge#10','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C23',4,'essay','teacher','토론의 네 역할 가운데 두 가지를 골라 각 역할이 할 일과 지켜야 할 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C23","difficulty":4,"kind":"essay","stem":"토론의 네 역할 가운데 두 가지를 골라 각 역할이 할 일과 지켜야 할 점을 쓰세요.","answer_guide":{"answer":"예: 사회자는 토론 주제와 규칙을 알리고 말차례를 이끌며, 토론이 주제에서 벗어나지 않게 한다. 어느 쪽에도 기울지 않아야 한다. 판정단은 판정 기준을 미리 정해 적어 두고, 토론에서 나온 말과 자료로 공정하게 판정한다. 자기 생각과 같은 편이라고 후하게 주지 않아야 한다.","scoring_points":["두 역할을 골랐는가","각 역할이 할 일을 썼는가","각 역할이 지켜야 할 점을 썼는가"]},"explanation":["네 역할 가운데 둘을 골라요.","할 일을 써요.","지켜야 할 점을 써요."]}'::jsonb),
('g6_1_kor_u3_L06_basic#1','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C26',1,'match','auto','근거를 따지는 기준과 확인하는 물음을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K6-1-u3-C26","difficulty":1,"kind":"match","stem":"근거를 따지는 기준과 확인하는 물음을 이으세요.","pairs":[{"l":"주장이나 이유와 가깝게 이어지는가?","r":"관련성"},{"l":"어디서 나온 자료인지 확인할 수 있는가?","r":"신뢰성"},{"l":"언제 누구를 조사했는지 밝혀져 있는가?","r":"충분성"}],"mis":"K6-1-u3-X35","explanation":["가까운지 묻는 물음이 있어요.","어디서 왔는지 묻는 물음이 있어요.","얼마나 자세한지 묻는 물음이 있어요."]}'::jsonb),
('g6_1_kor_u3_L06_basic#2','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C4',1,'mc','auto','글 ㉮의 주장은 무엇인가요?',ARRAY['K6-1-u3-X04']::text[],false,'{"seq":2,"concept":"K6-1-u3-C4","difficulty":1,"kind":"mc","stem":"글 ㉮의 주장은 무엇인가요?","options":[{"t":"학교 운동장은 저녁에도 마을 사람들에게 열어야 한다","correct":true},{"t":"동네에 마음 놓고 걷거나 뛸 곳이 마땅치 않다","mis":"K6-1-u3-X04"},{"t":"도시 계획과가 시민 사백 명에게 물은 조사","mis":"K6-1-u3-X04"},{"t":"운동장은 저녁에 비어 있다","mis":"K6-1-u3-X04"}],"explanation":["뛸 곳이 마땅치 않다는 것은 이유예요.","조사는 근거예요.","하자고 내세운 생각이 주장이에요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에도 마을 사람들에게 열어야 합니다.","우리 동네에는 마음 놓고 걷거나 뛸 곳이 마땅치 않기 때문입니다.","지난해 우리 시 도시 계획과가 시민 사백 명에게 물은 조사를 보면,","열 명 가운데 일곱 명이 가까운 곳에 운동할 공간이 부족하다고 답했습니다.","운동장은 낮 동안만 쓰이고 저녁에는 비어 있습니다.","열어 두는 시간을 정하고 관리하는 분을 두면 학교와 마을 모두에 도움이 됩니다."],"title":"글 ㉮ 「학교 운동장은 저녁에도 마을에 열어야 한다」"}}'::jsonb),
('g6_1_kor_u3_L06_basic#3','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C10',1,'mc','auto','글 ㉯가 든 근거는 무엇인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05']::text[],false,'{"seq":3,"concept":"K6-1-u3-C10","difficulty":1,"kind":"mc","stem":"글 ㉯가 든 근거는 무엇인가요?","options":[{"t":"교육청이 올해 낸 학교 시설 개방 점검 자료","correct":true},{"t":"학교는 학생이 안전하게 지내야 하는 곳이다","mis":"K6-1-u3-X04"},{"t":"시에서 걷기 좋은 길을 새로 내는 쪽이 낫다","mis":"K6-1-u3-X04"},{"t":"학교 운동장은 저녁에는 닫아야 한다","mis":"K6-1-u3-X05"}],"explanation":["안전하게 지내야 한다는 것은 이유예요.","길을 내자는 것은 글쓴이의 생각이에요.","어느 기관이 언제 낸 자료인지 밝혀진 것이 근거예요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에는 닫아야 합니다.","학교는 무엇보다 학생이 안전하게 지내야 하는 곳이기 때문입니다.","저녁에 문을 열어 두면 누가 드나드는지 알기 어렵습니다.","우리 교육청이 올해 낸 학교 시설 개방 점검 자료를 보면,","저녁에 운동장을 연 학교 스물여덟 곳 가운데 열아홉 곳이","쓰레기와 시설 파손 때문에 어려움을 겪는다고 답했습니다.","시에서 걷기 좋은 길을 새로 내는 쪽이 낫습니다."],"title":"글 ㉯ 「학교 운동장은 저녁에는 닫아야 한다」"}}'::jsonb),
('g6_1_kor_u3_L06_basic#4','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C28',1,'ox','auto','근거 자료를 다섯 개 넘게 내면 그것만으로 충분성을 갖춘 거예요.',ARRAY['K6-1-u3-X30']::text[],false,'{"seq":4,"concept":"K6-1-u3-C28","difficulty":1,"kind":"ox","stem":"근거 자료를 다섯 개 넘게 내면 그것만으로 충분성을 갖춘 거예요.","answer":"X","reason_options":[{"t":"충분하다는 것은 자료 하나가 언제 · 누구를 · 어떻게 조사했는지 밝혀져 있다는 뜻이기 때문에","correct":true},{"t":"자료는 많을수록 무조건 힘이 세기 때문에","mis":"K6-1-u3-X30"}],"mis":"K6-1-u3-X30","explanation":["개수를 늘려도 흐릿하면 그대로예요.","자세한지가 중요해요.","자료 하나라도 자세하면 충분할 수 있어요."]}'::jsonb),
('g6_1_kor_u3_L06_basic#5','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C27',2,'mc','auto','근거로 삼기 어려운 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X31']::text[],false,'{"seq":5,"concept":"K6-1-u3-C27","difficulty":2,"kind":"mc","stem":"근거로 삼기 어려운 것은 어느 것인가요?","options":[{"t":"어디에서 봤는지 모르는 동영상에서 들은 이야기","correct":true},{"t":"우리 시가 지난해 시민 사백 명에게 물은 조사","mis":"K6-1-u3-X35"},{"t":"교육청이 올해 낸 학교 시설 점검 자료","mis":"K6-1-u3-X35"},{"t":"모둠이 한 시간 동안 운동장 출입을 센 기록","mis":"K6-1-u3-X31"}],"explanation":["시의 조사는 출처와 때가 밝혀져 있어요.","교육청 자료도 확인할 수 있어요.","누가 만든 무엇인지 모르면 힘을 내지 못해요."]}'::jsonb),
('g6_1_kor_u3_L06_basic#6','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C29',2,'mc','auto','하윤이와 도겸이의 경험 가운데 근거로 쓰기에 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X32','K6-1-u3-X31']::text[],false,'{"seq":6,"concept":"K6-1-u3-C29","difficulty":2,"kind":"mc","stem":"하윤이와 도겸이의 경험 가운데 근거로 쓰기에 알맞은 것은 어느 것인가요?","options":[{"t":"도겸 — 정한 시간 동안 출입을 세어 정리했기 때문에","correct":true},{"t":"하윤 — 직접 겪은 일이라 더 생생하기 때문에","mis":"K6-1-u3-X32"},{"t":"둘 다 아니다 — 경험은 근거가 될 수 없기 때문에","mis":"K6-1-u3-X31"},{"t":"둘 다 알맞다 — 경험이면 무엇이든 되기 때문에","mis":"K6-1-u3-X32"}],"explanation":["지갑을 주운 일은 드문 일이에요.","경험도 근거가 될 수 있어요.","세거나 재어 정리해야 해요."],"asset":{"type":"speech","turns":[{"who":"하윤","text":"저는 저녁 운동장에서 지갑을 주운 적이 있습니다. 그러니 저녁 운동장은 위험합니다."},{"who":"도겸","text":"저희 모둠이 저녁 여섯 시부터 한 시간 동안 운동장 출입을 세었더니 마흔두 명이었습니다."}]}}'::jsonb),
('g6_1_kor_u3_L06_basic#7','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C30',2,'mc','auto','믿을 만한 자료를 고르는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X33','K6-1-u3-X27']::text[],false,'{"seq":7,"concept":"K6-1-u3-C30","difficulty":2,"kind":"mc","stem":"믿을 만한 자료를 고르는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"공신력 있는 곳에서 가장 최근에 낸, 주제와 직접 이어지는 자료를 고른다","correct":true},{"t":"무언가를 팔려는 광고 글도 숫자가 있으면 쓴다","mis":"K6-1-u3-X33"},{"t":"오래된 자료도 숫자가 크면 쓴다","mis":"K6-1-u3-X33"},{"t":"주제와 비슷해 보이는 다른 주제의 자료를 쓴다","mis":"K6-1-u3-X27"}],"explanation":["광고에 가까운 글은 피해요.","오래된 수치는 지금과 다를 수 있어요.","주제와 직접 이어져야 해요."]}'::jsonb),
('g6_1_kor_u3_L06_basic#8','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C31',2,'mc','auto','근거를 말할 때 먼저 밝히면 좋은 것은 어느 것인가요?',ARRAY['K6-1-u3-X34','K6-1-u3-X30']::text[],false,'{"seq":8,"concept":"K6-1-u3-C31","difficulty":2,"kind":"mc","stem":"근거를 말할 때 먼저 밝히면 좋은 것은 어느 것인가요?","options":[{"t":"누가 언제 낸 자료인지","correct":true},{"t":"「어디서 봤는데」라는 말","mis":"K6-1-u3-X34"},{"t":"자료의 세부 사항 전부","mis":"K6-1-u3-X34"},{"t":"자료를 찾는 데 걸린 시간","mis":"K6-1-u3-X30"}],"explanation":["「어디서 봤는데」는 자료를 흔들어요.","세부 사항은 추려서 전해요.","출처를 먼저 밝혀요."]}'::jsonb),
('g6_1_kor_u3_L06_basic#9','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C29',2,'ox','auto','내가 겪은 일은 어떤 경우에도 근거가 될 수 없어요.',ARRAY['K6-1-u3-X31']::text[],false,'{"seq":9,"concept":"K6-1-u3-C29","difficulty":2,"kind":"ox","stem":"내가 겪은 일은 어떤 경우에도 근거가 될 수 없어요.","answer":"X","reason_options":[{"t":"여러 사람이 그럴 만하다고 여길 일을 세거나 재어 정리하면 근거가 될 수 있기 때문에","correct":true},{"t":"경험은 모두 나에게만 일어난 일이기 때문에","mis":"K6-1-u3-X31"}],"mis":"K6-1-u3-X31","explanation":["드문 일은 근거가 되기 어려워요.","그러나 모든 경험이 그런 건 아니에요.","세거나 재어 정리하면 근거가 돼요."]}'::jsonb),
('g6_1_kor_u3_L06_basic#10','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C26',3,'mc','auto','글 ㉮의 근거를 세 물음으로 따져 본 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X30','K6-1-u3-X27']::text[],false,'{"seq":10,"concept":"K6-1-u3-C26","difficulty":3,"kind":"mc","stem":"글 ㉮의 근거를 세 물음으로 따져 본 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뛸 곳이 마땅치 않다는 이유와 이어지고, 도시 계획과라는 출처와 지난해 · 시민 사백 명이라는 조사 대상이 밝혀져 있다","correct":true},{"t":"숫자가 나왔으니 따져 볼 필요 없이 타당하다","mis":"K6-1-u3-X35"},{"t":"조사한 사람이 사백 명뿐이라 근거가 될 수 없다","mis":"K6-1-u3-X30"},{"t":"운동장 이야기라서 이유와 관련이 없다","mis":"K6-1-u3-X27"}],"explanation":["숫자만 보고 넘어가지 않아요.","사람 수만으로 따지지 않아요.","세 물음을 한 번씩 던져 봐요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에도 마을 사람들에게 열어야 합니다.","우리 동네에는 마음 놓고 걷거나 뛸 곳이 마땅치 않기 때문입니다.","지난해 우리 시 도시 계획과가 시민 사백 명에게 물은 조사를 보면,","열 명 가운데 일곱 명이 가까운 곳에 운동할 공간이 부족하다고 답했습니다.","운동장은 낮 동안만 쓰이고 저녁에는 비어 있습니다.","열어 두는 시간을 정하고 관리하는 분을 두면 학교와 마을 모두에 도움이 됩니다."],"title":"글 ㉮ 「학교 운동장은 저녁에도 마을에 열어야 한다」"}}'::jsonb),
('g6_1_kor_u3_L06_challenge#1','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C27',2,'mc','auto','「많은 사람이 그렇게 답했습니다.」라는 근거가 힘을 내지 못하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X31','K6-1-u3-X30','K6-1-u3-X27']::text[],false,'{"seq":1,"concept":"K6-1-u3-C27","difficulty":2,"kind":"mc","stem":"「많은 사람이 그렇게 답했습니다.」라는 근거가 힘을 내지 못하는 까닭은 무엇인가요?","options":[{"t":"언제 몇 명에게 물었는지 없기 때문에","correct":true},{"t":"사람에게 물은 자료는 근거가 될 수 없기 때문에","mis":"K6-1-u3-X31"},{"t":"많은 사람이 답했으니 오히려 충분하기 때문에","mis":"K6-1-u3-X30"},{"t":"주장과 반대되는 말이기 때문에","mis":"K6-1-u3-X27"}],"explanation":["설문도 근거가 될 수 있어요.","「많은」은 흐릿한 말이에요.","언제 · 누구를이 없어요."]}'::jsonb),
('g6_1_kor_u3_L06_challenge#2','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C26',2,'ox','auto','세 물음 가운데 하나만 걸려도 근거는 흔들릴 수 있어요.',ARRAY['K6-1-u3-X35']::text[],false,'{"seq":2,"concept":"K6-1-u3-C26","difficulty":2,"kind":"ox","stem":"세 물음 가운데 하나만 걸려도 근거는 흔들릴 수 있어요.","answer":"O","reason_options":[{"t":"이어지지 않거나 출처를 모르거나 흐릿하면 어느 쪽이든 이유를 제대로 뒷받침하지 못하기 때문에","correct":true},{"t":"세 물음 가운데 하나만 통과하면 충분하기 때문에","mis":"K6-1-u3-X35"}],"mis":"K6-1-u3-X35","explanation":["세 물음을 한 번씩 던져요.","하나만 걸려도 흔들려요.","전체적으로 타당한지 봐요."]}'::jsonb),
('g6_1_kor_u3_L06_challenge#3','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C27',3,'error','auto','운동장을 저녁에 여는 문제로 근거를 냈어요. 근거로 알맞지 않은 것을 낸 친구는 누구인가요?',ARRAY['K6-1-u3-X27','K6-1-u3-X28','K6-1-u3-X29']::text[],false,'{"seq":3,"concept":"K6-1-u3-C27","difficulty":3,"kind":"error","stem":"운동장을 저녁에 여는 문제로 근거를 냈어요. 근거로 알맞지 않은 것을 낸 친구는 누구인가요?","options":[{"t":"수아 — 「운동장을 열면 학교가 유명해집니다.」","correct":true,"mis_target":"K6-1-u3-X27"},{"t":"민재 — 「교육청이 올해 스물여덟 곳을 점검한 자료입니다.」","mis":"K6-1-u3-X28"},{"t":"해솔 — 「우리 시가 지난해 시민 사백 명에게 물은 조사입니다.」","mis":"K6-1-u3-X29"}],"explanation":["민재는 출처와 때를 밝혔어요.","해솔도 누구를 언제 조사했는지 밝혔어요.","수아의 말은 이유와 이어지지 않아요."]}'::jsonb),
('g6_1_kor_u3_L06_challenge#4','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C28',3,'mc','auto','「열 명 가운데 일곱 명」보다 「지난해 우리 시가 시민 사백 명에게 물어 열 명 가운데 일곱 명」이 더 센 까닭은 무엇인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X34']::text[],false,'{"seq":4,"concept":"K6-1-u3-C28","difficulty":3,"kind":"mc","stem":"「열 명 가운데 일곱 명」보다 「지난해 우리 시가 시민 사백 명에게 물어 열 명 가운데 일곱 명」이 더 센 까닭은 무엇인가요?","options":[{"t":"언제 · 누구를 조사했는지가 밝혀져 있어 더 구체적이기 때문에","correct":true},{"t":"글자 수가 더 많기 때문에","mis":"K6-1-u3-X30"},{"t":"숫자가 하나 더 들어 있기 때문에","mis":"K6-1-u3-X30"},{"t":"듣기에 더 어려워 보이기 때문에","mis":"K6-1-u3-X34"}],"explanation":["길이로 세지는 것이 아니에요.","숫자 개수도 아니에요.","언제 · 누구를이 밝혀져 있어요."]}'::jsonb),
('g6_1_kor_u3_L06_challenge#5','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C30',3,'mc','auto','신문 기사를 근거로 쓰려고 해요. 가장 먼저 살펴볼 것은 어느 것인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X35','K6-1-u3-X33']::text[],false,'{"seq":5,"concept":"K6-1-u3-C30","difficulty":3,"kind":"mc","stem":"신문 기사를 근거로 쓰려고 해요. 가장 먼저 살펴볼 것은 어느 것인가요?","options":[{"t":"광고에 가까운 글인지, 쓴 사람의 이름과 낸 때가 적혀 있는지","correct":true},{"t":"기사가 길고 어려운지","mis":"K6-1-u3-X30"},{"t":"사진이 많이 들어 있는지","mis":"K6-1-u3-X35"},{"t":"내 주장과 같은 말을 하는지만","mis":"K6-1-u3-X33"}],"explanation":["길고 어렵다고 믿을 만한 것은 아니에요.","사진 수로 판단하지 않아요.","광고인지 · 누가 언제 썼는지 봐요."]}'::jsonb),
('g6_1_kor_u3_L06_challenge#6','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C31',3,'mc','auto','근거를 내놓는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X34','K6-1-u3-X28']::text[],false,'{"seq":6,"concept":"K6-1-u3-C31","difficulty":3,"kind":"mc","stem":"근거를 내놓는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"중요한 내용만 추리고, 필요하면 표나 그림으로 보이며, 누가 언제 낸 자료인지 먼저 밝힌다","correct":true},{"t":"자료의 세부 사항을 처음부터 끝까지 모두 읽는다","mis":"K6-1-u3-X34"},{"t":"「어디서 봤는데」로 시작해 친근하게 말한다","mis":"K6-1-u3-X34"},{"t":"출처는 상대가 물을 때만 말한다","mis":"K6-1-u3-X28"}],"explanation":["모두 읽으면 중심이 흐려져요.","「어디서 봤는데」는 자료를 흔들어요.","출처를 먼저 밝혀요."]}'::jsonb),
('g6_1_kor_u3_L06_challenge#7','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C26',3,'mc','auto','글 ㉯의 근거를 따져 본 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X30','K6-1-u3-X31']::text[],false,'{"seq":7,"concept":"K6-1-u3-C26","difficulty":3,"kind":"mc","stem":"글 ㉯의 근거를 따져 본 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"교육청 · 올해 · 스물여덟 곳이 밝혀져 있고, 학생이 안전하게 지내야 한다는 이유와 이어진다","correct":true},{"t":"학교 이야기라서 따져 볼 것도 없이 타당하다","mis":"K6-1-u3-X35"},{"t":"자료가 하나뿐이라 충분하지 않다","mis":"K6-1-u3-X30"},{"t":"교육청 자료는 사람이 만든 것이라 믿을 수 없다","mis":"K6-1-u3-X31"}],"explanation":["따져 보지 않고 넘어가지 않아요.","하나라도 자세하면 충분할 수 있어요.","세 물음으로 보면 타당해요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에는 닫아야 합니다.","학교는 무엇보다 학생이 안전하게 지내야 하는 곳이기 때문입니다.","저녁에 문을 열어 두면 누가 드나드는지 알기 어렵습니다.","우리 교육청이 올해 낸 학교 시설 개방 점검 자료를 보면,","저녁에 운동장을 연 학교 스물여덟 곳 가운데 열아홉 곳이","쓰레기와 시설 파손 때문에 어려움을 겪는다고 답했습니다.","시에서 걷기 좋은 길을 새로 내는 쪽이 낫습니다."],"title":"글 ㉯ 「학교 운동장은 저녁에는 닫아야 한다」"}}'::jsonb),
('g6_1_kor_u3_L06_challenge#8','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C29',4,'mc','auto','「저녁 운동장은 관리가 어렵다」는 이유를 경험으로 뒷받침하려고 해요. 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X32','K6-1-u3-X28']::text[],false,'{"seq":8,"concept":"K6-1-u3-C29","difficulty":4,"kind":"mc","stem":"「저녁 운동장은 관리가 어렵다」는 이유를 경험으로 뒷받침하려고 해요. 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모둠이 일주일 동안 저녁마다 운동장에 남은 쓰레기 수를 세어 정리한 기록","correct":true},{"t":"저녁 운동장이 무서웠던 내 느낌","mis":"K6-1-u3-X04"},{"t":"어느 날 운동장에서 넘어진 내 일 하나","mis":"K6-1-u3-X32"},{"t":"어떤 동영상에서 본 이야기","mis":"K6-1-u3-X28"}],"explanation":["느낌은 근거가 아니에요.","드문 일 하나는 힘이 약해요.","세어서 정리한 경험은 근거가 돼요."]}'::jsonb),
('g6_1_kor_u3_L06_challenge#9','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C26',4,'essay','teacher','글 ㉯의 근거를 세 물음으로 하나씩 따져 보고, 이 근거를 더 타당하게 만들려면 무엇을 더 밝히면 좋을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C26","difficulty":4,"kind":"essay","stem":"글 ㉯의 근거를 세 물음으로 하나씩 따져 보고, 이 근거를 더 타당하게 만들려면 무엇을 더 밝히면 좋을지 쓰세요.","answer_guide":{"answer":"예: 이 자료는 쓰레기와 시설 파손 때문에 어려움을 겪는다는 내용이라 학생이 안전하게 지내야 한다는 이유와 이어진다. 교육청이 낸 자료라 출처가 분명하다. 올해, 운동장을 연 학교 스물여덟 곳을 점검했다고 밝혀 구체적이다. 더 타당하게 하려면 어떤 어려움이 몇 곳에서 있었는지, 그 학교들이 우리 학교와 비슷한 곳인지를 더 밝히면 좋겠다.","scoring_points":["관련성 · 신뢰성 · 충분성을 하나씩 따졌는가","글 ㉯의 내용으로 근거를 들어 따졌는가","더 밝힐 점을 알맞게 썼는가"]},"explanation":["세 물음을 한 번씩 던져요.","글의 내용으로 따져요.","더 밝힐 점을 찾아요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에는 닫아야 합니다.","학교는 무엇보다 학생이 안전하게 지내야 하는 곳이기 때문입니다.","저녁에 문을 열어 두면 누가 드나드는지 알기 어렵습니다.","우리 교육청이 올해 낸 학교 시설 개방 점검 자료를 보면,","저녁에 운동장을 연 학교 스물여덟 곳 가운데 열아홉 곳이","쓰레기와 시설 파손 때문에 어려움을 겪는다고 답했습니다.","시에서 걷기 좋은 길을 새로 내는 쪽이 낫습니다."],"title":"글 ㉯ 「학교 운동장은 저녁에는 닫아야 한다」"}}'::jsonb),
('g6_1_kor_u3_L06_challenge#10','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C28',4,'essay','teacher','「충분성은 자료가 많다는 뜻이 아니다」라는 말을 예를 들어 설명하고, 내가 겪은 일을 근거로 쓰려면 어떻게 해야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C28","difficulty":4,"kind":"essay","stem":"「충분성은 자료가 많다는 뜻이 아니다」라는 말을 예를 들어 설명하고, 내가 겪은 일을 근거로 쓰려면 어떻게 해야 하는지 쓰세요.","answer_guide":{"answer":"예: 「많은 사람이 그렇다고 했다」는 자료를 다섯 개 모아도 언제 누구에게 물었는지 없으면 여전히 흐릿하다. 반대로 「지난해 우리 시가 시민 사백 명에게 물은 조사」처럼 하나라도 언제 · 누구를 · 어떻게 조사했는지 밝혀져 있으면 충분할 수 있다. 내가 겪은 일을 근거로 쓰려면 나에게만 일어난 드문 일이 아니라 여러 사람이 그럴 만하다고 여길 일을 골라, 느낌으로 두지 말고 세거나 재어서 정리해야 한다.","scoring_points":["충분성이 개수가 아니라 구체성임을 예와 함께 썼는가","드문 경험은 근거가 되기 어렵다는 점을 썼는가","세거나 재어 정리하는 방법을 썼는가"]},"explanation":["흐릿한 자료 여러 개와 자세한 하나를 견줘요.","어떤 경험이 근거가 되기 어려운지 써요.","세거나 재는 방법을 써요."]}'::jsonb),
('g6_1_kor_u3_L08_basic#1','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C32',1,'mc','auto','사회 문제 토론 주제로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":1,"concept":"K6-1-u3-C32","difficulty":1,"kind":"mc","stem":"사회 문제 토론 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"공공 도서관을 밤 열 시까지 열어야 하는가","correct":true},{"t":"우리 시의 인구가 몇 명인가","mis":"K6-1-u3-X01"},{"t":"신호등이 빨간불일 때 건너면 안 되는가","mis":"K6-1-u3-X01"},{"t":"어제 비가 몇 시에 왔는가","mis":"K6-1-u3-X01"}],"explanation":["인구는 찾아보면 확인돼요.","빨간불에 건너지 않는 것은 정해진 규칙이에요.","찬반이 갈리고 무엇을 하자고 정하는 문제예요."]}'::jsonb),
('g6_1_kor_u3_L08_basic#2','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C27',1,'mc','auto','이 글의 근거에서 가장 큰 문제는 무엇인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X15','K6-1-u3-X35']::text[],false,'{"seq":2,"concept":"K6-1-u3-C27","difficulty":1,"kind":"mc","stem":"이 글의 근거에서 가장 큰 문제는 무엇인가요?","options":[{"t":"어디서 나온 자료인지 하나도 확인할 수 없다","correct":true},{"t":"글이 너무 짧다","mis":"K6-1-u3-X30"},{"t":"주장을 맨 앞과 맨 뒤에 두 번 썼다","mis":"K6-1-u3-X15"},{"t":"이모의 말에 높임말을 썼다","mis":"K6-1-u3-X35"}],"explanation":["길이는 문제가 아니에요.","주장을 다시 쓴 것은 큰 문제가 아니에요.","누리집 · 많은 사람 · 이모의 말 모두 확인할 수 없어요."],"asset":{"type":"passage","lines":["학교 주변 도로의 제한 속도를 더 낮춰서는 안 된다고 생각합니다.","어떤 누리집에서 봤는데, 속도를 낮추면 오히려 사고가 는다고 합니다.","많은 사람이 그렇게 말합니다.","게다가 저희 이모께서 운전할 때 답답하다고 하셨습니다.","따라서 제한 속도를 낮출 필요는 없습니다."],"title":"어느 학생이 쓴 글"}}'::jsonb),
('g6_1_kor_u3_L08_basic#3','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C33',1,'ox','auto','판정단은 토론에서 실제로 나온 말과 자료만으로 판정해요.',ARRAY['K6-1-u3-X24']::text[],false,'{"seq":3,"concept":"K6-1-u3-C33","difficulty":1,"kind":"ox","stem":"판정단은 토론에서 실제로 나온 말과 자료만으로 판정해요.","answer":"O","reason_options":[{"t":"미리 정한 기준으로 공정하게 판정해야 하기 때문에","correct":true},{"t":"평소 자기 생각을 넣어야 판정이 정확해지기 때문에","mis":"K6-1-u3-X24"}],"mis":"K6-1-u3-X24","explanation":["평소 생각은 판정과 관계없어요.","미리 정한 기준으로 봐요.","나온 말과 자료만으로 정해요."]}'::jsonb),
('g6_1_kor_u3_L08_basic#4','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C34',1,'mc','auto','토론 중에 메모해 두면 좋은 것은 어느 것인가요?',ARRAY['K6-1-u3-X38','K6-1-u3-X12']::text[],false,'{"seq":4,"concept":"K6-1-u3-C34","difficulty":1,"kind":"mc","stem":"토론 중에 메모해 두면 좋은 것은 어느 것인가요?","options":[{"t":"상대가 근거로 든 자료의 출처","correct":true},{"t":"상대의 목소리 크기와 말투","mis":"K6-1-u3-X38"},{"t":"상대가 입은 옷차림","mis":"K6-1-u3-X38"},{"t":"상대 발언 전체를 한 글자도 빠짐없이","mis":"K6-1-u3-X12"}],"explanation":["말투는 되받을 거리가 아니에요.","옷차림도 아니에요.","되받을 거리를 핵심만 적어요."]}'::jsonb),
('g6_1_kor_u3_L08_basic#5','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C35',2,'mc','auto','판정 기준 가운데 「반론하기」에서 보는 것은 어느 것인가요?',ARRAY['K6-1-u3-X06','K6-1-u3-X16','K6-1-u3-X08']::text[],false,'{"seq":5,"concept":"K6-1-u3-C35","difficulty":2,"kind":"mc","stem":"판정 기준 가운데 「반론하기」에서 보는 것은 어느 것인가요?","options":[{"t":"상대 이유나 근거의 문제를 찾아 되받았는가, 반론에 알맞게 답했는가","correct":true},{"t":"주장과 이유를 처음으로 냈는가","mis":"K6-1-u3-X06"},{"t":"누구의 목소리가 더 컸는가","mis":"K6-1-u3-X16"},{"t":"준비한 원고를 끝까지 읽었는가","mis":"K6-1-u3-X08"}],"explanation":["처음 내는 것은 주장 펼치기예요.","목소리는 기준이 아니에요.","되받고 답한 것을 봐요."]}'::jsonb),
('g6_1_kor_u3_L08_basic#6','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C32',2,'mc','auto','사회 문제를 주제로 정한 뒤 먼저 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X36','K6-1-u3-X16','K6-1-u3-X20']::text[],false,'{"seq":6,"concept":"K6-1-u3-C32","difficulty":2,"kind":"mc","stem":"사회 문제를 주제로 정한 뒤 먼저 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"지금 제한 속도가 얼마인지, 사고가 몇 건이었는지처럼 알려진 사실부터 함께 맞춰 본다","correct":true},{"t":"아는 것이 적어도 곧바로 토론을 시작한다","mis":"K6-1-u3-X36"},{"t":"판정 결과부터 정해 둔다","mis":"K6-1-u3-X16"},{"t":"주제를 정하자마자 역할부터 나눈다","mis":"K6-1-u3-X20"}],"explanation":["아는 것이 적으면 겉돌기 쉬워요.","판정은 토론 뒤에 해요.","사실부터 함께 맞춰요."]}'::jsonb),
('g6_1_kor_u3_L08_basic#7','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C22',2,'mc','auto','제한 속도 준비표에서 예상 반론에 대한 답변이 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X11','K6-1-u3-X14']::text[],false,'{"seq":7,"concept":"K6-1-u3-C22","difficulty":2,"kind":"mc","stem":"제한 속도 준비표에서 예상 반론에 대한 답변이 알맞은 까닭은 무엇인가요?","options":[{"t":"「속도 때문인지 알 수 없다」는 물음에 공사를 하지 않은 구역 자료로 곧바로 답했기 때문에","correct":true},{"t":"「어쨌든 속도를 낮추면 안전합니다」라고 되풀이했기 때문에","mis":"K6-1-u3-X13"},{"t":"자전거 사고 이야기로 넘어갔기 때문에","mis":"K6-1-u3-X11"},{"t":"상대가 준비를 안 했다고 짚었기 때문에","mis":"K6-1-u3-X14"}],"explanation":["되풀이는 답변이 아니에요.","다른 이야기로 넘어가지 않았어요.","물은 그 지점을 자료로 되받았어요."],"asset":{"type":"passage","lines":["주장 — 학교 주변 도로의 제한 속도를 더 낮춰야 합니다.","이유 — 속도가 낮을수록 멈추는 데 걸리는 거리가 짧아지기 때문입니다.","근거 — 우리 시 교통 안전과가 지난해 낸 어린이 보호 구역 사고 자료.","속도를 낮춘 구역에서 사고 건수가 줄었습니다.","예상 반론 — 줄어든 것이 속도 때문인지 공사 때문인지 알 수 없습니다.","우리 측 답변 — 같은 자료에 공사를 하지 않은 구역이 따로 나와 있고,","그 구역에서도 사고가 줄었습니다."],"title":"찬성 측 토론 준비표 (사회 문제)"}}'::jsonb),
('g6_1_kor_u3_L08_basic#8','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C34',2,'ox','auto','반론하기에서는 상대 말을 듣기보다 준비한 원고를 그대로 다시 읽는 것이 안전해요.',ARRAY['K6-1-u3-X08']::text[],false,'{"seq":8,"concept":"K6-1-u3-C34","difficulty":2,"kind":"ox","stem":"반론하기에서는 상대 말을 듣기보다 준비한 원고를 그대로 다시 읽는 것이 안전해요.","answer":"X","reason_options":[{"t":"반론은 그 순간에 들은 것으로만 할 수 있어 메모하며 들어야 하기 때문에","correct":true},{"t":"원고를 읽으면 실수가 없기 때문에","mis":"K6-1-u3-X08"}],"mis":"K6-1-u3-X08","explanation":["원고를 읽으면 혼잣말이 돼요.","반론은 들은 것으로 해요.","메모하며 들어요."]}'::jsonb),
('g6_1_kor_u3_L08_basic#9','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C36',2,'mc','auto','판정이 나온 뒤에 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X40','K6-1-u3-X18','K6-1-u3-X39']::text[],false,'{"seq":9,"concept":"K6-1-u3-C36","difficulty":2,"kind":"mc","stem":"판정이 나온 뒤에 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「저 근거는 나도 다시 찾아봐야겠다.」","correct":true},{"t":"「우리가 이겼다. 더 할 말 없다.」","mis":"K6-1-u3-X40"},{"t":"「판정이 이상하다.」","mis":"K6-1-u3-X18"},{"t":"「생각이 바뀌면 지는 거야.」","mis":"K6-1-u3-X39"}],"explanation":["승패만 남기면 아쉬워요.","판정에는 승복해요.","생각을 남기는 마무리가 좋아요."]}'::jsonb),
('g6_1_kor_u3_L08_basic#10','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C23',3,'mc','auto','청중이 많을 때 청중에게도 할 일을 주는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X37','K6-1-u3-X25']::text[],false,'{"seq":10,"concept":"K6-1-u3-C23","difficulty":3,"kind":"mc","stem":"청중이 많을 때 청중에게도 할 일을 주는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"청중이 메모하고 인상 깊은 근거를 말해야 토론이 살아나기 때문에","correct":true},{"t":"청중은 할 일이 없어 조용히 앉아 있으면 되기 때문에","mis":"K6-1-u3-X37"},{"t":"청중이 판정을 대신해야 하기 때문에","mis":"K6-1-u3-X25"},{"t":"청중이 토론자 대신 반론해야 하기 때문에","mis":"K6-1-u3-X25"}],"explanation":["청중에게도 할 일이 있어요.","판정은 판정단이 해요.","메모하고 인상 깊은 근거를 말해요."]}'::jsonb),
('g6_1_kor_u3_L08_challenge#1','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C33',2,'mc','auto','판정단이 판정의 바탕으로 삼을 것은 어느 것인가요?',ARRAY['K6-1-u3-X24','K6-1-u3-X16']::text[],false,'{"seq":1,"concept":"K6-1-u3-C33","difficulty":2,"kind":"mc","stem":"판정단이 판정의 바탕으로 삼을 것은 어느 것인가요?","options":[{"t":"미리 정한 기준으로, 토론에서 실제로 나온 말과 자료만 본다","correct":true},{"t":"평소 자기 생각과 같은 편에 후하게 준다","mis":"K6-1-u3-X24"},{"t":"친한 친구가 있는 편에 더 준다","mis":"K6-1-u3-X24"},{"t":"목소리가 큰 편을 고른다","mis":"K6-1-u3-X16"}],"explanation":["같은 편이라고 후하게 주지 않아요.","친한 사이는 판정과 관계없어요.","기준과 나온 내용만 봐요."]}'::jsonb),
('g6_1_kor_u3_L08_challenge#2','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C36',2,'ox','auto','토론이 끝난 뒤 생각이 조금 바뀌는 것은 부끄러운 일이에요.',ARRAY['K6-1-u3-X39']::text[],false,'{"seq":2,"concept":"K6-1-u3-C36","difficulty":2,"kind":"ox","stem":"토론이 끝난 뒤 생각이 조금 바뀌는 것은 부끄러운 일이에요.","answer":"X","reason_options":[{"t":"상대의 근거에서 배운 것이 있다는 뜻으로 토론을 한 보람이기 때문에","correct":true},{"t":"생각이 바뀌면 토론에서 진 것이기 때문에","mis":"K6-1-u3-X39"}],"mis":"K6-1-u3-X39","explanation":["판정에는 승복해요.","생각이 바뀌는 것은 진 것이 아니에요.","그것이 토론을 한 보람이에요."]}'::jsonb),
('g6_1_kor_u3_L08_challenge#3','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C34',3,'mc','auto','메모할 때 발언을 그대로 옮기지 않고 핵심만 짧게 적는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X12','K6-1-u3-X08','K6-1-u3-X38']::text[],false,'{"seq":3,"concept":"K6-1-u3-C34","difficulty":3,"kind":"mc","stem":"메모할 때 발언을 그대로 옮기지 않고 핵심만 짧게 적는 까닭은 무엇인가요?","options":[{"t":"다음 말을 놓치지 않고 되받을 거리를 찾기 위해서","correct":true},{"t":"발언은 모두 옮겨야 정확하지만 시간이 없어서","mis":"K6-1-u3-X12"},{"t":"상대 말은 어차피 중요하지 않기 때문에","mis":"K6-1-u3-X08"},{"t":"글씨를 예쁘게 쓰기 위해서","mis":"K6-1-u3-X38"}],"explanation":["다 옮기는 것이 좋은 메모가 아니에요.","상대 말을 들어야 되받아요.","핵심만 적어야 다음 말을 들어요."]}'::jsonb),
('g6_1_kor_u3_L08_challenge#4','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C27',3,'mc','auto','이 글을 더 타당하게 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X29','K6-1-u3-X30','K6-1-u3-X15']::text[],false,'{"seq":4,"concept":"K6-1-u3-C27","difficulty":3,"kind":"mc","stem":"이 글을 더 타당하게 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어느 기관이 언제 낸 사고 자료인지 밝히고, 이모의 말 대신 확인할 수 있는 자료를 든다","correct":true},{"t":"「많은 사람」을 「아주 많은 사람」으로 바꾼다","mis":"K6-1-u3-X29"},{"t":"누리집 이야기를 한 번 더 쓴다","mis":"K6-1-u3-X30"},{"t":"주장을 한 번 더 써서 힘준다","mis":"K6-1-u3-X15"}],"explanation":["「아주 많은」도 흐릿해요.","같은 이야기를 늘려도 그대로예요.","출처가 분명한 자료로 바꿔요."],"asset":{"type":"passage","lines":["학교 주변 도로의 제한 속도를 더 낮춰서는 안 된다고 생각합니다.","어떤 누리집에서 봤는데, 속도를 낮추면 오히려 사고가 는다고 합니다.","많은 사람이 그렇게 말합니다.","게다가 저희 이모께서 운전할 때 답답하다고 하셨습니다.","따라서 제한 속도를 낮출 필요는 없습니다."],"title":"어느 학생이 쓴 글"}}'::jsonb),
('g6_1_kor_u3_L08_challenge#5','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C35',3,'error','auto','판정단이 기준을 말했어요. 알맞지 않은 기준을 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X16','K6-1-u3-X35','K6-1-u3-X17']::text[],false,'{"seq":5,"concept":"K6-1-u3-C35","difficulty":3,"kind":"error","stem":"판정단이 기준을 말했어요. 알맞지 않은 기준을 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「더 오래 말한 쪽에 점수를 주겠습니다.」","correct":true,"mis_target":"K6-1-u3-X16"},{"t":"서하 — 「이유와 근거가 타당하고 믿을 만한가를 보겠습니다.」","mis":"K6-1-u3-X35"},{"t":"지후 — 「규칙을 지키고 예의 바르게 참여했는가를 보겠습니다.」","mis":"K6-1-u3-X17"}],"explanation":["서하는 주장 펼치기의 기준을 말했어요.","지후는 태도의 기준을 말했어요.","말한 길이는 기준이 아니에요."]}'::jsonb),
('g6_1_kor_u3_L08_challenge#6','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C32',3,'mc','auto','사회 문제 주제를 찾을 때 던지면 좋은 물음은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X19','K6-1-u3-X20']::text[],false,'{"seq":6,"concept":"K6-1-u3-C32","difficulty":3,"kind":"mc","stem":"사회 문제 주제를 찾을 때 던지면 좋은 물음은 어느 것인가요?","options":[{"t":"「늘 그래 왔던 일인데 꼭 그래야 할까?」, 「많은 친구가 관심 있어 할까?」","correct":true},{"t":"「자료를 찾으면 곧바로 답이 나올까?」","mis":"K6-1-u3-X01"},{"t":"「아무도 관심 없는 일일까?」","mis":"K6-1-u3-X19"},{"t":"「한쪽 편만 있을까?」","mis":"K6-1-u3-X20"}],"explanation":["곧바로 답이 나오면 토론이 안 돼요.","관심 있어야 근거를 찾을 마음이 생겨요.","당연한 일에 물어보세요."]}'::jsonb),
('g6_1_kor_u3_L08_challenge#7','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C34',3,'mc','auto','토론의 승패가 반론하기에서 갈린다고 하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X45','K6-1-u3-X08','K6-1-u3-X16']::text[],false,'{"seq":7,"concept":"K6-1-u3-C34","difficulty":3,"kind":"mc","stem":"토론의 승패가 반론하기에서 갈린다고 하는 까닭은 무엇인가요?","options":[{"t":"주장 펼치기는 준비한 대로 말하면 되지만, 반론은 그 순간 들은 것으로만 할 수 있기 때문에","correct":true},{"t":"반론하기에서 목소리를 가장 크게 내기 때문에","mis":"K6-1-u3-X45"},{"t":"반론하기에서 원고를 가장 길게 읽기 때문에","mis":"K6-1-u3-X08"},{"t":"판정단이 반론하기만 보기 때문에","mis":"K6-1-u3-X16"}],"explanation":["목소리 크기로 갈리지 않아요.","원고를 읽으면 혼잣말이 돼요.","그 순간 들은 것으로 되받아요."]}'::jsonb),
('g6_1_kor_u3_L08_challenge#8','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C36',4,'mc','auto','「판정이 이상하다」는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X18','K6-1-u3-X24','K6-1-u3-X39']::text[],false,'{"seq":8,"concept":"K6-1-u3-C36","difficulty":4,"kind":"mc","stem":"「판정이 이상하다」는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「판정은 정한 기준으로 본 결과니까 승복하자. 그리고 우리 근거에서 약했던 곳을 다시 찾아보자.」","correct":true},{"t":"「맞아, 우리가 옳았으니 판정은 무시하자.」","mis":"K6-1-u3-X18"},{"t":"「다음엔 판정단을 친한 친구로 하자.」","mis":"K6-1-u3-X24"},{"t":"「생각이 흔들리면 지는 거니까 절대 바꾸지 말자.」","mis":"K6-1-u3-X39"}],"explanation":["판정은 무시하지 않아요.","판정단은 공정해야 해요.","승복하고 배운 것을 남겨요."]}'::jsonb),
('g6_1_kor_u3_L08_challenge#9','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C34',4,'essay','teacher','토론 중에 메모해야 할 것 세 가지를 쓰고, 메모하며 듣는 것이 반론하기에 왜 중요한지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C34","difficulty":4,"kind":"essay","stem":"토론 중에 메모해야 할 것 세 가지를 쓰고, 메모하며 듣는 것이 반론하기에 왜 중요한지 쓰세요.","answer_guide":{"answer":"예: 상대측 주장을 한 문장으로, 상대가 든 이유의 개수와 내용, 상대가 근거로 든 자료의 출처(누가 언제 냈는지)를 메모한다. 주장 펼치기는 준비한 대로 말하면 되지만 반론하기는 그 순간 들은 것으로만 할 수 있다. 메모가 없으면 준비한 원고만 다시 읽게 되어 혼잣말이 되므로, 메모한 것 가운데 가장 약한 한 곳을 골라 되받아야 한다.","scoring_points":["되받을 거리가 되는 메모 세 가지를 썼는가","반론은 그 순간 들은 것으로 한다는 점을 썼는가","메모로 가장 약한 곳을 골라 되받는다는 점을 썼는가"]},"explanation":["되받을 거리를 떠올려요.","반론하기의 특징을 써요.","메모를 어떻게 쓰는지 써요."]}'::jsonb),
('g6_1_kor_u3_L08_challenge#10','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C27',4,'essay','teacher','이 글의 근거가 왜 믿기 어려운지 세 물음으로 따져 쓰고, 근거를 알맞게 바꾸어 다시 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C27","difficulty":4,"kind":"essay","stem":"이 글의 근거가 왜 믿기 어려운지 세 물음으로 따져 쓰고, 근거를 알맞게 바꾸어 다시 쓰세요.","answer_guide":{"answer":"예: 「어떤 누리집」은 어디인지 몰라 출처가 분명하지 않다. 「많은 사람」은 언제 몇 명에게 물었는지 없어 구체적이지 않다. 이모가 답답하다고 한 말은 한 사람의 느낌이라 속도와 사고 사이의 관계와 이어지지 않는다. 고친 근거 — 「우리 시 교통 안전과가 지난해 낸 자료를 보면, 제한 속도를 낮춘 뒤에도 사고가 줄지 않은 구역이 있었습니다.」처럼 누가 언제 낸 자료인지 밝힌다.","scoring_points":["출처 문제를 짚었는가","구체성 문제와 관련성 문제를 짚었는가","누가 언제 낸 자료인지 밝힌 근거로 바꾸어 썼는가"]},"explanation":["누리집의 문제를 짚어요.","많은 사람 · 이모의 말을 따져요.","확인할 수 있는 근거로 바꿔요."],"asset":{"type":"passage","lines":["학교 주변 도로의 제한 속도를 더 낮춰서는 안 된다고 생각합니다.","어떤 누리집에서 봤는데, 속도를 낮추면 오히려 사고가 는다고 합니다.","많은 사람이 그렇게 말합니다.","게다가 저희 이모께서 운전할 때 답답하다고 하셨습니다.","따라서 제한 속도를 낮출 필요는 없습니다."],"title":"어느 학생이 쓴 글"}}'::jsonb),
('g6_1_kor_u3_L11_basic#1','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C37',1,'mc','auto','역사 갈래에서 토론 주제가 되는 것은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":1,"concept":"K6-1-u3-C37","difficulty":1,"kind":"mc","stem":"역사 갈래에서 토론 주제가 되는 것은 어느 것인가요?","options":[{"t":"우리 지역의 옛 성곽을 원래 모습으로 되살려야 하는가","correct":true},{"t":"그 성곽이 몇 해에 쌓였는가","mis":"K6-1-u3-X01"},{"t":"조선의 도읍이 어디였는가","mis":"K6-1-u3-X01"},{"t":"성곽의 길이가 얼마인가","mis":"K6-1-u3-X01"}],"explanation":["쌓은 해는 찾으면 나와요.","도읍은 자료로 확인돼요.","평가와 선택이 갈리는 물음이라야 해요."]}'::jsonb),
('g6_1_kor_u3_L11_basic#2','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C39',1,'mc','auto','원탁 토론에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X41','K6-1-u3-X03']::text[],false,'{"seq":2,"concept":"K6-1-u3-C39","difficulty":1,"kind":"mc","stem":"원탁 토론에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"편을 나누지 않고 모두가 대등하게 돌아가며 말한다","correct":true},{"t":"찬성 측과 반대 측으로 나뉘어 정해진 단계대로 겨룬다","mis":"K6-1-u3-X41"},{"t":"사회자와 판정단이 꼭 있어야 한다","mis":"K6-1-u3-X41"},{"t":"한 사람만 계속 말한다","mis":"K6-1-u3-X03"}],"explanation":["편을 나누는 것은 찬반 토론이에요.","원탁 토론은 사회자를 따로 두지 않아요.","모두가 돌아가며 말해요."]}'::jsonb),
('g6_1_kor_u3_L11_basic#3','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C43',1,'mc','auto','「굵다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":3,"concept":"K6-1-u3-C43","difficulty":1,"kind":"mc","stem":"「굵다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[국따]","correct":true},{"t":"[굴따]","mis":"K6-1-u3-X44"},{"t":"[굵다]","mis":"K6-1-u3-X44"},{"t":"[구따]","mis":"K6-1-u3-X44"}],"explanation":["ㄺ 뒤에 ㄷ이 왔어요.","ㄺ은 [ㄱ]으로 소리 나요.","뒤의 ㄷ은 된소리가 돼요."]}'::jsonb),
('g6_1_kor_u3_L11_basic#4','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C40',1,'ox','auto','역사에 관한 논쟁에서는 한쪽이 옳고 다른 쪽은 틀렸다고 가려야 해요.',ARRAY['K6-1-u3-X42']::text[],false,'{"seq":4,"concept":"K6-1-u3-C40","difficulty":1,"kind":"ox","stem":"역사에 관한 논쟁에서는 한쪽이 옳고 다른 쪽은 틀렸다고 가려야 해요.","answer":"X","reason_options":[{"t":"옳고 그름이 아니라 무엇을 더 중요하게 여겼는지 관점이 다르기 때문에","correct":true},{"t":"역사에는 언제나 정답이 하나뿐이기 때문에","mis":"K6-1-u3-X42"}],"mis":"K6-1-u3-X42","explanation":["두 쪽 다 역사를 아낄 수 있어요.","아끼는 방법에 대한 생각이 달라요.","관점의 차이로 봐요."]}'::jsonb),
('g6_1_kor_u3_L11_basic#5','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C4',2,'match','auto','성곽 토론의 발언을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u3-C4","difficulty":2,"kind":"match","stem":"성곽 토론의 발언을 알맞게 이으세요.","pairs":[{"l":"모습을 갖춰야 고장의 역사를 배우는 곳이 된다","r":"찬성 측 이유"},{"l":"되살린 다른 고장 성곽의 방문자 기록","r":"찬성 측 근거"},{"l":"새로 만든 부분이 많으면 옛 성곽이라 하기 어렵다","r":"반대 측 이유"},{"l":"도청이 낸 복원 기준 안내 자료","r":"반대 측 근거"}],"mis":"K6-1-u3-X04","explanation":["까닭인지 자료인지 먼저 나눠요.","그다음 찬반을 갈라요.","같은 대상을 두고도 근거가 갈려요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"옛 성곽을 원래 모습으로 되살려야 합니다. 지금은 돌담 일부만 남아 있어 사람들이 그곳이 성곽이었는지도 모르고 지나갑니다. 모습을 갖춰야 고장의 역사를 배우는 곳이 됩니다."},{"who":"반대 측 윤재","text":"되살려서는 안 됩니다. 남아 있는 부분이 적어 되살리려면 대부분을 새로 만들어야 합니다. 새로 만든 부분이 많아지면 그것은 옛 성곽이 아니라 새 건물입니다."}]}}'::jsonb),
('g6_1_kor_u3_L11_basic#6','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C38',2,'mc','auto','모둠이 근거를 모으는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X43','K6-1-u3-X22']::text[],false,'{"seq":6,"concept":"K6-1-u3-C38","difficulty":2,"kind":"mc","stem":"모둠이 근거를 모으는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"찾을 영역을 나누고, 누가 언제 낸 자료인지 적고, 바꾸어 읽은 뒤 가장 센 두 가지를 고른다","correct":true},{"t":"모은 자료를 하나도 빼지 않고 모두 준비표에 옮긴다","mis":"K6-1-u3-X43"},{"t":"출처는 적지 않고 내용만 적는다","mis":"K6-1-u3-X22"},{"t":"한 사람이 모든 자료를 혼자 찾아 그대로 쓴다","mis":"K6-1-u3-X43"}],"explanation":["모두 옮기면 약한 것까지 들어가요.","출처를 함께 적어요.","나누어 찾고 골라 써요."]}'::jsonb),
('g6_1_kor_u3_L11_basic#7','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C41',2,'mc','auto','토론을 마친 뒤 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X40','K6-1-u3-X18','K6-1-u3-X39']::text[],false,'{"seq":7,"concept":"K6-1-u3-C41","difficulty":2,"kind":"mc","stem":"토론을 마친 뒤 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「사회를 맡은 친구가 말차례를 잘 지켜 줬어. 나는 성곽 기준 자료를 처음 알았어.」","correct":true},{"t":"「역시 우리 편이 이겼네. 상대는 준비가 부족했어.」","mis":"K6-1-u3-X40"},{"t":"「판정이 이상했어. 기준을 잘못 잡은 것 같아.」","mis":"K6-1-u3-X18"},{"t":"「생각이 바뀌었으니 내가 진 거야.」","mis":"K6-1-u3-X39"}],"explanation":["승패와 깎아내리기만 남기지 않아요.","판정에는 승복해요.","잘한 곳과 새로 안 것을 나눠요."]}'::jsonb),
('g6_1_kor_u3_L11_basic#8','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C43',2,'mc','auto','「옮기다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":8,"concept":"K6-1-u3-C43","difficulty":2,"kind":"mc","stem":"「옮기다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[옴기다]","correct":true},{"t":"[올기다]","mis":"K6-1-u3-X44"},{"t":"[오기다]","mis":"K6-1-u3-X44"},{"t":"[옮끼다]","mis":"K6-1-u3-X44"}],"explanation":["ㄻ 뒤에 자음이 왔어요.","ㄻ은 [ㅁ]으로 소리 나요.","[옴기다]로 읽어요."]}'::jsonb),
('g6_1_kor_u3_L11_basic#9','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C42',2,'mc','auto','토론을 잘하는 사람의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X45','K6-1-u3-X07','K6-1-u3-X08']::text[],false,'{"seq":9,"concept":"K6-1-u3-C42","difficulty":2,"kind":"mc","stem":"토론을 잘하는 사람의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"반론할 때 사람이 아니라 근거를 겨눈다","correct":true},{"t":"말을 가장 많이, 가장 크게 한다","mis":"K6-1-u3-X45"},{"t":"상대가 말할 때 끼어들어 되받는다","mis":"K6-1-u3-X07"},{"t":"준비한 원고를 처음부터 끝까지 읽는다","mis":"K6-1-u3-X08"}],"explanation":["많이 · 크게 말하는 것과 잘하는 것은 달라요.","말차례를 지켜요.","근거를 겨누어 되받아요."]}'::jsonb),
('g6_1_kor_u3_L11_basic#10','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C26',3,'mc','auto','사물함 토론에서 어느 쪽 근거가 더 타당한가요?',ARRAY['K6-1-u3-X32','K6-1-u3-X35','K6-1-u3-X31']::text[],false,'{"seq":10,"concept":"K6-1-u3-C26","difficulty":3,"kind":"mc","stem":"사물함 토론에서 어느 쪽 근거가 더 타당한가요?","options":[{"t":"찬성 측 — 지난달에 백쉰 명에게 물어 조사한 때와 사람 수가 분명하다","correct":true},{"t":"반대 측 — 친구에게 직접 물어본 이야기라 더 생생하다","mis":"K6-1-u3-X32"},{"t":"둘 다 똑같다 — 사람에게 물어본 자료라는 점이 같다","mis":"K6-1-u3-X35"},{"t":"둘 다 근거가 아니다 — 사람에게 물은 것은 근거가 될 수 없다","mis":"K6-1-u3-X31"}],"explanation":["생생함보다 구체성을 봐요.","언제 · 몇 명에게 물었는지 견줘요.","백쉰 명과 두 명은 같은 무게가 아니에요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 사물함에 자물쇠를 달아야 한다.","찬성 측 온유 — 물건을 잃어버리는 일이 실제로 있기 때문입니다.","우리 학교 고학년 백쉰 명에게 지난달에 물어보니,","마흔여덟 명이 사물함에서 물건을 잃은 적이 있다고 답했습니다.","반대 측 새얀 — 열고 닫기가 번거롭기 때문입니다.","제 친구 두 명에게 물어보니 둘 다 불편할 것 같다고 했습니다."],"title":"두 근거 견주기"}}'::jsonb),
('g6_1_kor_u3_L11_challenge#1','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C39',2,'mc','auto','원탁 토론이 찬반 토론보다 알맞은 경우는 어느 것인가요?',ARRAY['K6-1-u3-X41','K6-1-u3-X09','K6-1-u3-X05']::text[],false,'{"seq":1,"concept":"K6-1-u3-C39","difficulty":2,"kind":"mc","stem":"원탁 토론이 찬반 토론보다 알맞은 경우는 어느 것인가요?","options":[{"t":"답이 찬성과 반대 둘로 갈리지 않는 문제를 이야기할 때","correct":true},{"t":"판정단이 꼭 승패를 정해야 할 때","mis":"K6-1-u3-X41"},{"t":"한쪽 편이 반드시 이겨야 할 때","mis":"K6-1-u3-X09"},{"t":"근거 없이 말해도 될 때","mis":"K6-1-u3-X05"}],"explanation":["승패를 정하는 것은 찬반 토론이에요.","이기려는 것이 목적이 아니에요.","어느 토론이든 근거를 들어요."]}'::jsonb),
('g6_1_kor_u3_L11_challenge#2','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C43',2,'ox','auto','「늙고」는 [늘꼬]로 읽어요.',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":2,"concept":"K6-1-u3-C43","difficulty":2,"kind":"ox","stem":"「늙고」는 [늘꼬]로 읽어요.","answer":"O","reason_options":[{"t":"ㄺ 뒤에 ㄱ이 오면 [ㄹ]로 소리 나고 뒤의 ㄱ은 된소리가 되기 때문에","correct":true},{"t":"겹받침은 언제나 두 자음을 모두 소리 내기 때문에","mis":"K6-1-u3-X44"}],"mis":"K6-1-u3-X44","explanation":["ㄺ 뒤에 ㄱ이 왔어요.","이때는 [ㄹ]로 소리 나요.","[늘꼬]로 읽어요."]}'::jsonb),
('g6_1_kor_u3_L11_challenge#3','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C40',3,'mc','auto','벼리와 윤재의 생각을 알맞게 정리한 말은 어느 것인가요?',ARRAY['K6-1-u3-X42','K6-1-u3-X02']::text[],false,'{"seq":3,"concept":"K6-1-u3-C40","difficulty":3,"kind":"mc","stem":"벼리와 윤재의 생각을 알맞게 정리한 말은 어느 것인가요?","options":[{"t":"한쪽은 배움의 기회를, 다른 쪽은 남은 것의 진짜 모습을 앞에 두었다","correct":true},{"t":"벼리는 역사를 아끼고 윤재는 역사를 아끼지 않는다","mis":"K6-1-u3-X42"},{"t":"되살리자는 쪽이 옳고 반대하는 쪽은 틀렸다","mis":"K6-1-u3-X42"},{"t":"두 사람은 편을 나누지 않고 같은 방법을 찾고 있다","mis":"K6-1-u3-X02"}],"explanation":["두 사람 다 역사를 아껴요.","옳고 그름으로 가르지 않아요.","무엇을 더 중요하게 여겼는지 봐요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"옛 성곽을 원래 모습으로 되살려야 합니다. 지금은 돌담 일부만 남아 있어 사람들이 그곳이 성곽이었는지도 모르고 지나갑니다. 모습을 갖춰야 고장의 역사를 배우는 곳이 됩니다."},{"who":"반대 측 윤재","text":"되살려서는 안 됩니다. 남아 있는 부분이 적어 되살리려면 대부분을 새로 만들어야 합니다. 새로 만든 부분이 많아지면 그것은 옛 성곽이 아니라 새 건물입니다."}]}}'::jsonb),
('g6_1_kor_u3_L11_challenge#4','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C37',3,'mc','auto','실천 토론에서 주제를 고를 때의 조건으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X19','K6-1-u3-X01','K6-1-u3-X20']::text[],false,'{"seq":4,"concept":"K6-1-u3-C37","difficulty":3,"kind":"mc","stem":"실천 토론에서 주제를 고를 때의 조건으로 알맞은 것은 어느 것인가요?","options":[{"t":"어느 갈래든 찬반이 갈리고 양쪽 모두 근거를 찾을 수 있어야 한다","correct":true},{"t":"역사 갈래에서만 고를 수 있다","mis":"K6-1-u3-X19"},{"t":"연도나 이름처럼 답이 하나로 나오는 물음이 좋다","mis":"K6-1-u3-X01"},{"t":"한쪽 근거만 있으면 된다","mis":"K6-1-u3-X20"}],"explanation":["역사 · 환경 · 생활 어디서든 찾아요.","답이 하나로 나오면 토론이 안 돼요.","양쪽 모두 근거를 찾을 수 있어야 해요."]}'::jsonb),
('g6_1_kor_u3_L11_challenge#5','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C38',3,'mc','auto','「모습을 갖춰야 역사를 배우는 곳이 된다」는 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X27','K6-1-u3-X28']::text[],false,'{"seq":5,"concept":"K6-1-u3-C38","difficulty":3,"kind":"mc","stem":"「모습을 갖춰야 역사를 배우는 곳이 된다」는 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"되살린 다른 고장 성곽의 학생 단체 관람 수가 해마다 는 기록","correct":true},{"t":"돌담만 있으면 심심할 것 같다는 내 느낌","mis":"K6-1-u3-X04"},{"t":"공사에는 시간이 오래 걸린다는 일반적인 이야기","mis":"K6-1-u3-X27"},{"t":"어디서 봤는지 모르는 여행 동영상","mis":"K6-1-u3-X28"}],"explanation":["느낌은 근거가 아니에요.","공사 기간은 이유와 이어지지 않아요.","이유와 이어지고 확인할 수 있는 기록이에요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"옛 성곽을 원래 모습으로 되살려야 합니다. 지금은 돌담 일부만 남아 있어 사람들이 그곳이 성곽이었는지도 모르고 지나갑니다. 모습을 갖춰야 고장의 역사를 배우는 곳이 됩니다."},{"who":"반대 측 윤재","text":"되살려서는 안 됩니다. 남아 있는 부분이 적어 되살리려면 대부분을 새로 만들어야 합니다. 새로 만든 부분이 많아지면 그것은 옛 성곽이 아니라 새 건물입니다."}]}}'::jsonb),
('g6_1_kor_u3_L11_challenge#6','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C43',3,'error','auto','겹받침 낱말을 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":6,"concept":"K6-1-u3-C43","difficulty":3,"kind":"error","stem":"겹받침 낱말을 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"라온 — 「굵고」를 [국꼬]로 읽었다","correct":true,"mis_target":"K6-1-u3-X44"},{"t":"하율 — 「읊다」를 [읍따]로 읽었다","mis":"K6-1-u3-X44"},{"t":"서진 — 「젊지」를 [점찌]로 읽었다","mis":"K6-1-u3-X44"}],"explanation":["하율은 ㄿ을 [ㅂ]으로 읽었어요.","서진은 ㄻ을 [ㅁ]으로 읽었어요.","ㄺ 뒤에 ㄱ이 오면 [ㄹ] — [굴꼬]예요."]}'::jsonb),
('g6_1_kor_u3_L11_challenge#7','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C42',3,'mc','auto','「자신감 있게, 그러면서도 예의 바르게 표현하는 힘」이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X45','K6-1-u3-X05','K6-1-u3-X14']::text[],false,'{"seq":7,"concept":"K6-1-u3-C42","difficulty":3,"kind":"mc","stem":"「자신감 있게, 그러면서도 예의 바르게 표현하는 힘」이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"근거가 좋아도 무례하게 말하면 듣는 사람이 받아들이기 어렵기 때문에","correct":true},{"t":"크게 말할수록 이기기 때문에","mis":"K6-1-u3-X45"},{"t":"예의만 지키면 근거는 없어도 되기 때문에","mis":"K6-1-u3-X05"},{"t":"상대 말투를 겨누기 위해서","mis":"K6-1-u3-X14"}],"explanation":["크게 말한다고 이기지 않아요.","근거도 함께 있어야 해요.","자신감과 예의가 함께 필요해요."]}'::jsonb),
('g6_1_kor_u3_L11_challenge#8','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C41',4,'mc','auto','토론 뒤 소감 나누기에서 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u3-X40','K6-1-u3-X42','K6-1-u3-X39']::text[],false,'{"seq":8,"concept":"K6-1-u3-C41","difficulty":4,"kind":"mc","stem":"토론 뒤 소감 나누기에서 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「반대 측이 낸 복원 기준 자료를 듣고 되살릴 때 무엇을 지켜야 하는지 생각이 더 깊어졌어. 판정을 맡은 친구가 기준을 먼저 밝혀서 좋았어.」","correct":true},{"t":"「우리 편이 이겼으니 더 할 말이 없어.」","mis":"K6-1-u3-X40"},{"t":"「반대 측은 역사를 모르는 거야.」","mis":"K6-1-u3-X42"},{"t":"「생각이 바뀌면 진 거라 끝까지 안 바꿨어.」","mis":"K6-1-u3-X39"}],"explanation":["승패만 말하면 남는 것이 없어요.","상대 관점을 낮추지 않아요.","새로 안 것과 잘한 친구를 말해요."]}'::jsonb),
('g6_1_kor_u3_L11_challenge#9','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C40',4,'essay','teacher','성곽 토론에서 찬성 측과 반대 측이 각각 무엇을 중요하게 여겼는지 쓰고, 역사 문제로 토론할 때 상대 생각을 어떻게 대해야 하는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C40","difficulty":4,"kind":"essay","stem":"성곽 토론에서 찬성 측과 반대 측이 각각 무엇을 중요하게 여겼는지 쓰고, 역사 문제로 토론할 때 상대 생각을 어떻게 대해야 하는지 쓰세요.","answer_guide":{"answer":"예: 찬성 측 벼리는 사람들이 고장의 역사를 배울 수 있는 기회를 중요하게 여겼다. 반대 측 윤재는 남아 있는 옛 성곽의 진짜 모습을 지키는 것을 중요하게 여겼다. 두 사람 다 역사를 아끼지만 아끼는 방법이 다르다. 역사에 관한 논쟁에는 옳고 그름이 아니라 관점의 차이가 있으므로, 한쪽을 틀린 편으로 만들지 않고 판정 뒤에도 상대 생각을 낮추어 말하지 않아야 한다.","scoring_points":["찬성 측이 중요하게 여긴 것을 썼는가","반대 측이 중요하게 여긴 것을 썼는가","관점의 차이로 보고 상대를 낮추지 않는 태도를 썼는가"]},"explanation":["벼리가 앞에 둔 것을 찾아요.","윤재가 앞에 둔 것을 찾아요.","옳고 그름 대신 관점으로 봐요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"옛 성곽을 원래 모습으로 되살려야 합니다. 지금은 돌담 일부만 남아 있어 사람들이 그곳이 성곽이었는지도 모르고 지나갑니다. 모습을 갖춰야 고장의 역사를 배우는 곳이 됩니다."},{"who":"반대 측 윤재","text":"되살려서는 안 됩니다. 남아 있는 부분이 적어 되살리려면 대부분을 새로 만들어야 합니다. 새로 만든 부분이 많아지면 그것은 옛 성곽이 아니라 새 건물입니다."}]}}'::jsonb),
('g6_1_kor_u3_L11_challenge#10','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C43',4,'essay','teacher','ㄻ · ㄿ · ㄺ 겹받침이 있는 낱말을 하나씩 골라 소리 나는 대로 쓰고, 겹받침을 읽는 규칙을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C43","difficulty":4,"kind":"essay","stem":"ㄻ · ㄿ · ㄺ 겹받침이 있는 낱말을 하나씩 골라 소리 나는 대로 쓰고, 겹받침을 읽는 규칙을 설명하세요.","answer_guide":{"answer":"예: 닮다 [담따] · 읊다 [읍따] · 붉다 [북따]. 겹받침 뒤에 자음이 오면 두 자음 가운데 하나만 소리 난다. ㄻ은 [ㅁ], ㄿ은 [ㅂ], ㄺ은 [ㄱ]으로 소리 나고, 그 뒤에 오는 ㄱ · ㄷ · ㅂ · ㅅ · ㅈ은 된소리가 된다. 다만 ㄺ 뒤에 ㄱ이 오면 [ㄹ]로 소리 나서 「붉고」는 [불꼬]로 읽는다.","scoring_points":["세 겹받침 낱말을 하나씩 바르게 소리 나는 대로 썼는가","하나만 소리 나고 뒤 자음이 된소리가 된다는 규칙을 썼는가","ㄺ 뒤에 ㄱ이 올 때의 예외를 썼는가"]},"explanation":["세 겹받침을 하나씩 골라요.","어느 자음이 소리 나는지 써요.","ㄺ 뒤 ㄱ의 경우를 떠올려요."]}'::jsonb),
('g6_1_kor_u3_review_a#1','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C3',1,'mc','auto','찬성과 반대로 나뉘어 근거를 들어 자기 주장이 옳음을 밝히는 말하기를 무엇이라고 하나요?',ARRAY['K6-1-u3-X02','K6-1-u3-X03']::text[],false,'{"seq":1,"concept":"K6-1-u3-C3","difficulty":1,"kind":"mc","stem":"찬성과 반대로 나뉘어 근거를 들어 자기 주장이 옳음을 밝히는 말하기를 무엇이라고 하나요?","options":[{"t":"토론","correct":true},{"t":"토의","mis":"K6-1-u3-X02"},{"t":"연설","mis":"K6-1-u3-X03"},{"t":"대화","mis":"K6-1-u3-X02"}],"explanation":["토의는 편을 나누지 않아요.","연설은 한 사람이 알리는 말하기예요.","찬반으로 나뉘어 겨루면 토론이에요."]}'::jsonb),
('g6_1_kor_u3_review_a#2','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C4',1,'mc','auto','이유를 뒷받침하는 객관적인 자료를 무엇이라고 하나요?',ARRAY['K6-1-u3-X04','K6-1-u3-X06']::text[],false,'{"seq":2,"concept":"K6-1-u3-C4","difficulty":1,"kind":"mc","stem":"이유를 뒷받침하는 객관적인 자료를 무엇이라고 하나요?","options":[{"t":"근거","correct":true},{"t":"주장","mis":"K6-1-u3-X04"},{"t":"이유","mis":"K6-1-u3-X04"},{"t":"반론","mis":"K6-1-u3-X06"}],"explanation":["주장은 내세우는 생각이에요.","이유는 내 까닭이에요.","밖에서 가져온 자료가 근거예요."]}'::jsonb),
('g6_1_kor_u3_review_a#3','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C5',1,'mc','auto','토론의 첫 단계는 무엇인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":3,"concept":"K6-1-u3-C5","difficulty":1,"kind":"mc","stem":"토론의 첫 단계는 무엇인가요?","options":[{"t":"주장 펼치기","correct":true},{"t":"반론하기","mis":"K6-1-u3-X06"},{"t":"주장 다지기","mis":"K6-1-u3-X06"},{"t":"판정하기","mis":"K6-1-u3-X06"}],"explanation":["반론은 주장을 들은 뒤에 해요.","다지기는 셋째 단계예요.","먼저 주장을 펼쳐요."]}'::jsonb),
('g6_1_kor_u3_review_a#4','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C13',1,'ox','auto','반론할 때에는 상대의 말투나 사람이 아니라 주장 · 이유 · 근거를 겨누어요.',ARRAY['K6-1-u3-X14']::text[],false,'{"seq":4,"concept":"K6-1-u3-C13","difficulty":1,"kind":"ox","stem":"반론할 때에는 상대의 말투나 사람이 아니라 주장 · 이유 · 근거를 겨누어요.","answer":"O","reason_options":[{"t":"토론은 근거를 겨루는 공식적인 말하기이기 때문에","correct":true},{"t":"사람을 겨누어야 상대가 물러서기 때문에","mis":"K6-1-u3-X14"}],"mis":"K6-1-u3-X14","explanation":["사람을 겨누면 반론이 아니에요.","공식적인 말하기예요.","주장 · 이유 · 근거를 겨눠요."]}'::jsonb),
