('g6_1_kor_u3_review_a#6','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C23',1,'mc','auto','주제와 규칙을 알리고 말차례를 이끄는 역할은 무엇인가요?',ARRAY['K6-1-u3-X25']::text[],false,'{"seq":6,"concept":"K6-1-u3-C23","difficulty":1,"kind":"mc","stem":"주제와 규칙을 알리고 말차례를 이끄는 역할은 무엇인가요?","options":[{"t":"사회자","correct":true},{"t":"토론자","mis":"K6-1-u3-X25"},{"t":"판정단","mis":"K6-1-u3-X25"},{"t":"청중","mis":"K6-1-u3-X25"}],"explanation":["토론자는 주장을 말해요.","판정단은 판정해요.","이끄는 사람은 사회자예요."]}'::jsonb),
('g6_1_kor_u3_review_a#7','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C26',1,'mc','auto','근거를 따질 때 던지는 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X30']::text[],false,'{"seq":7,"concept":"K6-1-u3-C26","difficulty":1,"kind":"mc","stem":"근거를 따질 때 던지는 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「출처가 분명한가?」","correct":true},{"t":"「글씨가 예쁜가?」","mis":"K6-1-u3-X35"},{"t":"「자료가 길고 어려운가?」","mis":"K6-1-u3-X30"},{"t":"「내 마음에 드는가?」","mis":"K6-1-u3-X35"}],"explanation":["글씨는 상관없어요.","길이도 상관없어요.","어디서 나왔는지 물어요."]}'::jsonb),
('g6_1_kor_u3_review_a#8','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C43',1,'mc','auto','「읊다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":8,"concept":"K6-1-u3-C43","difficulty":1,"kind":"mc","stem":"「읊다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[읍따]","correct":true},{"t":"[을따]","mis":"K6-1-u3-X44"},{"t":"[읊다]","mis":"K6-1-u3-X44"},{"t":"[으따]","mis":"K6-1-u3-X44"}],"explanation":["ㄿ 뒤에 ㄷ이 왔어요.","ㄿ은 [ㅂ]으로 소리 나요.","뒤의 ㄷ은 된소리가 돼요."]}'::jsonb),
('g6_1_kor_u3_review_a#9','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C9',2,'mc','auto','도담이가 주장 펼치기에서 낸 근거는 무엇인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05','K6-1-u3-X28']::text[],false,'{"seq":9,"concept":"K6-1-u3-C9","difficulty":2,"kind":"mc","stem":"도담이가 주장 펼치기에서 낸 근거는 무엇인가요?","options":[{"t":"도서부가 이번 학기에 고학년 이백 명에게 물은 설문","correct":true},{"t":"쉬는 시간만으로는 책을 고를 시간이 모자란다","mis":"K6-1-u3-X04"},{"t":"점심시간에도 도서실을 열어야 한다","mis":"K6-1-u3-X05"},{"t":"어떤 누리집에서 본 이야기","mis":"K6-1-u3-X28"}],"explanation":["시간이 모자란다는 것은 이유예요.","열어야 한다는 것은 주장이에요.","물어서 센 설문이 근거예요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb),
('g6_1_kor_u3_review_a#10','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C13',2,'mc','auto','서아의 첫 반론이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X26','K6-1-u3-X11']::text[],false,'{"seq":10,"concept":"K6-1-u3-C13","difficulty":2,"kind":"mc","stem":"서아의 첫 반론이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"「그것도 모르십니까?」처럼 사람을 겨누었기 때문에","correct":true},{"t":"높임말을 썼기 때문에","mis":"K6-1-u3-X17"},{"t":"짧게 말했기 때문에","mis":"K6-1-u3-X26"},{"t":"주제와 이어졌기 때문에","mis":"K6-1-u3-X11"}],"explanation":["높임말은 써야 해요.","짧은 것은 문제가 아니에요.","사람을 겨누면 반론이 아니에요."],"asset":{"type":"speech","turns":[{"who":"반대 측 서아","text":"그것도 모르십니까? 점심시간에는 다들 운동장에 나갑니다."},{"who":"찬성 측 도담","text":"말씀 잘 들었습니다. 다만 저희 설문에서 백삼십 명이 빌리고 싶다고 답했습니다. 다들 운동장에 나간다는 말은 저희 자료와 맞지 않습니다."},{"who":"찬성 측 도담","text":"반대 측께 묻겠습니다. 다른 학교도 다 닫는다는 누리집은 어디이고, 언제 쓴 글입니까?"},{"who":"반대 측 서아","text":"누리집 이름은 적어 두지 못했습니다. 그런데 저는 요즘 급식 줄이 더 문제라고 봅니다."}]}}'::jsonb),
('g6_1_kor_u3_review_a#11','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C14',2,'mc','auto','서아의 주장 다지기가 약한 까닭은 무엇인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X17','K6-1-u3-X22']::text[],false,'{"seq":11,"concept":"K6-1-u3-C14","difficulty":2,"kind":"mc","stem":"서아의 주장 다지기가 약한 까닭은 무엇인가요?","options":[{"t":"반론에서 무너진 누리집 근거를 다시 꺼냈기 때문에","correct":true},{"t":"짧게 말했기 때문에","mis":"K6-1-u3-X15"},{"t":"높임말을 썼기 때문에","mis":"K6-1-u3-X17"},{"t":"새 근거를 찾아 왔기 때문에","mis":"K6-1-u3-X22"}],"explanation":["짧은 것은 오히려 좋아요.","높임말은 써야 해요.","무너진 근거를 꺼내면 약해져요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 도담","text":"요컨대 책을 읽고 싶은 학생이 많습니다. 백삼십 명이라는 설문은 반론에서도 흔들리지 않았습니다. 따라서 점심시간에도 도서실을 열어야 합니다."},{"who":"반대 측 서아","text":"처음에 말씀드린 대로 다른 학교도 다 닫는다는 점을 다시 말씀드립니다. 다른 학교도 다 닫으니 우리도 닫아야 합니다."}]}}'::jsonb),
('g6_1_kor_u3_review_a#12','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C33',2,'mc','auto','지우의 판정이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X16','K6-1-u3-X18']::text[],false,'{"seq":12,"concept":"K6-1-u3-C33","difficulty":2,"kind":"mc","stem":"지우의 판정이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"기준 없이 평소 자기 생각과 같은 편을 골랐기 때문에","correct":true},{"t":"찬성 측을 골랐기 때문에","mis":"K6-1-u3-X17"},{"t":"짧게 말했기 때문에","mis":"K6-1-u3-X16"},{"t":"판정을 했기 때문에","mis":"K6-1-u3-X18"}],"explanation":["어느 편을 골랐는지가 문제가 아니에요.","길이가 문제가 아니에요.","평소 생각으로 정한 것이 문제예요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb),
('g6_1_kor_u3_review_a#13','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C34',2,'mc','auto','은솔이의 메모 가운데 되받을 거리로 쓰기 어려운 것은 어느 것인가요?',ARRAY['K6-1-u3-X12','K6-1-u3-X08']::text[],false,'{"seq":13,"concept":"K6-1-u3-C34","difficulty":2,"kind":"mc","stem":"은솔이의 메모 가운데 되받을 거리로 쓰기 어려운 것은 어느 것인가요?","options":[{"t":"반대 측 말투 — 목소리가 컸음.","correct":true},{"t":"찬성 측 근거 — 도서부, 이번 학기, 고학년 이백 명 설문.","mis":"K6-1-u3-X12"},{"t":"반대 측 근거 — 어떤 누리집(어디인지 밝히지 않음).","mis":"K6-1-u3-X08"},{"t":"반대 측이 꺼낸 다른 이야기 — 급식 줄.","mis":"K6-1-u3-X08"}],"explanation":["근거의 출처는 되받을 거리예요.","밝히지 않은 출처도 짚을 곳이에요.","말투는 되받을 거리가 아니에요."],"asset":{"type":"passage","lines":["찬성 측 주장 — 점심시간에도 도서실을 열어야 한다.","찬성 측 이유 — 쉬는 시간만으로는 책 고를 시간이 모자란다.","찬성 측 근거 — 도서부, 이번 학기, 고학년 이백 명 설문.","반대 측 근거 — 어떤 누리집(어디인지 밝히지 않음).","반대 측이 꺼낸 다른 이야기 — 급식 줄.","반대 측 말투 — 목소리가 컸음."],"title":"청중 은솔이의 메모"}}'::jsonb),
('g6_1_kor_u3_review_a#14','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C22',2,'mc','auto','예상 반론에 미리 답변을 준비하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X23','K6-1-u3-X16']::text[],false,'{"seq":14,"concept":"K6-1-u3-C22","difficulty":2,"kind":"mc","stem":"예상 반론에 미리 답변을 준비하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 과정에서 내 근거의 약한 곳을 스스로 점검하게 되기 때문에","correct":true},{"t":"상대 원고를 미리 알 수 있기 때문에","mis":"K6-1-u3-X09"},{"t":"토론에서 반론하기를 건너뛰기 위해서","mis":"K6-1-u3-X23"},{"t":"판정단에게 점수를 받기 위해서","mis":"K6-1-u3-X16"}],"explanation":["상대 원고는 알 수 없어요.","반론하기는 건너뛰지 않아요.","내 근거의 약한 곳이 보여요."]}'::jsonb),
('g6_1_kor_u3_review_a#15','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C18',2,'mc','auto','우리 반 토론 주제를 고를 때 따질 조건을 바르게 말한 것은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X20','K6-1-u3-X19']::text[],false,'{"seq":15,"concept":"K6-1-u3-C18","difficulty":2,"kind":"mc","stem":"우리 반 토론 주제를 고를 때 따질 조건을 바르게 말한 것은 어느 것인가요?","options":[{"t":"친구들이 관심 있고, 찬반이 갈리고, 양쪽 근거를 찾을 수 있고, 우리 힘으로 바꿀 수 있는가","correct":true},{"t":"답이 정해져 있고 확인이 쉬운가","mis":"K6-1-u3-X01"},{"t":"한쪽 편만 있는가","mis":"K6-1-u3-X20"},{"t":"우리가 바꿀 수 없는 먼 일인가","mis":"K6-1-u3-X19"}],"explanation":["답이 정해지면 토론이 안 돼요.","찬반이 갈려야 해요.","관심 · 찬반 · 근거 · 바꿔 볼 수 있음을 따져요."]}'::jsonb),
('g6_1_kor_u3_review_a#16','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C29',2,'mc','auto','경험을 근거로 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X32','K6-1-u3-X31','K6-1-u3-X04']::text[],false,'{"seq":16,"concept":"K6-1-u3-C29","difficulty":2,"kind":"mc","stem":"경험을 근거로 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"느낌으로 두지 말고 세거나 재어서 정리해 내놓는다","correct":true},{"t":"나에게만 일어난 드문 일을 고른다","mis":"K6-1-u3-X32"},{"t":"경험은 근거가 될 수 없으니 쓰지 않는다","mis":"K6-1-u3-X31"},{"t":"생생하게 느낌만 말한다","mis":"K6-1-u3-X04"}],"explanation":["드문 일은 근거가 되기 어려워요.","경험도 근거가 될 수 있어요.","세거나 재어 정리해요."]}'::jsonb),
('g6_1_kor_u3_review_a#17','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C24',3,'mc','auto','찬반 토론의 진행 순서로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":17,"concept":"K6-1-u3-C24","difficulty":3,"kind":"mc","stem":"찬반 토론의 진행 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"주장 펼치기 → 반대 측 반론과 찬성 측 답변 → 찬성 측 반론과 반대 측 답변 → 주장 다지기 → 판정","correct":true},{"t":"판정 → 주장 펼치기 → 반론 → 주장 다지기","mis":"K6-1-u3-X06"},{"t":"반론 → 주장 펼치기 → 판정 → 주장 다지기","mis":"K6-1-u3-X06"},{"t":"주장 펼치기 → 주장 다지기 → 판정 → 반론","mis":"K6-1-u3-X06"}],"explanation":["판정은 맨 끝이에요.","반론은 펼친 뒤에 해요.","두 편이 번갈아 반론하고 답해요."]}'::jsonb),
('g6_1_kor_u3_review_a#18','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C28',3,'mc','auto','사물함 토론에서 새얀이의 근거를 더 타당하게 바꾸는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X32','K6-1-u3-X30','K6-1-u3-X28']::text[],false,'{"seq":18,"concept":"K6-1-u3-C28","difficulty":3,"kind":"mc","stem":"사물함 토론에서 새얀이의 근거를 더 타당하게 바꾸는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"언제, 몇 명에게 물었는지 밝혀 우리 반이나 학년 전체에게 물어본다","correct":true},{"t":"친구 두 명의 말을 더 생생하게 꾸민다","mis":"K6-1-u3-X32"},{"t":"두 명에게 다섯 번씩 묻는다","mis":"K6-1-u3-X30"},{"t":"누리집 이야기를 덧붙인다","mis":"K6-1-u3-X28"}],"explanation":["생생하게 꾸며도 두 명이에요.","같은 사람에게 여러 번 물어도 그대로예요.","대상을 넓히고 때를 밝혀요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 사물함에 자물쇠를 달아야 한다.","찬성 측 온유 — 물건을 잃어버리는 일이 실제로 있기 때문입니다.","우리 학교 고학년 백쉰 명에게 지난달에 물어보니,","마흔여덟 명이 사물함에서 물건을 잃은 적이 있다고 답했습니다.","반대 측 새얀 — 열고 닫기가 번거롭기 때문입니다.","제 친구 두 명에게 물어보니 둘 다 불편할 것 같다고 했습니다."],"title":"두 근거 견주기"}}'::jsonb),
('g6_1_kor_u3_review_a#19','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C12',3,'error','auto','반론에 대한 답변을 했어요. 알맞지 않은 답변을 한 친구는 누구인가요?',ARRAY['K6-1-u3-X13']::text[],false,'{"seq":19,"concept":"K6-1-u3-C12","difficulty":3,"kind":"error","stem":"반론에 대한 답변을 했어요. 알맞지 않은 답변을 한 친구는 누구인가요?","options":[{"t":"이안 — 「어쨌든 저희가 맞습니다. 맞으니까 맞습니다.」","correct":true,"mis_target":"K6-1-u3-X13"},{"t":"서윤 — 「그 점은 인정합니다. 다만 서로 다른 학년 사이의 일이 더 많았습니다.」","mis":"K6-1-u3-X13"},{"t":"하람 — 「조사한 때는 자료 맨 위에 적혀 있습니다.」","mis":"K6-1-u3-X13"}],"explanation":["서윤은 인정하고 다시 세웠어요.","하람은 물은 것에 곧바로 답했어요.","이안은 같은 말을 되풀이했어요."]}'::jsonb),
('g6_1_kor_u3_review_a#20','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C36',3,'mc','auto','도서실 토론 뒤 세 친구의 말 가운데 가장 알맞게 마무리한 사람은 누구인가요?',ARRAY['K6-1-u3-X18','K6-1-u3-X40','K6-1-u3-X39']::text[],false,'{"seq":20,"concept":"K6-1-u3-C36","difficulty":3,"kind":"mc","stem":"도서실 토론 뒤 세 친구의 말 가운데 가장 알맞게 마무리한 사람은 누구인가요?","options":[{"t":"도담 — 상대 근거에서 미처 생각 못 한 점을 받아들이고 더 찾아보려 했다","correct":true},{"t":"서아 — 판정이 이상하다며 판정단 탓을 했다","mis":"K6-1-u3-X18"},{"t":"아무도 없다 — 토론 뒤에는 승패만 말하면 된다","mis":"K6-1-u3-X40"},{"t":"아무도 없다 — 생각이 바뀌면 진 것이다","mis":"K6-1-u3-X39"}],"explanation":["판정에는 승복해요.","승패만 남기지 않아요.","생각을 남기는 마무리가 좋아요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"판정이 이상해. 우리가 진 건 판정단 탓이야."},{"who":"은솔","text":"나는 도서부 설문 자료를 처음 알았어. 사회를 맡은 하람이가 말차례를 잘 지켜 줬어."},{"who":"도담","text":"반대 측이 말한 지키는 분의 쉬는 시간은 미처 생각 못 했어. 도서부가 돌아가며 돕는 방법을 찾아봐야겠어."}]}}'::jsonb),
('g6_1_kor_u3_review_a#21','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C40',3,'mc','auto','「옛 건물을 헐고 남은 터를 공원으로 만들어야 한다」를 두고 토론할 때 알맞은 태도는 어느 것인가요?',ARRAY['K6-1-u3-X42','K6-1-u3-X40']::text[],false,'{"seq":21,"concept":"K6-1-u3-C40","difficulty":3,"kind":"mc","stem":"「옛 건물을 헐고 남은 터를 공원으로 만들어야 한다」를 두고 토론할 때 알맞은 태도는 어느 것인가요?","options":[{"t":"서로 무엇을 더 중요하게 여기는지 관점의 차이로 보고 상대 생각을 낮추어 말하지 않는다","correct":true},{"t":"공원으로 만들자는 쪽이 옳다고 먼저 정해 둔다","mis":"K6-1-u3-X42"},{"t":"역사를 아끼는 쪽과 아끼지 않는 쪽으로 나눈다","mis":"K6-1-u3-X42"},{"t":"판정 뒤 상대 생각은 틀렸다고 말한다","mis":"K6-1-u3-X40"}],"explanation":["옳은 쪽을 먼저 정하지 않아요.","두 쪽 다 아낄 수 있어요.","관점의 차이로 봐요."]}'::jsonb),
('g6_1_kor_u3_review_a#22','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C43',3,'mc','auto','「밝고」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":22,"concept":"K6-1-u3-C43","difficulty":3,"kind":"mc","stem":"「밝고」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[발꼬]","correct":true},{"t":"[박꼬]","mis":"K6-1-u3-X44"},{"t":"[발고]","mis":"K6-1-u3-X44"},{"t":"[밝고]","mis":"K6-1-u3-X44"}],"explanation":["ㄺ 뒤에 ㄱ이 왔어요.","이때는 [ㄹ]로 소리 나요.","뒤의 ㄱ은 된소리가 돼요."]}'::jsonb),
('g6_1_kor_u3_review_a#23','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C27',4,'mc','auto','반대 측 서아의 주장 펼치기를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u3-X29','K6-1-u3-X05','K6-1-u3-X32']::text[],false,'{"seq":23,"concept":"K6-1-u3-C27","difficulty":4,"kind":"mc","stem":"반대 측 서아의 주장 펼치기를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"이유는 그대로 두고, 「어떤 누리집」 대신 학교가 올해 낸 도서실 운영 안내처럼 누가 언제 냈는지 확인되는 자료를 근거로 든다","correct":true},{"t":"누리집 이야기를 「많은 누리집」으로 바꾼다","mis":"K6-1-u3-X29"},{"t":"근거를 빼고 이유만 여러 번 말한다","mis":"K6-1-u3-X05"},{"t":"자기 친구 한 명의 느낌을 근거로 더한다","mis":"K6-1-u3-X32"}],"explanation":["「많은」도 흐릿해요.","근거를 빼면 확인할 수 없어요.","출처가 분명한 자료로 바꿔요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb),
('g6_1_kor_u3_review_a#24','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C13',4,'essay','teacher','서아의 반론 두 군데에서 알맞지 않은 점을 찾아 쓰고, 찬성 측 근거를 겨누는 알맞은 반론으로 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u3-C13","difficulty":4,"kind":"essay","stem":"서아의 반론 두 군데에서 알맞지 않은 점을 찾아 쓰고, 찬성 측 근거를 겨누는 알맞은 반론으로 고쳐 쓰세요.","answer_guide":{"answer":"예: 첫째, 「그것도 모르십니까?」는 근거가 아니라 사람을 겨눈 말이다. 둘째, 「급식 줄이 더 문제」는 주장 펼치기에서 나온 내용과 상관없는 새 이야기이다. 고친 반론 — 「찬성 측 설문은 빌리고 싶다고 답한 학생 수를 보여 줍니다. 그런데 실제로 점심시간에 도서실에 올 수 있는 학생이 몇 명인지는 나와 있지 않습니다.」","scoring_points":["사람을 겨눈 점을 찾았는가","주제와 상관없는 이야기를 꺼낸 점을 찾았는가","찬성 측 근거를 겨누는 반론을 높임말로 썼는가"]},"explanation":["겨눈 곳이 어디인지 봐요.","주장 펼치기와 이어지는지 봐요.","근거를 겨누어 고쳐요."],"asset":{"type":"speech","turns":[{"who":"반대 측 서아","text":"그것도 모르십니까? 점심시간에는 다들 운동장에 나갑니다."},{"who":"찬성 측 도담","text":"말씀 잘 들었습니다. 다만 저희 설문에서 백삼십 명이 빌리고 싶다고 답했습니다. 다들 운동장에 나간다는 말은 저희 자료와 맞지 않습니다."},{"who":"찬성 측 도담","text":"반대 측께 묻겠습니다. 다른 학교도 다 닫는다는 누리집은 어디이고, 언제 쓴 글입니까?"},{"who":"반대 측 서아","text":"누리집 이름은 적어 두지 못했습니다. 그런데 저는 요즘 급식 줄이 더 문제라고 봅니다."}]}}'::jsonb),
('g6_1_kor_u3_review_a#25','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C5',4,'essay','teacher','토론의 네 단계를 차례대로 쓰고, 각 단계에서 지켜야 할 절차나 규칙을 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u3-C5","difficulty":4,"kind":"essay","stem":"토론의 네 단계를 차례대로 쓰고, 각 단계에서 지켜야 할 절차나 규칙을 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 주장 펼치기 — 주장과 이유, 근거를 함께 낸다. 반론하기 — 주장 펼치기에서 나온 내용에 대해서만 되받고, 사람이 아니라 근거를 겨눈다. 주장 다지기 — 같은 말을 되풀이하지 않고 남은 것만 추려 다시 세운다. 판정하기 — 판정단이 기준을 먼저 밝히고 토론에서 나온 내용만으로 정한다.","scoring_points":["네 단계를 차례대로 썼는가","단계마다 알맞은 규칙을 썼는가","판정에서 기준을 밝힌다는 점을 썼는가"]},"explanation":["네 단계의 이름을 차례로 써요.","단계마다 규칙을 하나씩 써요.","판정 기준을 떠올려요."]}'::jsonb),
('g6_1_kor_u3_review_b#1','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C2',1,'ox','auto','토의는 편을 나누어 겨루고, 토론은 편 없이 방법을 모으는 말하기예요.',ARRAY['K6-1-u3-X02']::text[],false,'{"seq":1,"concept":"K6-1-u3-C2","difficulty":1,"kind":"ox","stem":"토의는 편을 나누어 겨루고, 토론은 편 없이 방법을 모으는 말하기예요.","answer":"X","reason_options":[{"t":"반대로 토의는 편 없이 방법을 모으고, 토론은 찬반으로 나뉘어 겨루기 때문에","correct":true},{"t":"둘은 이름만 다르고 같은 말하기이기 때문에","mis":"K6-1-u3-X02"}],"mis":"K6-1-u3-X02","explanation":["두 말이 뒤바뀌었어요.","토의는 함께 방법을 모아요.","토론은 찬반으로 나뉘어요."]}'::jsonb),
('g6_1_kor_u3_review_b#2','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C4',1,'mc','auto','내가 옳다고 내세우는 생각을 무엇이라고 하나요?',ARRAY['K6-1-u3-X04','K6-1-u3-X06']::text[],false,'{"seq":2,"concept":"K6-1-u3-C4","difficulty":1,"kind":"mc","stem":"내가 옳다고 내세우는 생각을 무엇이라고 하나요?","options":[{"t":"주장","correct":true},{"t":"근거","mis":"K6-1-u3-X04"},{"t":"이유","mis":"K6-1-u3-X04"},{"t":"판정","mis":"K6-1-u3-X06"}],"explanation":["근거는 자료예요.","이유는 까닭이에요.","내세우는 생각이 주장이에요."]}'::jsonb),
('g6_1_kor_u3_review_b#3','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C5',1,'mc','auto','토론의 마지막 단계는 무엇인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":3,"concept":"K6-1-u3-C5","difficulty":1,"kind":"mc","stem":"토론의 마지막 단계는 무엇인가요?","options":[{"t":"판정하기","correct":true},{"t":"주장 펼치기","mis":"K6-1-u3-X06"},{"t":"반론하기","mis":"K6-1-u3-X06"},{"t":"주장 다지기","mis":"K6-1-u3-X06"}],"explanation":["펼치기는 첫 단계예요.","반론은 둘째 단계예요.","판정은 맨 끝이에요."]}'::jsonb),
('g6_1_kor_u3_review_b#4','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C13',1,'mc','auto','반론으로 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u3-X14']::text[],false,'{"seq":4,"concept":"K6-1-u3-C13","difficulty":1,"kind":"mc","stem":"반론으로 알맞은 말은 어느 것인가요?","options":[{"t":"「그 자료는 조사한 때가 나와 있지 않습니다.」","correct":true},{"t":"「그것도 모르십니까?」","mis":"K6-1-u3-X14"},{"t":"「그런 게 어디 있습니까?」","mis":"K6-1-u3-X14"},{"t":"「준비를 안 하셨군요.」","mis":"K6-1-u3-X14"}],"explanation":["모르냐고 묻는 말은 사람을 겨눠요.","깎아내리는 말도 마찬가지예요.","근거의 빈 곳을 짚어요."]}'::jsonb),
('g6_1_kor_u3_review_b#5','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C15',1,'ox','auto','판정은 어느 쪽이 더 큰 목소리로 말했는지로 정해요.',ARRAY['K6-1-u3-X16']::text[],false,'{"seq":5,"concept":"K6-1-u3-C15","difficulty":1,"kind":"ox","stem":"판정은 어느 쪽이 더 큰 목소리로 말했는지로 정해요.","answer":"X","reason_options":[{"t":"미리 밝힌 기준으로 어느 쪽이 더 설득력 있었는지 정하기 때문에","correct":true},{"t":"목소리가 크면 자신감이 있다는 뜻이기 때문에","mis":"K6-1-u3-X16"}],"mis":"K6-1-u3-X16","explanation":["목소리 크기는 기준이 아니에요.","기준을 먼저 밝혀요.","더 설득력 있게 말한 쪽을 정해요."]}'::jsonb),
('g6_1_kor_u3_review_b#6','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C23',1,'mc','auto','양측 발언을 메모하며 듣고, 끝나면 잘한 곳을 짚어 주는 역할은 무엇인가요?',ARRAY['K6-1-u3-X25']::text[],false,'{"seq":6,"concept":"K6-1-u3-C23","difficulty":1,"kind":"mc","stem":"양측 발언을 메모하며 듣고, 끝나면 잘한 곳을 짚어 주는 역할은 무엇인가요?","options":[{"t":"청중","correct":true},{"t":"사회자","mis":"K6-1-u3-X25"},{"t":"판정단","mis":"K6-1-u3-X25"},{"t":"토론자","mis":"K6-1-u3-X25"}],"explanation":["사회자는 이끌어요.","판정단은 정해요.","듣고 짚어 주는 사람은 청중이에요."]}'::jsonb),
('g6_1_kor_u3_review_b#7','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C26',1,'ox','auto','근거는 이유와 이어지는지, 출처가 분명한지, 구체적인지 따져 봐요.',ARRAY['K6-1-u3-X35']::text[],false,'{"seq":7,"concept":"K6-1-u3-C26","difficulty":1,"kind":"ox","stem":"근거는 이유와 이어지는지, 출처가 분명한지, 구체적인지 따져 봐요.","answer":"O","reason_options":[{"t":"세 물음 가운데 하나만 걸려도 근거가 흔들리기 때문에","correct":true},{"t":"숫자만 들어 있으면 따질 필요가 없기 때문에","mis":"K6-1-u3-X35"}],"mis":"K6-1-u3-X35","explanation":["세 물음을 한 번씩 던져요.","숫자만 보고 넘어가지 않아요.","전체적으로 타당한지 봐요."]}'::jsonb),
('g6_1_kor_u3_review_b#8','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C43',1,'mc','auto','「젊다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":8,"concept":"K6-1-u3-C43","difficulty":1,"kind":"mc","stem":"「젊다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[점따]","correct":true},{"t":"[절따]","mis":"K6-1-u3-X44"},{"t":"[젊다]","mis":"K6-1-u3-X44"},{"t":"[저따]","mis":"K6-1-u3-X44"}],"explanation":["ㄻ 뒤에 ㄷ이 왔어요.","ㄻ은 [ㅁ]으로 소리 나요.","뒤의 ㄷ은 된소리가 돼요."]}'::jsonb),
('g6_1_kor_u3_review_b#9','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C10',2,'mc','auto','서아가 든 근거의 문제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X05','K6-1-u3-X30','K6-1-u3-X17']::text[],false,'{"seq":9,"concept":"K6-1-u3-C10","difficulty":2,"kind":"mc","stem":"서아가 든 근거의 문제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어느 누리집인지 밝히지 않아 확인할 수 없다","correct":true},{"t":"이유가 하나도 없다","mis":"K6-1-u3-X05"},{"t":"너무 구체적이다","mis":"K6-1-u3-X30"},{"t":"높임말을 썼다","mis":"K6-1-u3-X17"}],"explanation":["서아도 이유는 말했어요.","구체적인 것은 문제가 아니에요.","출처를 밝히지 않았어요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb),
('g6_1_kor_u3_review_b#10','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C12',2,'mc','auto','도담이의 답변이 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":10,"concept":"K6-1-u3-C12","difficulty":2,"kind":"mc","stem":"도담이의 답변이 알맞은 까닭은 무엇인가요?","options":[{"t":"「다들 운동장에 나간다」는 말이 설문 자료와 맞지 않음을 밝혔기 때문에","correct":true},{"t":"같은 말을 되풀이했기 때문에","mis":"K6-1-u3-X13"},{"t":"서아의 말투를 문제 삼았기 때문에","mis":"K6-1-u3-X14"},{"t":"새로운 주제를 꺼냈기 때문에","mis":"K6-1-u3-X11"}],"explanation":["되풀이하지 않았어요.","말투를 겨누지 않았어요.","자료로 반론이 타당하지 않음을 밝혔어요."],"asset":{"type":"speech","turns":[{"who":"반대 측 서아","text":"그것도 모르십니까? 점심시간에는 다들 운동장에 나갑니다."},{"who":"찬성 측 도담","text":"말씀 잘 들었습니다. 다만 저희 설문에서 백삼십 명이 빌리고 싶다고 답했습니다. 다들 운동장에 나간다는 말은 저희 자료와 맞지 않습니다."},{"who":"찬성 측 도담","text":"반대 측께 묻겠습니다. 다른 학교도 다 닫는다는 누리집은 어디이고, 언제 쓴 글입니까?"},{"who":"반대 측 서아","text":"누리집 이름은 적어 두지 못했습니다. 그런데 저는 요즘 급식 줄이 더 문제라고 봅니다."}]}}'::jsonb),
('g6_1_kor_u3_review_b#11','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C14',2,'mc','auto','도담이의 주장 다지기가 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":11,"concept":"K6-1-u3-C14","difficulty":2,"kind":"mc","stem":"도담이의 주장 다지기가 알맞은 까닭은 무엇인가요?","options":[{"t":"반론에서도 흔들리지 않은 설문을 추려 짧게 다시 세웠기 때문에","correct":true},{"t":"처음 한 말을 그대로 되풀이했기 때문에","mis":"K6-1-u3-X15"},{"t":"상대 말투를 짚었기 때문에","mis":"K6-1-u3-X14"},{"t":"새로운 주제를 꺼냈기 때문에","mis":"K6-1-u3-X11"}],"explanation":["되풀이가 아니에요.","말투를 겨누지 않았어요.","남은 것을 추려 다시 세웠어요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 도담","text":"요컨대 책을 읽고 싶은 학생이 많습니다. 백삼십 명이라는 설문은 반론에서도 흔들리지 않았습니다. 따라서 점심시간에도 도서실을 열어야 합니다."},{"who":"반대 측 서아","text":"처음에 말씀드린 대로 다른 학교도 다 닫는다는 점을 다시 말씀드립니다. 다른 학교도 다 닫으니 우리도 닫아야 합니다."}]}}'::jsonb),
('g6_1_kor_u3_review_b#12','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C15',2,'mc','auto','나래의 판정이 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X24','K6-1-u3-X16']::text[],false,'{"seq":12,"concept":"K6-1-u3-C15","difficulty":2,"kind":"mc","stem":"나래의 판정이 알맞은 까닭은 무엇인가요?","options":[{"t":"미리 정한 기준을 밝히고 그 기준으로 정했으며 잘한 곳도 짚었기 때문에","correct":true},{"t":"찬성 측이 옳다고 가려 주었기 때문에","mis":"K6-1-u3-X17"},{"t":"평소 자기 생각을 말했기 때문에","mis":"K6-1-u3-X24"},{"t":"목소리가 큰 쪽을 골랐기 때문에","mis":"K6-1-u3-X16"}],"explanation":["옳고 그름을 가린 것이 아니에요.","평소 생각을 넣지 않았어요.","기준을 밝히고 정했어요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb),
('g6_1_kor_u3_review_b#13','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C27',2,'mc','auto','은솔이의 메모로 반대 측 근거를 겨누는 반론을 만든다면 무엇을 짚어야 하나요?',ARRAY['K6-1-u3-X14','K6-1-u3-X30','K6-1-u3-X17']::text[],false,'{"seq":13,"concept":"K6-1-u3-C27","difficulty":2,"kind":"mc","stem":"은솔이의 메모로 반대 측 근거를 겨누는 반론을 만든다면 무엇을 짚어야 하나요?","options":[{"t":"어느 누리집인지 밝히지 않아 확인할 수 없다는 점","correct":true},{"t":"반대 측 목소리가 컸다는 점","mis":"K6-1-u3-X14"},{"t":"반대 측 근거가 너무 구체적이라는 점","mis":"K6-1-u3-X30"},{"t":"반대 측이 높임말을 썼다는 점","mis":"K6-1-u3-X17"}],"explanation":["목소리는 사람을 겨눠요.","구체적인 것은 문제가 아니에요.","출처가 확인되지 않는 점을 짚어요."],"asset":{"type":"passage","lines":["찬성 측 주장 — 점심시간에도 도서실을 열어야 한다.","찬성 측 이유 — 쉬는 시간만으로는 책 고를 시간이 모자란다.","찬성 측 근거 — 도서부, 이번 학기, 고학년 이백 명 설문.","반대 측 근거 — 어떤 누리집(어디인지 밝히지 않음).","반대 측이 꺼낸 다른 이야기 — 급식 줄.","반대 측 말투 — 목소리가 컸음."],"title":"청중 은솔이의 메모"}}'::jsonb),
('g6_1_kor_u3_review_b#14','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C21',2,'mc','auto','설문 조사로 근거를 마련하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X29','K6-1-u3-X33']::text[],false,'{"seq":14,"concept":"K6-1-u3-C21","difficulty":2,"kind":"mc","stem":"설문 조사로 근거를 마련하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 반이나 학년에 직접 물어 수를 세고, 언제 몇 명에게 물었는지 적는다","correct":true},{"t":"친구 한두 명에게만 물어 모두의 생각이라고 쓴다","mis":"K6-1-u3-X29"},{"t":"물은 때와 사람 수는 적지 않는다","mis":"K6-1-u3-X29"},{"t":"내 생각과 같은 답만 골라 센다","mis":"K6-1-u3-X33"}],"explanation":["한두 명은 모두가 아니에요.","때와 사람 수를 적어요.","치우치지 않게 세요."]}'::jsonb),
('g6_1_kor_u3_review_b#15','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C32',2,'mc','auto','사회 문제 토론에서 「알려진 사실부터 함께 맞춰 본다」고 하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X16','K6-1-u3-X36']::text[],false,'{"seq":15,"concept":"K6-1-u3-C32","difficulty":2,"kind":"mc","stem":"사회 문제 토론에서 「알려진 사실부터 함께 맞춰 본다」고 하는 까닭은 무엇인가요?","options":[{"t":"아는 것이 적으면 토론이 겉돌기 쉽기 때문에","correct":true},{"t":"사실을 맞추면 토론할 필요가 없어지기 때문에","mis":"K6-1-u3-X01"},{"t":"판정 결과를 미리 정하기 위해서","mis":"K6-1-u3-X16"},{"t":"사실은 토론에 필요 없기 때문에","mis":"K6-1-u3-X36"}],"explanation":["사실을 맞춰도 생각은 갈려요.","판정은 토론 뒤에 해요.","사실을 알아야 겉돌지 않아요."]}'::jsonb),
('g6_1_kor_u3_review_b#16','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C30',2,'mc','auto','근거 자료로 가장 믿을 만한 것은 어느 것인가요?',ARRAY['K6-1-u3-X33','K6-1-u3-X27']::text[],false,'{"seq":16,"concept":"K6-1-u3-C30","difficulty":2,"kind":"mc","stem":"근거 자료로 가장 믿을 만한 것은 어느 것인가요?","options":[{"t":"우리 시가 올해 낸, 주제와 직접 이어지는 조사 자료","correct":true},{"t":"물건을 팔려는 회사가 쓴 광고 글","mis":"K6-1-u3-X33"},{"t":"아주 오래전에 나온 자료","mis":"K6-1-u3-X33"},{"t":"주제와 비슷해 보이는 다른 나라 이야기","mis":"K6-1-u3-X27"}],"explanation":["광고 글은 치우쳐요.","오래된 자료는 지금과 다를 수 있어요.","공신력 · 최근 · 직접 이어짐을 봐요."]}'::jsonb),
('g6_1_kor_u3_review_b#17','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C5',3,'error','auto','토론의 단계를 설명했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X06','K6-1-u3-X05','K6-1-u3-X16']::text[],false,'{"seq":17,"concept":"K6-1-u3-C5","difficulty":3,"kind":"error","stem":"토론의 단계를 설명했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"도겸 — 「주장 다지기에서는 상대 근거의 허점을 처음으로 짚어.」","correct":true,"mis_target":"K6-1-u3-X06"},{"t":"하윤 — 「주장 펼치기에서는 주장 · 이유 · 근거를 함께 내.」","mis":"K6-1-u3-X05"},{"t":"지안 — 「판정하기에서는 판정단이 기준을 밝혀.」","mis":"K6-1-u3-X16"}],"explanation":["하윤은 펼치기를 바르게 말했어요.","지안은 판정하기를 바르게 말했어요.","허점을 짚는 것은 반론하기예요."]}'::jsonb),
('g6_1_kor_u3_review_b#18','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C26',3,'mc','auto','사물함 토론에서 온유의 근거가 타당한 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X31','K6-1-u3-X17']::text[],false,'{"seq":18,"concept":"K6-1-u3-C26","difficulty":3,"kind":"mc","stem":"사물함 토론에서 온유의 근거가 타당한 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"물건을 잃는 일이 있다는 이유와 이어지고, 지난달 · 백쉰 명이라는 조사가 밝혀져 있다","correct":true},{"t":"숫자가 크니 따져 볼 필요가 없다","mis":"K6-1-u3-X35"},{"t":"설문은 근거가 될 수 없다","mis":"K6-1-u3-X31"},{"t":"찬성 측이니 맞다","mis":"K6-1-u3-X17"}],"explanation":["숫자만 보지 않아요.","설문도 근거가 돼요.","이유와 이어지고 구체적이에요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 사물함에 자물쇠를 달아야 한다.","찬성 측 온유 — 물건을 잃어버리는 일이 실제로 있기 때문입니다.","우리 학교 고학년 백쉰 명에게 지난달에 물어보니,","마흔여덟 명이 사물함에서 물건을 잃은 적이 있다고 답했습니다.","반대 측 새얀 — 열고 닫기가 번거롭기 때문입니다.","제 친구 두 명에게 물어보니 둘 다 불편할 것 같다고 했습니다."],"title":"두 근거 견주기"}}'::jsonb),
('g6_1_kor_u3_review_b#19','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C13',3,'mc','auto','반론할 때 높임말을 쓰고 공격적인 말투를 피하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X16','K6-1-u3-X14']::text[],false,'{"seq":19,"concept":"K6-1-u3-C13","difficulty":3,"kind":"mc","stem":"반론할 때 높임말을 쓰고 공격적인 말투를 피하는 까닭은 무엇인가요?","options":[{"t":"토론은 공식적인 말하기이고, 말투가 거칠어지면 근거가 아니라 사람을 겨누게 되기 때문에","correct":true},{"t":"높임말을 쓰면 무조건 이기기 때문에","mis":"K6-1-u3-X09"},{"t":"판정단이 말투만 보기 때문에","mis":"K6-1-u3-X16"},{"t":"높임말을 쓰면 상대에게 지는 것이기 때문에","mis":"K6-1-u3-X14"}],"explanation":["이기려고 쓰는 것이 아니에요.","판정단은 기준을 봐요.","공식적인 말하기라 존중해요."]}'::jsonb),
('g6_1_kor_u3_review_b#20','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C41',3,'mc','auto','은솔이의 말이 토론 뒤 나눌 이야기로 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X40','K6-1-u3-X18']::text[],false,'{"seq":20,"concept":"K6-1-u3-C41","difficulty":3,"kind":"mc","stem":"은솔이의 말이 토론 뒤 나눌 이야기로 알맞은 까닭은 무엇인가요?","options":[{"t":"새롭게 안 사실과 다른 역할을 맡은 친구의 잘한 점을 말했기 때문에","correct":true},{"t":"승패를 분명히 말했기 때문에","mis":"K6-1-u3-X40"},{"t":"판정 결과를 바꾸자고 했기 때문에","mis":"K6-1-u3-X18"},{"t":"상대의 준비 부족을 짚었기 때문에","mis":"K6-1-u3-X40"}],"explanation":["은솔이는 승패를 말하지 않았어요.","판정을 바꾸자고 하지 않았어요.","새로 안 것과 잘한 친구를 말했어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"판정이 이상해. 우리가 진 건 판정단 탓이야."},{"who":"은솔","text":"나는 도서부 설문 자료를 처음 알았어. 사회를 맡은 하람이가 말차례를 잘 지켜 줬어."},{"who":"도담","text":"반대 측이 말한 지키는 분의 쉬는 시간은 미처 생각 못 했어. 도서부가 돌아가며 돕는 방법을 찾아봐야겠어."}]}}'::jsonb),
('g6_1_kor_u3_review_b#21','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C38',3,'mc','auto','모둠이 모은 근거 가운데 준비표에 옮길 것을 고르는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X43','K6-1-u3-X30','K6-1-u3-X22']::text[],false,'{"seq":21,"concept":"K6-1-u3-C38","difficulty":3,"kind":"mc","stem":"모둠이 모은 근거 가운데 준비표에 옮길 것을 고르는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 편끼리 바꾸어 읽고 세 물음을 던져 가장 센 두 가지만 고른다","correct":true},{"t":"모은 것을 하나도 빼지 않고 모두 옮긴다","mis":"K6-1-u3-X43"},{"t":"가장 긴 자료부터 옮긴다","mis":"K6-1-u3-X30"},{"t":"출처를 지우고 내용만 옮긴다","mis":"K6-1-u3-X22"}],"explanation":["약한 것까지 옮기면 흔들려요.","길이로 고르지 않아요.","세 물음으로 골라요."]}'::jsonb),
('g6_1_kor_u3_review_b#22','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C43',3,'mc','auto','「묽고」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":22,"concept":"K6-1-u3-C43","difficulty":3,"kind":"mc","stem":"「묽고」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[물꼬]","correct":true},{"t":"[묵꼬]","mis":"K6-1-u3-X44"},{"t":"[물고]","mis":"K6-1-u3-X44"},{"t":"[묽고]","mis":"K6-1-u3-X44"}],"explanation":["ㄺ 뒤에 ㄱ이 왔어요.","이때는 [ㄹ]로 소리 나요.","뒤의 ㄱ은 된소리가 돼요."]}'::jsonb),
('g6_1_kor_u3_review_b#23','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C16',4,'mc','auto','두 판정단의 판정을 견주어 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X24','K6-1-u3-X16']::text[],false,'{"seq":23,"concept":"K6-1-u3-C16","difficulty":4,"kind":"mc","stem":"두 판정단의 판정을 견주어 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나래는 기준을 밝히고 토론에 나온 내용으로 정해 알맞고, 지우는 기준 없이 평소 생각으로 정해 알맞지 않다","correct":true},{"t":"두 사람 모두 찬성 측을 골랐으니 똑같이 알맞다","mis":"K6-1-u3-X17"},{"t":"지우가 솔직하게 자기 생각을 말해 더 알맞다","mis":"K6-1-u3-X24"},{"t":"판정은 누가 해도 결과가 같으니 따질 필요가 없다","mis":"K6-1-u3-X16"}],"explanation":["고른 편이 같아도 방법이 달라요.","평소 생각을 넣으면 안 돼요.","기준을 밝혔는지 봐요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb),
('g6_1_kor_u3_review_b#24','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C33',4,'essay','teacher','지우와 나래의 판정을 견주어 어느 판정이 알맞은지 까닭과 함께 쓰고, 판정단이 지켜야 할 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u3-C33","difficulty":4,"kind":"essay","stem":"지우와 나래의 판정을 견주어 어느 판정이 알맞은지 까닭과 함께 쓰고, 판정단이 지켜야 할 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 나래의 판정이 알맞다. 나래는 근거가 믿을 만한가와 반론에 알맞게 답했는가라는 기준을 먼저 밝히고, 그 기준으로 찬성 측이 더 설득력 있었다고 정했으며 반대 측이 잘한 곳도 짚었다. 지우는 기준 없이 원래 자기 생각과 같은 편을 골랐다. 판정단은 첫째, 판정 기준을 미리 정해 밝혀야 하고, 둘째, 자기 생각과 같은 편에 후하게 주지 않고 토론에서 나온 말과 자료만으로 판정해야 한다.","scoring_points":["알맞은 판정을 고르고 까닭을 썼는가","알맞지 않은 판정의 문제를 썼는가","판정단이 지킬 점 두 가지를 썼는가"]},"explanation":["두 판정을 견줘요.","기준을 밝혔는지 봐요.","공정함을 떠올려요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb),
('g6_1_kor_u3_review_b#25','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C7',4,'essay','teacher','「토론은 겨루는 방식이지만 목적은 이기는 것이 아니다」라는 말을 설명하고, 이 단원에서 배운 태도 두 가지와 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u3-C7","difficulty":4,"kind":"essay","stem":"「토론은 겨루는 방식이지만 목적은 이기는 것이 아니다」라는 말을 설명하고, 이 단원에서 배운 태도 두 가지와 이어 쓰세요.","answer_guide":{"answer":"예: 토론은 찬성과 반대로 나뉘어 겨루는 말하기이지만, 그렇게 겨루는 까닭은 더 합리적인 결정에 이르기 위해서이다. 그래서 상대를 누르려고 사람을 겨누지 않고 근거를 겨누어 반론해야 한다. 또 판정 결과에 승복하고, 토론 뒤에 생각이 바뀌는 것을 부끄러워하지 않으며 새로 알게 된 것을 나눈다.","scoring_points":["겨루는 방식과 목적을 구별해 설명했는가","근거를 겨누는 태도를 썼는가","승복하거나 생각을 나누는 태도를 썼는가"]},"explanation":["방식과 목적을 갈라요.","반론하는 태도를 떠올려요.","판정 뒤의 태도를 떠올려요."]}'::jsonb),
('g6_1_kor_u3_review_c#1','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C2',1,'mc','auto','「우리 반 학급 문고에 어떤 책을 들일지 의견 모으기」는 토의와 토론 가운데 무엇인가요?',ARRAY['K6-1-u3-X02','K6-1-u3-X06']::text[],false,'{"seq":1,"concept":"K6-1-u3-C2","difficulty":1,"kind":"mc","stem":"「우리 반 학급 문고에 어떤 책을 들일지 의견 모으기」는 토의와 토론 가운데 무엇인가요?","options":[{"t":"토의","correct":true},{"t":"토론","mis":"K6-1-u3-X02"},{"t":"판정","mis":"K6-1-u3-X06"},{"t":"반론","mis":"K6-1-u3-X06"}],"explanation":["편이 갈리지 않아요.","판정 · 반론은 토론의 단계예요.","함께 방법을 모으니 토의예요."]}'::jsonb),
