('g6_1_kor_u3_review_c#3','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C14',1,'mc','auto','자기편 주장을 정리해 다시 힘주어 말하는 단계는 무엇인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":3,"concept":"K6-1-u3-C14","difficulty":1,"kind":"mc","stem":"자기편 주장을 정리해 다시 힘주어 말하는 단계는 무엇인가요?","options":[{"t":"주장 다지기","correct":true},{"t":"주장 펼치기","mis":"K6-1-u3-X06"},{"t":"반론하기","mis":"K6-1-u3-X06"},{"t":"판정하기","mis":"K6-1-u3-X06"}],"explanation":["펼치기는 처음 내놓는 단계예요.","반론은 되받는 단계예요.","다시 세우는 단계는 주장 다지기예요."]}'::jsonb),
('g6_1_kor_u3_review_c#4','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C11',1,'mc','auto','상대의 주장에 맞서서 반대되는 자기 주장을 밝히는 말하기를 무엇이라고 하나요?',ARRAY['K6-1-u3-X06','K6-1-u3-X02']::text[],false,'{"seq":4,"concept":"K6-1-u3-C11","difficulty":1,"kind":"mc","stem":"상대의 주장에 맞서서 반대되는 자기 주장을 밝히는 말하기를 무엇이라고 하나요?","options":[{"t":"반론","correct":true},{"t":"판정","mis":"K6-1-u3-X06"},{"t":"주장 다지기","mis":"K6-1-u3-X06"},{"t":"토의","mis":"K6-1-u3-X02"}],"explanation":["판정은 판정단이 해요.","다지기는 자기편을 다시 세워요.","맞서서 되받는 것이 반론이에요."]}'::jsonb),
('g6_1_kor_u3_review_c#5','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C16',1,'ox','auto','토론자는 판정 결과에 승복하는 태도를 지녀요.',ARRAY['K6-1-u3-X18']::text[],false,'{"seq":5,"concept":"K6-1-u3-C16","difficulty":1,"kind":"ox","stem":"토론자는 판정 결과에 승복하는 태도를 지녀요.","answer":"O","reason_options":[{"t":"판정은 정한 기준으로 공정하게 낸 결과이기 때문에","correct":true},{"t":"판정은 늘 틀리기 때문에","mis":"K6-1-u3-X18"}],"mis":"K6-1-u3-X18","explanation":["판정은 기준으로 정해요.","결과가 마음에 안 들 수 있어요.","그래도 승복해요."]}'::jsonb),
('g6_1_kor_u3_review_c#6','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C23',1,'ox','auto','청중은 토론에서 할 일이 없어요.',ARRAY['K6-1-u3-X37']::text[],false,'{"seq":6,"concept":"K6-1-u3-C23","difficulty":1,"kind":"ox","stem":"청중은 토론에서 할 일이 없어요.","answer":"X","reason_options":[{"t":"메모하며 듣고 인상 깊은 근거를 말하는 할 일이 있기 때문에","correct":true},{"t":"토론자만 말하기 때문에","mis":"K6-1-u3-X37"}],"mis":"K6-1-u3-X37","explanation":["청중이 가장 많아요.","청중에게도 할 일이 있어요.","메모하고 짚어 줘요."]}'::jsonb),
('g6_1_kor_u3_review_c#7','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C28',1,'ox','auto','자료 하나라도 언제 · 누구를 · 어떻게 조사했는지 자세하면 충분할 수 있어요.',ARRAY['K6-1-u3-X30']::text[],false,'{"seq":7,"concept":"K6-1-u3-C28","difficulty":1,"kind":"ox","stem":"자료 하나라도 언제 · 누구를 · 어떻게 조사했는지 자세하면 충분할 수 있어요.","answer":"O","reason_options":[{"t":"충분성은 자료의 개수가 아니라 구체적인 정도이기 때문에","correct":true},{"t":"자료는 개수가 많아야만 충분하기 때문에","mis":"K6-1-u3-X30"}],"mis":"K6-1-u3-X30","explanation":["개수가 많다고 충분한 것이 아니에요.","자세한지가 중요해요.","하나라도 자세하면 충분할 수 있어요."]}'::jsonb),
('g6_1_kor_u3_review_c#8','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C43',1,'mc','auto','「닮다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":8,"concept":"K6-1-u3-C43","difficulty":1,"kind":"mc","stem":"「닮다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[담따]","correct":true},{"t":"[달따]","mis":"K6-1-u3-X44"},{"t":"[닮다]","mis":"K6-1-u3-X44"},{"t":"[다따]","mis":"K6-1-u3-X44"}],"explanation":["ㄻ 뒤에 ㄷ이 왔어요.","ㄻ은 [ㅁ]으로 소리 나요.","뒤의 ㄷ은 된소리가 돼요."]}'::jsonb),
('g6_1_kor_u3_review_c#9','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C9',2,'mc','auto','서아의 주장 펼치기에서 이유에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u3-X05','K6-1-u3-X04']::text[],false,'{"seq":9,"concept":"K6-1-u3-C9","difficulty":2,"kind":"mc","stem":"서아의 주장 펼치기에서 이유에 해당하는 것은 어느 것인가요?","options":[{"t":"도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문","correct":true},{"t":"점심시간에는 도서실을 닫아야 한다","mis":"K6-1-u3-X05"},{"t":"어떤 누리집에서 봤는데 다른 학교도 다 닫는다","mis":"K6-1-u3-X04"},{"t":"도서부가 고학년 이백 명에게 물은 설문","mis":"K6-1-u3-X04"}],"explanation":["닫아야 한다는 것은 주장이에요.","누리집 이야기는 근거로 든 것이에요.","그렇게 주장하는 까닭이 이유예요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb),
('g6_1_kor_u3_review_c#10','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C11',2,'mc','auto','서아의 마지막 말 「저는 요즘 급식 줄이 더 문제라고 봅니다.」의 문제는 무엇인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X17','K6-1-u3-X13']::text[],false,'{"seq":10,"concept":"K6-1-u3-C11","difficulty":2,"kind":"mc","stem":"서아의 마지막 말 「저는 요즘 급식 줄이 더 문제라고 봅니다.」의 문제는 무엇인가요?","options":[{"t":"주장 펼치기에서 나온 내용과 상관없는 새 이야기를 꺼냈다","correct":true},{"t":"근거를 너무 자세히 밝혔다","mis":"K6-1-u3-X30"},{"t":"높임말을 썼다","mis":"K6-1-u3-X17"},{"t":"상대 근거를 겨누었다","mis":"K6-1-u3-X13"}],"explanation":["근거를 밝히지도 않았어요.","높임말은 맞아요.","주제와 상관없는 말이에요."],"asset":{"type":"speech","turns":[{"who":"반대 측 서아","text":"그것도 모르십니까? 점심시간에는 다들 운동장에 나갑니다."},{"who":"찬성 측 도담","text":"말씀 잘 들었습니다. 다만 저희 설문에서 백삼십 명이 빌리고 싶다고 답했습니다. 다들 운동장에 나간다는 말은 저희 자료와 맞지 않습니다."},{"who":"찬성 측 도담","text":"반대 측께 묻겠습니다. 다른 학교도 다 닫는다는 누리집은 어디이고, 언제 쓴 글입니까?"},{"who":"반대 측 서아","text":"누리집 이름은 적어 두지 못했습니다. 그런데 저는 요즘 급식 줄이 더 문제라고 봅니다."}]}}'::jsonb),
('g6_1_kor_u3_review_c#11','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C14',2,'ox','auto','주장 다지기에서는 무너진 근거도 다시 꺼내 힘주어 말해야 해요.',ARRAY['K6-1-u3-X15']::text[],false,'{"seq":11,"concept":"K6-1-u3-C14","difficulty":2,"kind":"ox","stem":"주장 다지기에서는 무너진 근거도 다시 꺼내 힘주어 말해야 해요.","answer":"X","reason_options":[{"t":"반론에서 확인된 것만 골라야 하고 무너진 근거를 꺼내면 오히려 약해지기 때문에","correct":true},{"t":"한 번 낸 근거는 끝까지 지켜야 하기 때문에","mis":"K6-1-u3-X15"}],"mis":"K6-1-u3-X15","explanation":["무너진 근거는 힘이 없어요.","확인된 것만 골라요.","추려서 다시 세워요."]}'::jsonb),
('g6_1_kor_u3_review_c#12','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C16',2,'ox','auto','나래의 판정은 도서실을 열자는 생각이 옳다는 뜻이에요.',ARRAY['K6-1-u3-X17']::text[],false,'{"seq":12,"concept":"K6-1-u3-C16","difficulty":2,"kind":"ox","stem":"나래의 판정은 도서실을 열자는 생각이 옳다는 뜻이에요.","answer":"X","reason_options":[{"t":"정한 기준으로 보아 찬성 측이 더 설득력 있게 말했다는 뜻이기 때문에","correct":true},{"t":"판정은 옳은 생각을 가려 주는 일이기 때문에","mis":"K6-1-u3-X17"}],"mis":"K6-1-u3-X17","explanation":["판정은 옳고 그름을 가리지 않아요.","기준으로 본 설득력이에요.","두 생각은 그대로 남아요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb),
('g6_1_kor_u3_review_c#13','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C34',2,'ox','auto','은솔이처럼 발언을 그대로 옮기지 않고 핵심만 짧게 적는 것이 좋아요.',ARRAY['K6-1-u3-X08']::text[],false,'{"seq":13,"concept":"K6-1-u3-C34","difficulty":2,"kind":"ox","stem":"은솔이처럼 발언을 그대로 옮기지 않고 핵심만 짧게 적는 것이 좋아요.","answer":"O","reason_options":[{"t":"다음 말을 놓치지 않고 되받을 거리를 남길 수 있기 때문에","correct":true},{"t":"상대 말은 들을 필요가 없기 때문에","mis":"K6-1-u3-X08"}],"mis":"K6-1-u3-X08","explanation":["다 옮기면 다음 말을 놓쳐요.","상대 말은 잘 들어야 해요.","핵심만 짧게 적어요."],"asset":{"type":"passage","lines":["찬성 측 주장 — 점심시간에도 도서실을 열어야 한다.","찬성 측 이유 — 쉬는 시간만으로는 책 고를 시간이 모자란다.","찬성 측 근거 — 도서부, 이번 학기, 고학년 이백 명 설문.","반대 측 근거 — 어떤 누리집(어디인지 밝히지 않음).","반대 측이 꺼낸 다른 이야기 — 급식 줄.","반대 측 말투 — 목소리가 컸음."],"title":"청중 은솔이의 메모"}}'::jsonb),
('g6_1_kor_u3_review_c#14','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C20',2,'mc','auto','토론 준비표에 쓸 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X06','K6-1-u3-X21']::text[],false,'{"seq":14,"concept":"K6-1-u3-C20","difficulty":2,"kind":"mc","stem":"토론 준비표에 쓸 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주장 → 이유 → 이유마다 근거 → 예상 반론과 답변","correct":true},{"t":"근거 → 판정 → 주장","mis":"K6-1-u3-X06"},{"t":"예상 반론 → 주장 → 판정","mis":"K6-1-u3-X06"},{"t":"주장 → 이유 하나 → 끝","mis":"K6-1-u3-X21"}],"explanation":["판정은 준비표에 쓰지 않아요.","이유는 두세 가지, 근거와 반론까지 준비해요.","주장 아래 이유, 이유 아래 근거예요."]}'::jsonb),
('g6_1_kor_u3_review_c#15','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C37',2,'mc','auto','실천 토론에서 주제를 찾을 수 있는 갈래로 알맞게 짝 지은 것은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X06','K6-1-u3-X25']::text[],false,'{"seq":15,"concept":"K6-1-u3-C37","difficulty":2,"kind":"mc","stem":"실천 토론에서 주제를 찾을 수 있는 갈래로 알맞게 짝 지은 것은 어느 것인가요?","options":[{"t":"역사 · 환경 · 생활","correct":true},{"t":"연도 · 이름 · 길이","mis":"K6-1-u3-X01"},{"t":"판정 · 반론 · 다지기","mis":"K6-1-u3-X06"},{"t":"사회자 · 청중 · 판정단","mis":"K6-1-u3-X25"}],"explanation":["연도나 이름은 답이 하나예요.","그것은 토론의 단계예요.","역사 · 환경 · 생활에서 찾아요."]}'::jsonb),
('g6_1_kor_u3_review_c#16','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C39',2,'mc','auto','원탁 토론과 찬반 토론의 같은 점은 무엇인가요?',ARRAY['K6-1-u3-X41']::text[],false,'{"seq":16,"concept":"K6-1-u3-C39","difficulty":2,"kind":"mc","stem":"원탁 토론과 찬반 토론의 같은 점은 무엇인가요?","options":[{"t":"두 토론 모두 근거를 들어 말한다","correct":true},{"t":"두 토론 모두 판정단이 승패를 정한다","mis":"K6-1-u3-X41"},{"t":"두 토론 모두 편을 나눈다","mis":"K6-1-u3-X41"},{"t":"두 토론 모두 사회자가 반드시 있다","mis":"K6-1-u3-X41"}],"explanation":["원탁 토론은 판정단을 두지 않아요.","원탁 토론은 편을 나누지 않아요.","근거를 들어 말하는 점은 같아요."]}'::jsonb),
('g6_1_kor_u3_review_c#17','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C24',3,'mc','auto','같은 편끼리 반론과 답변을 맞춰 두려고 단계 사이에 두는 시간을 무엇이라고 하나요?',ARRAY['K6-1-u3-X06','K6-1-u3-X23']::text[],false,'{"seq":17,"concept":"K6-1-u3-C24","difficulty":3,"kind":"mc","stem":"같은 편끼리 반론과 답변을 맞춰 두려고 단계 사이에 두는 시간을 무엇이라고 하나요?","options":[{"t":"협의 시간","correct":true},{"t":"판정 시간","mis":"K6-1-u3-X06"},{"t":"반론 시간","mis":"K6-1-u3-X06"},{"t":"쉬는 시간","mis":"K6-1-u3-X23"}],"explanation":["판정은 끝에 해요.","반론은 단계 이름이에요.","같은 편끼리 맞추는 시간이에요."]}'::jsonb),
('g6_1_kor_u3_review_c#18','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C26',3,'error','auto','사물함 토론의 두 근거를 견주었어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X30','K6-1-u3-X29']::text[],false,'{"seq":18,"concept":"K6-1-u3-C26","difficulty":3,"kind":"error","stem":"사물함 토론의 두 근거를 견주었어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"보미 — 「두 근거 모두 사람에게 물었으니 똑같이 타당해.」","correct":true,"mis_target":"K6-1-u3-X35"},{"t":"지호 — 「백쉰 명과 두 명은 같은 무게가 아니야.」","mis":"K6-1-u3-X30"},{"t":"은재 — 「새얀이는 언제 물었는지도 밝히지 않았어.」","mis":"K6-1-u3-X29"}],"explanation":["지호는 사람 수를 바르게 견주었어요.","은재는 때를 바르게 짚었어요.","물은 방법이 같아도 구체성이 달라요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 사물함에 자물쇠를 달아야 한다.","찬성 측 온유 — 물건을 잃어버리는 일이 실제로 있기 때문입니다.","우리 학교 고학년 백쉰 명에게 지난달에 물어보니,","마흔여덟 명이 사물함에서 물건을 잃은 적이 있다고 답했습니다.","반대 측 새얀 — 열고 닫기가 번거롭기 때문입니다.","제 친구 두 명에게 물어보니 둘 다 불편할 것 같다고 했습니다."],"title":"두 근거 견주기"}}'::jsonb),
('g6_1_kor_u3_review_c#19','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C11',3,'mc','auto','반론할 때 되받을 수 있는 범위로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X11','K6-1-u3-X14']::text[],false,'{"seq":19,"concept":"K6-1-u3-C11","difficulty":3,"kind":"mc","stem":"반론할 때 되받을 수 있는 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"상대가 주장 펼치기에서 낸 주장 · 이유 · 근거","correct":true},{"t":"토론과 상관없는 요즘 일","mis":"K6-1-u3-X11"},{"t":"상대의 말투와 표정","mis":"K6-1-u3-X14"},{"t":"상대가 지난번 다른 토론에서 한 말","mis":"K6-1-u3-X11"}],"explanation":["상관없는 일은 꺼내지 않아요.","말투는 겨누지 않아요.","펼친 내용에 대해서만 되받아요."]}'::jsonb),
('g6_1_kor_u3_review_c#20','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C33',3,'error','auto','판정단의 마음가짐을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X24','K6-1-u3-X16']::text[],false,'{"seq":20,"concept":"K6-1-u3-C33","difficulty":3,"kind":"error","stem":"판정단의 마음가짐을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"지우 — 「나는 원래 찬성이니까 찬성 측에 점수를 더 줄 거야.」","correct":true,"mis_target":"K6-1-u3-X24"},{"t":"나래 — 「미리 정한 기준을 적어 두고 판정할게.」","mis":"K6-1-u3-X16"},{"t":"하람 — 「토론에서 나온 말과 자료만 볼게.」","mis":"K6-1-u3-X24"}],"explanation":["나래는 기준을 먼저 정했어요.","하람은 나온 내용만 봐요.","지우는 같은 편에 후하게 주려 해요."]}'::jsonb),
('g6_1_kor_u3_review_c#21','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C39',3,'mc','auto','「우리 마을 하천을 어떻게 가꿀까」처럼 여러 생각을 모아야 하는 문제를 이야기할 때 알맞은 토론은 어느 것인가요?',ARRAY['K6-1-u3-X41','K6-1-u3-X03']::text[],false,'{"seq":21,"concept":"K6-1-u3-C39","difficulty":3,"kind":"mc","stem":"「우리 마을 하천을 어떻게 가꿀까」처럼 여러 생각을 모아야 하는 문제를 이야기할 때 알맞은 토론은 어느 것인가요?","options":[{"t":"모두가 대등하게 돌아가며 말하는 원탁 토론","correct":true},{"t":"찬성과 반대로 나뉘는 찬반 토론","mis":"K6-1-u3-X41"},{"t":"판정단이 승패를 정하는 토론","mis":"K6-1-u3-X41"},{"t":"한 사람만 말하는 연설","mis":"K6-1-u3-X03"}],"explanation":["둘로 갈리지 않는 문제예요.","승패를 정할 문제가 아니에요.","모두가 대등하게 말해요."]}'::jsonb),
('g6_1_kor_u3_review_c#22','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C43',3,'error','auto','세 친구가 겹받침이 든 말을 읽었어요. 바르지 않게 읽은 친구는 누구인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":22,"concept":"K6-1-u3-C43","difficulty":3,"kind":"error","stem":"세 친구가 겹받침이 든 말을 읽었어요. 바르지 않게 읽은 친구는 누구인가요?","options":[{"t":"이안 — 「붉게」를 [북께]로 읽었다","correct":true,"mis_target":"K6-1-u3-X44"},{"t":"서아 — 「늙지」를 [늑찌]로 읽었다","mis":"K6-1-u3-X44"},{"t":"도담 — 「닮고」를 [담꼬]로 읽었다","mis":"K6-1-u3-X44"}],"explanation":["서아는 ㄺ을 [ㄱ]으로 읽었어요.","도담은 ㄻ을 [ㅁ]으로 읽었어요.","ㄺ 뒤에 ㄱ이 오면 [ㄹ] — [불께]예요."]}'::jsonb),
('g6_1_kor_u3_review_c#23','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C14',4,'mc','auto','서아의 주장 다지기를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":23,"concept":"K6-1-u3-C14","difficulty":4,"kind":"mc","stem":"서아의 주장 다지기를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"「요컨대 저희가 지키려는 것은 지키는 분의 쉬는 시간입니다. 그 시간을 지킬 방법이 없다면 점심시간에는 닫아야 합니다.」","correct":true},{"t":"「다른 학교도 다 닫으니 우리도 닫아야 합니다.」를 두 번 말한다","mis":"K6-1-u3-X15"},{"t":"「찬성 측은 준비가 부족했습니다.」라고 말한다","mis":"K6-1-u3-X14"},{"t":"「그런데 급식 줄도 문제입니다.」를 덧붙인다","mis":"K6-1-u3-X11"}],"explanation":["무너진 근거를 되풀이하지 않아요.","상대를 깎아내리지 않아요.","남은 이유로 다시 세워요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 도담","text":"요컨대 책을 읽고 싶은 학생이 많습니다. 백삼십 명이라는 설문은 반론에서도 흔들리지 않았습니다. 따라서 점심시간에도 도서실을 열어야 합니다."},{"who":"반대 측 서아","text":"처음에 말씀드린 대로 다른 학교도 다 닫는다는 점을 다시 말씀드립니다. 다른 학교도 다 닫으니 우리도 닫아야 합니다."}]}}'::jsonb),
('g6_1_kor_u3_review_c#24','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C26',4,'essay','teacher','도담이와 서아가 든 근거를 세 물음으로 따져 보고, 어느 쪽 근거가 더 타당한지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u3-C26","difficulty":4,"kind":"essay","stem":"도담이와 서아가 든 근거를 세 물음으로 따져 보고, 어느 쪽 근거가 더 타당한지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 도담이의 근거는 책을 고를 시간이 모자란다는 이유와 이어지고, 도서부라는 출처가 분명하며, 이번 학기 · 고학년 이백 명이라는 조사 대상이 밝혀져 있다. 서아의 근거는 다른 학교도 다 닫는다는 것인데, 어느 누리집인지 몰라 출처가 분명하지 않고, 지키는 분의 쉬는 시간이라는 이유와도 곧바로 이어지지 않는다. 그래서 도담이의 근거가 더 타당하다.","scoring_points":["도담이의 근거를 세 물음으로 따졌는가","서아의 근거를 세 물음으로 따졌는가","더 타당한 쪽과 까닭을 썼는가"]},"explanation":["이어지는지 따져요.","출처를 따져요.","구체적인지 따져요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb),
('g6_1_kor_u3_review_c#25','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C42',4,'essay','teacher','토론자에게 필요한 힘 가운데 내가 잘하는 것과 더 길러야 할 것을 하나씩 골라 까닭과 함께 쓰고, 기르기 위해 할 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u3-C42","difficulty":4,"kind":"essay","stem":"토론자에게 필요한 힘 가운데 내가 잘하는 것과 더 길러야 할 것을 하나씩 골라 까닭과 함께 쓰고, 기르기 위해 할 일을 쓰세요.","answer_guide":{"answer":"예: 나는 상대 말을 끝까지 듣고 메모하는 것은 잘해서 상대 근거의 타당성을 따져 보는 힘이 있다. 그러나 반론을 받았을 때 당황해서 같은 말을 되풀이하곤 해서, 반론에 알맞게 답하는 힘을 더 길러야 한다. 그래서 다음 토론에서는 예상 반론을 미리 세 가지 적고 각각에 자료로 답하는 연습을 하겠다.","scoring_points":["잘하는 힘과 까닭을 썼는가","더 길러야 할 힘과 까닭을 썼는가","기르기 위한 구체적인 할 일을 썼는가"]},"explanation":["네 가지 힘을 떠올려요.","내 모습과 견줘요.","할 일을 구체적으로 써요."]}'::jsonb),
('g6_1_kor_u3_review_d#1','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C1',1,'mc','auto','다음 가운데 찬반이 갈려 토론이 필요한 상황은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":1,"concept":"K6-1-u3-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 찬반이 갈려 토론이 필요한 상황은 어느 것인가요?","options":[{"t":"공원 한쪽에 반려견 놀이터를 만들지 정하기","correct":true},{"t":"공원이 언제 문을 열었는지 알아보기","mis":"K6-1-u3-X01"},{"t":"공원 넓이를 재어 보기","mis":"K6-1-u3-X01"},{"t":"공원 지도 보는 법 익히기","mis":"K6-1-u3-X01"}],"explanation":["문을 연 때는 찾아보면 알아요.","넓이는 재면 알아요.","찬반이 갈리는 문제에서 토론해요."]}'::jsonb),
('g6_1_kor_u3_review_d#2','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C10',1,'mc','auto','다음 가운데 근거로 쓸 수 있는 자료는 무엇인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05']::text[],false,'{"seq":2,"concept":"K6-1-u3-C10","difficulty":1,"kind":"mc","stem":"다음 가운데 근거로 쓸 수 있는 자료는 무엇인가요?","options":[{"t":"체육 교과 연구회가 낸 안전 지침","correct":true},{"t":"나누어 쓰면 더 재미없을 것 같다","mis":"K6-1-u3-X04"},{"t":"운동장이 좁아서 답답하다고 느낀다","mis":"K6-1-u3-X04"},{"t":"운동장은 나누어 써야 한다","mis":"K6-1-u3-X05"}],"explanation":["「같다」는 짐작이에요.","느낌은 근거가 아니에요.","누가 낸 자료인지 확인돼요."]}'::jsonb),
