('g6_1_kor_u4_L01_challenge#4','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C6',3,'error','auto','관용 표현에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X06']::text[],false,'{"seq":4,"concept":"K6-1-u4-C6","difficulty":3,"kind":"error","stem":"관용 표현에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"누리 — 「관용 표현은 많이 넣을수록 글이 좋아져.」","correct":true,"mis_target":"K6-1-u4-X07"},{"t":"다온 — 「상황에 어울리는 하나를 놓는 게 중요해.」","mis":"K6-1-u4-X07"},{"t":"시우 — 「굳어진 모양 그대로 써야 뜻이 살아.」","mis":"K6-1-u4-X06"}],"explanation":["다온이는 바르게 말했어요.","시우도 바르게 말했어요.","개수보다 어울림이 먼저예요."]}'::jsonb),
('g6_1_kor_u4_L01_challenge#5','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C4',3,'mc','auto','「책임이 커서 마음이 무겁다」 대신 「어깨가 무겁다」라고 말하면 좋아지는 점은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X09','K6-1-u4-X05']::text[],false,'{"seq":5,"concept":"K6-1-u4-C4","difficulty":3,"kind":"mc","stem":"「책임이 커서 마음이 무겁다」 대신 「어깨가 무겁다」라고 말하면 좋아지는 점은 어느 것인가요?","options":[{"t":"짧은 한마디로 전하면서 듣는 사람이 장면을 떠올리게 된다","correct":true},{"t":"뜻이 사전과 달라져 더 정확해진다","mis":"K6-1-u4-X01"},{"t":"말이 길어져 더 공손해진다","mis":"K6-1-u4-X09"},{"t":"어려워 보여 똑똑해 보인다","mis":"K6-1-u4-X05"}],"explanation":["뜻이 달라지는 것이 아니에요.","말은 오히려 짧아져요.","짧고 생생하게 전해져요."]}'::jsonb),
('g6_1_kor_u4_L01_challenge#6','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C7',3,'mc','auto','「진땀을 빼다」를 알맞게 쓸 수 있는 상황은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X01']::text[],false,'{"seq":6,"concept":"K6-1-u4-C7","difficulty":3,"kind":"mc","stem":"「진땀을 빼다」를 알맞게 쓸 수 있는 상황은 어느 것인가요?","options":[{"t":"준비가 부족한 채로 발표를 겨우 마쳤을 때","correct":true},{"t":"친구의 생일을 축하할 때","mis":"K6-1-u4-X08"},{"t":"더운 날 운동장에서 땀을 흘렸을 때","mis":"K6-1-u4-X01"},{"t":"비밀을 잘 지키는 친구를 칭찬할 때","mis":"K6-1-u4-X08"}],"explanation":["축하하는 자리와 어긋나요.","실제로 땀을 흘린 이야기가 아니에요.","몹시 애쓴 상황에 써요."]}'::jsonb),
('g6_1_kor_u4_L01_challenge#7','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C1',3,'mc','auto','「입을 모으다」의 뜻이 바르게 살아난 문장은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X08']::text[],false,'{"seq":7,"concept":"K6-1-u4-C1","difficulty":3,"kind":"mc","stem":"「입을 모으다」의 뜻이 바르게 살아난 문장은 어느 것인가요?","options":[{"t":"「반 친구들이 입을 모아 다솔이를 칭찬했다.」","correct":true},{"t":"「사진을 찍으려고 입술을 동그랗게 입을 모았다.」","mis":"K6-1-u4-X01"},{"t":"「혼자서 입을 모아 말했다.」","mis":"K6-1-u4-X08"},{"t":"「입을 모으면 입이 작아진다.」","mis":"K6-1-u4-X01"}],"explanation":["입술을 오므린 이야기가 아니에요.","혼자서는 입을 모을 수 없어요.","여럿이 같은 말을 한다는 뜻이에요."]}'::jsonb),
('g6_1_kor_u4_L01_challenge#8','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C6',4,'mc','auto','아라가 쓴 텃밭 일기를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X06']::text[],false,'{"seq":8,"concept":"K6-1-u4-C6","difficulty":4,"kind":"mc","stem":"아라가 쓴 텃밭 일기를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"어울리지 않는 표현은 덜어 내고, 마음이 가장 크게 움직인 자리에 꼭 맞는 하나만 남긴다","correct":true},{"t":"관용 표현을 하나 더 넣어 더 생생하게 만든다","mis":"K6-1-u4-X07"},{"t":"관용 표현을 모두 낱말 뜻대로 풀어 늘인다","mis":"K6-1-u4-X06"},{"t":"표현이 많아 좋은 글이니 그대로 둔다","mis":"K6-1-u4-X07"}],"explanation":["더 넣으면 더 흐려져요.","풀어 늘이면 뜻을 잃어요.","제자리에 하나면 충분해요."],"asset":{"type":"passage","lines":["오늘 텃밭에 물을 주었다. 다들 나를 당번으로 하자고 입을 모았다.","물뿌리개를 드니 눈코 뜰 새 없이 무거웠다.","진땀을 빼며 어깨가 무겁게 물을 주고, 입이 무겁게 집에 왔다."],"title":"아라가 쓴 텃밭 일기"}}'::jsonb),
('g6_1_kor_u4_L01_challenge#9','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C1',4,'essay','teacher','「입을 모으다」와 「가방을 열다」를 견주어, 무엇이 관용 표현이고 왜 그런지 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C1","difficulty":4,"kind":"essay","stem":"「입을 모으다」와 「가방을 열다」를 견주어, 무엇이 관용 표현이고 왜 그런지 설명하세요.","answer_guide":{"answer":"예: 「입을 모으다」는 관용 표현이다. 실제로 입을 모은 것이 아니라 여럿이 같은 말을 한다는 새로운 뜻이 있기 때문이다. 「가방을 열다」는 가방을 연다는 낱말 뜻 그대로라서 관용 표현이 아니다.","scoring_points":["「입을 모으다」를 관용 표현으로 골랐는가","낱말 뜻의 합과 다른 새로운 뜻이라는 까닭을 썼는가","「가방을 열다」가 뜻 그대로라는 점을 견주어 썼는가"]},"explanation":["두 말을 뜻 그대로 읽어 봐요.","뜻이 달라지는 쪽을 찾아요.","까닭을 견주어 써요."]}'::jsonb),
('g6_1_kor_u4_L01_challenge#10','kor',6,1,'u4','L01','g6_1_kor_u4_L01_challenge','lesson_challenge','K6-1-u4-C6',4,'essay','teacher','「관용 표현을 쓰는 것이 언제나 효과적인 것은 아니다」라는 말을 예를 들어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C6","difficulty":4,"kind":"essay","stem":"「관용 표현을 쓰는 것이 언제나 효과적인 것은 아니다」라는 말을 예를 들어 설명하세요.","answer_guide":{"answer":"예: 관용 표현은 상황에 맞을 때만 힘이 생긴다. 생일을 맞은 친구에게 「진땀을 뺐겠구나」라고 하면 뜻이 어긋나 어색해진다. 또 한 글에 관용 표현을 여러 개 넣으면 오히려 뜻이 흐려진다. 그래서 개수보다 지금 상황에 어울리는 표현인지를 먼저 살펴야 한다.","scoring_points":["상황에 맞을 때만 효과가 있다는 점을 썼는가","어긋나게 쓴 예를 들었는가","개수보다 어울림이 먼저라는 점을 썼는가"]},"explanation":["어긋난 예를 떠올려요.","많이 넣었을 때를 떠올려요.","먼저 볼 것을 정리해요."]}'::jsonb),
('g6_1_kor_u4_L02_basic#1','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C8',1,'mc','auto','대화 속 관용어의 뜻을 처음 알아볼 때 먼저 할 일은 어느 것인가요?',ARRAY['K6-1-u4-X10','K6-1-u4-X01']::text[],false,'{"seq":1,"concept":"K6-1-u4-C8","difficulty":1,"kind":"mc","stem":"대화 속 관용어의 뜻을 처음 알아볼 때 먼저 할 일은 어느 것인가요?","options":[{"t":"앞뒤 상황을 보고 뜻을 짐작해 본다","correct":true},{"t":"짐작하지 말고 사전부터 편다","mis":"K6-1-u4-X10"},{"t":"뜻을 모르면 그냥 넘어간다","mis":"K6-1-u4-X10"},{"t":"낱말 뜻을 그대로 더해 읽는다","mis":"K6-1-u4-X01"}],"explanation":["사전은 짐작한 뒤에 펴요.","모르면 짐작부터 해 봐요.","앞뒤 상황이 실마리예요."]}'::jsonb),
('g6_1_kor_u4_L02_basic#2','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C9',1,'mc','auto','「걱정 붙들어 매다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01']::text[],false,'{"seq":2,"concept":"K6-1-u4-C9","difficulty":1,"kind":"mc","stem":"「걱정 붙들어 매다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"걱정하지 말라고 안심시키다","correct":true},{"t":"걱정거리를 끈으로 꽁꽁 묶어 두다","mis":"K6-1-u4-X01"},{"t":"걱정을 오래 붙잡고 놓지 않다","mis":"K6-1-u4-X01"},{"t":"걱정거리를 남에게 넘기다","mis":"K6-1-u4-X01"}],"explanation":["끈으로 묶는 이야기가 아니에요.","걱정을 붙잡는 것도 아니에요.","안심하라는 말이에요."]}'::jsonb),
('g6_1_kor_u4_L02_basic#3','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C12',1,'mc','auto','다음 가운데 「입」이 들어간 관용어는 어느 것인가요?',ARRAY['K6-1-u4-X03']::text[],false,'{"seq":3,"concept":"K6-1-u4-C12","difficulty":1,"kind":"mc","stem":"다음 가운데 「입」이 들어간 관용어는 어느 것인가요?","options":[{"t":"입이 무겁다","correct":true},{"t":"입을 헹구다","mis":"K6-1-u4-X03"},{"t":"입을 벌려 하품하다","mis":"K6-1-u4-X03"},{"t":"입에 밥을 넣다","mis":"K6-1-u4-X03"}],"explanation":["입을 헹구는 것은 뜻 그대로예요.","하품도 뜻 그대로예요.","말이 신중하다는 새 뜻이 있어요."]}'::jsonb),
('g6_1_kor_u4_L02_basic#4','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C9',1,'ox','auto','관용어는 뜻만 외우면 충분해요.',ARRAY['K6-1-u4-X11']::text[],false,'{"seq":4,"concept":"K6-1-u4-C9","difficulty":1,"kind":"ox","stem":"관용어는 뜻만 외우면 충분해요.","answer":"X","reason_options":[{"t":"어떤 상황에서 쓰는 말인지까지 붙여 두어야 내 말이 되기 때문에","correct":true},{"t":"뜻을 알면 쓸 상황은 저절로 떠오르기 때문에","mis":"K6-1-u4-X11"}],"mis":"K6-1-u4-X11","explanation":["뜻만 외우면 금방 잊어요.","쓸 상황을 함께 붙여요.","그래야 내 말이 돼요."]}'::jsonb),
('g6_1_kor_u4_L02_basic#5','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C10',2,'mc','auto','다솔이가 예솔이를 두고 「귀가 밝다」고 한 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X12','K6-1-u4-X01']::text[],false,'{"seq":5,"concept":"K6-1-u4-C10","difficulty":2,"kind":"mc","stem":"다솔이가 예솔이를 두고 「귀가 밝다」고 한 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"소식이나 정보를 남보다 빨리 알아챈다","correct":true},{"t":"작은 소리도 잘 듣는 귀를 가졌다","mis":"K6-1-u4-X12"},{"t":"귀가 하얗고 깨끗하다","mis":"K6-1-u4-X12"},{"t":"들은 말을 함부로 옮긴다","mis":"K6-1-u4-X01"}],"explanation":["뒤에 이어진 말을 봐요.","귀의 생김새 이야기가 아니에요.","누가 무엇을 어디에 뒀는지 다 안다고 했어요."],"asset":{"type":"speech","turns":[{"who":"아라","text":"체육관 열쇠를 분명히 가방에 넣었는데 없어. 점심시간이 다 가는데 어쩌지."},{"who":"다솔","text":"예솔이한테 물어보자. 그 애는 귀가 밝아서, 누가 뭘 어디에 뒀다는 말은 다 듣고 있거든."},{"who":"예솔","text":"아침에 선생님이 교무실 서랍에 넣어 두셨다고 하셨어. 걱정 붙들어 매."},{"who":"아라","text":"휴, 이제야 마음이 놓인다. 아침 내내 진땀을 뺐어."}]}}'::jsonb),
('g6_1_kor_u4_L02_basic#6','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C9',2,'match','auto','상황에 어울리는 관용어를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u4-C9","difficulty":2,"kind":"match","stem":"상황에 어울리는 관용어를 알맞게 이으세요.","pairs":[{"l":"불안해하는 동생을 안심시킬 때","r":"걱정 붙들어 매"},{"l":"학급 대표를 맡아 부담이 클 때","r":"어깨가 무겁다"},{"l":"할 일이 몰려 쉴 틈이 없을 때","r":"눈코 뜰 새 없다"}],"mis":"K6-1-u4-X08","explanation":["안심시키는 말을 찾아요.","책임이 큰 마음을 찾아요.","몹시 바쁜 마음을 찾아요."]}'::jsonb),
('g6_1_kor_u4_L02_basic#7','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C11',2,'mc','auto','학교 방송 뉴스의 「눈코 뜰 새 없이」가 전하려는 것은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X12','K6-1-u4-X13']::text[],false,'{"seq":7,"concept":"K6-1-u4-C11","difficulty":2,"kind":"mc","stem":"학교 방송 뉴스의 「눈코 뜰 새 없이」가 전하려는 것은 어느 것인가요?","options":[{"t":"준비할 일이 많아 쉴 틈 없이 바쁘게 움직인다","correct":true},{"t":"준비가 끝나 여유롭게 기다리고 있다","mis":"K6-1-u4-X08"},{"t":"눈과 코가 아픈 학생이 많다","mis":"K6-1-u4-X12"},{"t":"방송에서는 관용어를 쓰면 안 된다","mis":"K6-1-u4-X13"}],"explanation":["여유로운 것과 반대예요.","눈과 코의 이야기가 아니에요.","얼마나 바쁜지를 한마디로 전했어요."],"asset":{"type":"passage","lines":["학교 방송 뉴스 — 「체육 대회 준비로 우리 학년 전체가","눈코 뜰 새 없이 움직이고 있습니다. 지금까지 방송실에서 전해 드렸습니다.」","학급 알림장 — 「도서 반납일이 지난 책이 많습니다.","반납만 하면 되니 걱정 붙들어 매고 내일까지 가져오세요.」"],"title":"매체 속 관용어"}}'::jsonb),
('g6_1_kor_u4_L02_basic#8','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C11',2,'ox','auto','학급 알림장처럼 글로 전하는 매체에는 관용어를 쓸 수 없어요.',ARRAY['K6-1-u4-X13']::text[],false,'{"seq":8,"concept":"K6-1-u4-C11","difficulty":2,"kind":"ox","stem":"학급 알림장처럼 글로 전하는 매체에는 관용어를 쓸 수 없어요.","answer":"X","reason_options":[{"t":"매체가 달라도 관용어는 뜻을 짧고 또렷하게 만드는 같은 일을 하기 때문에","correct":true},{"t":"관용어는 말로 할 때만 쓰는 표현이기 때문에","mis":"K6-1-u4-X13"}],"mis":"K6-1-u4-X13","explanation":["알림장에도 관용어가 놓였어요.","말로도 글로도 써요.","하는 일은 같아요."]}'::jsonb),
('g6_1_kor_u4_L02_basic#9','kor',6,1,'u4','L02','g6_1_kor_u4_L02_basic','lesson_basic','K6-1-u4-C13',2,'mc','auto','「귀가 밝다」의 뜻을 국어사전에서 찾을 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u4-X14']::text[],false,'{"seq":9,"concept":"K6-1-u4-C13","difficulty":2,"kind":"mc","stem":"「귀가 밝다」의 뜻을 국어사전에서 찾을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"중심이 되는 낱말 「귀」를 찾아 뜻풀이 아래쪽에 딸린 관용구를 본다","correct":true},{"t":"「귀가 밝다」 문장 전체를 한 번에 찾는다","mis":"K6-1-u4-X14"},{"t":"사전의 첫 쪽부터 차례로 넘겨 본다","mis":"K6-1-u4-X14"},{"t":"아무 낱말이나 먼저 눈에 띄는 것을 찾는다","mis":"K6-1-u4-X14"}],"explanation":["문장 전체로는 찾기 어려워요.","첫 쪽부터 넘기면 오래 걸려요.","중심 낱말을 앞세워 찾아요."]}'::jsonb),
