('g6_1_kor_u4_L02_challenge#1','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C12',2,'mc','auto','다음 가운데 「어깨」가 들어간 관용어가 아닌 것은 어느 것인가요?',ARRAY['K6-1-u4-X01']::text[],false,'{"seq":1,"concept":"K6-1-u4-C12","difficulty":2,"kind":"mc","stem":"다음 가운데 「어깨」가 들어간 관용어가 아닌 것은 어느 것인가요?","options":[{"t":"어깨를 주무르다","correct":true},{"t":"어깨가 무겁다","mis":"K6-1-u4-X01"},{"t":"어깨를 나란히 하다","mis":"K6-1-u4-X01"},{"t":"어깨가 처지다","mis":"K6-1-u4-X01"}],"explanation":["어깨가 무겁다는 책임이 크다는 뜻이에요.","어깨를 나란히 하다는 비슷한 힘을 지닌다는 뜻이에요.","어깨를 주무르는 것은 뜻 그대로예요."]}'::jsonb),
('g6_1_kor_u4_L02_challenge#2','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C8',2,'ox','auto','관용어의 뜻을 정확히 모르면 짐작하지 말고 넘어가야 해요.',ARRAY['K6-1-u4-X10']::text[],false,'{"seq":2,"concept":"K6-1-u4-C8","difficulty":2,"kind":"ox","stem":"관용어의 뜻을 정확히 모르면 짐작하지 말고 넘어가야 해요.","answer":"X","reason_options":[{"t":"앞뒤 상황을 보고 짐작한 뒤 사전에서 확인하면 뜻이 오래 남기 때문에","correct":true},{"t":"틀리게 짐작하면 안 되기 때문에","mis":"K6-1-u4-X10"}],"mis":"K6-1-u4-X10","explanation":["정확히 몰라도 괜찮아요.","짐작부터 시작해요.","짐작한 뒤 사전으로 확인해요."]}'::jsonb),
('g6_1_kor_u4_L02_challenge#3','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C8',3,'mc','auto','예솔이가 말한 「걱정 붙들어 매」의 뜻을 짐작하는 실마리로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X10']::text[],false,'{"seq":3,"concept":"K6-1-u4-C8","difficulty":3,"kind":"mc","stem":"예솔이가 말한 「걱정 붙들어 매」의 뜻을 짐작하는 실마리로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"예솔이가 열쇠가 있는 곳을 알려 준 다음에 이 말을 했다는 점","correct":true},{"t":"「붙들어 매다」를 낱말 뜻 그대로 풀어 본 것","mis":"K6-1-u4-X01"},{"t":"대화에 나온 사람이 몇 명인지","mis":"K6-1-u4-X10"},{"t":"사전을 펴 보기 전에는 실마리가 없다는 점","mis":"K6-1-u4-X10"}],"explanation":["낱말 뜻대로는 풀리지 않아요.","사람 수는 실마리가 아니에요.","앞뒤 상황이 실마리예요."],"asset":{"type":"speech","turns":[{"who":"아라","text":"체육관 열쇠를 분명히 가방에 넣었는데 없어. 점심시간이 다 가는데 어쩌지."},{"who":"다솔","text":"예솔이한테 물어보자. 그 애는 귀가 밝아서, 누가 뭘 어디에 뒀다는 말은 다 듣고 있거든."},{"who":"예솔","text":"아침에 선생님이 교무실 서랍에 넣어 두셨다고 하셨어. 걱정 붙들어 매."},{"who":"아라","text":"휴, 이제야 마음이 놓인다. 아침 내내 진땀을 뺐어."}]}}'::jsonb),
('g6_1_kor_u4_L02_challenge#4','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C13',3,'error','auto','모르는 관용어를 찾는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X10','K6-1-u4-X14']::text[],false,'{"seq":4,"concept":"K6-1-u4-C13","difficulty":3,"kind":"error","stem":"모르는 관용어를 찾는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태오 — 「모르는 관용어가 나오면 짐작하지 말고 사전부터 펴야 해.」","correct":true,"mis_target":"K6-1-u4-X10"},{"t":"소윤 — 「중심 낱말을 찾고 뜻풀이 아래쪽 관용구를 봐.」","mis":"K6-1-u4-X14"},{"t":"이안 — 「짐작한 뜻과 사전의 뜻을 맞춰 봐.」","mis":"K6-1-u4-X10"}],"explanation":["소윤이는 찾는 방법을 바르게 말했어요.","이안이도 바르게 말했어요.","사전을 먼저 펴지 않아요."]}'::jsonb),
('g6_1_kor_u4_L02_challenge#5','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C9',3,'mc','auto','「걱정 붙들어 매다」를 쓰기에 가장 알맞은 상황은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X01']::text[],false,'{"seq":5,"concept":"K6-1-u4-C9","difficulty":3,"kind":"mc","stem":"「걱정 붙들어 매다」를 쓰기에 가장 알맞은 상황은 어느 것인가요?","options":[{"t":"잃어버린 줄 알았던 공책을 찾았다고 불안해하는 짝에게 알려 줄 때","correct":true},{"t":"짝이 크게 다쳐 함께 걱정할 때","mis":"K6-1-u4-X08"},{"t":"이삿짐을 끈으로 묶을 때","mis":"K6-1-u4-X01"},{"t":"짝이 시험을 잘 봐 축하할 때","mis":"K6-1-u4-X08"}],"explanation":["함께 걱정하는 자리와 어긋나요.","끈으로 묶는 이야기가 아니에요.","안심시키는 자리에 써요."]}'::jsonb),
('g6_1_kor_u4_L02_challenge#6','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C11',3,'mc','auto','학급 알림장에서 「걱정 붙들어 매고」를 쓴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X20','K6-1-u4-X07']::text[],false,'{"seq":6,"concept":"K6-1-u4-C11","difficulty":3,"kind":"mc","stem":"학급 알림장에서 「걱정 붙들어 매고」를 쓴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"반납만 하면 되니 부담 갖지 말라고 안심시키려고","correct":true},{"t":"책을 끈으로 묶어 가져오라고","mis":"K6-1-u4-X01"},{"t":"반납하지 않은 학생을 꾸짖으려고","mis":"K6-1-u4-X20"},{"t":"알림장에는 관용어를 꼭 넣어야 해서","mis":"K6-1-u4-X07"}],"explanation":["끈 이야기가 아니에요.","꾸짖는 말이 아니에요.","안심하고 가져오라는 뜻이에요."],"asset":{"type":"passage","lines":["학교 방송 뉴스 — 「체육 대회 준비로 우리 학년 전체가","눈코 뜰 새 없이 움직이고 있습니다. 지금까지 방송실에서 전해 드렸습니다.」","학급 알림장 — 「도서 반납일이 지난 책이 많습니다.","반납만 하면 되니 걱정 붙들어 매고 내일까지 가져오세요.」"],"title":"매체 속 관용어"}}'::jsonb),
('g6_1_kor_u4_L02_challenge#7','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C10',3,'match','auto','몸을 가리키는 말이 든 관용어와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u4-C10","difficulty":3,"kind":"match","stem":"몸을 가리키는 말이 든 관용어와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"입이 무겁다","r":"말이 신중해 함부로 옮기지 않는다"},{"l":"입에 침이 마르다","r":"남을 거듭 칭찬하다"},{"l":"어깨를 나란히 하다","r":"서로 비슷한 힘을 지니다"}],"mis":"K6-1-u4-X12","explanation":["입이 실제로 무거운 것이 아니에요.","침이 정말 마른 것도 아니에요.","몸으로 마음과 태도를 나타냈어요."]}'::jsonb),
('g6_1_kor_u4_L02_challenge#8','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C12',4,'mc','auto','「귀」가 든 관용어 묶음을 만들 때 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X03','K6-1-u4-X01','K6-1-u4-X10']::text[],false,'{"seq":8,"concept":"K6-1-u4-C12","difficulty":4,"kind":"mc","stem":"「귀」가 든 관용어 묶음을 만들 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「귀가 밝다」와 「귀에 익다」는 넣고, 「귀를 씻다」는 뜻이 낱말 그대로라 뺀다","correct":true},{"t":"「귀」가 들었으니 셋 다 넣는다","mis":"K6-1-u4-X03"},{"t":"「귀를 씻다」만 넣고 나머지는 뺀다","mis":"K6-1-u4-X01"},{"t":"뜻을 모르는 것이 있으니 모두 뺀다","mis":"K6-1-u4-X10"}],"explanation":["낱말만 보고 넣지 않아요.","뜻 그대로인 말은 관용어가 아니에요.","낱말과 뜻을 함께 따져요."]}'::jsonb),
('g6_1_kor_u4_L02_challenge#9','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C8',4,'essay','teacher','「짐작 먼저, 사전은 나중」 순서로 관용어를 익히면 좋은 까닭을 쓰고, 「귀가 밝다」로 그 방법을 차례대로 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C8","difficulty":4,"kind":"essay","stem":"「짐작 먼저, 사전은 나중」 순서로 관용어를 익히면 좋은 까닭을 쓰고, 「귀가 밝다」로 그 방법을 차례대로 설명하세요.","answer_guide":{"answer":"예: 먼저 짐작해 보고 사전으로 확인하면 내가 생각한 뜻과 견주게 되어 뜻이 오래 남는다. 「귀가 밝다」는 「누가 뭘 어디에 뒀다는 말은 다 듣고 있다」는 뒷말을 보고 소식을 빨리 안다는 뜻으로 짐작한다. 그다음 사전에서 「귀」를 찾아 뜻풀이 아래 관용구를 보고, 짐작한 뜻과 맞춰 본다.","scoring_points":["짐작 먼저 하면 좋은 까닭을 썼는가","앞뒤 상황으로 짐작하는 방법을 썼는가","중심 낱말로 사전에서 확인하는 순서를 썼는가"]},"explanation":["까닭을 먼저 써요.","앞뒤 말을 실마리로 써요.","사전 찾는 순서를 써요."]}'::jsonb),
('g6_1_kor_u4_L02_challenge#10','kor',6,1,'u4','L02','g6_1_kor_u4_L02_challenge','lesson_challenge','K6-1-u4-C9',4,'essay','teacher','「입에 침이 마르다」의 뜻과 쓸 수 있는 상황을 쓰고, 내 경험이 드러나는 문장을 하나 지으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C9","difficulty":4,"kind":"essay","stem":"「입에 침이 마르다」의 뜻과 쓸 수 있는 상황을 쓰고, 내 경험이 드러나는 문장을 하나 지으세요.","answer_guide":{"answer":"예: 「입에 침이 마르다」는 남을 거듭 칭찬한다는 뜻이다. 누군가 한 일이 아주 좋아서 여러 번 칭찬할 때 쓴다. 지은 문장 — 「할머니께서는 내가 담근 김치가 맛있다고 입에 침이 마르게 칭찬하셨다.」","scoring_points":["뜻을 바르게 썼는가","쓸 수 있는 상황을 썼는가","내 경험이 드러나게 알맞은 문장을 지었는가"]},"explanation":["뜻을 먼저 써요.","쓸 상황을 붙여요.","내 경험으로 문장을 지어요."]}'::jsonb),
('g6_1_kor_u4_L03_basic#1','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C14',1,'mc','auto','「속담」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X15','K6-1-u4-X01']::text[],false,'{"seq":1,"concept":"K6-1-u4-C14","difficulty":1,"kind":"mc","stem":"「속담」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"예로부터 전해 오며 지혜나 교훈을 담은 말","correct":true},{"t":"그 자리에서 새로 지어낸 말","mis":"K6-1-u4-X15"},{"t":"낱말 뜻을 그대로 이은 말","mis":"K6-1-u4-X01"},{"t":"요즘 새로 생긴 줄임말","mis":"K6-1-u4-X15"}],"explanation":["지어낸 말이 아니에요.","뜻 그대로 이은 말도 아니에요.","예로부터 전해 오는 교훈의 말이에요."]}'::jsonb),
('g6_1_kor_u4_L03_basic#2','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C15',1,'mc','auto','「첫술에 배부르랴」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X16']::text[],false,'{"seq":2,"concept":"K6-1-u4-C15","difficulty":1,"kind":"mc","stem":"「첫술에 배부르랴」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"무슨 일이든 한 번에 큰 성과를 얻기는 어렵다","correct":true},{"t":"밥은 첫 숟가락이 가장 맛있다","mis":"K6-1-u4-X16"},{"t":"처음부터 많이 먹어야 배가 부르다","mis":"K6-1-u4-X16"},{"t":"한 번 하면 무슨 일이든 다 끝난다","mis":"K6-1-u4-X16"}],"explanation":["밥맛 이야기가 아니에요.","많이 먹으라는 말도 아니에요.","첫 숟가락으로는 배가 부르지 않아요."]}'::jsonb),
('g6_1_kor_u4_L03_basic#3','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C14',1,'mc','auto','대화에서 쓰인 속담은 어느 것인가요?',ARRAY['K6-1-u4-X15']::text[],false,'{"seq":3,"concept":"K6-1-u4-C14","difficulty":1,"kind":"mc","stem":"대화에서 쓰인 속담은 어느 것인가요?","options":[{"t":"빈 수레가 요란하다","correct":true},{"t":"세 골이나 먹었어","mis":"K6-1-u4-X15"},{"t":"오늘부터 하면 되지","mis":"K6-1-u4-X15"},{"t":"골키퍼를 제일 잘한다","mis":"K6-1-u4-X15"}],"explanation":["그 자리에서 한 말이에요.","이것도 그 자리에서 한 말이에요.","예로부터 전해 오는 말을 골라요."],"asset":{"type":"speech","turns":[{"who":"예솔","text":"한별이가 자기가 골키퍼를 제일 잘한다고 계속 말하더라. 그런데 오늘 경기에서는 세 골이나 먹었어."},{"who":"한별","text":"맞아. 빈 수레가 요란하다더니 내 이야기였네. 말 대신 연습을 했어야 했는데."},{"who":"예솔","text":"오늘부터 하면 되지. 첫술에 배부르랴."}]}}'::jsonb),
('g6_1_kor_u4_L03_basic#4','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C16',1,'ox','auto','「수레」처럼 요즘 잘 쓰지 않는 말이 든 속담은 낡아서 쓰지 않는 게 좋아요.',ARRAY['K6-1-u4-X17']::text[],false,'{"seq":4,"concept":"K6-1-u4-C16","difficulty":1,"kind":"ox","stem":"「수레」처럼 요즘 잘 쓰지 않는 말이 든 속담은 낡아서 쓰지 않는 게 좋아요.","answer":"X","reason_options":[{"t":"옛말은 조상의 생활이 말에 남은 흔적이라 우리 문화를 담고 있기 때문에","correct":true},{"t":"요즘 쓰지 않는 낱말이 들어 있으면 틀린 말이기 때문에","mis":"K6-1-u4-X17"}],"mis":"K6-1-u4-X17","explanation":["옛말이 있다고 못 쓰는 말이 되지 않아요.","옛 생활이 말에 남았어요.","무엇을 가리키는지 찾아봐요."]}'::jsonb),
('g6_1_kor_u4_L03_basic#5','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C15',2,'match','auto','속담과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u4-C15","difficulty":2,"kind":"match","stem":"속담과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"빈 수레가 요란하다","r":"잘 알지 못하는 사람이 오히려 더 떠든다"},{"l":"첫술에 배부르랴","r":"한 번에 큰 성과를 얻기 어렵다"},{"l":"가랑비에 옷 젖는 줄 모른다","r":"사소한 것이 쌓여 큰 것이 되는 줄 모른다"}],"mis":"K6-1-u4-X16","explanation":["빈 수레는 덜컹거려 시끄러워요.","첫 숟가락으로는 배가 안 불러요.","가는 비에도 어느새 젖어요."]}'::jsonb),
('g6_1_kor_u4_L03_basic#6','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C14',2,'mc','auto','한별이가 「빈 수레가 요란하다더니 내 이야기였네.」라고 말한 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X01']::text[],false,'{"seq":6,"concept":"K6-1-u4-C14","difficulty":2,"kind":"mc","stem":"한별이가 「빈 수레가 요란하다더니 내 이야기였네.」라고 말한 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"말만 앞세우고 연습하지 않은 자신을 돌아본다","correct":true},{"t":"경기에서 이긴 것을 자랑한다","mis":"K6-1-u4-X20"},{"t":"예솔이를 꾸짖는다","mis":"K6-1-u4-X20"},{"t":"수레를 끌고 와서 시끄러웠다고 말한다","mis":"K6-1-u4-X01"}],"explanation":["세 골이나 먹었어요.","예솔이를 꾸짖는 말이 아니에요.","자기 이야기라고 했어요."],"asset":{"type":"speech","turns":[{"who":"예솔","text":"한별이가 자기가 골키퍼를 제일 잘한다고 계속 말하더라. 그런데 오늘 경기에서는 세 골이나 먹었어."},{"who":"한별","text":"맞아. 빈 수레가 요란하다더니 내 이야기였네. 말 대신 연습을 했어야 했는데."},{"who":"예솔","text":"오늘부터 하면 되지. 첫술에 배부르랴."}]}}'::jsonb),
('g6_1_kor_u4_L03_basic#7','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C17',2,'mc','auto','「첫술에 배부르랴」와 뜻이 겹치는 속담은 어느 것인가요?',ARRAY['K6-1-u4-X18']::text[],false,'{"seq":7,"concept":"K6-1-u4-C17","difficulty":2,"kind":"mc","stem":"「첫술에 배부르랴」와 뜻이 겹치는 속담은 어느 것인가요?","options":[{"t":"급할수록 돌아가라","correct":true},{"t":"빈 수레가 요란하다","mis":"K6-1-u4-X18"},{"t":"고양이 목에 방울 달기","mis":"K6-1-u4-X18"},{"t":"바늘 도둑이 소도둑 된다","mis":"K6-1-u4-X18"}],"explanation":["빈 수레는 떠드는 이야기예요.","방울 달기는 해내기 어려운 일이에요.","서두른다고 빨라지지 않는다는 뜻이 겹쳐요."]}'::jsonb),
('g6_1_kor_u4_L03_basic#8','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C18',2,'mc','auto','「빈 수레가 요란하다」를 사전에서 찾을 때 앞세울 중심 낱말은 어느 것인가요?',ARRAY['K6-1-u4-X14']::text[],false,'{"seq":8,"concept":"K6-1-u4-C18","difficulty":2,"kind":"mc","stem":"「빈 수레가 요란하다」를 사전에서 찾을 때 앞세울 중심 낱말은 어느 것인가요?","options":[{"t":"수레","correct":true},{"t":"「빈 수레가 요란하다」 문장 전체","mis":"K6-1-u4-X14"},{"t":"사전의 맨 첫 낱말","mis":"K6-1-u4-X14"},{"t":"속담에 들어 있는 「가」","mis":"K6-1-u4-X14"}],"explanation":["문장 전체로 찾지 않아요.","첫 낱말부터 넘기지 않아요.","중심이 되는 낱말을 잡아요."]}'::jsonb),
('g6_1_kor_u4_L03_basic#9','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C15',2,'mc','auto','「가랑비에 옷 젖는 줄 모른다」가 그리는 장면으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X16']::text[],false,'{"seq":9,"concept":"K6-1-u4-C15","difficulty":2,"kind":"mc","stem":"「가랑비에 옷 젖는 줄 모른다」가 그리는 장면으로 알맞은 것은 어느 것인가요?","options":[{"t":"가늘게 내리는 비라 젖는 줄 모르다가 어느새 다 젖는다","correct":true},{"t":"굵은 비가 한꺼번에 쏟아져 금방 젖는다","mis":"K6-1-u4-X16"},{"t":"비가 와도 옷이 전혀 젖지 않는다","mis":"K6-1-u4-X16"},{"t":"비가 그친 뒤 옷이 빨리 마른다","mis":"K6-1-u4-X16"}],"explanation":["굵은 비가 아니에요.","젖지 않는 것도 아니에요.","조금씩 쌓여 다 젖어요."]}'::jsonb),
('g6_1_kor_u4_L03_basic#10','kor',6,1,'u4','L03','g6_1_kor_u4_L03_basic','lesson_basic','K6-1-u4-C17',3,'mc','auto','「가랑비에 옷 젖는 줄 모른다」와 「바늘 도둑이 소도둑 된다」를 견준 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X18','K6-1-u4-X16','K6-1-u4-X15']::text[],false,'{"seq":10,"concept":"K6-1-u4-C17","difficulty":3,"kind":"mc","stem":"「가랑비에 옷 젖는 줄 모른다」와 「바늘 도둑이 소도둑 된다」를 견준 말로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 작은 것이 쌓여 커진다는 뜻이지만 뒤의 것은 나쁜 일이 커지는 쪽으로 기운다","correct":true},{"t":"뜻이 똑같아 어느 상황에서나 바꿔 써도 된다","mis":"K6-1-u4-X18"},{"t":"두 속담은 뜻이 서로 반대이다","mis":"K6-1-u4-X16"},{"t":"앞의 것만 속담이고 뒤의 것은 관용어이다","mis":"K6-1-u4-X15"}],"explanation":["기우는 방향이 달라요.","뜻이 반대는 아니에요.","둘 다 속담이에요."]}'::jsonb),
('g6_1_kor_u4_L03_challenge#1','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C14',2,'mc','auto','속담이 간결하면서도 효과적인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X05','K6-1-u4-X09','K6-1-u4-X15']::text[],false,'{"seq":1,"concept":"K6-1-u4-C14","difficulty":2,"kind":"mc","stem":"속담이 간결하면서도 효과적인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"장면 하나로 말해 오래 남고, 여러 사람이 알아 풀어 설명하지 않아도 통한다","correct":true},{"t":"어려운 낱말이 많아 귀하게 들린다","mis":"K6-1-u4-X05"},{"t":"길게 풀어 설명해 자세하다","mis":"K6-1-u4-X09"},{"t":"그 자리에서 지어내 새롭다","mis":"K6-1-u4-X15"}],"explanation":["어려워서 힘이 센 것이 아니에요.","길게 풀지 않아요.","장면과 교훈으로 짧게 통해요."]}'::jsonb),
('g6_1_kor_u4_L03_challenge#2','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C18',2,'ox','auto','속담 사전 · 국어사전 · 인터넷 사전은 모두 중심 낱말을 앞세워 속담을 찾아요.',ARRAY['K6-1-u4-X14']::text[],false,'{"seq":2,"concept":"K6-1-u4-C18","difficulty":2,"kind":"ox","stem":"속담 사전 · 국어사전 · 인터넷 사전은 모두 중심 낱말을 앞세워 속담을 찾아요.","answer":"O","reason_options":[{"t":"사전은 낱말을 기준으로 짜여 있기 때문에","correct":true},{"t":"속담 문장 전체를 넣어야만 찾을 수 있기 때문에","mis":"K6-1-u4-X14"}],"mis":"K6-1-u4-X14","explanation":["셋은 생김새가 달라요.","그래도 찾는 길은 같아요.","중심 낱말을 앞세워요."]}'::jsonb),
('g6_1_kor_u4_L03_challenge#3','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C15',3,'mc','auto','다음 상황에 알맞은 속담은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X18']::text[],false,'{"seq":3,"concept":"K6-1-u4-C15","difficulty":3,"kind":"mc","stem":"다음 상황에 알맞은 속담은 어느 것인가요?","options":[{"t":"가랑비에 옷 젖는 줄 모른다","correct":true},{"t":"빈 수레가 요란하다","mis":"K6-1-u4-X08"},{"t":"첫술에 배부르랴","mis":"K6-1-u4-X18"},{"t":"고양이 목에 방울 달기","mis":"K6-1-u4-X08"}],"explanation":["떠드는 이야기가 아니에요.","한 번에 안 된다는 뜻과는 달라요.","작은 것이 쌓여 커졌어요."],"asset":{"type":"passage","lines":["날마다 십 분씩만 책을 읽었다. 대단한 일이라고 생각하지 않았는데,","한 학기가 지나고 보니 읽은 책이 스무 권이 넘어 있었다."],"title":"어느 학생의 이야기"}}'::jsonb),
('g6_1_kor_u4_L03_challenge#4','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C16',3,'error','auto','속담 속 옛말을 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X17']::text[],false,'{"seq":4,"concept":"K6-1-u4-C16","difficulty":3,"kind":"error","stem":"속담 속 옛말을 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"로하 — 「서당은 요즘 없으니 이 속담은 버려야 해.」","correct":true,"mis_target":"K6-1-u4-X17"},{"t":"지안 — 「서당이 무엇인지 찾아보면 옛 생활을 알 수 있어.」","mis":"K6-1-u4-X17"},{"t":"하윤 — 「풍월이 무슨 말인지 사전에서 찾아볼래.」","mis":"K6-1-u4-X17"}],"explanation":["지안이는 옛 생활을 알아보려 했어요.","하윤이는 낯선 말을 찾아보려 했어요.","옛말은 버릴 말이 아니에요."]}'::jsonb),
('g6_1_kor_u4_L03_challenge#5','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C17',3,'mc','auto','뜻이 비슷한 속담을 바꿔 쓸 수 있는지 정할 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u4-X18','K6-1-u4-X03']::text[],false,'{"seq":5,"concept":"K6-1-u4-C17","difficulty":3,"kind":"mc","stem":"뜻이 비슷한 속담을 바꿔 쓸 수 있는지 정할 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"뜻만이 아니라 어떤 상황에 쓰는 말인지, 기우는 방향까지 견준다","correct":true},{"t":"두 속담의 글자 수가 같은지 본다","mis":"K6-1-u4-X18"},{"t":"같은 낱말이 들었는지만 본다","mis":"K6-1-u4-X03"},{"t":"뜻이 조금이라도 겹치면 바꿔 쓴다","mis":"K6-1-u4-X18"}],"explanation":["글자 수와는 상관없어요.","같은 낱말은 기준이 아니에요.","쓸 상황까지 견줘요."]}'::jsonb),
('g6_1_kor_u4_L03_challenge#6','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C19',3,'mc','auto','「빈 수레가 요란하다」를 오늘 생활에 맞게 바꿔 지은 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X19','K6-1-u4-X06']::text[],false,'{"seq":6,"concept":"K6-1-u4-C19","difficulty":3,"kind":"mc","stem":"「빈 수레가 요란하다」를 오늘 생활에 맞게 바꿔 지은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「빈 필통이 요란하다」","correct":true},{"t":"「꽉 찬 필통이 요란하다」","mis":"K6-1-u4-X19"},{"t":"「빈 필통이 조용하다」","mis":"K6-1-u4-X19"},{"t":"「빈 수레가 요란하고 시끄럽다」","mis":"K6-1-u4-X06"}],"explanation":["꽉 차면 교훈이 달라져요.","조용하면 뜻이 반대가 돼요.","낱말만 바꾸고 교훈은 살려요."]}'::jsonb),
('g6_1_kor_u4_L03_challenge#7','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C18',3,'mc','auto','「서당 개 삼 년이면 풍월을 읊는다」에서 「풍월」의 뜻을 모를 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u4-X14','K6-1-u4-X10','K6-1-u4-X17']::text[],false,'{"seq":7,"concept":"K6-1-u4-C18","difficulty":3,"kind":"mc","stem":"「서당 개 삼 년이면 풍월을 읊는다」에서 「풍월」의 뜻을 모를 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"장면과 앞뒤 말로 짐작해 본 뒤 「풍월」을 사전에서 찾아 맞춰 본다","correct":true},{"t":"사전의 첫 쪽부터 넘기며 속담이 나올 때까지 읽는다","mis":"K6-1-u4-X14"},{"t":"짐작한 뜻을 찾아보지 않고 그대로 정답으로 삼는다","mis":"K6-1-u4-X10"},{"t":"모르는 낱말이 있으니 이 속담은 쓰지 않는다","mis":"K6-1-u4-X17"}],"explanation":["첫 쪽부터는 오래 걸려요.","짐작은 확인해야 해요.","짐작한 뒤 사전으로 맞춰 봐요."]}'::jsonb),
('g6_1_kor_u4_L03_challenge#8','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C17',4,'mc','auto','「처음에는 친구 지우개를 말없이 빌려 쓰던 것이 버릇이 되어, 나중에는 친구 물건을 허락 없이 가져가는 일이 잦아졌다.」에 가장 알맞은 속담과 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X18','K6-1-u4-X08','K6-1-u4-X16']::text[],false,'{"seq":8,"concept":"K6-1-u4-C17","difficulty":4,"kind":"mc","stem":"「처음에는 친구 지우개를 말없이 빌려 쓰던 것이 버릇이 되어, 나중에는 친구 물건을 허락 없이 가져가는 일이 잦아졌다.」에 가장 알맞은 속담과 까닭은 어느 것인가요?","options":[{"t":"「바늘 도둑이 소도둑 된다」 — 작은 잘못이 커지는 쪽으로 기우는 말이라 이 상황에 꼭 맞는다","correct":true},{"t":"「가랑비에 옷 젖는 줄 모른다」 — 작은 것이 쌓인다는 뜻이 같으니 더 알맞다","mis":"K6-1-u4-X18"},{"t":"「첫술에 배부르랴」 — 한 번에 되지 않는 일이기 때문이다","mis":"K6-1-u4-X08"},{"t":"「빈 수레가 요란하다」 — 물건을 가져가면 시끄럽기 때문이다","mis":"K6-1-u4-X16"}],"explanation":["뜻이 겹쳐도 기우는 방향이 달라요.","한 번에 안 되는 이야기가 아니에요.","작은 잘못이 커진 상황이에요."]}'::jsonb),
('g6_1_kor_u4_L03_challenge#9','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C16',4,'essay','teacher','속담 속에서 낯선 옛말을 만났을 때 어떻게 대하면 좋을지 쓰고, 속담 하나를 예로 들어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C16","difficulty":4,"kind":"essay","stem":"속담 속에서 낯선 옛말을 만났을 때 어떻게 대하면 좋을지 쓰고, 속담 하나를 예로 들어 설명하세요.","answer_guide":{"answer":"예: 낯선 옛말은 버릴 말이 아니라 조상의 생활이 남은 흔적이므로 무엇을 가리키는지 찾아보면 좋다. 「빈 수레가 요란하다」의 수레는 옛날 짐을 싣고 다니던 것인데, 짐이 없으면 덜컹거려 더 시끄럽다. 이 장면을 알면 잘 모르는 사람이 더 떠든다는 뜻이 저절로 이해되고 옛 생활도 엿볼 수 있다.","scoring_points":["옛말을 버리지 않고 찾아본다는 태도를 썼는가","옛말이 옛 생활의 흔적이라는 점을 썼는가","속담 하나를 예로 들어 설명했는가"]},"explanation":["옛말을 어떻게 대할지 써요.","옛 생활과 이어 봐요.","예를 하나 들어요."]}'::jsonb),
('g6_1_kor_u4_L03_challenge#10','kor',6,1,'u4','L03','g6_1_kor_u4_L03_challenge','lesson_challenge','K6-1-u4-C19',4,'essay','teacher','속담 하나를 골라 오늘 생활에 맞게 바꾸어 짓고, 담긴 교훈과 쓸 수 있는 상황을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C19","difficulty":4,"kind":"essay","stem":"속담 하나를 골라 오늘 생활에 맞게 바꾸어 짓고, 담긴 교훈과 쓸 수 있는 상황을 쓰세요.","answer_guide":{"answer":"예: 「가랑비에 옷 젖는 줄 모른다」를 「한 장씩 넘긴 책이 책장을 채운다」로 바꾸었다. 작은 것이 쌓여 큰 것이 된다는 교훈은 그대로 살렸다. 날마다 조금씩 읽은 책이 어느새 많이 쌓였을 때 쓸 수 있다.","scoring_points":["속담을 골라 낱말을 바꾸어 지었는가","원래 속담의 교훈을 살렸는가","쓸 수 있는 상황을 썼는가"]},"explanation":["속담을 하나 골라요.","교훈은 그대로 살려요.","쓸 상황을 적어요."]}'::jsonb),
('g6_1_kor_u4_L04_basic#1','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C20',1,'mc','auto','대화에서 쓰인 관용 표현은 어느 것인가요?',ARRAY['K6-1-u4-X15']::text[],false,'{"seq":1,"concept":"K6-1-u4-C20","difficulty":1,"kind":"mc","stem":"대화에서 쓰인 관용 표현은 어느 것인가요?","options":[{"t":"목마른 사람이 우물 판다","correct":true},{"t":"답답한 내가 먼저 가 볼게","mis":"K6-1-u4-X15"},{"t":"쉬는 시간마다 혼자 앉아 있어","mis":"K6-1-u4-X15"},{"t":"누군가 먼저 가서 말을 걸면 좋을 텐데","mis":"K6-1-u4-X15"}],"explanation":["그 자리에서 한 말이에요.","이것도 그 자리에서 한 말이에요.","예로부터 전해 오는 말을 골라요."],"asset":{"type":"speech","turns":[{"who":"초아","text":"새롬이가 전학 온 지 일주일이 됐는데 아직 아무하고도 말을 안 해. 쉬는 시간마다 혼자 앉아 있어."},{"who":"다솔","text":"누군가 먼저 가서 말을 걸면 좋을 텐데, 다들 눈치만 보고 있네."},{"who":"초아","text":"목마른 사람이 우물 판다잖아. 답답한 내가 먼저 가 볼게."}]}}'::jsonb),
('g6_1_kor_u4_L04_basic#2','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C21',1,'mc','auto','「마음이 굴뚝같다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X22']::text[],false,'{"seq":2,"concept":"K6-1-u4-C21","difficulty":1,"kind":"mc","stem":"「마음이 굴뚝같다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"무엇을 몹시 하고 싶어 하다","correct":true},{"t":"마음이 굴뚝처럼 시커멓다","mis":"K6-1-u4-X01"},{"t":"마음이 답답해 연기가 난다","mis":"K6-1-u4-X01"},{"t":"하기 싫은 마음이 크다","mis":"K6-1-u4-X22"}],"explanation":["굴뚝 색깔 이야기가 아니에요.","연기 이야기도 아니에요.","몹시 하고 싶은 마음이에요."]}'::jsonb),
('g6_1_kor_u4_L04_basic#3','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C22',1,'mc','auto','「낯이 뜨겁다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X21','K6-1-u4-X22']::text[],false,'{"seq":3,"concept":"K6-1-u4-C22","difficulty":1,"kind":"mc","stem":"「낯이 뜨겁다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"부끄러워 얼굴이 달아오르다","correct":true},{"t":"얼굴에 열이 나서 아프다","mis":"K6-1-u4-X21"},{"t":"화가 나서 소리를 지르다","mis":"K6-1-u4-X22"},{"t":"날씨가 더워 땀이 나다","mis":"K6-1-u4-X21"}],"explanation":["아파서 열이 나는 것이 아니에요.","화난 마음과는 달라요.","부끄러운 마음이에요."]}'::jsonb),
('g6_1_kor_u4_L04_basic#4','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C24',1,'ox','auto','같은 관용 표현이라도 누구에게 하느냐에 따라 뜻이 달라질 수 있어요.',ARRAY['K6-1-u4-X23']::text[],false,'{"seq":4,"concept":"K6-1-u4-C24","difficulty":1,"kind":"ox","stem":"같은 관용 표현이라도 누구에게 하느냐에 따라 뜻이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"같은 표현도 남을 가리키면 상처가 되고 자기를 가리키면 돌아봄이 되기 때문에","correct":true},{"t":"관용 표현은 굳어진 말이라 어디서나 똑같이 전해지기 때문에","mis":"K6-1-u4-X23"}],"mis":"K6-1-u4-X23","explanation":["뜻은 하나여도","듣는 사람이 달라지면","전해지는 것이 뒤집혀요."]}'::jsonb),
('g6_1_kor_u4_L04_basic#5','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C20',2,'mc','auto','초아가 「목마른 사람이 우물 판다잖아.」를 앞에 놓고 말한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X21']::text[],false,'{"seq":5,"concept":"K6-1-u4-C20","difficulty":2,"kind":"mc","stem":"초아가 「목마른 사람이 우물 판다잖아.」를 앞에 놓고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"답답한 내가 먼저 나서는 것이 당연하다고 전하려고","correct":true},{"t":"나서지 않는 친구들을 꾸짖으려고","mis":"K6-1-u4-X20"},{"t":"속담을 많이 안다는 것을 자랑하려고","mis":"K6-1-u4-X20"},{"t":"우물을 파러 가겠다고 알리려고","mis":"K6-1-u4-X21"}],"explanation":["꾸짖는 말이 아니에요.","자랑하려는 말도 아니에요.","그 말 뒤에 「내가 먼저 가 볼게」를 붙였어요."],"asset":{"type":"speech","turns":[{"who":"초아","text":"새롬이가 전학 온 지 일주일이 됐는데 아직 아무하고도 말을 안 해. 쉬는 시간마다 혼자 앉아 있어."},{"who":"다솔","text":"누군가 먼저 가서 말을 걸면 좋을 텐데, 다들 눈치만 보고 있네."},{"who":"초아","text":"목마른 사람이 우물 판다잖아. 답답한 내가 먼저 가 볼게."}]}}'::jsonb),
('g6_1_kor_u4_L04_basic#6','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C22',2,'mc','auto','「급할수록 돌아가라」가 담은 지혜가 드러난 소금 장수의 행동은 어느 것인가요?',ARRAY['K6-1-u4-X16','K6-1-u4-X20']::text[],false,'{"seq":6,"concept":"K6-1-u4-C22","difficulty":2,"kind":"mc","stem":"「급할수록 돌아가라」가 담은 지혜가 드러난 소금 장수의 행동은 어느 것인가요?","options":[{"t":"강을 따라 반나절을 걸어 얕은 여울목으로 건넜다","correct":true},{"t":"뱃삯을 두 배로 내고 서둘러 배를 탔다","mis":"K6-1-u4-X16"},{"t":"장에 가지 않고 집으로 되돌아갔다","mis":"K6-1-u4-X16"},{"t":"사공과 다투어 뱃삯을 깎았다","mis":"K6-1-u4-X20"}],"explanation":["서두르는 행동이에요.","포기하는 행동이에요.","돌아가는 길로 침착하게 해냈어요."],"asset":{"type":"passage","lines":["소금 장수는 강을 따라 위쪽으로 반나절을 걸어 얕은 여울목을 찾았다.","그는 지게를 지고 걸어서 강을 건넜고, 소금은 저물녘까지 모두 팔렸다.","그날 하루를 빈 배로 보낸 사공은 다음 날 소금 장수를 다시 만나자","낯이 뜨거워 고개를 들지 못했다."],"title":"옛이야기 「소금 장수와 나루터」 — 뒷부분"}}'::jsonb),
('g6_1_kor_u4_L04_basic#7','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C23',2,'match','auto','뜻이 비슷해 바꿔 쓸 수 있는 표현끼리 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u4-C23","difficulty":2,"kind":"match","stem":"뜻이 비슷해 바꿔 쓸 수 있는 표현끼리 알맞게 이으세요.","pairs":[{"l":"발등에 불이 떨어지다","r":"코앞에 닥치다"},{"l":"낯이 뜨겁다","r":"고개를 들지 못하다"},{"l":"마음이 굴뚝같다","r":"목이 빠지게 기다리다"}],"mis":"K6-1-u4-X22","explanation":["급한 마음끼리 이어요.","부끄러운 마음끼리 이어요.","간절한 마음끼리 이어요."]}'::jsonb),
('g6_1_kor_u4_L04_basic#8','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C24',2,'mc','auto','관용 표현을 알맞게 쓴 말은 어느 것인가요?',ARRAY['K6-1-u4-X23','K6-1-u4-X08']::text[],false,'{"seq":8,"concept":"K6-1-u4-C24","difficulty":2,"kind":"mc","stem":"관용 표현을 알맞게 쓴 말은 어느 것인가요?","options":[{"t":"「아직 서툴지만 첫술에 배부르랴. 천천히 해 볼게.」","correct":true},{"t":"상을 받은 친구에게 「개구리 올챙이 적 생각 못 하는구나.」","mis":"K6-1-u4-X23"},{"t":"아파서 결석한 친구에게 「눈코 뜰 새 없이 바빴겠구나.」","mis":"K6-1-u4-X08"},{"t":"발표를 잘한 친구에게 「빈 수레가 요란하다더니.」","mis":"K6-1-u4-X23"}],"explanation":["축하할 자리에서 깎아내려요.","아픈 친구와 바쁨은 어긋나요.","자기를 가리키는 자리라 알맞아요."]}'::jsonb),
('g6_1_kor_u4_L04_basic#9','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C25',2,'ox','auto','관용 표현을 친구들 앞에서 소리 내어 말하지 못하면 배우지 못한 거예요.',ARRAY['K6-1-u4-X24']::text[],false,'{"seq":9,"concept":"K6-1-u4-C25","difficulty":2,"kind":"ox","stem":"관용 표현을 친구들 앞에서 소리 내어 말하지 못하면 배우지 못한 거예요.","answer":"X","reason_options":[{"t":"쓰고 싶은 상황을 떠올리고 적어 보는 것부터 할 수 있는 만큼 나아가면 되기 때문에","correct":true},{"t":"관용 표현은 말로 해야만 배운 것이기 때문에","mis":"K6-1-u4-X24"}],"mis":"K6-1-u4-X24","explanation":["부담스러울 수 있어요.","떠올리기부터 시작해요.","적어 보기, 말해 보기로 나아가요."]}'::jsonb),
('g6_1_kor_u4_L04_basic#10','kor',6,1,'u4','L04','g6_1_kor_u4_L04_basic','lesson_basic','K6-1-u4-C26',3,'mc','auto','관용 표현을 쓸 상황을 짤 때 건너뛰지 말아야 할 마지막 칸은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X25']::text[],false,'{"seq":10,"concept":"K6-1-u4-C26","difficulty":3,"kind":"mc","stem":"관용 표현을 쓸 상황을 짤 때 건너뛰지 말아야 할 마지막 칸은 어느 것인가요?","options":[{"t":"표현의 뜻이 상황과 어긋나지 않는지 살피기","correct":true},{"t":"관용 표현을 몇 개 넣었는지 세기","mis":"K6-1-u4-X07"},{"t":"가장 어려운 표현으로 바꾸기","mis":"K6-1-u4-X25"},{"t":"대사를 되도록 길게 늘이기","mis":"K6-1-u4-X25"}],"explanation":["개수를 세는 칸이 아니에요.","어려운 표현이 좋은 것도 아니에요.","뜻과 상황이 맞는지 살펴요."]}'::jsonb),
('g6_1_kor_u4_L04_challenge#1','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C21',2,'mc','auto','새롬이가 「정말 하고 싶었다」 대신 「마음이 굴뚝같았는데」라고 말해서 더 전해진 것은 어느 것인가요?',ARRAY['K6-1-u4-X21','K6-1-u4-X20','K6-1-u4-X09']::text[],false,'{"seq":1,"concept":"K6-1-u4-C21","difficulty":2,"kind":"mc","stem":"새롬이가 「정말 하고 싶었다」 대신 「마음이 굴뚝같았는데」라고 말해서 더 전해진 것은 어느 것인가요?","options":[{"t":"말을 걸고 싶은 마음이 얼마나 컸는지","correct":true},{"t":"굴뚝이 있는 집에 산다는 것","mis":"K6-1-u4-X21"},{"t":"사실은 말을 걸기 싫었다는 것","mis":"K6-1-u4-X20"},{"t":"그냥 말한 것과 아무 차이가 없다","mis":"K6-1-u4-X09"}],"explanation":["굴뚝 이야기가 아니에요.","싫었다는 것이 아니에요.","마음의 크기가 함께 전해졌어요."],"asset":{"type":"speech","turns":[{"who":"새롬","text":"그때 네가 먼저 와 줘서 고마웠어. 사실 나도 말을 걸고 싶은 마음이 굴뚝같았는데, 첫마디가 안 나오더라."},{"who":"초아","text":"나도 사실은 떨렸어. 그런데 누구 한 사람은 먼저 움직여야 하잖아."}]}}'::jsonb),
('g6_1_kor_u4_L04_challenge#2','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C22',2,'ox','auto','「소금 장수는 발등에 불이 떨어진 심정이었다」는 소금 장수의 발등에 실제로 불이 붙었다는 뜻이에요.',ARRAY['K6-1-u4-X21']::text[],false,'{"seq":2,"concept":"K6-1-u4-C22","difficulty":2,"kind":"ox","stem":"「소금 장수는 발등에 불이 떨어진 심정이었다」는 소금 장수의 발등에 실제로 불이 붙었다는 뜻이에요.","answer":"X","reason_options":[{"t":"장이 오늘뿐이라 몹시 급한 마음을 나타낸 표현이기 때문에","correct":true},{"t":"이야기에 쓰인 말은 모두 실제로 일어난 일이기 때문에","mis":"K6-1-u4-X21"}],"mis":"K6-1-u4-X21","explanation":["「심정」이라고 했어요.","실제 불 이야기가 아니에요.","몹시 급한 마음이에요."],"asset":{"type":"passage","lines":["옛날, 소금을 지고 장을 다니는 장수가 있었다. 강 건너 장에 가려고","나루터에 닿았는데, 사공이 팔짱을 낀 채 말했다.","「오늘은 물이 불었으니 뱃삯을 두 배로 내시오.」","장이 서는 날은 오늘 하루뿐이었다. 소금 장수는 발등에 불이 떨어진","심정이었지만 지게를 내려놓고 생각했다. 「급할수록 돌아가라고 했지.」"],"title":"옛이야기 「소금 장수와 나루터」 — 앞부분"}}'::jsonb),
('g6_1_kor_u4_L04_challenge#3','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C22',3,'mc','auto','사공이 「낯이 뜨거워 고개를 들지 못했다」에 담긴 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X21','K6-1-u4-X20']::text[],false,'{"seq":3,"concept":"K6-1-u4-C22","difficulty":3,"kind":"mc","stem":"사공이 「낯이 뜨거워 고개를 들지 못했다」에 담긴 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"욕심을 부려 뱃삯을 올린 일이 부끄럽다","correct":true},{"t":"햇볕에 얼굴이 탔다","mis":"K6-1-u4-X21"},{"t":"소금 장수에게 화가 났다","mis":"K6-1-u4-X20"},{"t":"배를 지키느라 목이 아팠다","mis":"K6-1-u4-X21"}],"explanation":["햇볕 이야기가 아니에요.","화난 마음이 아니에요.","빈 배로 하루를 보낸 뒤의 부끄러움이에요."],"asset":{"type":"passage","lines":["소금 장수는 강을 따라 위쪽으로 반나절을 걸어 얕은 여울목을 찾았다.","그는 지게를 지고 걸어서 강을 건넜고, 소금은 저물녘까지 모두 팔렸다.","그날 하루를 빈 배로 보낸 사공은 다음 날 소금 장수를 다시 만나자","낯이 뜨거워 고개를 들지 못했다."],"title":"옛이야기 「소금 장수와 나루터」 — 뒷부분"}}'::jsonb),
('g6_1_kor_u4_L04_challenge#4','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C24',3,'error','auto','「빈 수레가 요란하다」를 쓴 친구들이에요. 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K6-1-u4-X23']::text[],false,'{"seq":4,"concept":"K6-1-u4-C24","difficulty":3,"kind":"error","stem":"「빈 수레가 요란하다」를 쓴 친구들이에요. 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"지호 — 노래 대회에서 상을 받은 짝에게 「빈 수레가 요란하다더니.」라고 말했다","correct":true,"mis_target":"K6-1-u4-X23"},{"t":"라희 — 연습을 미룬 자신을 돌아보며 「내가 빈 수레가 요란했구나.」라고 썼다","mis":"K6-1-u4-X23"},{"t":"도하 — 준비 없이 큰소리치던 자신을 떠올리며 일기에 이 속담을 썼다","mis":"K6-1-u4-X23"}],"explanation":["라희는 자신을 돌아봤어요.","도하도 자신을 돌아봤어요.","상 받은 짝에게는 깎아내리는 말이에요."]}'::jsonb),
('g6_1_kor_u4_L04_challenge#5','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C20',3,'mc','auto','소금 장수가 「급할수록 돌아가라고 했지.」라고 혼잣말한 의도로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X16']::text[],false,'{"seq":5,"concept":"K6-1-u4-C20","difficulty":3,"kind":"mc","stem":"소금 장수가 「급할수록 돌아가라고 했지.」라고 혼잣말한 의도로 알맞은 것은 어느 것인가요?","options":[{"t":"서두르기보다 다른 길을 찾아 침착하게 가려고 스스로 마음을 다잡으려고","correct":true},{"t":"사공에게 겁을 주려고","mis":"K6-1-u4-X20"},{"t":"장에 가는 것을 그만두려고","mis":"K6-1-u4-X16"},{"t":"속담을 외운 것을 뽐내려고","mis":"K6-1-u4-X20"}],"explanation":["사공에게 한 말이 아니에요.","그만두지 않았어요.","스스로 마음을 다잡았어요."],"asset":{"type":"passage","lines":["옛날, 소금을 지고 장을 다니는 장수가 있었다. 강 건너 장에 가려고","나루터에 닿았는데, 사공이 팔짱을 낀 채 말했다.","「오늘은 물이 불었으니 뱃삯을 두 배로 내시오.」","장이 서는 날은 오늘 하루뿐이었다. 소금 장수는 발등에 불이 떨어진","심정이었지만 지게를 내려놓고 생각했다. 「급할수록 돌아가라고 했지.」"],"title":"옛이야기 「소금 장수와 나루터」 — 앞부분"}}'::jsonb),
('g6_1_kor_u4_L04_challenge#6','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C23',3,'mc','auto','「발등에 불이 떨어지다」와 바꿔 쓸 수 있는 표현은 어느 것인가요?',ARRAY['K6-1-u4-X22']::text[],false,'{"seq":6,"concept":"K6-1-u4-C23","difficulty":3,"kind":"mc","stem":"「발등에 불이 떨어지다」와 바꿔 쓸 수 있는 표현은 어느 것인가요?","options":[{"t":"코앞에 닥치다","correct":true},{"t":"낯이 뜨겁다","mis":"K6-1-u4-X22"},{"t":"어깨너머로 배우다","mis":"K6-1-u4-X22"},{"t":"입이 무겁다","mis":"K6-1-u4-X22"}],"explanation":["낯이 뜨겁다는 부끄러움이에요.","어깨너머로 배우다는 보고 배우는 거예요.","급한 마음끼리 바꿔 써요."]}'::jsonb),
('g6_1_kor_u4_L04_challenge#7','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C26',3,'mc','auto','짧은 대화를 지은 뒤 관용 표현을 빼고 다시 읽어 보는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X09','K6-1-u4-X07','K6-1-u4-X25']::text[],false,'{"seq":7,"concept":"K6-1-u4-C26","difficulty":3,"kind":"mc","stem":"짧은 대화를 지은 뒤 관용 표현을 빼고 다시 읽어 보는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 표현이 대화에 무엇을 더했는지 알 수 있어서","correct":true},{"t":"관용 표현이 없는 대화가 언제나 더 좋아서","mis":"K6-1-u4-X09"},{"t":"관용 표현의 개수를 늘리려고","mis":"K6-1-u4-X07"},{"t":"읽는 시간을 줄이려고","mis":"K6-1-u4-X25"}],"explanation":["빼는 것이 늘 좋은 것은 아니에요.","개수를 늘리려는 것이 아니에요.","표현이 더한 것을 견줘 봐요."]}'::jsonb),
('g6_1_kor_u4_L04_challenge#8','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C24',4,'mc','auto','짝이 넘어져 무릎을 다치고 울고 있어요. 이 자리에서 가장 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u4-X23','K6-1-u4-X08','K6-1-u4-X07']::text[],false,'{"seq":8,"concept":"K6-1-u4-C24","difficulty":4,"kind":"mc","stem":"짝이 넘어져 무릎을 다치고 울고 있어요. 이 자리에서 가장 알맞은 말은 어느 것인가요?","options":[{"t":"관용 표현을 넣지 않고 「많이 아팠지? 보건실에 같이 가자.」라고 말한다","correct":true},{"t":"「원숭이도 나무에서 떨어진다더니.」라고 웃으며 말한다","mis":"K6-1-u4-X23"},{"t":"「첫술에 배부르랴.」라고 말한다","mis":"K6-1-u4-X08"},{"t":"관용 표현을 셋 넣어 길게 위로한다","mis":"K6-1-u4-X07"}],"explanation":["아픈 친구를 웃으며 놀리면 안 돼요.","뜻이 상황과 어긋나요.","관용 표현이 언제나 알맞은 것은 아니에요."]}'::jsonb),
('g6_1_kor_u4_L04_challenge#9','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C20',4,'essay','teacher','초아가 「목마른 사람이 우물 판다잖아.」라고 말한 의도를 쓰고, 「내가 먼저 가 볼게.」라고만 말했을 때와 무엇이 다른지 견주어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C20","difficulty":4,"kind":"essay","stem":"초아가 「목마른 사람이 우물 판다잖아.」라고 말한 의도를 쓰고, 「내가 먼저 가 볼게.」라고만 말했을 때와 무엇이 다른지 견주어 쓰세요.","answer_guide":{"answer":"예: 초아는 새롬이를 걱정하는 답답한 사람이 자기이니 자기가 먼저 나서는 것이 당연하다고 전하려고 이 속담을 썼다. 「내가 먼저 가 볼게.」라고만 하면 뜻은 통하지만 왜 나서는지와 그때의 마음은 보이지 않는다. 속담을 앞에 놓으니 나서는 까닭과 마음이 함께 전해진다.","scoring_points":["초아의 의도를 바르게 썼는가","그냥 말했을 때 빠지는 것을 썼는가","속담이 더한 까닭과 마음을 견주어 썼는가"]},"explanation":["속담 뒤에 붙은 말을 봐요.","그냥 말한 것과 견줘요.","무엇이 더 전해졌는지 써요."],"asset":{"type":"speech","turns":[{"who":"초아","text":"새롬이가 전학 온 지 일주일이 됐는데 아직 아무하고도 말을 안 해. 쉬는 시간마다 혼자 앉아 있어."},{"who":"다솔","text":"누군가 먼저 가서 말을 걸면 좋을 텐데, 다들 눈치만 보고 있네."},{"who":"초아","text":"목마른 사람이 우물 판다잖아. 답답한 내가 먼저 가 볼게."}]}}'::jsonb),
('g6_1_kor_u4_L04_challenge#10','kor',6,1,'u4','L04','g6_1_kor_u4_L04_challenge','lesson_challenge','K6-1-u4-C26',4,'essay','teacher','관용 표현 하나를 골라 상황 짜기 네 칸(표현 · 상황 · 누가 누구에게 · 어긋나지 않는지)을 채우고, 그 표현이 한 번 들어간 짧은 대화를 지으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C26","difficulty":4,"kind":"essay","stem":"관용 표현 하나를 골라 상황 짜기 네 칸(표현 · 상황 · 누가 누구에게 · 어긋나지 않는지)을 채우고, 그 표현이 한 번 들어간 짧은 대화를 지으세요.","answer_guide":{"answer":"예: 표현 — 발등에 불이 떨어지다. 상황 — 숙제 마감이 내일 아침인데 아직 시작하지 않았다. 누가 누구에게 — 형이 동생에게. 살피기 — 급한 마음을 나타내는 말이라 상황과 어긋나지 않는다. 대화 — 형: 「숙제 다 했어?」 동생: 「아직 하나도 안 했어.」 형: 「발등에 불이 떨어졌네. 지금 바로 시작하자.」 동생: 「응, 도와줘.」","scoring_points":["네 칸을 모두 채웠는가","표현의 뜻과 상황이 어긋나지 않는가","표현이 한 번 들어간 대화를 지었는가"]},"explanation":["표현과 상황을 정해요.","누가 누구에게 말할지 정해요.","마지막 칸을 꼭 살펴요."]}'::jsonb),
('g6_1_kor_u4_L06_basic#1','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C27',1,'mc','auto','「견학 기록문」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X29','K6-1-u4-X26']::text[],false,'{"seq":1,"concept":"K6-1-u4-C27","difficulty":1,"kind":"mc","stem":"「견학 기록문」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"견학하고 새롭게 안 사실을 중심으로 보고 듣고 느낀 것을 쓴 글","correct":true},{"t":"하루 일을 돌아보며 마음만 적은 글","mis":"K6-1-u4-X30"},{"t":"어떤 곳을 알리려고 사실만 적은 안내문","mis":"K6-1-u4-X29"},{"t":"지어낸 인물이 나오는 이야기","mis":"K6-1-u4-X26"}],"explanation":["마음만 있으면 일기예요.","사실만 있으면 안내문이에요.","새로 안 사실과 마음이 함께 있어요."]}'::jsonb),
('g6_1_kor_u4_L06_basic#2','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C28',1,'match','auto','견학 기록문의 세 가지와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u4-C28","difficulty":1,"kind":"match","stem":"견학 기록문의 세 가지와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"여정","r":"어디를 거쳐 어떻게 다녔는지, 다닌 길"},{"l":"견문","r":"보고 들은 것, 새롭게 안 사실"},{"l":"감상","r":"생각하거나 느낀 것"}],"mis":"K6-1-u4-X27","explanation":["다닌 길은 여정이에요.","보고 들은 것은 견문이에요.","느낀 것은 감상이에요."]}'::jsonb),
('g6_1_kor_u4_L06_basic#3','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C29',1,'mc','auto','견학 기록문의 처음 부분에 쓰는 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":3,"concept":"K6-1-u4-C29","difficulty":1,"kind":"mc","stem":"견학 기록문의 처음 부분에 쓰는 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"견학한 까닭 · 함께 간 사람 · 견학 장소","correct":true},{"t":"견학한 내용 정리와 깨달은 점","mis":"K6-1-u4-X28"},{"t":"전시실에서 본 것과 그때의 마음","mis":"K6-1-u4-X28"},{"t":"다음에 가고 싶은 다른 곳의 목록","mis":"K6-1-u4-X28"}],"explanation":["정리와 깨달음은 끝이에요.","본 것과 마음은 가운데예요.","처음에는 개요를 알려요."]}'::jsonb),
('g6_1_kor_u4_L06_basic#4','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C30',1,'ox','auto','견학 기록문에는 새로 안 사실과 그때의 마음이 함께 들어가야 해요.',ARRAY['K6-1-u4-X29']::text[],false,'{"seq":4,"concept":"K6-1-u4-C30","difficulty":1,"kind":"ox","stem":"견학 기록문에는 새로 안 사실과 그때의 마음이 함께 들어가야 해요.","answer":"O","reason_options":[{"t":"사실만 남으면 안내문이 되고 마음만 남으면 일기가 되기 때문에","correct":true},{"t":"새로 안 사실만 적어도 충분하기 때문에","mis":"K6-1-u4-X29"}],"mis":"K6-1-u4-X29","explanation":["사실만으로는 부족해요.","마음만으로도 부족해요.","둘이 함께 있어야 해요."]}'::jsonb),
('g6_1_kor_u4_L06_basic#5','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C31',2,'mc','auto','「갯벌 생태관을 다녀와서」라는 제목만 보고 짐작할 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X31','K6-1-u4-X26']::text[],false,'{"seq":5,"concept":"K6-1-u4-C31","difficulty":2,"kind":"mc","stem":"「갯벌 생태관을 다녀와서」라는 제목만 보고 짐작할 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"갯벌을 다루는 전시관에 다녀온 뒤 쓴 글이고, 갯벌에 대해 새로 안 것이 담겼을 것이다","correct":true},{"t":"갯벌을 지키자고 주장하는 글일 것이다","mis":"K6-1-u4-X31"},{"t":"갯벌에 사는 인물이 나오는 옛이야기일 것이다","mis":"K6-1-u4-X26"},{"t":"생태관에 가는 길만 적은 글일 것이다","mis":"K6-1-u4-X31"}],"explanation":["「다녀와서」는 주장하는 말이 아니에요.","옛이야기가 아니에요.","다녀온 곳과 새로 안 것을 짐작해요."]}'::jsonb),
('g6_1_kor_u4_L06_basic#6','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C28',2,'mc','auto','첫째 문단에서 여정에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":6,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"첫째 문단에서 여정에 해당하는 것은 어느 것인가요?","options":[{"t":"「버스로 사십 분을 달려 바닷가 마을에 닿았다.」","correct":true},{"t":"「목이 빠지게 기다리던 날이었다.」","mis":"K6-1-u4-X27"},{"t":"「학교에서 갯벌 이야기를 들었다.」","mis":"K6-1-u4-X27"},{"t":"「실제 갯벌을 보고 싶었다.」","mis":"K6-1-u4-X27"}],"explanation":["기다린 마음은 감상 쪽이에요.","들은 까닭은 여정이 아니에요.","어떻게 다녔는지가 여정이에요."],"asset":{"type":"passage","lines":["지난 토요일, 가족과 함께 우리 고장의 갯벌 생태관에 다녀왔다.","학교에서 갯벌 이야기를 들은 뒤로 실제 갯벌을 보고 싶었는데,","마침 주말에 문을 연다고 해서 목이 빠지게 기다리던 날이었다.","버스로 사십 분을 달려 바닷가 마을에 닿았다."],"title":"「갯벌 생태관을 다녀와서」 — 첫째 문단"}}'::jsonb),
('g6_1_kor_u4_L06_basic#7','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C28',2,'mc','auto','셋째 · 넷째 문단에서 견문에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":7,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"셋째 · 넷째 문단에서 견문에 해당하는 것은 어느 것인가요?","options":[{"t":"「짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있다.」","correct":true},{"t":"「마지막으로 관찰 데크에 올랐다.」","mis":"K6-1-u4-X27"},{"t":"「다음 전시실로 들어갔다.」","mis":"K6-1-u4-X27"},{"t":"「쉬어 가는 곳이었다는 것을 처음 알아 놀랐다.」","mis":"K6-1-u4-X27"}],"explanation":["관찰 데크에 오른 것은 여정이에요.","전시실로 간 것도 여정이에요.","새로 안 사실이 견문이에요."],"asset":{"type":"passage","lines":["다음 전시실에는 집게발 한쪽이 유난히 큰 칠게와 짱뚱어가 있었다.","짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있어서","썰물 때 갯벌 위를 돌아다닌다고 한다.","마지막으로 오른 관찰 데크에서는 망원경으로 새를 볼 수 있었다.","봄과 가을이면 도요새가 이 갯벌에 들러 먹이를 먹고 힘을 채운다고 했다.","갯벌이 새들에게 쉬어 가는 곳이었다는 것을 처음 알았다."],"title":"「갯벌 생태관을 다녀와서」 — 셋째 · 넷째 문단"}}'::jsonb),
('g6_1_kor_u4_L06_basic#8','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C27',2,'ox','auto','견학 기록문을 쓸 때 견학한 곳에서 새로 안 사실은 그럴듯하게 꾸며 써도 돼요.',ARRAY['K6-1-u4-X26']::text[],false,'{"seq":8,"concept":"K6-1-u4-C27","difficulty":2,"kind":"ox","stem":"견학 기록문을 쓸 때 견학한 곳에서 새로 안 사실은 그럴듯하게 꾸며 써도 돼요.","answer":"X","reason_options":[{"t":"견학 기록문은 정보를 전하는 글이라 새로 안 사실은 참이어야 하기 때문에","correct":true},{"t":"읽는 사람이 재미있기만 하면 되기 때문에","mis":"K6-1-u4-X26"}],"mis":"K6-1-u4-X26","explanation":["견학 기록문은 사실을 실어 날라요.","꾸민 사실은 거짓을 전해요.","새로 안 사실은 참이어야 해요."]}'::jsonb),
('g6_1_kor_u4_L06_basic#9','kor',6,1,'u4','L06','g6_1_kor_u4_L06_basic','lesson_basic','K6-1-u4-C29',2,'mc','auto','견학 기록문의 끝 부분에 들어갈 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":9,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"견학 기록문의 끝 부분에 들어갈 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「이번 견학으로 갯벌이 수많은 생물이 기대어 사는 곳임을 알게 되었다.」","correct":true},{"t":"「지난 토요일, 가족과 함께 갯벌 생태관에 다녀왔다.」","mis":"K6-1-u4-X28"},{"t":"「다음 전시실에는 칠게와 짱뚱어가 있었다.」","mis":"K6-1-u4-X28"},{"t":"「버스로 바닷가 마을에 닿았다.」","mis":"K6-1-u4-X28"}],"explanation":["간 때와 사람은 처음이에요.","전시실에서 본 것은 가운데예요.","정리하고 깨달은 점이 끝이에요."]}'::jsonb),
