('g6_1_kor_u4_L06_challenge#3','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C30',3,'mc','auto','이 글이 견학 기록문이 되려면 무엇을 더해야 할까요?',ARRAY['K6-1-u4-X30','K6-1-u4-X07']::text[],false,'{"seq":3,"concept":"K6-1-u4-C30","difficulty":3,"kind":"mc","stem":"이 글이 견학 기록문이 되려면 무엇을 더해야 할까요?","options":[{"t":"그곳에서 보고 들어 새로 안 사실","correct":true},{"t":"「재미있었다」를 여러 번 더 쓴다","mis":"K6-1-u4-X30"},{"t":"관용 표현을 많이 넣는다","mis":"K6-1-u4-X07"},{"t":"지금도 견학 기록문이니 그대로 둔다","mis":"K6-1-u4-X30"}],"explanation":["느낌을 늘려도 그대로예요.","관용 표현 개수가 문제가 아니에요.","견문이 빠져 일기에 가까워요."],"asset":{"type":"passage","lines":["오늘 갯벌 생태관에 갔다.","재미있었다. 신기했다. 또 오고 싶다."],"title":"어느 학생의 견학 글"}}'::jsonb),
('g6_1_kor_u4_L06_challenge#4','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C27',3,'error','auto','견학 기록문에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X26','K6-1-u4-X29']::text[],false,'{"seq":4,"concept":"K6-1-u4-C27","difficulty":3,"kind":"error","stem":"견학 기록문에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"세아 — 「견학한 곳에서 새로 안 사실은 재미있게 지어내도 괜찮아.」","correct":true,"mis_target":"K6-1-u4-X26"},{"t":"준서 — 「견학한 곳은 우리 고장 어디라도 될 수 있어.」","mis":"K6-1-u4-X26"},{"t":"유나 — 「새로 안 사실을 중심에 놓고 내 마음도 적어.」","mis":"K6-1-u4-X29"}],"explanation":["준서는 바르게 말했어요.","유나도 바르게 말했어요.","새로 안 사실은 참이어야 해요."]}'::jsonb),
('g6_1_kor_u4_L06_challenge#5','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C29',3,'mc','auto','첫째 문단에 들어 있지 않은 것은 어느 것인가요?',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":5,"concept":"K6-1-u4-C29","difficulty":3,"kind":"mc","stem":"첫째 문단에 들어 있지 않은 것은 어느 것인가요?","options":[{"t":"갯벌 흙 속 생물이 물을 거른다는 사실","correct":true},{"t":"간 때 — 지난 토요일","mis":"K6-1-u4-X28"},{"t":"함께 간 사람 — 가족","mis":"K6-1-u4-X28"},{"t":"간 까닭 — 실제 갯벌을 보고 싶어서","mis":"K6-1-u4-X28"}],"explanation":["간 때가 들어 있어요.","함께 간 사람도 들어 있어요.","새로 안 사실은 가운데에 나와요."],"asset":{"type":"passage","lines":["지난 토요일, 가족과 함께 우리 고장의 갯벌 생태관에 다녀왔다.","학교에서 갯벌 이야기를 들은 뒤로 실제 갯벌을 보고 싶었는데,","마침 주말에 문을 연다고 해서 목이 빠지게 기다리던 날이었다.","버스로 사십 분을 달려 바닷가 마을에 닿았다."],"title":"「갯벌 생태관을 다녀와서」 — 첫째 문단"}}'::jsonb),
('g6_1_kor_u4_L06_challenge#6','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C28',3,'mc','auto','둘째 문단의 「입이 딱 벌어졌다」는 여정 · 견문 · 감상 가운데 무엇인가요?',ARRAY['K6-1-u4-X27','K6-1-u4-X28']::text[],false,'{"seq":6,"concept":"K6-1-u4-C28","difficulty":3,"kind":"mc","stem":"둘째 문단의 「입이 딱 벌어졌다」는 여정 · 견문 · 감상 가운데 무엇인가요?","options":[{"t":"감상","correct":true},{"t":"견문","mis":"K6-1-u4-X27"},{"t":"여정","mis":"K6-1-u4-X27"},{"t":"처음 부분의 까닭","mis":"K6-1-u4-X28"}],"explanation":["새로 안 사실이 아니에요.","다닌 길도 아니에요.","놀란 마음을 나타냈어요."],"asset":{"type":"passage","lines":["가장 먼저 들어간 곳은 갯벌을 설명하는 전시실이었다.","갯벌은 밀물 때 바닷물에 잠기고 썰물 때 드러나는 땅이라고 한다.","갯벌 흙 속에는 눈에 보이지 않을 만큼 작은 생물이 헤아릴 수 없이 많고,","이 생물들이 바닷물로 흘러든 더러운 물질을 걸러 준다고 했다.","바닷물을 걸러 주는 일을 흙이 한다는 말에 입이 딱 벌어졌다."],"title":"「갯벌 생태관을 다녀와서」 — 둘째 문단"}}'::jsonb),
('g6_1_kor_u4_L06_challenge#7','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C31',3,'mc','auto','셋째 · 넷째 문단의 중심 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X31']::text[],false,'{"seq":7,"concept":"K6-1-u4-C31","difficulty":3,"kind":"mc","stem":"셋째 · 넷째 문단의 중심 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"갯벌 생물과 도요새를 보며 갯벌이 생물이 기대어 쉬는 곳임을 알았다","correct":true},{"t":"가족과 함께 갯벌 생태관에 다녀왔다","mis":"K6-1-u4-X31"},{"t":"갯벌의 소중함을 알고 눈여겨보기로 했다","mis":"K6-1-u4-X31"},{"t":"버스를 타고 바닷가 마을에 갔다","mis":"K6-1-u4-X31"}],"explanation":["다녀온 것은 첫째 문단이에요.","다짐은 끝 문단이에요.","가운데 문단은 본 것과 안 것이에요."],"asset":{"type":"passage","lines":["다음 전시실에는 집게발 한쪽이 유난히 큰 칠게와 짱뚱어가 있었다.","짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있어서","썰물 때 갯벌 위를 돌아다닌다고 한다.","마지막으로 오른 관찰 데크에서는 망원경으로 새를 볼 수 있었다.","봄과 가을이면 도요새가 이 갯벌에 들러 먹이를 먹고 힘을 채운다고 했다.","갯벌이 새들에게 쉬어 가는 곳이었다는 것을 처음 알았다."],"title":"「갯벌 생태관을 다녀와서」 — 셋째 · 넷째 문단"}}'::jsonb),
('g6_1_kor_u4_L06_challenge#8','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C30',4,'mc','auto','두 친구가 쓴 글을 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X29','K6-1-u4-X30']::text[],false,'{"seq":8,"concept":"K6-1-u4-C30","difficulty":4,"kind":"mc","stem":"두 친구가 쓴 글을 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"㉮는 감상이 빠져 안내문에, ㉯는 견문이 빠져 일기에 가깝고, 둘을 엮어야 견학 기록문이 된다","correct":true},{"t":"㉮만 견학 기록문이다","mis":"K6-1-u4-X29"},{"t":"㉯만 견학 기록문이다","mis":"K6-1-u4-X30"},{"t":"둘 다 견학 기록문이다","mis":"K6-1-u4-X29"}],"explanation":["㉮에는 마음이 없어요.","㉯에는 새로 안 사실이 없어요.","두 가지가 함께 있어야 해요."],"asset":{"type":"passage","lines":["㉮ 갯벌은 썰물 때 드러나는 땅이다. 짱뚱어는 살갗으로 숨을 쉰다.","　 도요새는 봄과 가을에 갯벌에 들른다.","㉯ 갯벌에 갔다. 재미있었다. 신기했다. 또 오고 싶다."],"title":"두 친구가 쓴 글"}}'::jsonb),
('g6_1_kor_u4_L06_challenge#9','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C28',4,'essay','teacher','이 부분에서 여정 · 견문 · 감상을 하나씩 찾아 쓰고, 각각 그렇게 본 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C28","difficulty":4,"kind":"essay","stem":"이 부분에서 여정 · 견문 · 감상을 하나씩 찾아 쓰고, 각각 그렇게 본 까닭을 쓰세요.","answer_guide":{"answer":"예: 여정 — 「마지막으로 오른 관찰 데크」처럼 다음 곳으로 옮겨 간 길이 드러난다. 견문 — 「짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있다」는 그곳에서 새로 안 사실이다. 감상 — 「쉬어 가는 곳이었다는 것을 처음 알았다」에는 몰랐던 것을 깨달은 글쓴이의 마음이 담겼다.","scoring_points":["여정을 바르게 찾았는가","견문을 바르게 찾았는가","감상을 찾고 까닭을 썼는가"]},"explanation":["다닌 길을 찾아요.","새로 안 사실을 찾아요.","마음이 드러난 곳을 찾아요."],"asset":{"type":"passage","lines":["다음 전시실에는 집게발 한쪽이 유난히 큰 칠게와 짱뚱어가 있었다.","짱뚱어는 물 밖에서도 살갗으로 숨을 쉴 수 있어서","썰물 때 갯벌 위를 돌아다닌다고 한다.","마지막으로 오른 관찰 데크에서는 망원경으로 새를 볼 수 있었다.","봄과 가을이면 도요새가 이 갯벌에 들러 먹이를 먹고 힘을 채운다고 했다.","갯벌이 새들에게 쉬어 가는 곳이었다는 것을 처음 알았다."],"title":"「갯벌 생태관을 다녀와서」 — 셋째 · 넷째 문단"}}'::jsonb),
('g6_1_kor_u4_L06_challenge#10','kor',6,1,'u4','L06','g6_1_kor_u4_L06_challenge','lesson_challenge','K6-1-u4-C30',4,'essay','teacher','견학 기록문이 안내문과 일기와 어떻게 다른지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C30","difficulty":4,"kind":"essay","stem":"견학 기록문이 안내문과 일기와 어떻게 다른지 설명하세요.","answer_guide":{"answer":"예: 안내문은 그곳에 대한 사실만 알려 주고, 일기는 그날 느낀 마음을 중심으로 적는다. 견학 기록문은 그 사이에 서는 글로, 견학하고 새롭게 안 사실을 중심에 놓으면서 그것을 알고 내 마음이 어떻게 움직였는지도 함께 적는다. 그래서 견문과 감상이 함께 있어야 한다.","scoring_points":["안내문의 특징을 썼는가","일기의 특징을 썼는가","견학 기록문은 견문과 감상을 함께 담는다고 썼는가"]},"explanation":["안내문을 떠올려요.","일기를 떠올려요.","그 사이의 글을 설명해요."]}'::jsonb),
('g6_1_kor_u4_L08_basic#1','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C32',1,'mc','auto','견학 기록문을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X32','K6-1-u4-X38']::text[],false,'{"seq":1,"concept":"K6-1-u4-C32","difficulty":1,"kind":"mc","stem":"견학 기록문을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"보고 들은 것과 그때의 마음을 오래 남길 수 있다","correct":true},{"t":"글씨를 빨리 쓰는 연습이 된다","mis":"K6-1-u4-X32"},{"t":"외운 낱말의 개수를 늘릴 수 있다","mis":"K6-1-u4-X32"},{"t":"다른 사람 글보다 길게 쓸 수 있다","mis":"K6-1-u4-X38"}],"explanation":["글씨 연습이 목적이 아니에요.","낱말 외우기도 아니에요.","흐려지는 것을 붙잡아 남겨요."]}'::jsonb),
('g6_1_kor_u4_L08_basic#2','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C33',1,'mc','auto','쓸 견학을 고를 때 가장 중요한 일은 어느 것인가요?',ARRAY['K6-1-u4-X33']::text[],false,'{"seq":2,"concept":"K6-1-u4-C33","difficulty":1,"kind":"mc","stem":"쓸 견학을 고를 때 가장 중요한 일은 어느 것인가요?","options":[{"t":"왜 기억에 남는지 한 줄로 적어 보기","correct":true},{"t":"가장 먼 곳을 고르기","mis":"K6-1-u4-X33"},{"t":"사진을 가장 많이 찍은 곳 고르기","mis":"K6-1-u4-X33"},{"t":"친구가 다녀온 곳을 따라 고르기","mis":"K6-1-u4-X33"}],"explanation":["먼 곳이 좋은 것은 아니에요.","사진 수로 정하지 않아요.","기억에 남은 까닭이 감상이 돼요."]}'::jsonb),
('g6_1_kor_u4_L08_basic#3','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C34',1,'mc','auto','목적 · 주제 · 읽을 사람 가운데 글의 모양을 가장 많이 바꾸는 것은 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X34']::text[],false,'{"seq":3,"concept":"K6-1-u4-C34","difficulty":1,"kind":"mc","stem":"목적 · 주제 · 읽을 사람 가운데 글의 모양을 가장 많이 바꾸는 것은 어느 것인가요?","options":[{"t":"읽을 사람","correct":true},{"t":"글씨 크기","mis":"K6-1-u4-X38"},{"t":"종이 색깔","mis":"K6-1-u4-X38"},{"t":"제목의 글자 수","mis":"K6-1-u4-X34"}],"explanation":["글씨 크기는 셋에 들지 않아요.","종이 색도 아니에요.","누가 읽느냐에 따라 낱말과 설명이 달라져요."]}'::jsonb),
('g6_1_kor_u4_L08_basic#4','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C36',1,'ox','auto','관용 표현은 견문 자리보다 감상 자리에 얹는 것이 잘 어울려요.',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":4,"concept":"K6-1-u4-C36","difficulty":1,"kind":"ox","stem":"관용 표현은 견문 자리보다 감상 자리에 얹는 것이 잘 어울려요.","answer":"O","reason_options":[{"t":"견문은 사실이고 감상은 마음이라 사실 자리에 얹으면 무엇이 사실인지 흐려지기 때문에","correct":true},{"t":"관용 표현은 어디에 넣어도 똑같기 때문에","mis":"K6-1-u4-X36"}],"mis":"K6-1-u4-X36","explanation":["견문은 사실이에요.","감상은 마음이에요.","관용 표현은 마음 쪽에 놓여요."]}'::jsonb),
('g6_1_kor_u4_L08_basic#5','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C34',2,'mc','auto','읽을 사람이 저학년 동생이라면 무엇을 바꾸면 좋을까요?',ARRAY['K6-1-u4-X34','K6-1-u4-X30']::text[],false,'{"seq":5,"concept":"K6-1-u4-C34","difficulty":2,"kind":"mc","stem":"읽을 사람이 저학년 동생이라면 무엇을 바꾸면 좋을까요?","options":[{"t":"어려운 낱말은 풀어 쓰고 낯선 것은 한 줄 더 설명한다","correct":true},{"t":"문단을 모두 없애고 한 덩어리로 길게 쓴다","mis":"K6-1-u4-X34"},{"t":"새로 안 사실은 빼고 느낀 점만 남긴다","mis":"K6-1-u4-X30"},{"t":"어른이 읽을 때와 똑같이 쓴다","mis":"K6-1-u4-X34"}],"explanation":["문단을 없애면 더 읽기 어려워요.","견문을 빼면 일기가 돼요.","동생이 멈출 곳을 풀어 줘요."]}'::jsonb),
('g6_1_kor_u4_L08_basic#6','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C35',2,'match','auto','「소방서를 다녀와서」에 쓸 내용과 들어갈 자리를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u4-C35","difficulty":2,"kind":"match","stem":"「소방서를 다녀와서」에 쓸 내용과 들어갈 자리를 알맞게 이으세요.","pairs":[{"l":"소방관이 하는 일을 알아보려고 반 친구들과 소방서에 갔다","r":"처음"},{"l":"방화복을 들어 보니 생각보다 훨씬 무거웠다","r":"가운데"},{"l":"소방관의 하루가 어떤 하루인지 알게 되었다","r":"끝"}],"mis":"K6-1-u4-X28","explanation":["까닭과 함께 간 사람은 처음이에요.","본 것과 느낀 것은 가운데예요.","정리와 깨달음은 끝이에요."]}'::jsonb),
('g6_1_kor_u4_L08_basic#7','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C35',2,'mc','auto','조직표의 가운데를 짤 때 알맞은 요령은 어느 것인가요?',ARRAY['K6-1-u4-X35','K6-1-u4-X30','K6-1-u4-X07']::text[],false,'{"seq":7,"concept":"K6-1-u4-C35","difficulty":2,"kind":"mc","stem":"조직표의 가운데를 짤 때 알맞은 요령은 어느 것인가요?","options":[{"t":"본 것 하나에 느낀 것 하나를 짝지어 간다","correct":true},{"t":"본 것만 모두 늘어놓고 느낌은 끝에 몰아 쓴다","mis":"K6-1-u4-X35"},{"t":"느낀 것만 적는다","mis":"K6-1-u4-X30"},{"t":"문단마다 관용 표현을 하나씩 넣는다","mis":"K6-1-u4-X07"}],"explanation":["사실만 늘어놓은 글이 돼요.","느낌만 있으면 일기가 돼요.","본 것과 느낀 것을 짝지어요."],"asset":{"type":"passage","lines":["처음 — 까닭(소방관이 하는 일 알아보기) · 반 친구들과 · 우리 고장 소방서","가운데 첫째 — 차고의 소방차 / 소화전에 호스를 잇는다는 것을 앎","　→ 소방차 한 대로 다 되는 줄 알았던 생각이 바뀜","가운데 둘째 — 방화복을 들어 봄 / 무게가 상당함 → 입고 뛴다는 말에 놀람","가운데 셋째 — 신고 받는 곳 / 위치부터 말해야 함 → 나도 그래야겠다고 생각함","끝 — 소방관의 하루는 기다림과 준비로 채워짐 → 길을 비켜 주겠다는 다짐"],"title":"「소방서를 다녀와서」 조직표"}}'::jsonb),
('g6_1_kor_u4_L08_basic#8','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C36',2,'mc','auto','관용 표현을 알맞은 자리에 놓은 문장은 어느 것인가요?',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":8,"concept":"K6-1-u4-C36","difficulty":2,"kind":"mc","stem":"관용 표현을 알맞은 자리에 놓은 문장은 어느 것인가요?","options":[{"t":"「이것을 입고 뛴다니 손이 열 개라도 모자라겠다.」","correct":true},{"t":"「소화전에 호스를 잇는데 손이 열 개라도 모자란다.」","mis":"K6-1-u4-X36"},{"t":"「신고할 때 위치를 먼저 말하는 것은 눈코 뜰 새 없다.」","mis":"K6-1-u4-X36"},{"t":"「물탱크의 물은 진땀을 빼며 금방 바닥난다.」","mis":"K6-1-u4-X36"}],"explanation":["사실 자리에 얹었어요.","이것도 사실 자리예요.","놀란 마음 자리에 놓였어요."],"asset":{"type":"passage","lines":["먼저 차고에서 소방차를 보았다. 나는 소방차에 실린 물만으로","불을 끄는 줄 알았는데, 물탱크의 물은 금방 바닥나기 때문에","길가의 소화전에 호스를 이어 물을 끌어 쓴다고 한다.","다음으로 방화복을 들어 보았다. 한 손으로는 들리지 않을 만큼 무거웠다.","이것을 다 입고 계단을 뛰어오른다는 말에","손이 열 개라도 모자라겠다는 생각이 들었다."],"title":"「소방서를 다녀와서」 — 가운데 부분"}}'::jsonb),
('g6_1_kor_u4_L08_basic#9','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C38',2,'mc','auto','견학 기록문을 고쳐 쓸 때 살펴볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X07']::text[],false,'{"seq":9,"concept":"K6-1-u4-C38","difficulty":2,"kind":"mc","stem":"견학 기록문을 고쳐 쓸 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"여정 · 견문 · 감상이 전해지는가","correct":true},{"t":"글씨를 예쁘게 썼는가","mis":"K6-1-u4-X38"},{"t":"다른 사람 글보다 긴가","mis":"K6-1-u4-X38"},{"t":"관용 표현을 많이 넣었는가","mis":"K6-1-u4-X07"}],"explanation":["글씨 모양은 갈래를 정하지 않아요.","길이도 아니에요.","갈래가 갖출 것을 살펴요."]}'::jsonb),
('g6_1_kor_u4_L08_basic#10','kor',6,1,'u4','L08','g6_1_kor_u4_L08_basic','lesson_basic','K6-1-u4-C37',3,'mc','auto','「관용 표현을 세 개 넣으랬으니 문단마다 하나씩 넣자.」라는 생각에 대해 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u4-X37','K6-1-u4-X07','K6-1-u4-X09']::text[],false,'{"seq":10,"concept":"K6-1-u4-C37","difficulty":3,"kind":"mc","stem":"「관용 표현을 세 개 넣으랬으니 문단마다 하나씩 넣자.」라는 생각에 대해 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"마음이 없는 자리에 얹힌 표현은 겉도니, 가장 크게 마음이 움직인 자리에 하나만 놓아도 된다","correct":true},{"t":"세 개를 다 채워야 좋은 글이 된다","mis":"K6-1-u4-X37"},{"t":"더 많이 넣을수록 좋은 글이 된다","mis":"K6-1-u4-X07"},{"t":"관용 표현은 하나도 쓰면 안 된다","mis":"K6-1-u4-X09"}],"explanation":["칸을 채우는 글이 아니에요.","개수가 문제가 아니에요.","제자리에 하나면 충분해요."]}'::jsonb),
('g6_1_kor_u4_L08_challenge#1','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C35',2,'mc','auto','생각그물로 견학 기록문의 재료를 모을 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u4-X35','K6-1-u4-X29','K6-1-u4-X30']::text[],false,'{"seq":1,"concept":"K6-1-u4-C35","difficulty":2,"kind":"mc","stem":"생각그물로 견학 기록문의 재료를 모을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"순서는 신경 쓰지 않고 다섯 갈래로 떠오르는 대로 모은다","correct":true},{"t":"처음부터 처음 · 가운데 · 끝 차례대로만 적는다","mis":"K6-1-u4-X35"},{"t":"견문 갈래만 가득 채운다","mis":"K6-1-u4-X29"},{"t":"감상 갈래만 가득 채운다","mis":"K6-1-u4-X30"}],"explanation":["순서는 조직표에서 잡아요.","견문만 모으면 감상이 없어요.","다섯 갈래를 고루 모아요."]}'::jsonb),
('g6_1_kor_u4_L08_challenge#2','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C37',2,'ox','auto','견학 기록문에서 담을 것이 없는 자리는 비워 두어도 돼요.',ARRAY['K6-1-u4-X37']::text[],false,'{"seq":2,"concept":"K6-1-u4-C37","difficulty":2,"kind":"ox","stem":"견학 기록문에서 담을 것이 없는 자리는 비워 두어도 돼요.","answer":"O","reason_options":[{"t":"가장 중요한 것은 진솔함이고 칸은 채울 것이 아니라 담을 그릇이기 때문에","correct":true},{"t":"정해진 칸을 다 채워야 견학 기록문이 되기 때문에","mis":"K6-1-u4-X37"}],"mis":"K6-1-u4-X37","explanation":["억지로 채우면 겉돌아요.","진솔함이 가장 중요해요.","담을 것이 없으면 비워도 돼요."]}'::jsonb),
('g6_1_kor_u4_L08_challenge#3','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C33',3,'mc','auto','쓸 견학을 고를 때 「기억에 남은 까닭」을 적어 두는 것이 중요한 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X28','K6-1-u4-X33']::text[],false,'{"seq":3,"concept":"K6-1-u4-C33","difficulty":3,"kind":"mc","stem":"쓸 견학을 고를 때 「기억에 남은 까닭」을 적어 두는 것이 중요한 까닭은 어느 것인가요?","options":[{"t":"그 까닭이 곧 글의 감상이 되기 때문에","correct":true},{"t":"까닭이 길수록 글이 길어지기 때문에","mis":"K6-1-u4-X38"},{"t":"처음 부분에는 까닭만 쓰면 되기 때문에","mis":"K6-1-u4-X28"},{"t":"읽을 사람이 까닭을 외워야 하기 때문에","mis":"K6-1-u4-X33"}],"explanation":["길이를 늘리려는 것이 아니에요.","처음에는 까닭 말고도 써요.","까닭이 감상으로 이어져요."]}'::jsonb),
('g6_1_kor_u4_L08_challenge#4','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C36',3,'error','auto','「소방서를 다녀와서」에 관용 표현을 넣어 보았어요. 알맞지 않게 넣은 친구는 누구인가요?',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":4,"concept":"K6-1-u4-C36","difficulty":3,"kind":"error","stem":"「소방서를 다녀와서」에 관용 표현을 넣어 보았어요. 알맞지 않게 넣은 친구는 누구인가요?","options":[{"t":"은호 — 「물탱크의 물은 발등에 불이 떨어지게 금방 바닥난다.」","correct":true,"mis_target":"K6-1-u4-X36"},{"t":"서진 — 「돌아오는 길에 마주친 소방차가 오래도록 눈에 선했다.」","mis":"K6-1-u4-X36"},{"t":"나윤 — 「이것을 입고 뛴다니 손이 열 개라도 모자라겠다는 생각이 들었다.」","mis":"K6-1-u4-X36"}],"explanation":["서진이는 마음 자리에 놓았어요.","나윤이도 마음 자리에 놓았어요.","사실 자리에 얹으면 흐려져요."]}'::jsonb),
('g6_1_kor_u4_L08_challenge#5','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C38',3,'mc','auto','읽을 사람이 가족이라면 견학 기록문을 어떻게 나누면 좋을까요?',ARRAY['K6-1-u4-X39']::text[],false,'{"seq":5,"concept":"K6-1-u4-C38","difficulty":3,"kind":"mc","stem":"읽을 사람이 가족이라면 견학 기록문을 어떻게 나누면 좋을까요?","options":[{"t":"가족이 함께 보는 곳에 붙이거나 가족에게 직접 읽어 준다","correct":true},{"t":"공책에 써서 서랍에 넣어 둔다","mis":"K6-1-u4-X39"},{"t":"가장 많이 인쇄해 여러 곳에 붙인다","mis":"K6-1-u4-X39"},{"t":"가족이 보지 않는 반 게시판에만 올린다","mis":"K6-1-u4-X39"}],"explanation":["서랍 속 글은 읽을 수 없어요.","많이 붙인다고 읽는 것이 아니에요.","읽을 사람이 정말 읽을 수 있는 방법이에요."]}'::jsonb),
('g6_1_kor_u4_L08_challenge#6','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C35',3,'mc','auto','조직표의 「소방차 한 대로 다 되는 줄 알았던 생각이 바뀜」은 무엇인가요?',ARRAY['K6-1-u4-X27','K6-1-u4-X28']::text[],false,'{"seq":6,"concept":"K6-1-u4-C35","difficulty":3,"kind":"mc","stem":"조직표의 「소방차 한 대로 다 되는 줄 알았던 생각이 바뀜」은 무엇인가요?","options":[{"t":"견문에 짝지은 감상","correct":true},{"t":"여정","mis":"K6-1-u4-X27"},{"t":"처음 부분의 견학한 까닭","mis":"K6-1-u4-X28"},{"t":"끝 부분의 정리","mis":"K6-1-u4-X28"}],"explanation":["다닌 길이 아니에요.","견학한 까닭도 아니에요.","새로 안 사실 뒤에 붙인 마음이에요."],"asset":{"type":"passage","lines":["처음 — 까닭(소방관이 하는 일 알아보기) · 반 친구들과 · 우리 고장 소방서","가운데 첫째 — 차고의 소방차 / 소화전에 호스를 잇는다는 것을 앎","　→ 소방차 한 대로 다 되는 줄 알았던 생각이 바뀜","가운데 둘째 — 방화복을 들어 봄 / 무게가 상당함 → 입고 뛴다는 말에 놀람","가운데 셋째 — 신고 받는 곳 / 위치부터 말해야 함 → 나도 그래야겠다고 생각함","끝 — 소방관의 하루는 기다림과 준비로 채워짐 → 길을 비켜 주겠다는 다짐"],"title":"「소방서를 다녀와서」 조직표"}}'::jsonb),
('g6_1_kor_u4_L08_challenge#7','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C32',3,'mc','auto','견학 기록문이 읽는 사람에게 주는 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X32']::text[],false,'{"seq":7,"concept":"K6-1-u4-C32","difficulty":3,"kind":"mc","stem":"견학 기록문이 읽는 사람에게 주는 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"가 보지 못한 사람에게 그곳을 알리고, 가려는 사람이 무엇을 볼지 미리 알게 한다","correct":true},{"t":"읽는 사람의 글씨가 좋아진다","mis":"K6-1-u4-X32"},{"t":"쓴 사람이 외운 낱말 수가 늘어난다","mis":"K6-1-u4-X32"},{"t":"읽는 사람은 견학을 갈 필요가 없어진다","mis":"K6-1-u4-X32"}],"explanation":["글씨와는 상관없어요.","낱말 수도 아니에요.","그곳의 모습이 읽는 사람에게 건너가요."]}'::jsonb),
('g6_1_kor_u4_L08_challenge#8','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C34',4,'mc','auto','이 부분을 저학년 동생에게 읽어 줄 글로 고친다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X07','K6-1-u4-X34']::text[],false,'{"seq":8,"concept":"K6-1-u4-C34","difficulty":4,"kind":"mc","stem":"이 부분을 저학년 동생에게 읽어 줄 글로 고친다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「물탱크」 「소화전」 「방화복」을 동생이 알 수 있게 풀어 쓰고 한 줄씩 더 설명한다","correct":true},{"t":"새로 안 사실을 빼고 느낌만 남긴다","mis":"K6-1-u4-X30"},{"t":"관용 표현을 더 넣어 재미있게 만든다","mis":"K6-1-u4-X07"},{"t":"누가 읽든 같으니 그대로 둔다","mis":"K6-1-u4-X34"}],"explanation":["견문을 빼면 안 돼요.","관용 표현 개수가 문제가 아니에요.","읽을 사람에 맞게 풀어 줘요."],"asset":{"type":"passage","lines":["먼저 차고에서 소방차를 보았다. 나는 소방차에 실린 물만으로","불을 끄는 줄 알았는데, 물탱크의 물은 금방 바닥나기 때문에","길가의 소화전에 호스를 이어 물을 끌어 쓴다고 한다.","다음으로 방화복을 들어 보았다. 한 손으로는 들리지 않을 만큼 무거웠다.","이것을 다 입고 계단을 뛰어오른다는 말에","손이 열 개라도 모자라겠다는 생각이 들었다."],"title":"「소방서를 다녀와서」 — 가운데 부분"}}'::jsonb),
('g6_1_kor_u4_L08_challenge#9','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C35',4,'essay','teacher','내가 다녀온 견학 하나로 조직표를 짜 보세요. 처음 · 가운데 둘 · 끝으로 나누고, 가운데에는 본 것 하나에 느낀 것 하나를 짝지으세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C35","difficulty":4,"kind":"essay","stem":"내가 다녀온 견학 하나로 조직표를 짜 보세요. 처음 · 가운데 둘 · 끝으로 나누고, 가운데에는 본 것 하나에 느낀 것 하나를 짝지으세요.","answer_guide":{"answer":"예: 처음 — 별을 가까이 보고 싶어서 가족과 고장의 천문대에 갔다. 가운데 첫째 — 망원경 방에서 달을 보았다 / 달 표면에 크고 작은 구덩이가 많았다 → 매끈할 줄 알았는데 놀랐다. 가운데 둘째 — 별자리 방에서 설명을 들었다 / 별은 스스로 빛을 낸다 → 밤하늘이 다르게 보였다. 끝 — 하늘에 대해 새로 안 것이 많았다 → 다음에는 별자리 지도를 들고 밤하늘을 보겠다.","scoring_points":["처음에 까닭 · 함께 간 사람 · 장소를 썼는가","가운데마다 본 것과 느낀 것을 짝지었는가","끝에 정리와 깨달은 점을 썼는가"]},"explanation":["처음에 개요를 써요.","가운데는 본 것과 느낀 것을 짝지어요.","끝에 정리해요."]}'::jsonb),
('g6_1_kor_u4_L08_challenge#10','kor',6,1,'u4','L08','g6_1_kor_u4_L08_challenge','lesson_challenge','K6-1-u4-C37',4,'essay','teacher','「여정 · 견문 · 감상도, 관용 표현도 채워야 할 칸이 아니라 담을 그릇이다」라는 말을 설명하고, 관용 표현을 어디에 몇 개 놓을지 내 생각을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C37","difficulty":4,"kind":"essay","stem":"「여정 · 견문 · 감상도, 관용 표현도 채워야 할 칸이 아니라 담을 그릇이다」라는 말을 설명하고, 관용 표현을 어디에 몇 개 놓을지 내 생각을 쓰세요.","answer_guide":{"answer":"예: 견학 기록문에서 가장 중요한 것은 진솔함이라, 마음이 없는 자리에 억지로 표현을 채우면 글이 겉돈다. 그래서 담을 것이 있을 때 담고, 없으면 비워 두어도 된다. 나는 관용 표현을 문단마다 넣지 않고, 가장 크게 놀라거나 마음이 움직인 감상 자리에 하나만 놓겠다.","scoring_points":["칸 채우기가 아니라는 뜻을 설명했는가","진솔함이 중요하다는 점을 썼는가","관용 표현을 놓을 자리와 개수를 내 생각으로 썼는가"]},"explanation":["칸과 그릇을 견줘요.","진솔함을 떠올려요.","자리와 개수를 정해요."]}'::jsonb),
('g6_1_kor_u4_L11_basic#1','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C39',1,'mc','auto','다음 가운데 동물이 들어간 관용 표현은 어느 것인가요?',ARRAY['K6-1-u4-X03']::text[],false,'{"seq":1,"concept":"K6-1-u4-C39","difficulty":1,"kind":"mc","stem":"다음 가운데 동물이 들어간 관용 표현은 어느 것인가요?","options":[{"t":"원숭이도 나무에서 떨어진다","correct":true},{"t":"강아지에게 물을 주었다","mis":"K6-1-u4-X03"},{"t":"새가 나뭇가지에 앉았다","mis":"K6-1-u4-X03"},{"t":"고양이가 낮잠을 잤다","mis":"K6-1-u4-X03"}],"explanation":["강아지 이야기가 뜻 그대로예요.","새 이야기도 뜻 그대로예요.","잘하는 사람도 실수한다는 새 뜻이에요."]}'::jsonb),
('g6_1_kor_u4_L11_basic#2','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C40',1,'mc','auto','관용 표현 사전 한 장에 담을 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X41']::text[],false,'{"seq":2,"concept":"K6-1-u4-C40","difficulty":1,"kind":"mc","stem":"관용 표현 사전 한 장에 담을 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"표현 · 뜻 · 쓸 수 있는 상황","correct":true},{"t":"표현이 만들어진 정확한 때","mis":"K6-1-u4-X41"},{"t":"그 표현을 아는 친구의 수","mis":"K6-1-u4-X41"},{"t":"그 표현을 쓴 횟수","mis":"K6-1-u4-X41"}],"explanation":["만들어진 때는 꺼내 쓰는 데 쓸모없어요.","친구 수도 마찬가지예요.","세 칸이 있어야 꺼내 쓸 수 있어요."]}'::jsonb),
('g6_1_kor_u4_L11_basic#3','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C42',1,'mc','auto','학급 전체 앞에서 발표할 때 지킬 예절로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X42','K6-1-u4-X43']::text[],false,'{"seq":3,"concept":"K6-1-u4-C42","difficulty":1,"kind":"mc","stem":"학급 전체 앞에서 발표할 때 지킬 예절로 알맞은 것은 어느 것인가요?","options":[{"t":"존댓말로, 모두 들을 수 있는 크기로 말한다","correct":true},{"t":"둘레에 들리지 않게 작은 소리로 말한다","mis":"K6-1-u4-X42"},{"t":"생각날 때마다 끼어들어 말한다","mis":"K6-1-u4-X43"},{"t":"친구와 쉬는 시간에 하듯 반말로 말한다","mis":"K6-1-u4-X42"}],"explanation":["작은 소리는 짝과 이야기할 때예요.","끼어들면 안 돼요.","여럿이 듣는 자리에 맞게 말해요."]}'::jsonb),
('g6_1_kor_u4_L11_basic#4','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C41',1,'ox','auto','관용 표현 사전에는 아무도 모르는 어려운 표현을 많이 모을수록 좋아요.',ARRAY['K6-1-u4-X40']::text[],false,'{"seq":4,"concept":"K6-1-u4-C41","difficulty":1,"kind":"ox","stem":"관용 표현 사전에는 아무도 모르는 어려운 표현을 많이 모을수록 좋아요.","answer":"X","reason_options":[{"t":"개수도 어려움도 아닌 내가 쓸 자리가 떠오르는 표현을 골라야 하기 때문에","correct":true},{"t":"어려운 표현이 많아야 좋은 사전이기 때문에","mis":"K6-1-u4-X40"}],"mis":"K6-1-u4-X40","explanation":["만든 나조차 안 쓰는 사전이 돼요.","개수가 기준이 아니에요.","쓸 자리가 떠오르는 표현을 골라요."]}'::jsonb),
('g6_1_kor_u4_L11_basic#5','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C39',2,'match','auto','몸을 가리키는 말이 든 표현과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u4-C39","difficulty":2,"kind":"match","stem":"몸을 가리키는 말이 든 표현과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"어깨너머로 배우다","r":"옆에서 보고 들으며 배우다"},{"l":"목에 힘을 주다","r":"잘난 체하며 거만하게 굴다"},{"l":"등을 떠밀다","r":"하기 싫어하는 사람을 억지로 나서게 하다"}],"mis":"K6-1-u4-X12","explanation":["어깨 위로 넘어다보는 장면이에요.","목을 꼿꼿이 세운 장면이에요.","등을 밀어 내보내는 장면이에요."]}'::jsonb),
('g6_1_kor_u4_L11_basic#6','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C39',2,'mc','auto','「고양이 목에 방울 달기」를 쓰기에 알맞은 상황은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X01']::text[],false,'{"seq":6,"concept":"K6-1-u4-C39","difficulty":2,"kind":"mc","stem":"「고양이 목에 방울 달기」를 쓰기에 알맞은 상황은 어느 것인가요?","options":[{"t":"학급 회의에서 모두 좋다고 했지만 맡겠다고 나서는 사람이 없을 때","correct":true},{"t":"늘 잘하던 친구가 한 번 틀렸을 때","mis":"K6-1-u4-X08"},{"t":"옆에서 지켜보다 어느새 할 줄 알게 되었을 때","mis":"K6-1-u4-X08"},{"t":"고양이에게 목걸이를 사 줄 때","mis":"K6-1-u4-X01"}],"explanation":["실수 이야기는 원숭이 속담이에요.","보고 익힌 것은 서당 개 속담이에요.","말은 좋은데 해내기 어려운 일이에요."]}'::jsonb),
('g6_1_kor_u4_L11_basic#7','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C39',2,'mc','auto','관용 표현을 낱말로 묶을 때와 마음으로 묶을 때를 알맞게 견준 것은 어느 것인가요?',ARRAY['K6-1-u4-X44']::text[],false,'{"seq":7,"concept":"K6-1-u4-C39","difficulty":2,"kind":"mc","stem":"관용 표현을 낱말로 묶을 때와 마음으로 묶을 때를 알맞게 견준 것은 어느 것인가요?","options":[{"t":"낱말로 묶으면 찾기가 쉽고, 마음으로 묶으면 쓰기가 쉽다","correct":true},{"t":"낱말로 묶으면 쓰기가 쉽고, 마음으로 묶으면 찾기가 쉽다","mis":"K6-1-u4-X44"},{"t":"둘 다 쓸모가 없으니 흩어 두는 게 낫다","mis":"K6-1-u4-X44"},{"t":"둘은 똑같아서 어느 쪽이든 차이가 없다","mis":"K6-1-u4-X44"}],"explanation":["두 말이 뒤바뀌었어요.","묶어 두면 빨리 떠올라요.","둘은 좋은 점이 달라요."]}'::jsonb),
('g6_1_kor_u4_L11_basic#8','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C28',2,'mc','auto','「도서관 서고를 다녀와서」 앞부분에서 여정에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":8,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"「도서관 서고를 다녀와서」 앞부분에서 여정에 해당하는 것은 어느 것인가요?","options":[{"t":"「사서 선생님을 따라 처음 일반 서고에 들어갔다.」","correct":true},{"t":"「책의 주제에 따라 숫자를 정해 꽂는다.」","mis":"K6-1-u4-X27"},{"t":"「내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다.」","mis":"K6-1-u4-X27"},{"t":"「모든 책에는 숫자가 붙어 있었다.」","mis":"K6-1-u4-X27"}],"explanation":["숫자로 꽂는 것은 새로 안 사실이에요.","깨달은 마음은 감상이에요.","어디로 들어갔는지가 여정이에요."],"asset":{"type":"passage","lines":["지난 화요일, 우리 반은 고장의 도서관에 갔다.","사서 선생님을 따라 처음 들어간 곳은 일반 서고였다.","모든 책에는 숫자가 붙어 있었다. 책의 주제에 따라 숫자를 정해 두고","그 차례대로 꽂는다고 한다. 내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다."],"title":"「도서관 서고를 다녀와서」 — 앞부분"}}'::jsonb),
('g6_1_kor_u4_L11_basic#9','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C42',2,'mc','auto','쉬는 시간에 친구와 이야기할 때 지킬 예절로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X42','K6-1-u4-X43']::text[],false,'{"seq":9,"concept":"K6-1-u4-C42","difficulty":2,"kind":"mc","stem":"쉬는 시간에 친구와 이야기할 때 지킬 예절로 알맞은 것은 어느 것인가요?","options":[{"t":"둘레에 방해가 되지 않게 작은 소리로, 말차례를 지키며 반응을 보인다","correct":true},{"t":"발표할 때처럼 모두 들리게 큰 소리로 말한다","mis":"K6-1-u4-X42"},{"t":"친구 말이 끝나기 전에 끼어든다","mis":"K6-1-u4-X43"},{"t":"고개를 돌리고 대꾸하지 않는다","mis":"K6-1-u4-X43"}],"explanation":["큰 소리는 둘레에 방해가 돼요.","말차례를 지켜요.","고개를 끄덕이며 반응해요."]}'::jsonb),
('g6_1_kor_u4_L11_basic#10','kor',6,1,'u4','L11','g6_1_kor_u4_L11_basic','lesson_basic','K6-1-u4-C42',3,'mc','auto','상황에 따라 언어 예절을 정하는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X43']::text[],false,'{"seq":10,"concept":"K6-1-u4-C42","difficulty":3,"kind":"mc","stem":"상황에 따라 언어 예절을 정하는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람이 편하게 들을 수 있는가","correct":true},{"t":"외운 예절 목록에 있는가","mis":"K6-1-u4-X43"},{"t":"내가 편하게 말할 수 있는가","mis":"K6-1-u4-X43"},{"t":"목소리가 충분히 큰가","mis":"K6-1-u4-X43"}],"explanation":["목록에 없는 상황도 있어요.","말하는 사람이 기준이 아니에요.","듣는 사람을 두고 정해요."]}'::jsonb),
('g6_1_kor_u4_L11_challenge#1','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C9',2,'mc','auto','「손때가 묻은 책」의 「손때가 묻다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X12']::text[],false,'{"seq":1,"concept":"K6-1-u4-C9","difficulty":2,"kind":"mc","stem":"「손때가 묻은 책」의 「손때가 묻다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"오래 쓰고 매만져 정이 들다","correct":true},{"t":"손을 씻지 않아 책이 더러워졌다","mis":"K6-1-u4-X01"},{"t":"새로 사서 아주 깨끗하다","mis":"K6-1-u4-X01"},{"t":"손으로 만지면 안 되는 책이다","mis":"K6-1-u4-X12"}],"explanation":["더러워진 이야기가 아니에요.","새 책과 반대예요.","오래 아껴 써 온 마음이에요."],"asset":{"type":"passage","lines":["다음으로 간 보존 서고는 공기가 서늘했다.","종이는 습기와 더위에 약해서 온도와 습도를 늘 일정하게 지킨다고 했다.","오래된 책은 따로 두고, 넘길 때에도 두 손으로 조심해 다룬다고 한다.","표지가 닳고 손때가 묻은 책들이 나란히 서 있는 모습을 한참 바라보았다.","이번 견학으로 도서관이 책을 지키는 곳이라는 것을 알게 되었다."],"title":"「도서관 서고를 다녀와서」 — 뒷부분"}}'::jsonb),
('g6_1_kor_u4_L11_challenge#2','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C40',2,'ox','auto','관용 표현 사전의 쓸 상황은 내가 겪은 일이나 겪을 법한 일로 적어요.',ARRAY['K6-1-u4-X11']::text[],false,'{"seq":2,"concept":"K6-1-u4-C40","difficulty":2,"kind":"ox","stem":"관용 표현 사전의 쓸 상황은 내가 겪은 일이나 겪을 법한 일로 적어요.","answer":"O","reason_options":[{"t":"내 상황이 적힌 사전이라야 필요할 때 떠오르기 때문에","correct":true},{"t":"쓸 상황은 사전에 적힌 예문을 그대로 옮겨야 하기 때문에","mis":"K6-1-u4-X11"}],"mis":"K6-1-u4-X11","explanation":["뜻만 적으면 한 번 보고 덮어요.","내 상황이라야 떠올라요.","셋째 칸이 가장 중요해요."]}'::jsonb),
('g6_1_kor_u4_L11_challenge#3','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C9',3,'mc','auto','「내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다.」에 담긴 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X21']::text[],false,'{"seq":3,"concept":"K6-1-u4-C9","difficulty":3,"kind":"mc","stem":"「내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다.」에 담긴 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"헝클어져 있던 일의 갈피가 잡혀 까닭을 깨달았다","correct":true},{"t":"흩어진 실을 한 가닥으로 묶었다","mis":"K6-1-u4-X01"},{"t":"도서관에서 길을 잃고 헤맸다","mis":"K6-1-u4-X21"},{"t":"머리카락을 가지런히 묶었다","mis":"K6-1-u4-X01"}],"explanation":["실을 묶은 이야기가 아니에요.","길을 잃은 것도 아니에요.","왜 헤맸는지 깨달았어요."],"asset":{"type":"passage","lines":["지난 화요일, 우리 반은 고장의 도서관에 갔다.","사서 선생님을 따라 처음 들어간 곳은 일반 서고였다.","모든 책에는 숫자가 붙어 있었다. 책의 주제에 따라 숫자를 정해 두고","그 차례대로 꽂는다고 한다. 내가 늘 헤매던 까닭이 그제야 가닥이 잡혔다."],"title":"「도서관 서고를 다녀와서」 — 앞부분"}}'::jsonb),
('g6_1_kor_u4_L11_challenge#4','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C42',3,'error','auto','친구의 발표를 듣는 모습이에요. 예절에 알맞지 않은 친구는 누구인가요?',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":4,"concept":"K6-1-u4-C42","difficulty":3,"kind":"error","stem":"친구의 발표를 듣는 모습이에요. 예절에 알맞지 않은 친구는 누구인가요?","options":[{"t":"하린 — 발표하는 친구 쪽을 보지 않고 짝과 작은 소리로 이야기했다","correct":true,"mis_target":"K6-1-u4-X42"},{"t":"시안 — 바른 자세로 발표하는 친구를 보며 끝까지 들었다","mis":"K6-1-u4-X42"},{"t":"연우 — 발표가 끝난 뒤 존댓말로 궁금한 것을 물었다","mis":"K6-1-u4-X42"}],"explanation":["시안이는 끝까지 경청했어요.","연우는 끝난 뒤 존댓말로 물었어요.","발표 중에는 짝과 이야기하지 않아요."]}'::jsonb),
('g6_1_kor_u4_L11_challenge#5','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C41',3,'mc','auto','관용 표현 사전에 넣을 표현을 고르는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X40']::text[],false,'{"seq":5,"concept":"K6-1-u4-C41","difficulty":3,"kind":"mc","stem":"관용 표현 사전에 넣을 표현을 고르는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이번 달에 한 번은 쓸 자리가 떠오르는 표현 다섯 개를 고른다","correct":true},{"t":"아무도 모르는 어려운 표현을 스무 개 고른다","mis":"K6-1-u4-X40"},{"t":"가장 긴 표현부터 고른다","mis":"K6-1-u4-X40"},{"t":"사전 앞쪽에 나오는 표현을 차례대로 고른다","mis":"K6-1-u4-X40"}],"explanation":["어려운 표현은 쓰지 않게 돼요.","길이는 기준이 아니에요.","쓸 자리가 떠오르는지가 기준이에요."]}'::jsonb),
('g6_1_kor_u4_L11_challenge#6','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C39',3,'mc','auto','「서당 개 삼 년이면 풍월을 읊는다」를 쓰기에 알맞은 상황은 어느 것인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X01']::text[],false,'{"seq":6,"concept":"K6-1-u4-C39","difficulty":3,"kind":"mc","stem":"「서당 개 삼 년이면 풍월을 읊는다」를 쓰기에 알맞은 상황은 어느 것인가요?","options":[{"t":"옆에서 지켜보기만 했는데 어느새 할 줄 알게 되었을 때","correct":true},{"t":"늘 잘하던 친구가 한 번 실수했을 때","mis":"K6-1-u4-X08"},{"t":"모두 찬성했지만 아무도 나서지 않는 일을 두고","mis":"K6-1-u4-X08"},{"t":"강아지를 오래 길렀을 때","mis":"K6-1-u4-X01"}],"explanation":["실수는 원숭이 속담이에요.","나서지 않는 일은 방울 달기예요.","오래 보고 들어 저절로 익혔어요."]}'::jsonb),
('g6_1_kor_u4_L11_challenge#7','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C42',3,'mc','auto','공식적인 말하기에서 목소리 크기 · 표정 · 자세까지 살피는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X43','K6-1-u4-X42']::text[],false,'{"seq":7,"concept":"K6-1-u4-C42","difficulty":3,"kind":"mc","stem":"공식적인 말하기에서 목소리 크기 · 표정 · 자세까지 살피는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"말의 내용뿐 아니라 이것들도 듣는 사람이 편하게 듣는 데 영향을 주기 때문에","correct":true},{"t":"외워야 할 예절 목록에 적혀 있기 때문에","mis":"K6-1-u4-X43"},{"t":"말의 내용은 중요하지 않기 때문에","mis":"K6-1-u4-X43"},{"t":"비공식적인 자리와 예절이 같기 때문에","mis":"K6-1-u4-X42"}],"explanation":["목록이라서가 아니에요.","내용도 중요해요.","듣는 사람이 편한지가 기준이에요."]}'::jsonb),
('g6_1_kor_u4_L11_challenge#8','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C40',4,'mc','auto','누리가 만든 사전 한 장을 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u4-X41','K6-1-u4-X11','K6-1-u4-X40']::text[],false,'{"seq":8,"concept":"K6-1-u4-C40","difficulty":4,"kind":"mc","stem":"누리가 만든 사전 한 장을 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"뜻은 「여러 번 들어 익숙하다」처럼 내 말로 줄이고, 쓸 상황에 내가 겪은 일을 적고, 친구 수는 뺀다","correct":true},{"t":"아는 친구의 수를 더 정확히 세어 적는다","mis":"K6-1-u4-X41"},{"t":"사전 뜻풀이를 더 길게 옮겨 적는다","mis":"K6-1-u4-X11"},{"t":"다른 표현을 세 개 더 채워 넣는다","mis":"K6-1-u4-X40"}],"explanation":["친구 수는 쓸모가 없어요.","길게 옮기면 내 말이 아니에요.","세 칸을 제대로 채워요."],"asset":{"type":"passage","lines":["표현 — 귀에 익다","뜻 — (사전 뜻풀이를 한 글자도 빼지 않고 길게 옮겨 적음)","쓸 수 있는 상황 — (비어 있음)","덧붙임 — 이 표현을 아는 우리 반 친구의 수"],"title":"누리가 만든 관용 표현 사전 한 장"}}'::jsonb),
('g6_1_kor_u4_L11_challenge#9','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C39',4,'essay','teacher','관용 표현 사전의 주제를 하나 정하고(낱말로 묶기 또는 마음으로 묶기), 그 주제에 맞는 표현 두 개를 골라 표현 · 뜻 · 쓸 수 있는 상황을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u4-C39","difficulty":4,"kind":"essay","stem":"관용 표현 사전의 주제를 하나 정하고(낱말로 묶기 또는 마음으로 묶기), 그 주제에 맞는 표현 두 개를 골라 표현 · 뜻 · 쓸 수 있는 상황을 쓰세요.","answer_guide":{"answer":"예: 주제 — 마음으로 묶기, 「간절함」. 표현 하나 — 목이 빠지게 기다리다 / 몹시 애타게 기다리다 / 방학에 할머니 댁에 갈 날을 기다릴 때. 표현 둘 — 마음이 굴뚝같다 / 무엇을 몹시 하고 싶어 하다 / 감기로 축구 시합에 못 나갔지만 뛰고 싶을 때.","scoring_points":["묶는 방법과 주제를 정했는가","주제에 맞는 표현 두 개를 골랐는가","표현마다 뜻과 내 쓸 상황을 썼는가"]},"explanation":["묶는 방법을 정해요.","주제에 맞는 표현을 골라요.","세 칸을 채워요."]}'::jsonb),
('g6_1_kor_u4_L11_challenge#10','kor',6,1,'u4','L11','g6_1_kor_u4_L11_challenge','lesson_challenge','K6-1-u4-C42',4,'essay','teacher','쉬는 시간에 친구와 이야기할 때와 학급 전체 앞에서 발표할 때 지킬 예절이 어떻게 다른지 쓰고, 왜 달라지는지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u4-C42","difficulty":4,"kind":"essay","stem":"쉬는 시간에 친구와 이야기할 때와 학급 전체 앞에서 발표할 때 지킬 예절이 어떻게 다른지 쓰고, 왜 달라지는지 설명하세요.","answer_guide":{"answer":"예: 쉬는 시간에는 둘레에 방해가 되지 않게 작은 소리로 말하고, 말차례를 지키며 고개를 끄덕이는 등 반응을 보인다. 발표할 때에는 존댓말로, 모두 들을 수 있는 크기로, 바른 자세로 듣는 사람을 보며 말한다. 듣는 사람의 수와 자리가 달라 듣는 사람이 편하게 들을 수 있는 방법도 달라지기 때문이다.","scoring_points":["비공식적인 말하기의 예절을 썼는가","공식적인 말하기의 예절을 썼는가","듣는 사람을 기준으로 달라지는 까닭을 썼는가"]},"explanation":["쉬는 시간을 떠올려요.","발표하는 자리를 떠올려요.","듣는 사람을 두고 까닭을 써요."]}'::jsonb),
('g6_1_kor_u4_review_a#1','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C1',1,'mc','auto','오래 쓰이며 굳어져 낱말 뜻의 합과는 다른 새로운 뜻을 지닌 말을 무엇이라고 하나요?',ARRAY['K6-1-u4-X05']::text[],false,'{"seq":1,"concept":"K6-1-u4-C1","difficulty":1,"kind":"mc","stem":"오래 쓰이며 굳어져 낱말 뜻의 합과는 다른 새로운 뜻을 지닌 말을 무엇이라고 하나요?","options":[{"t":"관용 표현","correct":true},{"t":"줄임말","mis":"K6-1-u4-X05"},{"t":"흉내 내는 말","mis":"K6-1-u4-X05"},{"t":"높임말","mis":"K6-1-u4-X05"}],"explanation":["줄임말은 짧게 줄인 말이에요.","흉내 내는 말은 소리나 모양을 흉내 내요.","굳어져 새 뜻을 지닌 말이에요."]}'::jsonb),
('g6_1_kor_u4_review_a#2','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C3',1,'mc','auto','「진땀을 빼다」는 관용어와 속담 가운데 무엇인가요?',ARRAY['K6-1-u4-X04','K6-1-u4-X01']::text[],false,'{"seq":2,"concept":"K6-1-u4-C3","difficulty":1,"kind":"mc","stem":"「진땀을 빼다」는 관용어와 속담 가운데 무엇인가요?","options":[{"t":"관용어","correct":true},{"t":"속담","mis":"K6-1-u4-X04"},{"t":"관용 표현이 아니다","mis":"K6-1-u4-X01"},{"t":"표어","mis":"K6-1-u4-X04"}],"explanation":["교훈을 담은 말이 아니에요.","뜻 그대로가 아니에요.","낱말이 합쳐져 새 뜻을 이룬 관용어예요."]}'::jsonb),
('g6_1_kor_u4_review_a#3','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C9',1,'mc','auto','「진땀을 빼다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01']::text[],false,'{"seq":3,"concept":"K6-1-u4-C9","difficulty":1,"kind":"mc","stem":"「진땀을 빼다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"어려운 일을 겪으며 몹시 애를 쓰다","correct":true},{"t":"흐르는 땀을 수건으로 닦다","mis":"K6-1-u4-X01"},{"t":"땀이 전혀 나지 않다","mis":"K6-1-u4-X01"},{"t":"더워서 겉옷을 벗다","mis":"K6-1-u4-X01"}],"explanation":["땀 닦는 이야기가 아니에요.","땀이 안 나는 것도 아니에요.","몹시 애쓴다는 뜻이에요."]}'::jsonb),
