('g6_1_kor_u4_review_a#5','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C24',1,'mc','auto','관용 표현을 쓰기 전에 뜻과 함께 살필 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X40']::text[],false,'{"seq":5,"concept":"K6-1-u4-C24","difficulty":1,"kind":"mc","stem":"관용 표현을 쓰기 전에 뜻과 함께 살필 것은 어느 것인가요?","options":[{"t":"듣는 사람과 지금 이 자리","correct":true},{"t":"표현의 글자 수","mis":"K6-1-u4-X07"},{"t":"표현을 몇 개 넣는지","mis":"K6-1-u4-X07"},{"t":"표현이 얼마나 어려운지","mis":"K6-1-u4-X40"}],"explanation":["글자 수는 상관없어요.","개수도 상관없어요.","누구에게, 어떤 자리인지 봐요."]}'::jsonb),
('g6_1_kor_u4_review_a#6','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C27',1,'mc','auto','견학하고 새롭게 안 사실을 중심으로 보고 듣고 느낀 것을 쓴 글은 무엇인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X29','K6-1-u4-X26']::text[],false,'{"seq":6,"concept":"K6-1-u4-C27","difficulty":1,"kind":"mc","stem":"견학하고 새롭게 안 사실을 중심으로 보고 듣고 느낀 것을 쓴 글은 무엇인가요?","options":[{"t":"견학 기록문","correct":true},{"t":"일기","mis":"K6-1-u4-X30"},{"t":"안내문","mis":"K6-1-u4-X29"},{"t":"지어낸 이야기","mis":"K6-1-u4-X26"}],"explanation":["일기는 마음 중심이에요.","안내문은 사실만 있어요.","새로 안 사실과 마음이 함께 있어요."]}'::jsonb),
('g6_1_kor_u4_review_a#7','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C34',1,'mc','auto','견학 기록문을 쓰기 전에 정해 둘 세 가지는 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X07','K6-1-u4-X34']::text[],false,'{"seq":7,"concept":"K6-1-u4-C34","difficulty":1,"kind":"mc","stem":"견학 기록문을 쓰기 전에 정해 둘 세 가지는 어느 것인가요?","options":[{"t":"목적 · 주제 · 읽을 사람","correct":true},{"t":"글씨체 · 종이 · 펜","mis":"K6-1-u4-X38"},{"t":"길이 · 문단 수 · 관용 표현 개수","mis":"K6-1-u4-X07"},{"t":"제목 · 사진 · 날씨","mis":"K6-1-u4-X34"}],"explanation":["도구는 정할 것이 아니에요.","개수는 기준이 아니에요.","왜, 무엇을, 누구에게 쓸지 정해요."]}'::jsonb),
('g6_1_kor_u4_review_a#8','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C40',1,'mc','auto','관용 표현 사전 한 장에 쓸 상황을 적는 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X37','K6-1-u4-X41']::text[],false,'{"seq":8,"concept":"K6-1-u4-C40","difficulty":1,"kind":"mc","stem":"관용 표현 사전 한 장에 쓸 상황을 적는 까닭은 어느 것인가요?","options":[{"t":"필요할 때 떠올라 꺼내 쓸 수 있어서","correct":true},{"t":"쪽수를 채우려고","mis":"K6-1-u4-X37"},{"t":"표현이 생긴 때를 알리려고","mis":"K6-1-u4-X41"},{"t":"아는 친구 수를 세려고","mis":"K6-1-u4-X41"}],"explanation":["쪽수 채우기가 아니에요.","생긴 때는 쓸모없어요.","내 상황이 적혀야 떠올라요."]}'::jsonb),
('g6_1_kor_u4_review_a#9','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C9',2,'mc','auto','하늬가 말한 「코앞에 닥쳤는데」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X08','K6-1-u4-X12']::text[],false,'{"seq":9,"concept":"K6-1-u4-C9","difficulty":2,"kind":"mc","stem":"하늬가 말한 「코앞에 닥쳤는데」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"대회가 아주 가까이 다가왔다","correct":true},{"t":"코 바로 앞에 무엇이 놓였다","mis":"K6-1-u4-X01"},{"t":"대회가 아주 멀리 남았다","mis":"K6-1-u4-X08"},{"t":"코가 막혀 노래하기 어렵다","mis":"K6-1-u4-X12"}],"explanation":["코 앞에 물건이 놓인 것이 아니에요.","멀리 남은 것과 반대예요.","날이 바짝 다가왔다는 뜻이에요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb),
('g6_1_kor_u4_review_a#10','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C23',2,'mc','auto','하늬의 「목이 빠지게 기다릴게」와 가리키는 마음이 가장 가까운 표현은 어느 것인가요?',ARRAY['K6-1-u4-X22']::text[],false,'{"seq":10,"concept":"K6-1-u4-C23","difficulty":2,"kind":"mc","stem":"하늬의 「목이 빠지게 기다릴게」와 가리키는 마음이 가장 가까운 표현은 어느 것인가요?","options":[{"t":"마음이 굴뚝같다","correct":true},{"t":"낯이 뜨겁다","mis":"K6-1-u4-X22"},{"t":"발등에 불이 떨어지다","mis":"K6-1-u4-X22"},{"t":"입이 무겁다","mis":"K6-1-u4-X22"}],"explanation":["낯이 뜨겁다는 부끄러움이에요.","발등에 불은 급함이에요.","간절한 마음끼리 가까워요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb),
('g6_1_kor_u4_review_a#11','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C29',2,'mc','auto','로아 글의 첫 두 줄에 들어 있는 처음 부분의 내용은 어느 것인가요?',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":11,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"로아 글의 첫 두 줄에 들어 있는 처음 부분의 내용은 어느 것인가요?","options":[{"t":"언제 · 누구와 · 왜 · 어디에 갔는지","correct":true},{"t":"견학을 정리하고 깨달은 점","mis":"K6-1-u4-X28"},{"t":"물을 소독하는 방법","mis":"K6-1-u4-X28"},{"t":"다음에 가고 싶은 곳","mis":"K6-1-u4-X28"}],"explanation":["깨달은 점은 끝이에요.","소독은 가운데의 견문이에요.","처음에는 개요를 알려요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb),
('g6_1_kor_u4_review_a#12','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C28',2,'mc','auto','로아 글 뒷부분에서 여정이 드러난 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":12,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"로아 글 뒷부분에서 여정이 드러난 것은 어느 것인가요?","options":[{"t":"「다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.」","correct":true},{"t":"「소독을 해서 해로운 균을 없앤다고 했다.」","mis":"K6-1-u4-X27"},{"t":"「물을 틀어 놓은 채로 양치하지 않아야겠다.」","mis":"K6-1-u4-X27"},{"t":"「여러 단계를 거친다는 것을 알았다.」","mis":"K6-1-u4-X27"}],"explanation":["소독은 새로 안 사실이에요.","다짐은 감상과 깨달음이에요.","어디로 옮겨 갔는지가 여정이에요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb),
('g6_1_kor_u4_review_a#13','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C36',2,'mc','auto','다음 가운데 관용 표현이 감상 자리에 알맞게 놓인 문장은 어느 것인가요?',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":13,"concept":"K6-1-u4-C36","difficulty":2,"kind":"mc","stem":"다음 가운데 관용 표현이 감상 자리에 알맞게 놓인 문장은 어느 것인가요?","options":[{"t":"「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다.」","correct":true},{"t":"「약품은 눈코 뜰 새 없이 알갱이를 뭉치게 한다.」","mis":"K6-1-u4-X36"},{"t":"「소독은 진땀을 빼며 해로운 균을 없앤다.」","mis":"K6-1-u4-X36"},{"t":"「모래층은 손이 열 개라도 모자라게 물을 거른다.」","mis":"K6-1-u4-X36"}],"explanation":["사실 자리에 얹었어요.","이것도 사실 자리예요.","놀란 마음 자리에 놓였어요."]}'::jsonb),
('g6_1_kor_u4_review_a#14','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C29',2,'mc','auto','로아의 조직표에서 처음 칸에 더해야 할 것은 어느 것인가요?',ARRAY['K6-1-u4-X28','K6-1-u4-X07']::text[],false,'{"seq":14,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"로아의 조직표에서 처음 칸에 더해야 할 것은 어느 것인가요?","options":[{"t":"견학한 까닭(수돗물이 어떻게 만들어지는지 알아보려고)","correct":true},{"t":"견학을 정리한 깨달은 점","mis":"K6-1-u4-X28"},{"t":"소독하는 방법","mis":"K6-1-u4-X28"},{"t":"넣을 관용 표현","mis":"K6-1-u4-X07"}],"explanation":["깨달은 점은 끝 칸이에요.","소독은 가운데 칸이에요.","처음에는 까닭도 들어가요."],"asset":{"type":"passage","lines":["처음 — 지난 금요일 · 반 친구들과 · 고장의 정수장","가운데 첫째 — 강물 끌어오는 곳 / 알갱이를 뭉쳐 가라앉힘 / (느낀 것 없음)","가운데 둘째 — 모래와 자갈 층 / 물을 거름 / (느낀 것 없음)","가운데 셋째 — 소독하는 곳 / 해로운 균을 없앰 / (느낀 것 없음)","끝 — 정말 재미있었다."],"title":"로아의 조직표 (고치기 전)"}}'::jsonb),
('g6_1_kor_u4_review_a#15','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C17',2,'mc','auto','「급할수록 돌아가라」와 「첫술에 배부르랴」를 바꿔 쓸 수 있는지 정할 때 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X18','K6-1-u4-X16']::text[],false,'{"seq":15,"concept":"K6-1-u4-C17","difficulty":2,"kind":"mc","stem":"「급할수록 돌아가라」와 「첫술에 배부르랴」를 바꿔 쓸 수 있는지 정할 때 알맞은 것은 어느 것인가요?","options":[{"t":"서두른다고 빨라지지 않는다는 뜻이 겹치지만, 쓸 상황까지 견주어 정한다","correct":true},{"t":"뜻이 겹치니 언제나 바꿔 쓴다","mis":"K6-1-u4-X18"},{"t":"글자 수가 달라 바꿀 수 없다","mis":"K6-1-u4-X18"},{"t":"두 속담은 뜻이 반대이다","mis":"K6-1-u4-X16"}],"explanation":["늘 바꿀 수 있는 것은 아니에요.","글자 수는 상관없어요.","쓸 상황까지 견줘요."]}'::jsonb),
('g6_1_kor_u4_review_a#16','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C42',2,'mc','auto','시온이의 발표에서 고칠 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":16,"concept":"K6-1-u4-C42","difficulty":2,"kind":"mc","stem":"시온이의 발표에서 고칠 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"모두 들을 수 있는 크기로, 듣는 사람을 보며, 존댓말로 말한다","correct":true},{"t":"지금보다 더 작은 목소리로 말한다","mis":"K6-1-u4-X42"},{"t":"반말을 그대로 쓴다","mis":"K6-1-u4-X42"},{"t":"쉬는 시간에 짝과 이야기하듯 편하게 말한다","mis":"K6-1-u4-X42"}],"explanation":["작은 목소리는 여럿에게 안 들려요.","여럿 앞에서는 존댓말을 써요.","공식적인 자리에 맞게 말해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb),
('g6_1_kor_u4_review_a#17','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C1',3,'error','auto','「입을 모으다」를 설명했어요. 알맞지 않게 설명한 친구는 누구인가요?',ARRAY['K6-1-u4-X01']::text[],false,'{"seq":17,"concept":"K6-1-u4-C1","difficulty":3,"kind":"error","stem":"「입을 모으다」를 설명했어요. 알맞지 않게 설명한 친구는 누구인가요?","options":[{"t":"하랑 — 「입술을 동그랗게 모은다는 뜻이야.」","correct":true,"mis_target":"K6-1-u4-X01"},{"t":"다은 — 「여럿이 같은 말을 한다는 뜻이야.」","mis":"K6-1-u4-X01"},{"t":"주원 — 「낱말 뜻의 합과는 다른 뜻을 지녔어.」","mis":"K6-1-u4-X01"}],"explanation":["다은이는 뜻을 바르게 말했어요.","주원이는 성질을 바르게 말했어요.","글자 그대로 읽으면 안 돼요."]}'::jsonb),
('g6_1_kor_u4_review_a#18','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C17',3,'error','auto','비슷한 속담을 견주어 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X18']::text[],false,'{"seq":18,"concept":"K6-1-u4-C17","difficulty":3,"kind":"error","stem":"비슷한 속담을 견주어 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"은재 — 「가랑비 속담과 바늘 도둑 속담은 기우는 방향까지 똑같아.」","correct":true,"mis_target":"K6-1-u4-X18"},{"t":"민결 — 「둘 다 작은 것이 쌓인다는 뜻이 겹쳐.」","mis":"K6-1-u4-X18"},{"t":"서율 — 「바늘 도둑은 나쁜 일이 커지는 쪽이야.」","mis":"K6-1-u4-X18"}],"explanation":["민결이는 겹치는 뜻을 바르게 말했어요.","서율이는 기우는 방향을 바르게 말했어요.","기우는 방향은 달라요."]}'::jsonb),
('g6_1_kor_u4_review_a#19','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C24',3,'error','auto','친구들이 관용 표현을 쓴 말이에요. 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K6-1-u4-X08','K6-1-u4-X23']::text[],false,'{"seq":19,"concept":"K6-1-u4-C24","difficulty":3,"kind":"error","stem":"친구들이 관용 표현을 쓴 말이에요. 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"라온 — 아파서 결석한 짝에게 「눈코 뜰 새 없이 바빴겠구나.」라고 했다","correct":true,"mis_target":"K6-1-u4-X08"},{"t":"예린 — 늘 잘하던 친구가 실수하자 「원숭이도 나무에서 떨어진다잖아.」라고 위로했다","mis":"K6-1-u4-X23"},{"t":"도윤 — 연습을 미룬 자신에게 「내가 빈 수레가 요란했구나.」라고 썼다","mis":"K6-1-u4-X23"}],"explanation":["예린이는 위로하는 자리에 맞게 썼어요.","도윤이는 자신을 돌아봤어요.","아픈 친구에게 바빴냐고 하면 어긋나요."]}'::jsonb),
('g6_1_kor_u4_review_a#20','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C30',3,'error','auto','견학 기록문을 고쳐 쓰자는 의견이에요. 알맞지 않은 의견을 낸 친구는 누구인가요?',ARRAY['K6-1-u4-X29','K6-1-u4-X30','K6-1-u4-X35']::text[],false,'{"seq":20,"concept":"K6-1-u4-C30","difficulty":3,"kind":"error","stem":"견학 기록문을 고쳐 쓰자는 의견이에요. 알맞지 않은 의견을 낸 친구는 누구인가요?","options":[{"t":"하율 — 「사실만 늘어놓으면 깔끔하니 마음은 다 지우자.」","correct":true,"mis_target":"K6-1-u4-X29"},{"t":"지유 — 「느낌만 있으니 새로 안 사실을 더하자.」","mis":"K6-1-u4-X30"},{"t":"건우 — 「본 것 하나에 느낀 것 하나를 붙이자.」","mis":"K6-1-u4-X35"}],"explanation":["지유는 견문을 더하자고 했어요.","건우는 짝짓자고 했어요.","마음을 다 지우면 안내문이 돼요."]}'::jsonb),
('g6_1_kor_u4_review_a#21','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C34',3,'mc','auto','같은 정수장 견학을 할머니께 보낼 글로 쓴다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X34','K6-1-u4-X30','K6-1-u4-X07']::text[],false,'{"seq":21,"concept":"K6-1-u4-C34","difficulty":3,"kind":"mc","stem":"같은 정수장 견학을 할머니께 보낼 글로 쓴다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"할머니가 궁금해하실 만한 것을 골라 읽기 편하게 쓰고, 큰 글씨나 직접 읽어 드리는 방법도 생각한다","correct":true},{"t":"누구에게 보내든 똑같이 쓴다","mis":"K6-1-u4-X34"},{"t":"새로 안 사실을 빼고 느낌만 쓴다","mis":"K6-1-u4-X30"},{"t":"관용 표현을 가득 넣는다","mis":"K6-1-u4-X07"}],"explanation":["읽을 사람이 달라지면 글도 달라져요.","견문을 빼면 안 돼요.","읽을 사람을 생각해요."]}'::jsonb),
('g6_1_kor_u4_review_a#22','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C41',3,'error','auto','관용 표현 사전을 만들 계획이에요. 알맞지 않은 계획을 말한 친구는 누구인가요?',ARRAY['K6-1-u4-X40']::text[],false,'{"seq":22,"concept":"K6-1-u4-C41","difficulty":3,"kind":"error","stem":"관용 표현 사전을 만들 계획이에요. 알맞지 않은 계획을 말한 친구는 누구인가요?","options":[{"t":"태린 — 「아무도 모르는 어려운 표현으로 스무 개를 채울래.」","correct":true,"mis_target":"K6-1-u4-X40"},{"t":"소이 — 「이번 달에 한 번은 쓸 표현 다섯 개를 고를래.」","mis":"K6-1-u4-X40"},{"t":"하진 — 「쓸 상황이 안 떠오르는 표현은 다음으로 미룰래.」","mis":"K6-1-u4-X40"}],"explanation":["소이는 쓸 표현을 골랐어요.","하진이도 바르게 계획했어요.","어려운 표현을 채우면 쓰지 않게 돼요."]}'::jsonb),
('g6_1_kor_u4_review_a#23','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C20',4,'mc','auto','합창 대회 대화에서 세 친구가 관용 표현을 쓴 방식을 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X01','K6-1-u4-X20']::text[],false,'{"seq":23,"concept":"K6-1-u4-C20","difficulty":4,"kind":"mc","stem":"합창 대회 대화에서 세 친구가 관용 표현을 쓴 방식을 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"저마다 상황과 듣는 사람에 맞는 표현을 골라 감싸 주고, 다짐하고, 응원하는 마음을 짧고 또렷하게 전했다","correct":true},{"t":"관용 표현을 많이 넣었으니 좋은 대화다","mis":"K6-1-u4-X07"},{"t":"모두 낱말 뜻 그대로 썼다","mis":"K6-1-u4-X01"},{"t":"가온이는 이든이를 놀리려고 속담을 썼다","mis":"K6-1-u4-X20"}],"explanation":["개수 때문에 좋은 것이 아니에요.","낱말 뜻 그대로가 아니에요.","가온이는 감싸 주려 했어요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb),
('g6_1_kor_u4_review_a#24','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C24',4,'essay','teacher','대회에서 이든이가 반주를 한 군데 틀렸어요. 하늬가 할 말을 관용 표현 하나를 넣어 쓰고, 그 표현이 이 자리와 듣는 사람에게 알맞은 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u4-C24","difficulty":4,"kind":"essay","stem":"대회에서 이든이가 반주를 한 군데 틀렸어요. 하늬가 할 말을 관용 표현 하나를 넣어 쓰고, 그 표현이 이 자리와 듣는 사람에게 알맞은 까닭을 쓰세요.","answer_guide":{"answer":"예: 「원숭이도 나무에서 떨어진다잖아. 그동안 밤마다 연습한 거 다 알아. 다음엔 더 잘될 거야.」 이든이는 실수해서 속상할 것이므로 위로하는 말이 필요하다. 「원숭이도 나무에서 떨어진다」는 잘하는 사람도 실수할 때가 있다는 뜻이라 이든이를 감싸 주는 자리에 맞는다. 「빈 수레가 요란하다」처럼 깎아내리는 표현은 이 자리에 맞지 않는다.","scoring_points":["관용 표현 하나를 넣어 하늬의 말을 썼는가","표현의 뜻이 상황과 맞는 까닭을 썼는가","듣는 사람의 마음을 생각한 까닭을 썼는가"]},"explanation":["이든이의 마음을 떠올려요.","위로하는 표현을 골라요.","까닭을 함께 써요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb),
('g6_1_kor_u4_review_a#25','kor',6,1,'u4','','g6_1_kor_u4_review_a','unit_review','K6-1-u4-C6',4,'essay','teacher','「관용 표현은 제자리에 놓일 때만 힘을 낸다」는 말을 개수 · 듣는 사람 · 글의 자리 세 가지와 이어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u4-C6","difficulty":4,"kind":"essay","stem":"「관용 표현은 제자리에 놓일 때만 힘을 낸다」는 말을 개수 · 듣는 사람 · 글의 자리 세 가지와 이어 설명하세요.","answer_guide":{"answer":"예: 첫째, 관용 표현은 많이 넣는다고 좋아지지 않고 상황에 맞는 하나가 힘이 크다. 둘째, 같은 표현도 누구에게 하느냐에 따라 위로가 되기도 하고 상처가 되기도 하므로 듣는 사람과 자리를 살펴야 한다. 셋째, 견학 기록문에서는 사실을 전하는 견문 자리가 아니라 마음이 드러나는 감상 자리에 놓아야 한다.","scoring_points":["개수의 문제를 썼는가","듣는 사람과 자리의 문제를 썼는가","글에서 놓일 자리(감상)를 썼는가"]},"explanation":["개수를 떠올려요.","듣는 사람을 떠올려요.","견학 기록문의 자리를 떠올려요."]}'::jsonb),
('g6_1_kor_u4_review_b#1','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C2',1,'ox','auto','「창문을 닦다」는 관용 표현이에요.',ARRAY['K6-1-u4-X02']::text[],false,'{"seq":1,"concept":"K6-1-u4-C2","difficulty":1,"kind":"ox","stem":"「창문을 닦다」는 관용 표현이에요.","answer":"X","reason_options":[{"t":"낱말 뜻을 그대로 더해도 말이 통하기 때문에","correct":true},{"t":"두 낱말이 합쳐진 말은 모두 관용 표현이기 때문에","mis":"K6-1-u4-X02"}],"mis":"K6-1-u4-X02","explanation":["창문을 정말 닦는 말이에요.","뜻이 달라지지 않아요.","뜻 그대로면 관용 표현이 아니에요."]}'::jsonb),
('g6_1_kor_u4_review_b#2','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C4',1,'mc','auto','관용 표현에 우리 문화가 담겨 있다는 것을 보여 주는 것은 어느 것인가요?',ARRAY['K6-1-u4-X17','K6-1-u4-X01','K6-1-u4-X05']::text[],false,'{"seq":2,"concept":"K6-1-u4-C4","difficulty":1,"kind":"mc","stem":"관용 표현에 우리 문화가 담겨 있다는 것을 보여 주는 것은 어느 것인가요?","options":[{"t":"속담 속 수레 · 서당처럼 옛 생활 모습이 남아 있다","correct":true},{"t":"요즘 새로 만든 말이 많다","mis":"K6-1-u4-X17"},{"t":"낱말 뜻 그대로라 누구나 안다","mis":"K6-1-u4-X01"},{"t":"외국에서 들어온 말이 대부분이다","mis":"K6-1-u4-X05"}],"explanation":["오래 전해 온 말이에요.","낱말 뜻 그대로가 아니에요.","옛 생활이 말 속에 남았어요."]}'::jsonb),
('g6_1_kor_u4_review_b#3','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C9',1,'mc','auto','「눈코 뜰 새 없다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X12','K6-1-u4-X08']::text[],false,'{"seq":3,"concept":"K6-1-u4-C9","difficulty":1,"kind":"mc","stem":"「눈코 뜰 새 없다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"몹시 바쁘다","correct":true},{"t":"잠이 와서 눈이 감긴다","mis":"K6-1-u4-X01"},{"t":"감기로 코가 막혔다","mis":"K6-1-u4-X12"},{"t":"아무 일도 없어 한가하다","mis":"K6-1-u4-X08"}],"explanation":["졸린 이야기가 아니에요.","코가 막힌 것도 아니에요.","쉴 틈 없이 바쁘다는 뜻이에요."]}'::jsonb),
('g6_1_kor_u4_review_b#4','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C15',1,'mc','auto','「가랑비에 옷 젖는 줄 모른다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X16']::text[],false,'{"seq":4,"concept":"K6-1-u4-C15","difficulty":1,"kind":"mc","stem":"「가랑비에 옷 젖는 줄 모른다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"사소한 것이 쌓여 큰 것이 되는 줄 모른다","correct":true},{"t":"비 오는 날에는 우산을 꼭 챙겨라","mis":"K6-1-u4-X16"},{"t":"젖은 옷은 금방 마른다","mis":"K6-1-u4-X16"},{"t":"큰비가 와야 옷이 젖는다","mis":"K6-1-u4-X16"}],"explanation":["우산 이야기가 아니에요.","옷 마르는 이야기도 아니에요.","작은 것이 쌓여 커져요."]}'::jsonb),
('g6_1_kor_u4_review_b#5','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C24',1,'ox','auto','상을 받은 친구에게 「빈 수레가 요란하다더니.」라고 말하는 것은 알맞아요.',ARRAY['K6-1-u4-X23']::text[],false,'{"seq":5,"concept":"K6-1-u4-C24","difficulty":1,"kind":"ox","stem":"상을 받은 친구에게 「빈 수레가 요란하다더니.」라고 말하는 것은 알맞아요.","answer":"X","reason_options":[{"t":"축하하려던 말이 깎아내리는 말이 되기 때문에","correct":true},{"t":"속담을 쓰면 말이 생생해지기 때문에","mis":"K6-1-u4-X23"}],"mis":"K6-1-u4-X23","explanation":["뜻은 하나지만","남을 가리키면 상처가 돼요.","듣는 사람과 자리를 봐요."]}'::jsonb),
('g6_1_kor_u4_review_b#6','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C28',1,'mc','auto','「그곳에서 보고 들은 것, 새롭게 안 사실」을 무엇이라고 하나요?',ARRAY['K6-1-u4-X27','K6-1-u4-X31']::text[],false,'{"seq":6,"concept":"K6-1-u4-C28","difficulty":1,"kind":"mc","stem":"「그곳에서 보고 들은 것, 새롭게 안 사실」을 무엇이라고 하나요?","options":[{"t":"견문","correct":true},{"t":"여정","mis":"K6-1-u4-X27"},{"t":"감상","mis":"K6-1-u4-X27"},{"t":"제목","mis":"K6-1-u4-X31"}],"explanation":["여정은 다닌 길이에요.","감상은 느낀 것이에요.","보고 들은 것은 견문이에요."]}'::jsonb),
('g6_1_kor_u4_review_b#7','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C35',1,'mc','auto','견학 기록문의 가운데가 사실만 늘어놓은 글이 되지 않게 하는 방법은 어느 것인가요?',ARRAY['K6-1-u4-X35','K6-1-u4-X29','K6-1-u4-X07']::text[],false,'{"seq":7,"concept":"K6-1-u4-C35","difficulty":1,"kind":"mc","stem":"견학 기록문의 가운데가 사실만 늘어놓은 글이 되지 않게 하는 방법은 어느 것인가요?","options":[{"t":"본 것 하나에 느낀 것 하나를 붙여 간다","correct":true},{"t":"느낌은 모두 끝에 몰아 쓴다","mis":"K6-1-u4-X35"},{"t":"사실 문장을 더 늘린다","mis":"K6-1-u4-X29"},{"t":"문단마다 관용 표현을 넣는다","mis":"K6-1-u4-X07"}],"explanation":["몰아 쓰면 가운데는 사실만 남아요.","사실을 늘리면 더 안내문 같아요.","본 것과 느낀 것을 짝지어요."]}'::jsonb),
('g6_1_kor_u4_review_b#8','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C42',1,'mc','auto','다음 가운데 공식적인 말하기 상황은 어느 것인가요?',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":8,"concept":"K6-1-u4-C42","difficulty":1,"kind":"mc","stem":"다음 가운데 공식적인 말하기 상황은 어느 것인가요?","options":[{"t":"학급 전체 앞에서 조사한 내용을 발표할 때","correct":true},{"t":"쉬는 시간에 짝과 이야기할 때","mis":"K6-1-u4-X42"},{"t":"집에서 동생과 놀 때","mis":"K6-1-u4-X42"},{"t":"점심을 먹으며 친구와 이야기할 때","mis":"K6-1-u4-X42"}],"explanation":["짝과의 이야기는 비공식적이에요.","동생과도 비공식적이에요.","여럿 앞에서 발표하는 자리예요."]}'::jsonb),
('g6_1_kor_u4_review_b#9','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C20',2,'mc','auto','가온이가 「원숭이도 나무에서 떨어진다고」를 쓴 의도로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X21']::text[],false,'{"seq":9,"concept":"K6-1-u4-C20","difficulty":2,"kind":"mc","stem":"가온이가 「원숭이도 나무에서 떨어진다고」를 쓴 의도로 알맞은 것은 어느 것인가요?","options":[{"t":"늘 잘하던 이든이도 늦을 수 있다고 감싸 주려고","correct":true},{"t":"이든이를 놀리려고","mis":"K6-1-u4-X20"},{"t":"원숭이 이야기를 들려주려고","mis":"K6-1-u4-X21"},{"t":"이든이에게 반주를 그만두라고 하려고","mis":"K6-1-u4-X20"}],"explanation":["놀리는 말이 아니에요.","원숭이 이야기가 아니에요.","실수해도 괜찮다고 감싸 줬어요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb),
('g6_1_kor_u4_review_b#10','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C24',2,'mc','auto','대회에서 이든이가 반주를 한 군데 틀렸어요. 하늬가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X23','K6-1-u4-X08']::text[],false,'{"seq":10,"concept":"K6-1-u4-C24","difficulty":2,"kind":"mc","stem":"대회에서 이든이가 반주를 한 군데 틀렸어요. 하늬가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「원숭이도 나무에서 떨어진다잖아. 다음엔 더 잘될 거야.」","correct":true},{"t":"「빈 수레가 요란하다더니.」","mis":"K6-1-u4-X23"},{"t":"「개구리 올챙이 적 생각 못 하는구나.」","mis":"K6-1-u4-X23"},{"t":"「고양이 목에 방울 달기네.」","mis":"K6-1-u4-X08"}],"explanation":["깎아내리는 말이 돼요.","이것도 상처가 돼요.","실수한 친구를 위로하는 자리예요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb),
('g6_1_kor_u4_review_b#11','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C28',2,'mc','auto','로아 글 앞부분에서 견문에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u4-X27']::text[],false,'{"seq":11,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"로아 글 앞부분에서 견문에 해당하는 것은 어느 것인가요?","options":[{"t":"「약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.」","correct":true},{"t":"「학교에서 버스를 타고 강가로 갔다.」","mis":"K6-1-u4-X27"},{"t":"「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다.」","mis":"K6-1-u4-X27"},{"t":"「먼저 강물을 끌어오는 곳을 보았다.」","mis":"K6-1-u4-X27"}],"explanation":["버스를 탄 것은 여정이에요.","놀란 마음은 감상이에요.","새로 안 사실이 견문이에요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb),
('g6_1_kor_u4_review_b#12','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C29',2,'mc','auto','「앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다.」는 글의 어느 부분에 어울리나요?',ARRAY['K6-1-u4-X28','K6-1-u4-X31']::text[],false,'{"seq":12,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"「앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다.」는 글의 어느 부분에 어울리나요?","options":[{"t":"끝 — 깨달은 점과 다짐","correct":true},{"t":"처음 — 견학한 까닭","mis":"K6-1-u4-X28"},{"t":"가운데 — 새로 안 사실","mis":"K6-1-u4-X28"},{"t":"제목","mis":"K6-1-u4-X31"}],"explanation":["까닭이 아니에요.","새로 안 사실이 아니에요.","정리와 다짐은 끝이에요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb),
('g6_1_kor_u4_review_b#13','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C37',2,'mc','auto','로아가 「관용 표현을 세 개는 넣어야 해.」라며 문단마다 넣으려 할 때 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X37','K6-1-u4-X09']::text[],false,'{"seq":13,"concept":"K6-1-u4-C37","difficulty":2,"kind":"mc","stem":"로아가 「관용 표현을 세 개는 넣어야 해.」라며 문단마다 넣으려 할 때 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「마음이 가장 크게 움직인 자리에 하나면 충분해.」","correct":true},{"t":"「셋이 모자라면 다섯 개 넣어.」","mis":"K6-1-u4-X07"},{"t":"「칸을 채우는 게 제일 중요해.」","mis":"K6-1-u4-X37"},{"t":"「관용 표현은 하나도 쓰지 마.」","mis":"K6-1-u4-X09"}],"explanation":["많이 넣는다고 좋아지지 않아요.","칸 채우기가 아니에요.","제자리에 하나면 충분해요."]}'::jsonb),
('g6_1_kor_u4_review_b#14','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C35',2,'mc','auto','로아의 조직표 가운데 칸들의 문제로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X27','K6-1-u4-X29']::text[],false,'{"seq":14,"concept":"K6-1-u4-C35","difficulty":2,"kind":"mc","stem":"로아의 조직표 가운데 칸들의 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"본 것에 짝지은 느낀 것이 없어 사실만 늘어놓은 글이 되기 쉽다","correct":true},{"t":"견문이 너무 많아 일기가 된다","mis":"K6-1-u4-X30"},{"t":"차례가 없어 여정이 보이지 않는다","mis":"K6-1-u4-X27"},{"t":"고칠 곳이 없다","mis":"K6-1-u4-X29"}],"explanation":["견문이 많으면 일기가 아니라 안내문 쪽이에요.","차례는 있어요.","느낀 것이 빠졌어요."],"asset":{"type":"passage","lines":["처음 — 지난 금요일 · 반 친구들과 · 고장의 정수장","가운데 첫째 — 강물 끌어오는 곳 / 알갱이를 뭉쳐 가라앉힘 / (느낀 것 없음)","가운데 둘째 — 모래와 자갈 층 / 물을 거름 / (느낀 것 없음)","가운데 셋째 — 소독하는 곳 / 해로운 균을 없앰 / (느낀 것 없음)","끝 — 정말 재미있었다."],"title":"로아의 조직표 (고치기 전)"}}'::jsonb),
('g6_1_kor_u4_review_b#15','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C19',2,'mc','auto','속담을 바꾸어 지을 때 꼭 함께 적을 것은 어느 것인가요?',ARRAY['K6-1-u4-X19','K6-1-u4-X41']::text[],false,'{"seq":15,"concept":"K6-1-u4-C19","difficulty":2,"kind":"mc","stem":"속담을 바꾸어 지을 때 꼭 함께 적을 것은 어느 것인가요?","options":[{"t":"어떤 상황에서 쓸 말인지","correct":true},{"t":"바꾼 낱말의 글자 수","mis":"K6-1-u4-X19"},{"t":"원래 속담이 생긴 때","mis":"K6-1-u4-X41"},{"t":"바꾼 속담을 아는 친구의 수","mis":"K6-1-u4-X41"}],"explanation":["글자 수는 상관없어요.","생긴 때는 쓸모없어요.","쓸 상황을 함께 적어요."]}'::jsonb),
('g6_1_kor_u4_review_b#16','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C42',2,'mc','auto','다인이의 행동을 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X43','K6-1-u4-X42']::text[],false,'{"seq":16,"concept":"K6-1-u4-C42","difficulty":2,"kind":"mc","stem":"다인이의 행동을 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"공식적인 자리에서 발표를 끝까지 경청하지 않았다","correct":true},{"t":"작은 소리였으니 괜찮다","mis":"K6-1-u4-X43"},{"t":"쉬는 시간 이야기라 괜찮다","mis":"K6-1-u4-X42"},{"t":"다인이는 예절을 잘 지켰다","mis":"K6-1-u4-X43"}],"explanation":["작은 소리여도 경청하지 않았어요.","발표 도중이었어요.","끝까지 들어야 해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb),
('g6_1_kor_u4_review_b#17','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C5',3,'mc','auto','「손이 열 개라도 모자라다」를 바르게 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u4-X06']::text[],false,'{"seq":17,"concept":"K6-1-u4-C5","difficulty":3,"kind":"mc","stem":"「손이 열 개라도 모자라다」를 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「잔치 준비로 손이 열 개라도 모자랐다.」","correct":true},{"t":"「잔치 준비로 손이 아홉 개라도 모자랐다.」","mis":"K6-1-u4-X06"},{"t":"「잔치 준비로 손가락이 열 개라도 모자랐다.」","mis":"K6-1-u4-X06"},{"t":"「잔치 준비로 두 손이 열 개라도 넉넉했다.」","mis":"K6-1-u4-X06"}],"explanation":["수를 바꾸면 안 돼요.","낱말을 바꿔도 안 돼요.","굳어진 모양 그대로 써요."]}'::jsonb),
('g6_1_kor_u4_review_b#18','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C16',3,'mc','auto','「서당 개 삼 년이면 풍월을 읊는다」에서 「서당」이 옛날 아이들이 글을 배우던 곳임을 알고 나서 할 생각으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X17','K6-1-u4-X01']::text[],false,'{"seq":18,"concept":"K6-1-u4-C16","difficulty":3,"kind":"mc","stem":"「서당 개 삼 년이면 풍월을 읊는다」에서 「서당」이 옛날 아이들이 글을 배우던 곳임을 알고 나서 할 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"옛 배움터가 말 속에 남아 옛 생활을 엿볼 수 있다","correct":true},{"t":"서당이 없어졌으니 틀린 속담이다","mis":"K6-1-u4-X17"},{"t":"개가 실제로 글을 읽었다는 뜻이다","mis":"K6-1-u4-X01"},{"t":"요즘 말로만 바꿔 써야 한다","mis":"K6-1-u4-X17"}],"explanation":["없어졌다고 틀린 말이 아니에요.","개가 글을 읽은 것이 아니에요.","옛 생활이 남은 흔적이에요."]}'::jsonb),
('g6_1_kor_u4_review_b#19','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C20',3,'mc','auto','초아와 같은 의도로 「목마른 사람이 우물 판다」를 쓴 말은 어느 것인가요?',ARRAY['K6-1-u4-X20','K6-1-u4-X01']::text[],false,'{"seq":19,"concept":"K6-1-u4-C20","difficulty":3,"kind":"mc","stem":"초아와 같은 의도로 「목마른 사람이 우물 판다」를 쓴 말은 어느 것인가요?","options":[{"t":"「목마른 사람이 우물 판다잖아. 궁금한 내가 먼저 선생님께 여쭤볼게.」","correct":true},{"t":"「너희는 왜 아무도 안 나서니? 목마른 사람이 우물 판다잖아.」","mis":"K6-1-u4-X20"},{"t":"「나는 이런 속담도 알아. 목마른 사람이 우물 판다.」","mis":"K6-1-u4-X20"},{"t":"「목마른 사람이 우물 판다니까 우물을 파러 가자.」","mis":"K6-1-u4-X01"}],"explanation":["남을 꾸짖는 말이 됐어요.","자랑하는 말이 됐어요.","아쉬운 내가 먼저 나선다는 뜻이에요."]}'::jsonb),
('g6_1_kor_u4_review_b#20','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C31',3,'mc','auto','「도서관 서고를 다녀와서」라는 제목만 보고 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K6-1-u4-X31','K6-1-u4-X26']::text[],false,'{"seq":20,"concept":"K6-1-u4-C31","difficulty":3,"kind":"mc","stem":"「도서관 서고를 다녀와서」라는 제목만 보고 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"도서관에서 책을 보관하는 곳에 다녀와 새로 안 것을 쓴 글일 것이다","correct":true},{"t":"도서관 이용 규칙을 지키자고 주장하는 글일 것이다","mis":"K6-1-u4-X31"},{"t":"책 속 인물이 나오는 이야기일 것이다","mis":"K6-1-u4-X26"},{"t":"서고에 가는 길만 적은 글일 것이다","mis":"K6-1-u4-X31"}],"explanation":["주장하는 글이 아니에요.","이야기가 아니에요.","다녀온 곳과 새로 안 것을 짐작해요."]}'::jsonb),
('g6_1_kor_u4_review_b#21','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C38',3,'error','auto','고쳐 쓸 때 한 일이에요. 알맞지 않게 고친 친구는 누구인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X36']::text[],false,'{"seq":21,"concept":"K6-1-u4-C38","difficulty":3,"kind":"error","stem":"고쳐 쓸 때 한 일이에요. 알맞지 않게 고친 친구는 누구인가요?","options":[{"t":"시하 — 짝 글보다 짧아서 아무 문장이나 더 늘렸다","correct":true,"mis_target":"K6-1-u4-X38"},{"t":"로운 — 여정 · 견문 · 감상이 다 전해지는지 다시 읽었다","mis":"K6-1-u4-X38"},{"t":"채이 — 관용 표현이 상황에 맞게 놓였는지 살폈다","mis":"K6-1-u4-X36"}],"explanation":["로운이는 갈래가 갖출 것을 살폈어요.","채이도 바르게 살폈어요.","길이는 고쳐 쓸 기준이 아니에요."]}'::jsonb),
('g6_1_kor_u4_review_b#22','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C40',3,'mc','auto','「목에 힘을 주다」 사전 한 장에서 「쓸 수 있는 상황」 칸을 알맞게 쓴 것은 어느 것인가요?',ARRAY['K6-1-u4-X11','K6-1-u4-X41','K6-1-u4-X01']::text[],false,'{"seq":22,"concept":"K6-1-u4-C40","difficulty":3,"kind":"mc","stem":"「목에 힘을 주다」 사전 한 장에서 「쓸 수 있는 상황」 칸을 알맞게 쓴 것은 어느 것인가요?","options":[{"t":"상을 받고 나서 친구들 앞에서 거만하게 구는 사람을 두고","correct":true},{"t":"잘난 체하며 거만하게 굴다(뜻을 한 번 더 씀)","mis":"K6-1-u4-X11"},{"t":"이 표현이 처음 생긴 때","mis":"K6-1-u4-X41"},{"t":"목 운동을 하는 방법","mis":"K6-1-u4-X01"}],"explanation":["뜻은 둘째 칸이에요.","생긴 때는 쓸모없어요.","내가 쓸 상황을 적어요."]}'::jsonb),
('g6_1_kor_u4_review_b#23','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C30',4,'mc','auto','로아 글을 고치려는 의견 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X29','K6-1-u4-X30','K6-1-u4-X07']::text[],false,'{"seq":23,"concept":"K6-1-u4-C30","difficulty":4,"kind":"mc","stem":"로아 글을 고치려는 의견 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사실 문장은 그대로 두고, 모래와 자갈 층과 소독 문장 뒤에 그때의 마음을 한 문장씩 붙인다","correct":true},{"t":"감상 문장을 모두 지워 깔끔한 안내문으로 만든다","mis":"K6-1-u4-X29"},{"t":"견문을 모두 지우고 느낌만 남긴다","mis":"K6-1-u4-X30"},{"t":"문장마다 관용 표현을 하나씩 넣는다","mis":"K6-1-u4-X07"}],"explanation":["감상을 지우면 안내문이 돼요.","견문을 지우면 일기가 돼요.","본 것에 느낀 것을 짝지어요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb),
('g6_1_kor_u4_review_b#24','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C28',4,'essay','teacher','로아 글 앞부분에서 여정 · 견문 · 감상을 하나씩 찾아 쓰고, 각각 그렇게 본 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u4-C28","difficulty":4,"kind":"essay","stem":"로아 글 앞부분에서 여정 · 견문 · 감상을 하나씩 찾아 쓰고, 각각 그렇게 본 까닭을 쓰세요.","answer_guide":{"answer":"예: 여정 — 「학교에서 버스를 타고 강가로 갔다」는 어떻게 다녔는지 보여 준다. 견문 — 「약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다」는 정수장에서 새로 안 사실이다. 감상 — 「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다」는 놀란 마음을 나타낸다.","scoring_points":["여정을 찾고 까닭을 썼는가","견문을 찾고 까닭을 썼는가","감상을 찾고 까닭을 썼는가"]},"explanation":["다닌 길을 찾아요.","새로 안 사실을 찾아요.","마음이 드러난 곳을 찾아요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb),
('g6_1_kor_u4_review_b#25','kor',6,1,'u4','','g6_1_kor_u4_review_b','unit_review','K6-1-u4-C30',4,'essay','teacher','견학 기록문이 안내문이나 일기와 다른 점을 쓰고, 좋은 견학 기록문이 갖추어야 할 것을 세 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u4-C30","difficulty":4,"kind":"essay","stem":"견학 기록문이 안내문이나 일기와 다른 점을 쓰고, 좋은 견학 기록문이 갖추어야 할 것을 세 가지 쓰세요.","answer_guide":{"answer":"예: 안내문은 사실만, 일기는 마음만 중심으로 쓰지만 견학 기록문은 새롭게 안 사실을 중심에 놓고 그때의 마음도 함께 적는다. 좋은 견학 기록문은 첫째, 여정 · 견문 · 감상이 드러나고, 둘째, 처음 · 가운데 · 끝의 짜임이 있으며, 셋째, 새로 안 사실이 참이고 마음이 진솔하게 담겨 있어야 한다.","scoring_points":["안내문 · 일기와 다른 점을 썼는가","여정 · 견문 · 감상이나 짜임을 썼는가","사실이 참이고 마음이 진솔해야 함을 썼는가"]},"explanation":["두 글과 견줘요.","갖출 것을 떠올려요.","세 가지를 써요."]}'::jsonb),
('g6_1_kor_u4_review_c#1','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C2',1,'mc','auto','다음 가운데 낱말 뜻의 합과 다른 새 뜻을 지닌 관용 표현은 어느 것인가요?',ARRAY['K6-1-u4-X02']::text[],false,'{"seq":1,"concept":"K6-1-u4-C2","difficulty":1,"kind":"mc","stem":"다음 가운데 낱말 뜻의 합과 다른 새 뜻을 지닌 관용 표현은 어느 것인가요?","options":[{"t":"입이 무겁다","correct":true},{"t":"문을 닫다","mis":"K6-1-u4-X02"},{"t":"손을 씻다","mis":"K6-1-u4-X02"},{"t":"책을 읽다","mis":"K6-1-u4-X02"}],"explanation":["문을 닫는 것은 뜻 그대로예요.","손을 씻는 것도 뜻 그대로예요.","말이 신중하다는 새 뜻이 있어요."]}'::jsonb),
