('g6_1_kor_u4_review_c#5','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C21',1,'mc','auto','「마음이 굴뚝같았다」를 고르면 「정말 하고 싶었다」보다 더 전해지는 것은 어느 것인가요?',ARRAY['K6-1-u4-X21','K6-1-u4-X20','K6-1-u4-X09']::text[],false,'{"seq":5,"concept":"K6-1-u4-C21","difficulty":1,"kind":"mc","stem":"「마음이 굴뚝같았다」를 고르면 「정말 하고 싶었다」보다 더 전해지는 것은 어느 것인가요?","options":[{"t":"하고 싶은 마음의 크기","correct":true},{"t":"굴뚝이 얼마나 높은지","mis":"K6-1-u4-X21"},{"t":"하기 싫은 마음","mis":"K6-1-u4-X20"},{"t":"아무것도 더 전해지지 않는다","mis":"K6-1-u4-X09"}],"explanation":["굴뚝 이야기가 아니에요.","싫은 마음이 아니에요.","마음의 크기가 함께 전해져요."]}'::jsonb),
('g6_1_kor_u4_review_c#6','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C28',1,'mc','auto','「어디를 거쳐 어떻게 다녔는지, 다닌 길」을 무엇이라고 하나요?',ARRAY['K6-1-u4-X27','K6-1-u4-X28']::text[],false,'{"seq":6,"concept":"K6-1-u4-C28","difficulty":1,"kind":"mc","stem":"「어디를 거쳐 어떻게 다녔는지, 다닌 길」을 무엇이라고 하나요?","options":[{"t":"여정","correct":true},{"t":"견문","mis":"K6-1-u4-X27"},{"t":"감상","mis":"K6-1-u4-X27"},{"t":"끝 부분","mis":"K6-1-u4-X28"}],"explanation":["견문은 보고 들은 것이에요.","감상은 느낀 것이에요.","다닌 길은 여정이에요."]}'::jsonb),
('g6_1_kor_u4_review_c#7','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C36',1,'ox','auto','관용 표현은 사실을 전하는 견문 자리에 얹는 것이 좋아요.',ARRAY['K6-1-u4-X36']::text[],false,'{"seq":7,"concept":"K6-1-u4-C36","difficulty":1,"kind":"ox","stem":"관용 표현은 사실을 전하는 견문 자리에 얹는 것이 좋아요.","answer":"X","reason_options":[{"t":"견문은 사실이라 관용 표현을 얹으면 무엇이 사실인지 흐려지기 때문에","correct":true},{"t":"사실 자리에 얹어야 글이 재미있어지기 때문에","mis":"K6-1-u4-X36"}],"mis":"K6-1-u4-X36","explanation":["견문은 사실이에요.","관용 표현은 마음을 나타내요.","감상 자리에 놓아요."]}'::jsonb),
('g6_1_kor_u4_review_c#8','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C42',1,'ox','auto','공식적인 말하기와 비공식적인 말하기에서 지킬 예절은 똑같아요.',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":8,"concept":"K6-1-u4-C42","difficulty":1,"kind":"ox","stem":"공식적인 말하기와 비공식적인 말하기에서 지킬 예절은 똑같아요.","answer":"X","reason_options":[{"t":"듣는 사람과 자리가 달라 편하게 들을 수 있는 방법도 달라지기 때문에","correct":true},{"t":"예절은 어디서나 한 가지 목록이기 때문에","mis":"K6-1-u4-X42"}],"mis":"K6-1-u4-X42","explanation":["같은 교실이라도","듣는 사람과 자리가 달라지면","예절도 달라져요."]}'::jsonb),
('g6_1_kor_u4_review_c#9','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C10',2,'mc','auto','이든이가 말한 「어깨가 무거워서」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X12','K6-1-u4-X20']::text[],false,'{"seq":9,"concept":"K6-1-u4-C10","difficulty":2,"kind":"mc","stem":"이든이가 말한 「어깨가 무거워서」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"반주를 맡은 책임이 커서 마음이 무거웠다","correct":true},{"t":"악보 가방이 무거웠다","mis":"K6-1-u4-X12"},{"t":"피아노를 옮겨 어깨가 아팠다","mis":"K6-1-u4-X12"},{"t":"반주가 하기 싫었다","mis":"K6-1-u4-X20"}],"explanation":["가방 이야기가 아니에요.","어깨가 아픈 것도 아니에요.","책임이 큰 마음이에요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb),
('g6_1_kor_u4_review_c#10','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C11',2,'mc','auto','학급 안내문에 「대회가 코앞에 닥쳤으니 모두 연습해 주세요.」라고 쓴 것을 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X13','K6-1-u4-X01']::text[],false,'{"seq":10,"concept":"K6-1-u4-C11","difficulty":2,"kind":"mc","stem":"학급 안내문에 「대회가 코앞에 닥쳤으니 모두 연습해 주세요.」라고 쓴 것을 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"글로 전하는 매체에서도 관용어가 급함을 짧고 또렷하게 전한다","correct":true},{"t":"안내문에는 관용어를 쓰면 안 된다","mis":"K6-1-u4-X13"},{"t":"글로 쓰면 말로 할 때와 뜻이 달라진다","mis":"K6-1-u4-X13"},{"t":"코앞에 물건을 두라는 뜻이다","mis":"K6-1-u4-X01"}],"explanation":["안내문에도 쓸 수 있어요.","뜻은 그대로예요.","매체가 달라도 하는 일은 같아요."]}'::jsonb),
('g6_1_kor_u4_review_c#11','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C28',2,'mc','auto','「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다.」는 무엇에 해당하나요?',ARRAY['K6-1-u4-X27','K6-1-u4-X28']::text[],false,'{"seq":11,"concept":"K6-1-u4-C28","difficulty":2,"kind":"mc","stem":"「흙탕물이 맑아지는 모습에 입이 딱 벌어졌다.」는 무엇에 해당하나요?","options":[{"t":"감상","correct":true},{"t":"여정","mis":"K6-1-u4-X27"},{"t":"견문","mis":"K6-1-u4-X27"},{"t":"견학한 까닭","mis":"K6-1-u4-X28"}],"explanation":["다닌 길이 아니에요.","새로 안 사실이 아니에요.","놀란 마음이에요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb),
('g6_1_kor_u4_review_c#12','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C35',2,'mc','auto','로아 글 뒷부분의 모래와 자갈 층 문장 뒤에 무엇을 붙이면 본 것과 느낀 것이 짝지어질까요?',ARRAY['K6-1-u4-X35','K6-1-u4-X07']::text[],false,'{"seq":12,"concept":"K6-1-u4-C35","difficulty":2,"kind":"mc","stem":"로아 글 뒷부분의 모래와 자갈 층 문장 뒤에 무엇을 붙이면 본 것과 느낀 것이 짝지어질까요?","options":[{"t":"「모래와 자갈만으로 물이 걸러진다니 신기했다.」처럼 그때의 마음 한 문장","correct":true},{"t":"모래가 몇 층인지 같은 사실 문장 하나 더","mis":"K6-1-u4-X35"},{"t":"관용 표현 세 개","mis":"K6-1-u4-X07"},{"t":"아무것도 붙이지 않고 다음 문장으로","mis":"K6-1-u4-X35"}],"explanation":["사실을 더하면 사실만 늘어요.","개수는 문제가 아니에요.","본 것 뒤에 마음을 붙여요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb),
('g6_1_kor_u4_review_c#13','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C38',2,'mc','auto','로아가 글을 고쳐 쓸 때 살펴볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X38','K6-1-u4-X07']::text[],false,'{"seq":13,"concept":"K6-1-u4-C38","difficulty":2,"kind":"mc","stem":"로아가 글을 고쳐 쓸 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"견학한 까닭이 드러나는가","correct":true},{"t":"글씨를 예쁘게 썼는가","mis":"K6-1-u4-X38"},{"t":"짝의 글보다 긴가","mis":"K6-1-u4-X38"},{"t":"관용 표현을 많이 넣었는가","mis":"K6-1-u4-X07"}],"explanation":["글씨는 갈래를 정하지 않아요.","길이도 아니에요.","견학 기록문이 갖출 것을 봐요."]}'::jsonb),
('g6_1_kor_u4_review_c#14','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C29',2,'mc','auto','로아의 조직표 끝 칸을 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X28']::text[],false,'{"seq":14,"concept":"K6-1-u4-C29","difficulty":2,"kind":"mc","stem":"로아의 조직표 끝 칸을 알맞게 고친 것은 어느 것인가요?","options":[{"t":"물이 여러 단계를 거친다는 것을 정리하고, 물을 아껴 쓰겠다는 깨달은 점을 쓴다","correct":true},{"t":"「정말 정말 재미있었다」로 늘린다","mis":"K6-1-u4-X30"},{"t":"새로 본 시설을 끝에 더한다","mis":"K6-1-u4-X28"},{"t":"끝 칸을 처음 칸과 바꾼다","mis":"K6-1-u4-X28"}],"explanation":["느낌만 늘리면 일기 같아요.","새 견문은 가운데예요.","끝에는 정리와 깨달음을 써요."],"asset":{"type":"passage","lines":["처음 — 지난 금요일 · 반 친구들과 · 고장의 정수장","가운데 첫째 — 강물 끌어오는 곳 / 알갱이를 뭉쳐 가라앉힘 / (느낀 것 없음)","가운데 둘째 — 모래와 자갈 층 / 물을 거름 / (느낀 것 없음)","가운데 셋째 — 소독하는 곳 / 해로운 균을 없앰 / (느낀 것 없음)","끝 — 정말 재미있었다."],"title":"로아의 조직표 (고치기 전)"}}'::jsonb),
('g6_1_kor_u4_review_c#15','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C13',2,'mc','auto','「귀에 익다」의 뜻을 몰라 찾을 때 알맞은 순서는 어느 것인가요?',ARRAY['K6-1-u4-X14','K6-1-u4-X11','K6-1-u4-X10']::text[],false,'{"seq":15,"concept":"K6-1-u4-C13","difficulty":2,"kind":"mc","stem":"「귀에 익다」의 뜻을 몰라 찾을 때 알맞은 순서는 어느 것인가요?","options":[{"t":"앞뒤 상황으로 짐작 → 「귀」를 사전에서 찾아 뜻풀이 아래 관용구 → 짐작과 맞춰 보기","correct":true},{"t":"사전의 첫 쪽부터 넘기기 → 나올 때까지 읽기","mis":"K6-1-u4-X14"},{"t":"뜻은 모른 채 「귀에 익다」를 통째로 외우기","mis":"K6-1-u4-X11"},{"t":"짐작한 뜻을 찾아보지 않고 정답으로 삼기","mis":"K6-1-u4-X10"}],"explanation":["첫 쪽부터는 오래 걸려요.","뜻을 모른 채 외우면 쓰지 못해요.","짐작한 뒤 확인해요."]}'::jsonb),
('g6_1_kor_u4_review_c#16','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C42',2,'ox','auto','태하가 발표가 끝난 뒤 존댓말로 질문한 것은 공식적인 말하기 예절에 맞아요.',ARRAY['K6-1-u4-X42']::text[],false,'{"seq":16,"concept":"K6-1-u4-C42","difficulty":2,"kind":"ox","stem":"태하가 발표가 끝난 뒤 존댓말로 질문한 것은 공식적인 말하기 예절에 맞아요.","answer":"O","reason_options":[{"t":"발표를 끝까지 듣고 여럿이 듣는 자리에 맞게 존댓말을 썼기 때문에","correct":true},{"t":"질문은 언제나 반말로 해야 하기 때문에","mis":"K6-1-u4-X42"}],"mis":"K6-1-u4-X42","explanation":["끝까지 들었어요.","끝난 뒤 물었어요.","자리에 맞게 존댓말을 썼어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb),
('g6_1_kor_u4_review_c#17','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C7',3,'mc','auto','「입에 침이 마르다」를 알맞게 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X08']::text[],false,'{"seq":17,"concept":"K6-1-u4-C7","difficulty":3,"kind":"mc","stem":"「입에 침이 마르다」를 알맞게 쓴 문장은 어느 것인가요?","options":[{"t":"「할머니께서는 손주 자랑에 입에 침이 마르셨다.」","correct":true},{"t":"「물을 오래 안 마셔 입에 침이 말랐다.」","mis":"K6-1-u4-X01"},{"t":"「짝이 미워서 입에 침이 마르게 흉을 보았다.」","mis":"K6-1-u4-X08"},{"t":"「비밀을 지키느라 입에 침이 말랐다.」","mis":"K6-1-u4-X08"}],"explanation":["실제로 침이 마른 이야기예요.","거듭 칭찬하는 뜻과 어긋나요.","거듭 칭찬하는 자리에 써요."]}'::jsonb),
('g6_1_kor_u4_review_c#18','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C14',3,'mc','auto','「작은 잘못을 그냥 넘기다 보면 큰 잘못이 된다」는 교훈을 담은 속담은 어느 것인가요?',ARRAY['K6-1-u4-X16']::text[],false,'{"seq":18,"concept":"K6-1-u4-C14","difficulty":3,"kind":"mc","stem":"「작은 잘못을 그냥 넘기다 보면 큰 잘못이 된다」는 교훈을 담은 속담은 어느 것인가요?","options":[{"t":"바늘 도둑이 소도둑 된다","correct":true},{"t":"첫술에 배부르랴","mis":"K6-1-u4-X16"},{"t":"빈 수레가 요란하다","mis":"K6-1-u4-X16"},{"t":"서당 개 삼 년이면 풍월을 읊는다","mis":"K6-1-u4-X16"}],"explanation":["한 번에 안 된다는 교훈이에요.","떠드는 이야기예요.","보고 익히는 이야기예요."]}'::jsonb),
('g6_1_kor_u4_review_c#19','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C25',3,'mc','auto','관용 표현으로 대화하기가 부담스러운 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X24']::text[],false,'{"seq":19,"concept":"K6-1-u4-C25","difficulty":3,"kind":"mc","stem":"관용 표현으로 대화하기가 부담스러운 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「쓰고 싶은 상황을 떠올려 공책에 적어 보는 것부터 해 보자.」","correct":true},{"t":"「앞에 나와 크게 말할 때까지 연습해.」","mis":"K6-1-u4-X24"},{"t":"「말로 못 하면 배우지 못한 거야.」","mis":"K6-1-u4-X24"},{"t":"「그럼 관용 표현은 배우지 마.」","mis":"K6-1-u4-X24"}],"explanation":["처음부터 크게 말하지 않아도 돼요.","말 못 해도 배운 거예요.","할 수 있는 만큼부터 해요."]}'::jsonb),
('g6_1_kor_u4_review_c#20','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C36',3,'mc','auto','「종이는 습기와 더위에 약해서 온도와 습도를 일정하게 지킨다」는 문장에 관용 표현을 얹지 않는 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X36','K6-1-u4-X09']::text[],false,'{"seq":20,"concept":"K6-1-u4-C36","difficulty":3,"kind":"mc","stem":"「종이는 습기와 더위에 약해서 온도와 습도를 일정하게 지킨다」는 문장에 관용 표현을 얹지 않는 까닭은 어느 것인가요?","options":[{"t":"사실을 전하는 견문 자리라 얹으면 무엇이 사실인지 흐려지기 때문에","correct":true},{"t":"관용 표현은 글 끝에만 쓸 수 있기 때문에","mis":"K6-1-u4-X36"},{"t":"서고와 관련된 관용 표현이 없기 때문에","mis":"K6-1-u4-X36"},{"t":"관용 표현은 견학 기록문에 쓰면 안 되기 때문에","mis":"K6-1-u4-X09"}],"explanation":["끝에만 쓰는 것이 아니에요.","관련 표현이 있고 없고가 아니에요.","견문은 사실을 전해요."],"asset":{"type":"passage","lines":["다음으로 간 보존 서고는 공기가 서늘했다.","종이는 습기와 더위에 약해서 온도와 습도를 늘 일정하게 지킨다고 했다.","오래된 책은 따로 두고, 넘길 때에도 두 손으로 조심해 다룬다고 한다.","표지가 닳고 손때가 묻은 책들이 나란히 서 있는 모습을 한참 바라보았다.","이번 견학으로 도서관이 책을 지키는 곳이라는 것을 알게 되었다."],"title":"「도서관 서고를 다녀와서」 — 뒷부분"}}'::jsonb),
('g6_1_kor_u4_review_c#21','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C35',3,'mc','auto','생각그물과 조직표를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X35']::text[],false,'{"seq":21,"concept":"K6-1-u4-C35","difficulty":3,"kind":"mc","stem":"생각그물과 조직표를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"생각그물로 떠오르는 대로 모은 뒤 조직표에서 처음 · 가운데 · 끝으로 순서를 잡는다","correct":true},{"t":"조직표로 순서를 먼저 정하고 생각그물은 쓰지 않는다","mis":"K6-1-u4-X35"},{"t":"생각그물만 그리고 바로 글을 끝낸다","mis":"K6-1-u4-X35"},{"t":"둘 다 쓰지 않고 떠오르는 대로 쓴다","mis":"K6-1-u4-X35"}],"explanation":["재료부터 모아요.","순서도 잡아야 해요.","모으고, 나누고, 써요."]}'::jsonb),
('g6_1_kor_u4_review_c#22','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C42',3,'mc','auto','같은 교실에서 학급 회의 때 의견을 말할 때와 짝과 회의 준비를 이야기할 때 예절이 다른 까닭은 어느 것인가요?',ARRAY['K6-1-u4-X42','K6-1-u4-X43']::text[],false,'{"seq":22,"concept":"K6-1-u4-C42","difficulty":3,"kind":"mc","stem":"같은 교실에서 학급 회의 때 의견을 말할 때와 짝과 회의 준비를 이야기할 때 예절이 다른 까닭은 어느 것인가요?","options":[{"t":"같은 교실이어도 듣는 사람과 자리가 달라 편하게 듣는 방법이 달라지기 때문에","correct":true},{"t":"교실이 같으니 예절도 같다","mis":"K6-1-u4-X42"},{"t":"회의 때만 예절이 있다","mis":"K6-1-u4-X43"},{"t":"짝과 이야기할 때는 예절이 필요 없다","mis":"K6-1-u4-X43"}],"explanation":["교실이 같아도 자리가 달라요.","어느 자리에나 예절이 있어요.","듣는 사람을 두고 정해요."]}'::jsonb),
('g6_1_kor_u4_review_c#23','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C29',4,'mc','auto','로아의 조직표 전체를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X35','K6-1-u4-X28']::text[],false,'{"seq":23,"concept":"K6-1-u4-C29","difficulty":4,"kind":"mc","stem":"로아의 조직표 전체를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"처음에 견학한 까닭을 더하고, 가운데마다 느낀 것을 하나씩 짝짓고, 끝에 정리와 깨달은 점을 쓴다","correct":true},{"t":"끝의 「정말 재미있었다」를 세 번 쓴다","mis":"K6-1-u4-X30"},{"t":"가운데 칸을 하나로 합치고 느낌은 뺀다","mis":"K6-1-u4-X35"},{"t":"처음을 지우고 가운데부터 시작한다","mis":"K6-1-u4-X28"}],"explanation":["느낌만 늘리면 일기 같아요.","느낌을 빼면 사실만 남아요.","세 부분을 모두 고쳐요."],"asset":{"type":"passage","lines":["처음 — 지난 금요일 · 반 친구들과 · 고장의 정수장","가운데 첫째 — 강물 끌어오는 곳 / 알갱이를 뭉쳐 가라앉힘 / (느낀 것 없음)","가운데 둘째 — 모래와 자갈 층 / 물을 거름 / (느낀 것 없음)","가운데 셋째 — 소독하는 곳 / 해로운 균을 없앰 / (느낀 것 없음)","끝 — 정말 재미있었다."],"title":"로아의 조직표 (고치기 전)"}}'::jsonb),
('g6_1_kor_u4_review_c#24','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C36',4,'essay','teacher','로아 글 뒷부분에 관용 표현을 하나 넣는다면 어느 문장 뒤에 어떤 표현을 넣을지 쓰고, 그 자리를 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u4-C36","difficulty":4,"kind":"essay","stem":"로아 글 뒷부분에 관용 표현을 하나 넣는다면 어느 문장 뒤에 어떤 표현을 넣을지 쓰고, 그 자리를 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 「수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.」 뒤에 「그동안 물을 펑펑 쓴 것을 생각하니 낯이 뜨거웠다.」를 넣겠다. 이 문장은 깨달은 마음이 드러나는 감상 자리라서 관용 표현이 잘 어울린다. 소독이나 모래층처럼 사실을 전하는 견문 자리에 넣으면 무엇이 사실인지 흐려진다.","scoring_points":["넣을 자리와 관용 표현을 썼는가","그 자리가 감상 자리라는 까닭을 썼는가","견문 자리에 넣지 않는 까닭을 썼는가"]},"explanation":["마음이 드러난 문장을 찾아요.","어울리는 표현을 골라요.","견문 자리와 견줘요."],"asset":{"type":"passage","lines":["다음으로 모래와 자갈을 깐 층으로 물을 거르는 곳에 갔다.","마지막으로 소독을 해서 물속의 해로운 균을 없앤 뒤 집으로 보낸다고 했다.","수도꼭지만 틀면 나오던 물이 이렇게 여러 단계를 거친다는 것을 알았다.","앞으로는 물을 틀어 놓은 채로 양치하지 않아야겠다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 뒷부분"}}'::jsonb),
('g6_1_kor_u4_review_c#25','kor',6,1,'u4','','g6_1_kor_u4_review_c','unit_review','K6-1-u4-C21',4,'essay','teacher','「관용 표현을 고르는 일은 전하고 싶은 마음을 고르는 일이다」라는 말을 예를 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u4-C21","difficulty":4,"kind":"essay","stem":"「관용 표현을 고르는 일은 전하고 싶은 마음을 고르는 일이다」라는 말을 예를 들어 설명하세요.","answer_guide":{"answer":"예: 「정말 하고 싶었다」라고 말하면 뜻은 통하지만, 「마음이 굴뚝같았다」라고 하면 얼마나 하고 싶었는지 그 마음의 크기까지 전해진다. 또 「내가 먼저 가 볼게」 대신 「목마른 사람이 우물 판다잖아. 답답한 내가 먼저 가 볼게」라고 하면 나서는 까닭과 마음이 함께 전해진다. 그래서 관용 표현을 고르는 것은 어떤 마음을 전할지 고르는 일이다.","scoring_points":["그냥 말한 것과 관용 표현을 견준 예를 들었는가","관용 표현으로 더 전해지는 마음을 썼는가","마음을 고르는 일이라는 뜻을 정리했는가"]},"explanation":["그냥 말한 것과 견줘요.","더 전해지는 것을 찾아요.","마음을 고르는 일로 정리해요."]}'::jsonb),
('g6_1_kor_u4_review_d#1','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C3',1,'mc','auto','예로부터 전해 오며 지혜나 교훈을 담은 말을 무엇이라고 하나요?',ARRAY['K6-1-u4-X04','K6-1-u4-X15']::text[],false,'{"seq":1,"concept":"K6-1-u4-C3","difficulty":1,"kind":"mc","stem":"예로부터 전해 오며 지혜나 교훈을 담은 말을 무엇이라고 하나요?","options":[{"t":"속담","correct":true},{"t":"관용어","mis":"K6-1-u4-X04"},{"t":"줄임말","mis":"K6-1-u4-X15"},{"t":"표어","mis":"K6-1-u4-X15"}],"explanation":["관용어는 교훈을 꼭 담지는 않아요.","줄임말은 전해 오는 말이 아니에요.","교훈을 담고 전해 오면 속담이에요."]}'::jsonb),
('g6_1_kor_u4_review_d#2','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C6',1,'mc','auto','관용 표현을 쓸 때 가장 먼저 살필 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X40']::text[],false,'{"seq":2,"concept":"K6-1-u4-C6","difficulty":1,"kind":"mc","stem":"관용 표현을 쓸 때 가장 먼저 살필 것은 어느 것인가요?","options":[{"t":"지금 이 상황에 어울리는가","correct":true},{"t":"몇 개나 넣었는가","mis":"K6-1-u4-X07"},{"t":"얼마나 어려운 표현인가","mis":"K6-1-u4-X40"},{"t":"몇 글자인가","mis":"K6-1-u4-X07"}],"explanation":["개수가 먼저가 아니에요.","어려운 표현이 좋은 것도 아니에요.","상황에 어울리는지가 먼저예요."]}'::jsonb),
('g6_1_kor_u4_review_d#3','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C8',1,'ox','auto','모르는 관용어는 앞뒤 상황을 보고 먼저 짐작해 봐요.',ARRAY['K6-1-u4-X10']::text[],false,'{"seq":3,"concept":"K6-1-u4-C8","difficulty":1,"kind":"ox","stem":"모르는 관용어는 앞뒤 상황을 보고 먼저 짐작해 봐요.","answer":"O","reason_options":[{"t":"짐작한 뒤 사전에서 확인하면 뜻이 오래 남기 때문에","correct":true},{"t":"짐작하면 틀리니 사전부터 펴야 하기 때문에","mis":"K6-1-u4-X10"}],"mis":"K6-1-u4-X10","explanation":["정확히 몰라도 괜찮아요.","앞뒤 상황이 실마리예요.","짐작한 뒤 사전으로 확인해요."]}'::jsonb),
('g6_1_kor_u4_review_d#4','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C18',1,'mc','auto','속담을 사전에서 찾을 때 앞세울 것은 어느 것인가요?',ARRAY['K6-1-u4-X14']::text[],false,'{"seq":4,"concept":"K6-1-u4-C18","difficulty":1,"kind":"mc","stem":"속담을 사전에서 찾을 때 앞세울 것은 어느 것인가요?","options":[{"t":"속담에서 중심이 되는 낱말","correct":true},{"t":"속담 전체 문장","mis":"K6-1-u4-X14"},{"t":"사전의 맨 첫 쪽","mis":"K6-1-u4-X14"},{"t":"속담이 생긴 때","mis":"K6-1-u4-X14"}],"explanation":["문장 전체로 찾지 않아요.","첫 쪽부터 넘기지 않아요.","중심 낱말을 잡아요."]}'::jsonb),
('g6_1_kor_u4_review_d#5','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C23',1,'mc','auto','「낯이 뜨겁다」와 바꿔 쓸 수 있는 표현은 어느 것인가요?',ARRAY['K6-1-u4-X22']::text[],false,'{"seq":5,"concept":"K6-1-u4-C23","difficulty":1,"kind":"mc","stem":"「낯이 뜨겁다」와 바꿔 쓸 수 있는 표현은 어느 것인가요?","options":[{"t":"고개를 들지 못하다","correct":true},{"t":"코앞에 닥치다","mis":"K6-1-u4-X22"},{"t":"목이 빠지게 기다리다","mis":"K6-1-u4-X22"},{"t":"어깨가 무겁다","mis":"K6-1-u4-X22"}],"explanation":["코앞에 닥치다는 급함이에요.","목이 빠지게 기다리다는 간절함이에요.","부끄러운 마음끼리 바꿔요."]}'::jsonb),
('g6_1_kor_u4_review_d#6','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C29',1,'ox','auto','견학 기록문의 끝 부분에는 견학한 내용을 정리하고 깨달은 점을 써요.',ARRAY['K6-1-u4-X28']::text[],false,'{"seq":6,"concept":"K6-1-u4-C29","difficulty":1,"kind":"ox","stem":"견학 기록문의 끝 부분에는 견학한 내용을 정리하고 깨달은 점을 써요.","answer":"O","reason_options":[{"t":"끝은 견학을 정리하고 마무리하는 자리이기 때문에","correct":true},{"t":"끝에는 견학한 까닭과 장소를 처음 밝혀야 하기 때문에","mis":"K6-1-u4-X28"}],"mis":"K6-1-u4-X28","explanation":["까닭과 장소는 처음이에요.","본 것은 가운데예요.","끝에서 정리하고 깨달은 점을 써요."]}'::jsonb),
('g6_1_kor_u4_review_d#7','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C38',1,'mc','auto','쓴 견학 기록문을 나눌 방법을 고르는 기준은 어느 것인가요?',ARRAY['K6-1-u4-X39','K6-1-u4-X38']::text[],false,'{"seq":7,"concept":"K6-1-u4-C38","difficulty":1,"kind":"mc","stem":"쓴 견학 기록문을 나눌 방법을 고르는 기준은 어느 것인가요?","options":[{"t":"내가 정한 읽을 사람이 정말 읽을 수 있는가","correct":true},{"t":"가장 많이 인쇄할 수 있는가","mis":"K6-1-u4-X39"},{"t":"가장 빨리 끝나는가","mis":"K6-1-u4-X39"},{"t":"가장 예뻐 보이는가","mis":"K6-1-u4-X38"}],"explanation":["많이 인쇄한다고 읽는 것이 아니에요.","빨리 끝나는 것이 기준이 아니에요.","읽을 사람에게 닿는지가 기준이에요."]}'::jsonb),
('g6_1_kor_u4_review_d#8','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C39',1,'mc','auto','「어깨너머로 배우다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X12','K6-1-u4-X01','K6-1-u4-X22']::text[],false,'{"seq":8,"concept":"K6-1-u4-C39","difficulty":1,"kind":"mc","stem":"「어깨너머로 배우다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"옆에서 보고 들으며 배우다","correct":true},{"t":"어깨를 다쳐 쉬면서 배우다","mis":"K6-1-u4-X12"},{"t":"친구 어깨 위에 올라가 보다","mis":"K6-1-u4-X01"},{"t":"하기 싫은 사람을 억지로 나서게 하다","mis":"K6-1-u4-X22"}],"explanation":["다친 이야기가 아니에요.","어깨 위에 오른 것도 아니에요.","옆에서 보고 익혀요."]}'::jsonb),
('g6_1_kor_u4_review_d#9','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C15',2,'mc','auto','이든이가 「첫술에 배부르랴」를 쓴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X16']::text[],false,'{"seq":9,"concept":"K6-1-u4-C15","difficulty":2,"kind":"mc","stem":"이든이가 「첫술에 배부르랴」를 쓴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 번에 잘되지 않아도 조금씩 나아질 것이라는 마음을 전하려고","correct":true},{"t":"밥을 먹고 연습하겠다고 하려고","mis":"K6-1-u4-X01"},{"t":"이번 대회는 포기하겠다고 하려고","mis":"K6-1-u4-X16"},{"t":"처음부터 완벽해야 한다고 하려고","mis":"K6-1-u4-X16"}],"explanation":["밥 이야기가 아니에요.","포기하는 말이 아니에요.","한 번에 되지 않아도 괜찮다는 말이에요."],"asset":{"type":"speech","turns":[{"who":"하늬","text":"합창 대회가 코앞에 닥쳤는데 반주를 맡은 이든이가 아직 악보를 다 못 외웠대. 걱정이야."},{"who":"가온","text":"이든이는 늘 잘하잖아. 원숭이도 나무에서 떨어진다고, 이번엔 좀 늦을 수도 있지."},{"who":"이든","text":"사실 어깨가 무거워서 밤마다 연습했어. 그래도 첫술에 배부르랴, 내일은 더 나아질 거야."},{"who":"하늬","text":"그럼 걱정 붙들어 맬게. 우리 모두 네 반주를 목이 빠지게 기다릴게."}]}}'::jsonb),
('g6_1_kor_u4_review_d#10','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C22',2,'ox','auto','「소금 장수와 나루터」에서 「급할수록 돌아가라」는 이야기가 담은 지혜를 한마디로 전해요.',ARRAY['K6-1-u4-X21']::text[],false,'{"seq":10,"concept":"K6-1-u4-C22","difficulty":2,"kind":"ox","stem":"「소금 장수와 나루터」에서 「급할수록 돌아가라」는 이야기가 담은 지혜를 한마디로 전해요.","answer":"O","reason_options":[{"t":"서두르는 대신 돌아가 얕은 여울목으로 건넌 소금 장수의 행동과 이어지기 때문에","correct":true},{"t":"실제로 먼 길을 돌아가라는 뜻만 있기 때문에","mis":"K6-1-u4-X21"}],"mis":"K6-1-u4-X21","explanation":["소금 장수는 서두르지 않았어요.","다른 길을 찾았어요.","돌아가는 지혜가 담겼어요."],"asset":{"type":"passage","lines":["소금 장수는 강을 따라 위쪽으로 반나절을 걸어 얕은 여울목을 찾았다.","그는 지게를 지고 걸어서 강을 건넜고, 소금은 저물녘까지 모두 팔렸다.","그날 하루를 빈 배로 보낸 사공은 다음 날 소금 장수를 다시 만나자","낯이 뜨거워 고개를 들지 못했다."],"title":"옛이야기 「소금 장수와 나루터」 — 뒷부분"}}'::jsonb),
('g6_1_kor_u4_review_d#11','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C27',2,'mc','auto','로아의 글이 견학 기록문으로서 믿을 만한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X26','K6-1-u4-X07','K6-1-u4-X30']::text[],false,'{"seq":11,"concept":"K6-1-u4-C27","difficulty":2,"kind":"mc","stem":"로아의 글이 견학 기록문으로서 믿을 만한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"새로 안 사실(알갱이를 뭉쳐 가라앉힘)이 실제로 참인 내용이기 때문에","correct":true},{"t":"재미있게 지어낸 사실이 많기 때문에","mis":"K6-1-u4-X26"},{"t":"관용 표현을 많이 넣었기 때문에","mis":"K6-1-u4-X07"},{"t":"느낌만 솔직하게 적었기 때문에","mis":"K6-1-u4-X30"}],"explanation":["지어낸 사실은 믿을 수 없어요.","관용 표현 개수와는 상관없어요.","새로 안 사실이 참이어야 해요."],"asset":{"type":"passage","lines":["지난 금요일, 우리 반은 수돗물이 어떻게 만들어지는지 알아보려고","고장의 정수장에 다녀왔다. 학교에서 버스를 타고 강가로 갔다.","먼저 강물을 끌어오는 곳을 보았다. 강물에는 흙 알갱이가 섞여 있어서","약품을 넣어 작은 알갱이끼리 뭉치게 한 뒤 가라앉힌다고 했다.","흙탕물이 맑아지는 모습에 입이 딱 벌어졌다."],"title":"로아의 견학 기록문 「정수장을 다녀와서」 — 앞부분"}}'::jsonb),
('g6_1_kor_u4_review_d#12','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C30',2,'ox','auto','로아 글에서 「입이 딱 벌어졌다」 같은 감상을 모두 지우면 안내문에 가까워져요.',ARRAY['K6-1-u4-X29']::text[],false,'{"seq":12,"concept":"K6-1-u4-C30","difficulty":2,"kind":"ox","stem":"로아 글에서 「입이 딱 벌어졌다」 같은 감상을 모두 지우면 안내문에 가까워져요.","answer":"O","reason_options":[{"t":"감상이 빠지면 사실만 남기 때문에","correct":true},{"t":"감상이 없어도 견학 기록문이 되기 때문에","mis":"K6-1-u4-X29"}],"mis":"K6-1-u4-X29","explanation":["감상은 마음이에요.","마음이 빠지면 사실만 남아요.","사실만 남으면 안내문이에요."]}'::jsonb),
('g6_1_kor_u4_review_d#13','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C34',2,'mc','auto','로아가 이 글을 저학년 동생에게 읽어 준다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X30','K6-1-u4-X34','K6-1-u4-X07']::text[],false,'{"seq":13,"concept":"K6-1-u4-C34","difficulty":2,"kind":"mc","stem":"로아가 이 글을 저학년 동생에게 읽어 준다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「소독」 「약품」처럼 어려운 낱말을 쉽게 풀어 말한다","correct":true},{"t":"새로 안 사실을 모두 뺀다","mis":"K6-1-u4-X30"},{"t":"쓴 그대로 읽는다","mis":"K6-1-u4-X34"},{"t":"관용 표현을 더 넣는다","mis":"K6-1-u4-X07"}],"explanation":["견문을 빼면 안 돼요.","읽을 사람을 생각해요.","동생이 알 수 있게 풀어요."]}'::jsonb),
('g6_1_kor_u4_review_d#14','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C33',2,'ox','auto','로아가 조직표를 짜기 전에 왜 정수장이 기억에 남았는지 한 줄로 적어 두면 감상을 쓰기 쉬워요.',ARRAY['K6-1-u4-X33']::text[],false,'{"seq":14,"concept":"K6-1-u4-C33","difficulty":2,"kind":"ox","stem":"로아가 조직표를 짜기 전에 왜 정수장이 기억에 남았는지 한 줄로 적어 두면 감상을 쓰기 쉬워요.","answer":"O","reason_options":[{"t":"기억에 남은 까닭이 곧 글의 감상이 되기 때문에","correct":true},{"t":"까닭은 글에 쓰지 않는 것이기 때문에","mis":"K6-1-u4-X33"}],"mis":"K6-1-u4-X33","explanation":["까닭을 먼저 적어요.","그 까닭이 마음이에요.","감상으로 이어져요."]}'::jsonb),
('g6_1_kor_u4_review_d#15','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C39',2,'mc','auto','「놀람 · 부끄러움 · 간절함」처럼 묶은 관용 표현 사전을 알맞게 설명한 것은 어느 것인가요?',ARRAY['K6-1-u4-X44']::text[],false,'{"seq":15,"concept":"K6-1-u4-C39","difficulty":2,"kind":"mc","stem":"「놀람 · 부끄러움 · 간절함」처럼 묶은 관용 표현 사전을 알맞게 설명한 것은 어느 것인가요?","options":[{"t":"마음으로 묶은 사전이라 쓸 때 꺼내기 쉽다","correct":true},{"t":"낱말로 묶은 사전이라 찾기 쉽다","mis":"K6-1-u4-X44"},{"t":"아무렇게나 묶은 사전이다","mis":"K6-1-u4-X44"},{"t":"묶지 않아 흩어진 사전이다","mis":"K6-1-u4-X44"}],"explanation":["같은 낱말로 묶은 것이 아니에요.","같은 마음끼리 묶었어요.","마음으로 묶으면 쓰기가 쉬워요."]}'::jsonb),
('g6_1_kor_u4_review_d#16','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C42',2,'mc','auto','시온이의 발표를 고칠 때 세울 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X43']::text[],false,'{"seq":16,"concept":"K6-1-u4-C42","difficulty":2,"kind":"mc","stem":"시온이의 발표를 고칠 때 세울 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 친구들이 편하게 들을 수 있는가","correct":true},{"t":"예절 목록을 몇 개 지켰는가","mis":"K6-1-u4-X43"},{"t":"시온이가 편하게 말할 수 있는가","mis":"K6-1-u4-X43"},{"t":"발표가 얼마나 짧은가","mis":"K6-1-u4-X43"}],"explanation":["목록 개수가 기준이 아니에요.","말하는 사람이 기준이 아니에요.","듣는 사람을 두고 정해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb),
('g6_1_kor_u4_review_d#17','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C6',3,'mc','auto','텃밭 일기 한 편에 관용 표현 네 개를 모두 넣으려는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X07','K6-1-u4-X06']::text[],false,'{"seq":17,"concept":"K6-1-u4-C6","difficulty":3,"kind":"mc","stem":"텃밭 일기 한 편에 관용 표현 네 개를 모두 넣으려는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"상황에 꼭 맞는 하나를 골라 제자리에 놓자","correct":true},{"t":"넷 다 넣으면 더 생생해지니 그대로 넣자","mis":"K6-1-u4-X07"},{"t":"더 찾아서 다섯 개로 늘리자","mis":"K6-1-u4-X07"},{"t":"넷 모두 낱말 뜻대로 풀어 쓰자","mis":"K6-1-u4-X06"}],"explanation":["많이 넣으면 뜻이 흐려져요.","개수를 늘릴 일이 아니에요.","제자리에 하나가 힘이 커요."]}'::jsonb),
('g6_1_kor_u4_review_d#18','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C18',3,'mc','auto','인터넷 사전으로 속담을 찾는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u4-X14','K6-1-u4-X10']::text[],false,'{"seq":18,"concept":"K6-1-u4-C18","difficulty":3,"kind":"mc","stem":"인터넷 사전으로 속담을 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"중심 낱말을 검색한 뒤 관용구와 속담을 갈라 보는 기능을 쓴다","correct":true},{"t":"속담 사전의 첫 쪽부터 넘긴다","mis":"K6-1-u4-X14"},{"t":"짐작한 뜻을 검색해 바로 정답으로 삼는다","mis":"K6-1-u4-X10"},{"t":"속담과 상관없는 낱말을 아무거나 넣는다","mis":"K6-1-u4-X14"}],"explanation":["인터넷 사전은 넘기지 않아요.","짐작은 확인해야 해요.","중심 낱말을 앞세워요."]}'::jsonb),
('g6_1_kor_u4_review_d#19','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C26',3,'mc','auto','「발등에 불이 떨어지다」로 짧은 대화를 지을 때 알맞은 상황은 어느 것인가요?',ARRAY['K6-1-u4-X01','K6-1-u4-X25']::text[],false,'{"seq":19,"concept":"K6-1-u4-C26","difficulty":3,"kind":"mc","stem":"「발등에 불이 떨어지다」로 짧은 대화를 지을 때 알맞은 상황은 어느 것인가요?","options":[{"t":"숙제 마감이 내일 아침인데 아직 시작하지 않은 동생에게 형이 말하는 장면","correct":true},{"t":"불꽃놀이를 구경하는 장면","mis":"K6-1-u4-X01"},{"t":"시간이 많이 남아 느긋한 장면","mis":"K6-1-u4-X25"},{"t":"상을 받아 기뻐하는 장면","mis":"K6-1-u4-X25"}],"explanation":["실제 불 이야기가 아니에요.","느긋한 것과 반대예요.","몹시 급한 상황에 맞아요."]}'::jsonb),
('g6_1_kor_u4_review_d#20','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C27',3,'mc','auto','견학한 곳을 이름 없는 곳으로 지어 쓸 때 꼭 지켜야 할 것은 어느 것인가요?',ARRAY['K6-1-u4-X26','K6-1-u4-X29']::text[],false,'{"seq":20,"concept":"K6-1-u4-C27","difficulty":3,"kind":"mc","stem":"견학한 곳을 이름 없는 곳으로 지어 쓸 때 꼭 지켜야 할 것은 어느 것인가요?","options":[{"t":"그 안에서 새로 안 사실은 실제로 참이어야 한다","correct":true},{"t":"새로 안 사실도 마음껏 지어도 된다","mis":"K6-1-u4-X26"},{"t":"견학한 곳은 반드시 유명한 곳이어야 한다","mis":"K6-1-u4-X26"},{"t":"감상은 빼야 한다","mis":"K6-1-u4-X29"}],"explanation":["사실을 지으면 거짓을 전해요.","이름 없는 곳도 괜찮아요.","무대는 지어도 사실은 참이어야 해요."]}'::jsonb),
('g6_1_kor_u4_review_d#21','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C32',3,'mc','auto','견학 기록문을 쓰는 까닭을 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u4-X32','K6-1-u4-X37']::text[],false,'{"seq":21,"concept":"K6-1-u4-C32","difficulty":3,"kind":"mc","stem":"견학 기록문을 쓰는 까닭을 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"쓰는 사람에게도 남고, 읽는 사람에게도 건너간다","correct":true},{"t":"글씨 연습과 낱말 외우기에 좋다","mis":"K6-1-u4-X32"},{"t":"정해진 칸을 채우는 연습이 된다","mis":"K6-1-u4-X37"},{"t":"견학 숙제를 빨리 끝낼 수 있다","mis":"K6-1-u4-X32"}],"explanation":["글씨 연습이 목적이 아니에요.","칸 채우기가 아니에요.","남기고, 전하고, 도움이 돼요."]}'::jsonb),
('g6_1_kor_u4_review_d#22','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C39',3,'mc','auto','동물이 든 표현과 몸이 든 표현으로 나눈 사전의 좋은 점은 어느 것인가요?',ARRAY['K6-1-u4-X11','K6-1-u4-X44','K6-1-u4-X40']::text[],false,'{"seq":22,"concept":"K6-1-u4-C39","difficulty":3,"kind":"mc","stem":"동물이 든 표현과 몸이 든 표현으로 나눈 사전의 좋은 점은 어느 것인가요?","options":[{"t":"같은 낱말로 묶어 필요할 때 빨리 찾을 수 있다","correct":true},{"t":"쓸 상황을 적지 않아도 된다","mis":"K6-1-u4-X11"},{"t":"마음으로 묶은 것과 똑같다","mis":"K6-1-u4-X44"},{"t":"표현 개수가 저절로 많아진다","mis":"K6-1-u4-X40"}],"explanation":["쓸 상황은 늘 적어요.","마음으로 묶은 것과는 달라요.","낱말로 묶으면 찾기가 쉬워요."]}'::jsonb),
('g6_1_kor_u4_review_d#23','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C42',4,'mc','auto','시온이네 반 발표 장면 전체를 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u4-X42','K6-1-u4-X43']::text[],false,'{"seq":23,"concept":"K6-1-u4-C42","difficulty":4,"kind":"mc","stem":"시온이네 반 발표 장면 전체를 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"시온이는 목소리 크기 · 자세 · 존댓말을, 다인이는 경청을 고쳐야 하고, 태하는 공식적인 자리에 맞게 말했다","correct":true},{"t":"세 사람 모두 예절을 잘 지켰다","mis":"K6-1-u4-X42"},{"t":"태하가 끼어들어 잘못했다","mis":"K6-1-u4-X43"},{"t":"다인이는 작은 소리라 괜찮고 시온이만 고치면 된다","mis":"K6-1-u4-X43"}],"explanation":["잘못한 사람이 있어요.","태하는 끝난 뒤 물었어요.","다인이도 경청하지 않았어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb),
('g6_1_kor_u4_review_d#24','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C42',4,'essay','teacher','시온이의 발표를 공식적인 말하기 예절에 맞게 고쳐 쓰고, 「듣는 사람이 편하게 들을 수 있는가」라는 기준으로 고친 까닭을 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u4-C42","difficulty":4,"kind":"essay","stem":"시온이의 발표를 공식적인 말하기 예절에 맞게 고쳐 쓰고, 「듣는 사람이 편하게 들을 수 있는가」라는 기준으로 고친 까닭을 설명하세요.","answer_guide":{"answer":"예: (반 친구들을 바라보며, 모두에게 들리는 목소리로) 「저희 모둠은 정수장에 대해 알아보았습니다. 정수장에서는 물을 여러 단계를 거쳐 깨끗하게 만든다고 합니다.」 여럿이 듣는 자리라 작은 목소리로는 뒤쪽 친구들이 들을 수 없고, 칠판을 보고 말하면 듣는 사람이 집중하기 어렵다. 또 공식적인 자리이므로 존댓말을 써야 듣는 사람이 편하게 들을 수 있다.","scoring_points":["존댓말로 고쳐 썼는가","목소리 크기와 자세를 고쳤는가","듣는 사람을 기준으로 까닭을 설명했는가"]},"explanation":["말을 고쳐요.","목소리와 자세도 고쳐요.","듣는 사람을 두고 설명해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이제 시온이가 모둠에서 조사한 내용을 반 친구들 앞에서 발표하겠습니다."},{"who":"시온","text":"(작은 목소리로, 칠판 쪽을 보며) 우리 모둠은 정수장에 대해 알아봤어. 물을 여러 번 거른대."},{"who":"다인","text":"(발표 도중에 짝에게) 이따 쉬는 시간에 뭐 할래?"},{"who":"태하","text":"(발표가 끝나자) 잘 들었습니다. 소독은 어떻게 하는지 여쭤봐도 될까요?"}]}}'::jsonb),
('g6_1_kor_u4_review_d#25','kor',6,1,'u4','','g6_1_kor_u4_review_d','unit_review','K6-1-u4-C41',4,'essay','teacher','나만의 관용 표현 사전에 넣을 표현 하나를 골라 표현 · 뜻 · 쓸 수 있는 상황을 쓰고, 그 표현을 고른 기준을 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u4-C41","difficulty":4,"kind":"essay","stem":"나만의 관용 표현 사전에 넣을 표현 하나를 골라 표현 · 뜻 · 쓸 수 있는 상황을 쓰고, 그 표현을 고른 기준을 설명하세요.","answer_guide":{"answer":"예: 표현 — 귀에 익다. 뜻 — 여러 번 들어 익숙하다. 쓸 수 있는 상황 — 처음 배우는 노래인데 엄마가 자주 부르셔서 이미 익숙할 때. 고른 기준 — 어렵거나 멋있어 보이는 표현보다 이번 달에 내가 실제로 쓸 자리가 떠오르는 표현이라서 골랐다.","scoring_points":["표현과 뜻을 바르게 썼는가","내가 겪은 쓸 상황을 썼는가","내가 쓸 자리가 떠오르는가라는 기준을 썼는가"]},"explanation":["표현을 하나 골라요.","세 칸을 채워요.","고른 기준을 써요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K6-1-u5-C1','kor',6,1,'u5',1,'주장하는 글의 뜻 — 주장하는 글은 어떤 문제에 대해 다른 사람을 설득할 목적으로 쓰는 글로, 본 것을 그대로 전하는 글이나 마음을 적는 일기와 달리 「어떻게 하면 좋겠다」는 생각을 세워 남을 움직이려 한다',ARRAY['6국03-02 쓰기']::text[],1),
('K6-1-u5-C2','kor',6,1,'u5',1,'주장 · 이유 · 근거 — 주장은 어떤 문제에 대해 내세우는 글쓴이의 의견, 이유는 그렇게 주장하는 주관적인 까닭, 근거는 이유를 뒷받침하는 객관적인 자료이며, 주장만 있으면 우기는 말이 되고 근거가 없으면 혼자만의 생각에 머문다 — 본 것을 그대로 말한 문장은 주장이 아니라 문제 상황이다',ARRAY['6국03-02 쓰기']::text[],2),
('K6-1-u5-C3','kor',6,1,'u5',1,'주장하는 글을 쓰면 좋은 점 — 왜 그렇게 여기는지 스스로 따져 보게 되어 생각이 정돈되고 · 글로 남아 여러 사람을 움직이며 · 무엇이 문제인지 찾다 보면 둘레를 다시 보게 되고, 함께 쓰는 곳을 위한 글이라 쓰는 사람에게 책임이 따른다',ARRAY['6국03-02 쓰기']::text[],3),
('K6-1-u5-C4','kor',6,1,'u5',1,'문제마다 다른 주장 — 같은 학교 안이라도 무엇이 불편한지가 다르면 펼칠 주장도 달라지므로, 먼저 불편을 잡고 그 불편을 없앨 방법을 주장으로 세운다(사물함 칸이 없다 → 반마다 칸을 정하자)',ARRAY['6국03-02 쓰기']::text[],4),
('K6-1-u5-C5','kor',6,1,'u5',1,'쓰는 동안 점검하면 좋은 점 — 점검하지 않고 쓰면 다 쓰고 나서야 하려던 말이 아니었음을 깨달아 고칠 곳이 한꺼번에 몰리지만, 쓰면서 점검하면 어긋난 부분을 그때그때 바로잡고 내 글을 한 걸음 떨어져 볼 수 있다',ARRAY['6국03-05 쓰기']::text[],5),
('K6-1-u5-C6','kor',6,1,'u5',1,'완성이 아니라 과정 — 이 단원은 흠 없는 글 한 편을 내놓는 시간이 아니라 쓰고 살펴보고 고치는 길을 익히는 시간이며, 처음부터 잘 쓴 사람이 아니라 다시 살펴본 사람이 좋은 글에 닿으므로 우선 한 줄부터 적어 본다',ARRAY['6국03-05 쓰기']::text[],6),
('K6-1-u5-C7','kor',6,1,'u5',2,'이유는 내 생각, 근거는 밖에서 — 이유는 「∼하기 때문이다」로 이어지는 내 주관적인 까닭이고, 근거는 조사 결과 · 기사 · 전문가의 말처럼 밖에서 가져와 누구나 확인할 수 있는 자료라서, 둘을 섞지 않는 것이 첫걸음이다',ARRAY['6국03-02 쓰기']::text[],7),
('K6-1-u5-C8','kor',6,1,'u5',2,'글에서 근거 찾기 — 글쓴이의 생각을 말한 문장과, 밖에서 가져와 출처를 붙인 자료를 갈라 보면 근거가 보이며, 설문 결과 · 직접 센 기록 · 선생님 면담처럼 누구나 확인할 수 있는 것이 근거다',ARRAY['6국03-02 쓰기']::text[],8),
('K6-1-u5-C9','kor',6,1,'u5',2,'이유의 타당성 — 이유를 볼 때에는 「주장과 이유가 관련 있는가」 · 「이유가 주장을 잘 설명하는가」를 물으며, 옳은 말이어도 주장과 이어지지 않으면(운동장을 나누자 ← 급식을 남기면 아깝다) 이유가 되지 못한다',ARRAY['6국03-02 쓰기']::text[],9),
('K6-1-u5-C10','kor',6,1,'u5',2,'근거의 타당성 — 근거를 볼 때에는 「이유와 근거가 관련 있는가」 · 「근거의 출처를 믿을 수 있는가」 · 「이유를 뒷받침하는 객관적인 자료인가」를 묻고, 주장하는 글은 고개를 끄덕이며만 읽지 않고 「정말 그런가」를 물으며 읽는다',ARRAY['6국03-02 쓰기']::text[],10),
('K6-1-u5-C11','kor',6,1,'u5',2,'서론 — 서론은 문제 제기와 주장 밝히기를 하는 부분으로, 왜 이 글을 쓰게 되었는지 · 지금 무엇이 불편한지를 밝히고 글쓴이의 의견을 뚜렷이 드러내며, 이어서 무엇을 살펴볼지 한 줄로 안내하기도 한다',ARRAY['6국03-02 쓰기']::text[],11),
('K6-1-u5-C12','kor',6,1,'u5',2,'본론 — 본론은 이유와 그 이유를 뒷받침하는 근거로 주장을 펼쳐 나가는 부분으로, 이유는 「첫째 · 둘째」처럼 갈라 적으면 따라오기 쉽고, 하나의 이유에 근거가 여러 개 붙기도 한다',ARRAY['6국03-02 쓰기']::text[],12),
('K6-1-u5-C13','kor',6,1,'u5',2,'결론 — 결론은 앞에서 말한 이유를 짧게 모아 요약하고 주장을 한 번 더 강조하는 부분이며, 때로는 「이렇게 하면 어떻게 될 것이다」처럼 앞을 내다보는 내용을 담고, 처음 꺼내는 새 근거를 두는 부분이 아니다',ARRAY['6국03-02 쓰기']::text[],13),
('K6-1-u5-C14','kor',6,1,'u5',2,'중심 문장과 뒷받침 문장 — 중심 문장은 그 문단을 대표하는 한 문장이고 나머지는 그것을 받쳐 주는 뒷받침 문장이며, 본론 문단에서는 대개 「첫째, ∼하기 때문이다」가 중심 문장이고 수나 조사 결과가 든 문장은 대개 뒷받침 문장이다 — 중심 문장만 이어 읽으면 글의 뼈대가 드러난다',ARRAY['6국03-02 쓰기']::text[],14),
('K6-1-u5-C15','kor',6,1,'u5',2,'출처가 붙었다고 다 타당하지는 않다 — 출처는 자료가 어디서 왔는지를 알려 줄 뿐이라 「이 자료가 이 이유를 정말 뒷받침하는가」를 한 번 더 보아야 하며, 타당하다고 판단했다면 그렇게 판단한 까닭도 함께 말할 수 있어야 한다 — 「그냥 그럴 것 같아서」는 판단이 아니다',ARRAY['6국03-02 쓰기']::text[],15),
('K6-1-u5-C16','kor',6,1,'u5',4,'인용 자료의 갈래 — 주장하는 글에는 수로 나타낸 통계 자료 · 그 일을 잘 아는 사람의 전문가 의견 · 누구나 확인할 수 있는 기록이나 규칙인 사실 자료 · 실험이나 조사의 결과가 들어오며, 넷 다 내가 만든 것이 아니라 출처를 밝혀야 한다',ARRAY['6국03-02 쓰기']::text[],16),
('K6-1-u5-C17','kor',6,1,'u5',4,'인용과 표절 — 인용은 다른 사람의 말이나 글 · 자료를 가져와 내 글에서 쓰는 것으로 글을 튼튼하게 하지만, 출처를 밝히지 않거나 · 여러 글에서 조각조각 가져와 내 글인 척하거나 · 표나 사진을 출처 없이 쓰면 표절이 된다',ARRAY['6국03-02 쓰기']::text[],17),
('K6-1-u5-C18','kor',6,1,'u5',4,'출처를 밝히는 까닭 — 출처를 밝히면 만든 사람의 권리를 지키고 · 어디까지가 내 말인지 읽는 사람이 알 수 있고 · 원래 어떤 상황에서 나온 말인지 확인할 수 있어 뜻이 정확히 전해지며, 이것은 예의가 아니라 지켜야 할 약속이다',ARRAY['6국03-02 쓰기']::text[],18),
('K6-1-u5-C19','kor',6,1,'u5',4,'뜻을 비틀지 않기 — 인용에는 출처를 밝히는 일과 뜻을 왜곡하지 않는 일이 함께 붙으므로, 만든 사람이 하려던 말을 먼저 정확히 이해하고 그대로 살려 옮긴 뒤 출처를 붙이며, 출처를 적었어도 뜻을 과장하거나 비틀면 소용이 없다',ARRAY['6국03-02 쓰기']::text[],19),
('K6-1-u5-C20','kor',6,1,'u5',4,'저작물 · 저작자 · 저작권 — 저작물은 사람의 생각이나 감정을 표현한 창작물, 저작자는 그것을 만든 사람, 저작권은 저작자가 저작물에 대해 가지는 권리이며, 글 · 그림 · 사진 · 노래 · 영상이 모두 저작물이고 내가 쓴 주장하는 글도 저작물이라 나도 저작자다',ARRAY['6국03-02 쓰기']::text[],20),
('K6-1-u5-C21','kor',6,1,'u5',4,'출처의 네 가지 — 출처에는 누가 만들었는가(만든 사람이나 기관) · 언제 나왔는가(만든 시기) · 무엇인가(자료의 이름) · 어디에 실렸는가(실린 곳)가 들어가며, 네 가지가 다 있어야 읽는 사람이 직접 찾아가 확인할 수 있다 — 하나라도 빠지면 「어딘가에서 봤다」와 다르지 않다',ARRAY['6국03-02 쓰기']::text[],21),
('K6-1-u5-C22','kor',6,1,'u5',4,'출처 적는 차례와 부호 — 출처를 적는 차례와 부호는 조금씩 다를 수 있지만 네 가지가 빠지지 않는 것이 중요하며, 표나 그래프를 가져올 때에는 제목과 만든 곳을 함께 적는다',ARRAY['6국03-02 쓰기']::text[],22),
('K6-1-u5-C23','kor',6,1,'u5',4,'믿을 수 있는 자료 — 공공 기관의 누리집 · 신문과 방송의 기사 · 학교가 낸 기록 · 내가 직접 한 조사와 면담은 믿을 만하고, 누가 썼는지 · 언제 올라왔는지 모르는 글이나 옮겨 적은 것만 있는 글은 한 번 더 확인하며, 직접 조사한 자료도 언제 · 누구에게 · 어디서 했는지 적어 두면 훌륭한 근거가 된다',ARRAY['6국03-02 쓰기']::text[],23),
('K6-1-u5-C24','kor',6,1,'u5',4,'많이 인용할수록 좋은 글이 아니다 — 자료를 잔뜩 붙이고 내 문장이 몇 줄뿐이면 글쓴이의 생각이 남지 않으므로, 내 이유를 세우고 그 이유에 꼭 맞는 자료를 붙이며, 주장과 분명한 관련이 없는 자료는 글을 무겁게만 한다',ARRAY['6국03-02 쓰기']::text[],24),
('K6-1-u5-C25','kor',6,1,'u5',4,'쓰기 윤리 — 글을 쓰는 사람은 확인되지 않은 사실을 쓰지 않았는가 · 인용할 때 출처를 정확히 밝혔는가 · 다른 사람을 헐뜯는 말을 쓰지 않았는가를 스스로 물으며, 글의 길이나 어려운 낱말의 수는 쓰기 윤리와 관계가 없다',ARRAY['6국03-02 쓰기']::text[],25),
('K6-1-u5-C26','kor',6,1,'u5',6,'주제 · 목적 · 대상 — 주장을 펼치기 전에 어떤 문제를 다룰지(주제) · 무엇을 이루고 싶은지(목적) · 누가 들을지(대상)를 정하면 할 말이 좁혀지며, 대상이 달라지면 주장 자체가 아니라 고르는 근거와 말하는 방법이 달라진다',ARRAY['6국03-02 쓰기']::text[],26),
('K6-1-u5-C27','kor',6,1,'u5',6,'주장은 명료하게 — 주장은 무엇을 하자는 것인지 한 가지로 읽혀야 하며(「비 오는 날 우산은 우산꽂이에 꽂읍시다」), 뜻이 흐리거나(「우산을 잘 관리합시다」) 두 가지로 읽히면(「복도를 더 좋게 만듭시다」) 아무리 좋은 근거를 붙여도 무엇을 설득당한 것인지 남지 않는다',ARRAY['6국03-02 쓰기']::text[],27),
('K6-1-u5-C28','kor',6,1,'u5',6,'이유 세우기 — 이유는 내 주관적인 까닭이지만 하나하나가 주장을 뒷받침해야 하므로, 주장이 이루어지면 사라지는 불편이라야 이유가 되고, 주장과 이어지지 않으면 사실이어도 이유가 되지 못한다',ARRAY['6국03-02 쓰기']::text[],28),
('K6-1-u5-C29','kor',6,1,'u5',6,'근거를 찾는 길 — 직접 조사하기(설문 · 수 세기) · 여쭈어 보기(면담) · 기사와 책 찾기 · 공공 자료 보기 가운데 어느 길로 찾든, 이 자료가 그 이유를 정말 뒷받침하는가와 출처를 믿을 수 있는가를 보며, 이유가 말하는 낱말(넘어짐 · 잃어버림 · 미끄러움)이 든 자료를 짝짓는다',ARRAY['6국03-02 쓰기']::text[],29),
('K6-1-u5-C30','kor',6,1,'u5',6,'객관적인 자료 — 「나는 그렇게 느꼈다」나 「아마 다들 그럴 것이다」는 아무리 진심이어도 객관적인 자료가 아니며, 그 자리에 없던 사람도 나중에 찾아가 확인할 수 있어야 근거다',ARRAY['6국03-02 쓰기']::text[],30),
('K6-1-u5-C31','kor',6,1,'u5',6,'예상되는 반박에 대비하기 — 반대할 사람이 할 말을 미리 떠올리는 것은 내 주장을 차갑게 다시 보는 일로, 못 들은 척하면 발표하는 그 자리에서 무너지지만 맞는 말을 받아들여 내용을 보태면 주장이 더 단단해진다',ARRAY['6국03-02 쓰기']::text[],31),
('K6-1-u5-C32','kor',6,1,'u5',6,'말로 먼저 펼쳐 보기 — 정리한 내용을 종이에 쓰기 전에 서론(문제와 주장) → 본론(이유마다 근거와 출처) → 결론(주장을 다시 힘주어) 차례로 소리 내어 말해 보면 쓰기 부담이 줄고, 말한 뒤 주장이 뚜렷했는지 · 출처를 밝혔는지 스스로 확인한다',ARRAY['6국03-02 쓰기']::text[],32),
('K6-1-u5-C33','kor',6,1,'u5',8,'주제를 고르는 두 조건 — 주장하는 글의 주제는 주장 · 이유 · 근거를 댈 수 있고 · 여러 사람에게 알릴 만한 문제여야 하며, 좋은 주제는 내가 실제로 겪은 일 가운데 우리가 바꿀 수 있는 일에서 나온다 — 나 혼자만의 일이나 근거를 찾을 수 없는 일은 글이 되지 않는다',ARRAY['6국03-05 쓰기']::text[],33),
('K6-1-u5-C34','kor',6,1,'u5',8,'계획하기 — 계획하기는 글을 쓸 준비를 하는 과정으로 글을 쓰는 목적 · 글의 주제 · 글을 읽을 사람을 정하며, 이것이 정해지면 어떤 말투로 쓸지와 어떤 근거를 고를지도 함께 정해진다',ARRAY['6국03-05 쓰기']::text[],34),
('K6-1-u5-C35','kor',6,1,'u5',8,'계획하기는 쓰기 전에만이 아니다 — 계획하기는 글을 쓰기 전에만 거치는 단계가 아니라, 쓰다가 읽을 사람이 달라져야 함을 알면 언제든 계획으로 되돌아가 고칠 수 있으며, 어긋난 계획을 붙들고 끝까지 가지 않는다',ARRAY['6국03-05 쓰기']::text[],35),
('K6-1-u5-C36','kor',6,1,'u5',8,'내용 생성하기 — 내용 생성하기는 쓸 거리를 떠올리고 자료를 모으는 과정으로, 핵심 낱말과 짧은 문장으로 떠오르는 것을 최대한 많이 꺼내 놓고(문장 다듬기는 나중), 찾은 자료의 출처를 그때 함께 적어 두어야 나중에 찾아 헤매지 않는다',ARRAY['6국03-05 쓰기']::text[],36),
('K6-1-u5-C37','kor',6,1,'u5',8,'내용 조직하기와 통일성 — 내용 조직하기는 떠올린 것을 서론 · 본론 · 결론 짜임에 맞게 늘어놓아 개요를 짜는 과정이며, 이때 글의 주제와 세부 내용이 서로 가깝게 이어지는 성질인 통일성을 살펴 옳은 말이라도 주제와 이어지지 않는 내용은 걸러 낸다',ARRAY['6국03-05 쓰기']::text[],37),
('K6-1-u5-C38','kor',6,1,'u5',8,'중심 문장부터 세우기 — 중심 문장이 없으면 문단이 어색해지지만 뒷받침 문장은 없어도 문단이 하나의 생각을 담을 수 있으므로, 문단을 짤 때에는 「이 문단에서 하고 싶은 말」을 한 문장으로 먼저 세우고 그 아래에 근거와 설명을 붙인다',ARRAY['6국03-05 쓰기']::text[],38),
('K6-1-u5-C39','kor',6,1,'u5',8,'표현하기 — 표현하기는 조직한 것을 바탕으로 스스로 문장을 써 처음 글을 쓰는 과정으로, 조직하기까지 낱말과 어구로 적었던 것을 문장으로 풀며, 읽을 사람이 이해할 수 있게 쓰고, 쓰다가 더 좋은 생각이 떠오르면 앞 단계로 돌아가 내용을 보태도 된다',ARRAY['6국03-05 쓰기']::text[],39),
('K6-1-u5-C40','kor',6,1,'u5',10,'점검하고 조정하기 — 점검은 다 쓴 뒤에 채점하는 일이 아니라 쓰는 도중에 내가 한 일을 되돌아보고 · 고칠 곳을 찾고 · 방향을 다시 잡는 일이며, 쓰기 과정 다섯 단계 한가운데에 놓여 어느 단계에서나 일어난다',ARRAY['6국03-05 쓰기']::text[],40),
('K6-1-u5-C41','kor',6,1,'u5',10,'쓰기 과정 다섯 단계 — 계획하기(목적 · 주제 · 읽을 사람 정하기) → 내용 생성하기(쓸 거리 떠올리고 자료 모으기) → 내용 조직하기(짜임에 맞게 늘어놓기) → 표현하기(문장으로 써 내려가기) → 고쳐쓰기(손볼 곳 찾아 고치기)',ARRAY['6국03-05 쓰기']::text[],41),
('K6-1-u5-C42','kor',6,1,'u5',10,'쓰기는 되돌아오는 성질을 지닌다 — 쓰기 과정은 앞으로만 가는 길이 아니라 쓰다가 근거가 약하면 내용 생성하기로, 조직하다가 계획으로 되돌아가는 것이 정상이며, 되돌아가는 것은 처음부터 다시 하는 실패가 아니라 쓰기의 성질이라 되돌아간 단계에서 글이 좋아진다',ARRAY['6국03-05 쓰기']::text[],42),
('K6-1-u5-C43','kor',6,1,'u5',10,'단계마다 점검할 것 — 계획하기는 목적 · 주제 · 읽을 사람을 정했는가, 내용 생성하기는 아는 것을 먼저 꺼내고 모자란 부분을 채울 자료를 찾았는가, 내용 조직하기는 짜임에 맞게 · 관련 있는 것끼리 묶어 늘어놓았는가, 표현하기는 짜임대로 문장이 되었고 읽을 사람이 알아듣는가를 묻는다 — 표현하기 점검의 잣대는 내가 아니라 읽을 사람이다',ARRAY['6국03-05 쓰기']::text[],43),
('K6-1-u5-C44','kor',6,1,'u5',10,'점검은 흠 잡기가 아니다 — 고칠 곳을 찾아냈다는 것은 볼 줄 알게 되었다는 뜻이고 이 단원이 재는 것은 완성된 글의 흠이 아니라 고쳐 가는 과정이므로, 다시 쓰기가 버거우면 원래 글 위에 쪽지를 붙여 고칠 말만 얹어도 되고 한 군데만 고쳐도 점검을 한 것이다',ARRAY['6국03-05 쓰기']::text[],44),
('K6-1-u5-C45','kor',6,1,'u5',10,'고쳐쓰기의 세 수준 — 글 수준(주제가 드러나는가 · 짜임에 맞는가) · 문단 수준(중심 문장을 뒷받침 문장이 받치는가 · 문장끼리 이어지는가) · 문장과 낱말 수준(이해하기 쉬운가 · 띄어쓰기와 맞춤법)으로 나누어 고치며, 큰 것부터 손보면 헛수고가 줄지만 반드시 이 차례일 필요는 없어 눈에 띄는 곳부터 손대도 된다',ARRAY['6국03-05 쓰기']::text[],45),
('K6-1-u5-C46','kor',6,1,'u5',10,'띄어쓰기와 맞춤법 살피기 — 문장과 낱말 수준에서는 띄어쓰기가 바른가 · 맞춤법이 틀리지 않았는가 · 읽는 사람이 알기 쉬운 낱말을 골랐는가를 민감하게 살펴 바르게 고치며(「안돼요」 → 「안 돼요」), 이것도 글쓰기의 한 부분이다',ARRAY['6국04-06 문법']::text[],46),
('K6-1-u5-C47','kor',6,1,'u5',12,'실천할 문제와 한 문장 주장 — 실천 활동의 문제는 우리 힘으로 바꿀 수 있고 근거를 댈 수 있어야 하며(비 오는 날이 많다 ✗), 주장은 「∼합시다 · ∼하지 맙시다」처럼 할 일이 드러나는 한 문장으로 만든다 — 길어질수록 흐려진다',ARRAY['6국03-02 쓰기']::text[],47),
('K6-1-u5-C48','kor',6,1,'u5',12,'주장을 펼치는 여러 방법과 근거 — 만화 · 공익 광고 · 표어 · 노랫말 바꾸기처럼 방법은 여러 가지지만 주장 · 이유 · 근거는 그대로 있어야 하며, 큰 글씨나 화려한 그림은 눈길을 끌 뿐 생각을 바꾸지 못하므로 어떤 방법이든 확인할 수 있는 근거 하나는 남긴다 — 사람을 움직이는 것은 목소리의 크기가 아니라 근거다',ARRAY['6국03-02 쓰기']::text[],48),
('K6-1-u5-C49','kor',6,1,'u5',12,'네 칸 짜임 — 의견(하고 싶은 말 한 문장) → 까닭(왜 그렇게 여기는지) → 사례(실제로 있었던 일이나 조사 결과) → 제안(그러니 이렇게 하자)의 네 칸은 서론 · 본론 · 결론을 짧게 줄인 틀로, 표어 · 만화 · 짧은 알림 글처럼 길게 쓸 수 없는 곳에서 근거가 사라지는 것을 막는다',ARRAY['6국03-02 쓰기']::text[],49),
('K6-1-u5-C50','kor',6,1,'u5',12,'말한 대로 해 보기 — 주장하는 글이 닿아야 할 마지막 걸음은 종이가 아니라 생활이라, 내가 알린 대로 내가 먼저 일주일 동안 해 보고 날마다 지켰는지 표시하고 무엇이 달라졌는지 적으며, 잘된 점과 아쉬운 점 한 줄이 다음 주장의 출발선이 된다',ARRAY['6국03-02 쓰기']::text[],50),
('K6-1-u5-C51','kor',6,1,'u5',12,'흐린 출처 알아보기 — 「어떤 조사에 따르면」 · 「어떤 선생님께서」처럼 누가 · 언제 · 무엇을 · 어디에 실었는지가 빠진 출처는 읽는 사람이 확인할 길이 없어 근거가 아니라 짐작이나 떠도는 말이 되며, 만든 사람의 권리도 지키지 못한 것이 된다',ARRAY['6국03-02 쓰기']::text[],51),
('K6-1-u5-C52','kor',6,1,'u5',12,'비와 눈을 가리키는 우리말 — 같은 비 · 눈이라도 언제 · 얼마나 · 어떻게 내리느냐에 따라 여우비(볕이 난 날 잠깐 오다 그치는 비) · 먼지잼(먼지나 겨우 가라앉힐 만큼 조금 오는 비) · 밤비(밤에 내리는 비) · 도둑눈(밤사이 사람들 모르게 내린 눈) · 숫눈(쌓인 뒤 아무도 밟지 않은 눈) · 가루눈(가루처럼 잘게 내리는 눈)처럼 이름이 달라지며, 사전에서 「비」나 「눈」을 표제어로 잡고 딸린 말을 찾아 넓힌다 (기초 다지기)',ARRAY['기초 다지기(우리말)']::text[],52)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K6-1-u5-X01','kor',6,'u5',ARRAY['K6-1-u5-C1']::text[],'주장하는 글을 본 것을 그대로 전하는 글이나 마음만 적는 일기와 같은 글로 여긴다','설득할 목적이 있나?'),
('K6-1-u5-X02','kor',6,'u5',ARRAY['K6-1-u5-C2','K6-1-u5-C4']::text[],'본 것을 그대로 말한 문제 상황 문장을 주장으로 고른다','어떻게 하자고 내세웠나?'),
('K6-1-u5-X03','kor',6,'u5',ARRAY['K6-1-u5-C7','K6-1-u5-C2']::text[],'이유와 근거를 섞어, 내 생각을 근거로 여기거나 밖에서 가져온 자료를 이유로 여긴다','내 생각 · 밖의 자료'),
('K6-1-u5-X04','kor',6,'u5',ARRAY['K6-1-u5-C2']::text[],'주장만 힘주어 말하면 이유나 근거가 없어도 설득된다고 여긴다','주장만 있으면 우기는 말'),
('K6-1-u5-X05','kor',6,'u5',ARRAY['K6-1-u5-C3']::text[],'주장하는 글을 쓰면 좋은 점을 모르거나, 나만을 위한 글이라 책임이 따르지 않는다고 여긴다','정돈 · 움직임 · 책임'),
('K6-1-u5-X06','kor',6,'u5',ARRAY['K6-1-u5-C5','K6-1-u5-C40']::text[],'글쓰기를 점검하는 일을 글씨 · 줄 수 · 빠르기를 재는 일로 여긴다','무엇을 다시 보게 되나'),
('K6-1-u5-X07','kor',6,'u5',ARRAY['K6-1-u5-C6','K6-1-u5-C44']::text[],'처음부터 흠 없는 완성 글을 내야 한다고 여겨 첫 문장부터 손이 멈춘다','과정을 익히는 시간'),
('K6-1-u5-X08','kor',6,'u5',ARRAY['K6-1-u5-C9','K6-1-u5-C28']::text[],'옳은 말이기만 하면 주장과 이어지지 않아도 이유가 된다고 여긴다','주장과 관련 있나?'),
('K6-1-u5-X09','kor',6,'u5',ARRAY['K6-1-u5-C30','K6-1-u5-C8']::text[],'「나는 그렇게 느꼈다」 · 「아마 다들 그럴 것이다」 같은 느낌이나 짐작을 근거로 쓴다','남이 확인할 수 있나?'),
('K6-1-u5-X10','kor',6,'u5',ARRAY['K6-1-u5-C11','K6-1-u5-C12','K6-1-u5-C13']::text[],'서론 · 본론 · 결론이 맡은 몫을 헷갈린다(서론에 근거만 잔뜩 · 본론에 문제 제기만)','제기 · 펼치기 · 모으기'),
('K6-1-u5-X11','kor',6,'u5',ARRAY['K6-1-u5-C13']::text[],'결론에서 처음 꺼내는 새로운 근거를 내놓아야 한다고 여긴다','결론은 모으고 힘주기'),
('K6-1-u5-X12','kor',6,'u5',ARRAY['K6-1-u5-C12']::text[],'하나의 이유에는 근거가 꼭 하나만 붙어야 한다고 여긴다','여러 개 붙기도 해요'),
('K6-1-u5-X13','kor',6,'u5',ARRAY['K6-1-u5-C14','K6-1-u5-C38']::text[],'수나 조사 결과가 든 뒷받침 문장을 그 문단의 중심 문장으로 고른다','문단을 한 문장으로 줄이면'),
('K6-1-u5-X14','kor',6,'u5',ARRAY['K6-1-u5-C15']::text[],'출처가 붙어 있기만 하면 그 근거는 무조건 타당하다고 여긴다','이 이유를 정말 받치나'),
('K6-1-u5-X15','kor',6,'u5',ARRAY['K6-1-u5-C15','K6-1-u5-C10']::text[],'타당한지를 까닭 없이 「그냥 그럴 것 같아서」로 판단한다','판단에도 까닭을'),
('K6-1-u5-X16','kor',6,'u5',ARRAY['K6-1-u5-C16','K6-1-u5-C17']::text[],'남이 만든 표 · 말 · 문장도 내 글에 넣으면 출처를 밝히지 않아도 된다고 여기거나, 내가 세운 주장에도 출처가 필요하다고 여긴다','내가 만들었나?'),
('K6-1-u5-X17','kor',6,'u5',ARRAY['K6-1-u5-C17']::text[],'여러 글에서 조각조각 가져와 이어 붙이면 내 글이 된다고 여긴다','조각 이어 붙이기도 표절'),
('K6-1-u5-X18','kor',6,'u5',ARRAY['K6-1-u5-C18']::text[],'출처를 밝히는 일을 해도 되고 안 해도 되는 예의 정도로 여긴다','지켜야 할 약속'),
('K6-1-u5-X19','kor',6,'u5',ARRAY['K6-1-u5-C19']::text[],'출처만 적으면 원래 뜻을 내 주장에 맞게 세게 바꾸거나 비틀어도 된다고 여긴다','뜻을 그대로 살려요'),
('K6-1-u5-X20','kor',6,'u5',ARRAY['K6-1-u5-C20']::text[],'저작물 · 저작자 · 저작권을 헷갈리거나, 학생이 쓴 글은 저작물이 아니라고 여긴다','물건 · 사람 · 권리'),
('K6-1-u5-X21','kor',6,'u5',ARRAY['K6-1-u5-C21']::text[],'출처의 네 가지 가운데 하나쯤 빠져도 읽는 사람이 찾아갈 수 있다고 여긴다','네 가지가 다 있어야'),
('K6-1-u5-X22','kor',6,'u5',ARRAY['K6-1-u5-C22']::text[],'출처를 적는 차례와 부호는 하나로 정해져 있어 조금만 달라도 틀린다고 여기거나, 표를 가져올 때 제목과 만든 곳을 빠뜨린다','차례보다 네 가지'),
('K6-1-u5-X23','kor',6,'u5',ARRAY['K6-1-u5-C23']::text[],'누가 썼는지 · 언제 올라왔는지 모르는 글을 믿을 만한 자료로 여기거나, 직접 한 조사는 근거가 될 수 없다고 여긴다','찾아가 확인할 수 있나'),
('K6-1-u5-X24','kor',6,'u5',ARRAY['K6-1-u5-C24']::text[],'자료를 많이 인용할수록 좋은 글이 된다고 여긴다','내 생각이 남나?'),
('K6-1-u5-X25','kor',6,'u5',ARRAY['K6-1-u5-C25']::text[],'쓰기 윤리를 글의 길이나 어려운 낱말 수로 여기거나, 남을 헐뜯는 말은 상관없다고 여긴다','참 · 출처 · 헐뜯지 않기'),
('K6-1-u5-X26','kor',6,'u5',ARRAY['K6-1-u5-C26']::text[],'듣는 사람이 달라지면 주장 자체를 바꿔야 한다고 여기거나, 대상을 생각하지 않고 근거와 말투를 고른다','바뀌는 것은 전하는 방법'),
('K6-1-u5-X27','kor',6,'u5',ARRAY['K6-1-u5-C27','K6-1-u5-C47']::text[],'뜻이 흐리거나 두 가지로 읽히는 주장(「복도를 더 좋게 만듭시다」)도 괜찮다고 여긴다','한 가지로 읽히나?'),
('K6-1-u5-X28','kor',6,'u5',ARRAY['K6-1-u5-C31']::text[],'반대하는 말은 못 들은 척해야 내 주장이 흔들리지 않는다고 여긴다','미리 떠올리면 단단해져요'),
('K6-1-u5-X29','kor',6,'u5',ARRAY['K6-1-u5-C33']::text[],'나 혼자만의 일이나 근거를 찾을 수 없는 일을 주장하는 글의 주제로 고른다','근거 · 여럿에게 알릴 만함'),
('K6-1-u5-X30','kor',6,'u5',ARRAY['K6-1-u5-C35']::text[],'계획은 이미 세웠으니 쓰는 도중에 계획으로 되돌아가면 안 된다고 여긴다','언제든 되돌아가요'),
('K6-1-u5-X31','kor',6,'u5',ARRAY['K6-1-u5-C36']::text[],'내용 생성하기 단계에서 문장부터 다듬느라 떠오르는 것을 꺼내 놓지 못한다','핵심 낱말로 많이'),
('K6-1-u5-X32','kor',6,'u5',ARRAY['K6-1-u5-C36']::text[],'자료를 찾을 때 출처는 나중에 적으면 된다고 미뤄 둔다','지금 적어 두어요'),
('K6-1-u5-X33','kor',6,'u5',ARRAY['K6-1-u5-C37']::text[],'옳은 말이면 글의 주제와 이어지지 않아도 넣어도 된다고 여긴다(통일성)','주제와 이어지나?'),
('K6-1-u5-X34','kor',6,'u5',ARRAY['K6-1-u5-C38']::text[],'중심 문장 없이 뒷받침 문장만 늘어놓아 문단을 짠다','하고 싶은 말 한 문장'),
('K6-1-u5-X35','kor',6,'u5',ARRAY['K6-1-u5-C39','K6-1-u5-C43']::text[],'표현하기를 점검할 때 내가 읽어 매끄러우면 된다고 여겨 나만 아는 줄임말을 그대로 둔다','잣대는 읽을 사람'),
('K6-1-u5-X36','kor',6,'u5',ARRAY['K6-1-u5-C40']::text[],'점검을 글을 다 쓴 뒤에 한 번 채점하는 일로 여긴다','쓰는 도중에 방향을'),
('K6-1-u5-X37','kor',6,'u5',ARRAY['K6-1-u5-C41']::text[],'쓰기 과정 다섯 단계의 이름과 하는 일을 헷갈린다','정하기 · 모으기 · 늘어놓기'),
('K6-1-u5-X38','kor',6,'u5',ARRAY['K6-1-u5-C42']::text[],'앞 단계로 되돌아가면 처음부터 다시 하는 실패라고 여긴다','쓰기의 성질'),
('K6-1-u5-X39','kor',6,'u5',ARRAY['K6-1-u5-C43']::text[],'점검 질문을 엉뚱한 단계에 붙인다(계획하기에서 띄어쓰기를 묻는 식)','그 단계에서 한 일'),
('K6-1-u5-X40','kor',6,'u5',ARRAY['K6-1-u5-C44']::text[],'고칠 곳이 많으면 망한 글이라 여기거나, 고치려면 반드시 새 종이에 전부 다시 써야 한다고 여긴다','쪽지 하나도 점검'),
('K6-1-u5-X41','kor',6,'u5',ARRAY['K6-1-u5-C45']::text[],'고쳐쓰기 세 수준을 헷갈리거나, 반드시 맞춤법부터 또는 반드시 정해진 차례로만 고쳐야 한다고 여긴다','크기를 견줘요'),
('K6-1-u5-X42','kor',6,'u5',ARRAY['K6-1-u5-C46']::text[],'띄어쓰기와 맞춤법은 글쓰기와 상관없는 일이라 살피지 않아도 된다고 여긴다','낱말도 민감하게'),
('K6-1-u5-X43','kor',6,'u5',ARRAY['K6-1-u5-C47']::text[],'우리 힘으로 바꿀 수 없는 문제(날씨 · 방학 길이)를 실천 활동의 문제로 고른다','우리가 바꿀 수 있나?'),
('K6-1-u5-X44','kor',6,'u5',ARRAY['K6-1-u5-C48']::text[],'큰 글씨나 화려한 그림처럼 눈에 띄기만 하면 근거가 없어도 설득된다고 여긴다','근거 하나는 남겨요'),
('K6-1-u5-X45','kor',6,'u5',ARRAY['K6-1-u5-C49']::text[],'네 칸 짜임(의견 · 까닭 · 사례 · 제안)의 차례나 칸마다 들어갈 것을 헷갈린다','꺼내고 · 왜 · 실제 · 다시'),
('K6-1-u5-X46','kor',6,'u5',ARRAY['K6-1-u5-C50']::text[],'주장을 알리고 나면 끝이라 여겨 내가 먼저 해 보는 일은 하지 않아도 된다고 여긴다','마지막 걸음은 생활'),
('K6-1-u5-X47','kor',6,'u5',ARRAY['K6-1-u5-C51','K6-1-u5-C21']::text[],'「어떤 조사에 따르면」 · 「어떤 선생님께서」처럼 흐린 말도 출처를 밝힌 것으로 여긴다','누가 · 언제 · 무엇 · 어디'),
('K6-1-u5-X48','kor',6,'u5',ARRAY['K6-1-u5-C52']::text[],'비와 눈을 가리키는 우리말의 뜻을 헷갈리거나, 우리말에는 비와 눈을 갈라 부르는 말이 없다고 여긴다','언제 · 얼마나 · 어떻게')
